const CREDENTIAL_VALUE_PATTERN = /(?<![A-Za-z0-9])(?:client_secret|access_token|refresh_token)\b["']?\s*[:=]\s*["']?(?!(?:\[?REDACTED\]?|<redacted>|\*{3,})(?:["'\s,;&}]|$))[^"'\s,;&}]+/i;
const DEEPBANK_VALUE_PATTERN = /\bDEEPBANK_[A-Z0-9_]+\s*=\s*["']?(?!(?:\[?REDACTED\]?|<redacted>|\*{3,})(?:["'\s,;&}]|$))[^"'\s,;&}]+/i;
const DEEPBANK_INTERNAL_MARKER_PATTERN = /(?:__)?DEEPBANK_(?:E2E|UNEXPECTED)_[A-Z0-9_]+(?:__)?/i;

const TECHNICAL_FAILURE_PATTERNS = [
  /模型未配置/,
  /cannot execute/i,
  /SkillHub 地址未配置/,
  DEEPBANK_INTERNAL_MARKER_PATTERN,
  DEEPBANK_VALUE_PATTERN,
  /Bearer\s+[A-Za-z0-9._-]+/,
  /\beyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/,
  /BEGIN (?:RSA|OPENSSH) PRIVATE KEY/i,
  CREDENTIAL_VALUE_PATTERN,
  /\bTraceback \(most recent call last\):/i,
  /\bUncaught (?:Error|TypeError|ReferenceError|RangeError|SyntaxError|Exception)\b/i,
  /(?:^|\n)\s*[A-Za-z_$][\w.$]*(?:Error|Exception):\s*\S/im,
  /\bAPI Error\b/i,
  /litellm\.BadRequestError/i,
  /发生内部错误/,
  /系统内部错误/,
  /错误码\s*[:：]?\s*(?:[A-Z_]+[-_]?\d{2,}|\d{4,}|HTTP\s*5\d{2}|5\d{2})/i,
];

const SAFE_NATIVE_ACKNOWLEDGEMENT_LABEL = /^(?:OK|确定|知道了)$/;
const SAFE_NATIVE_ATTACHMENT_INFO_MESSAGE = /(?:暂不支持的附件类型|附件类型.*不支持|上传失败|单个(?:文档|文件).*超过|(?:文档)?附件总大小.*超过|每轮最多添加\s*\d+\s*个附件|一次最多选择\s*\d+\s*个附件)/i;
const SAFE_NATIVE_ARTIFACT_PREVIEW_INFO_MESSAGE = /^无法在 QWork 内预览该 HTML 文件\s+.+\.html$/i;

function coreBetaCapabilityItemIdentity(item) {
  if (item == null) return '';
  if (typeof item === 'string' || typeof item === 'number') return String(item).trim();
  for (const key of ['key', 'id', 'slug', 'name', 'label', 'title']) {
    const value = String(item?.[key] || '').trim();
    if (value) return value;
  }
  return '';
}

export function coreBetaSelectedCapabilityIdentities(items) {
  return (Array.isArray(items) ? items : [])
    .map(coreBetaCapabilityItemIdentity)
    .filter(Boolean);
}

function coreBetaMcpCrossSurfaceTaskGuard(before = {}, after = {}) {
  const beforeTask = before?.task || {};
  const afterTask = after?.task || {};
  const guard = {
    task_absent_before: beforeTask?.id == null,
    task_absent_after: afterTask?.id == null,
    not_running_before: beforeTask?.running === false,
    not_running_after: afterTask?.running === false,
    message_count_zero_before: Number(beforeTask?.message_count) === 0,
    message_count_zero_after: Number(afterTask?.message_count) === 0,
    send_count_observed: Number.isFinite(Number(beforeTask?.send_count))
      && Number.isFinite(Number(afterTask?.send_count)),
    send_count_unchanged: Number(beforeTask?.send_count) === Number(afterTask?.send_count),
  };
  guard.valid = Object.values(guard).every(Boolean);
  return guard;
}

function coreBetaMcpReceiptScreenshotValid(screenshot = {}) {
  const screenshotPath = String(screenshot?.path || '');
  if (
    screenshot?.valid !== true
    || !coreBetaBatchScreenshotPresent(screenshotPath)
    || !/^[a-f0-9]{64}$/i.test(String(screenshot?.sha256 || ''))
  ) return false;
  return createHash('sha256').update(fs.readFileSync(screenshotPath)).digest('hex') === screenshot.sha256;
}

export function coreBetaMcpCrossSurfaceReceiptEvidenceValid(receipt = {}) {
  const key = String(receipt?.key || '').trim();
  const interaction = receipt?.interaction || {};
  const stage = String(interaction?.stage || '');
  const selectedConnectors = receipt?.selected_connectors;
  const selectedByReadback = Array.isArray(selectedConnectors)
    && coreBetaSelectedCapabilityIdentities(selectedConnectors).includes(key);
  const interactionSelectedConnectors = interaction?.selected_connectors;
  const selectedByInteraction = Array.isArray(interactionSelectedConnectors)
    && coreBetaSelectedCapabilityIdentities(interactionSelectedConnectors).includes(key);
  const publicReadback = receipt?.public_readback || {};
  const before = publicReadback?.before || {};
  const after = publicReadback?.after || {};
  const expectedTaskGuard = coreBetaMcpCrossSurfaceTaskGuard(before, after);
  const taskGuard = receipt?.task_guard || {};
  const selectedBefore = before?.connectors?.selected;
  const selectedAfter = after?.connectors?.selected;
  const publicStateValid = Boolean(
    receipt?.case_id
    && before?.case_id === receipt.case_id
    && after?.case_id === receipt.case_id
    && typeof before?.captured_at === 'string'
    && typeof after?.captured_at === 'string'
    && Array.isArray(selectedBefore)
    && selectedBefore.length === 0
    && Array.isArray(selectedAfter)
    && JSON.stringify(selectedAfter) === JSON.stringify(selectedConnectors)
    && after?.capabilities !== null
    && typeof after?.capabilities === 'object'
    && !after.capabilities?.__error
  );
  const selectionReceipt = stage === 'manual_connector_selection'
    && receipt?.reset_ok === true
    && receipt?.selection_attempted === true
    && Array.isArray(interactionSelectedConnectors)
    && receipt?.selected === selectedByInteraction;
  const manualModeFailureReceipt = stage === 'manual_mode'
    && receipt?.reset_ok === false
    && receipt?.selection_attempted === false
    && receipt?.selected === false
    && receipt?.capability_selected === false
    && interaction?.expected_state_observed === false
    && interaction?.category === 'bug'
    && interaction?.aria_checked === 'false'
    && interaction?.manual_surface
    && typeof interaction.manual_surface === 'object';
  return Boolean(
    receipt?.schema_version === 'qbot-core-beta-mcp-cross-surface-receipt/v1'
    && Number.isInteger(receipt?.index)
    && typeof receipt?.captured_at === 'string'
    && key
    && interaction?.schema_version === 'qbot-core-beta-capability-interaction/v1'
    && interaction?.capability_kind === 'connector'
    && String(interaction?.expected_identity || '') === key
    && interaction?.control_located === true
    && interaction?.click_dispatched === true
    && typeof interaction?.expected_state_observed === 'boolean'
    && ['', 'bug'].includes(String(interaction?.category || ''))
    && (selectionReceipt || manualModeFailureReceipt)
    && typeof receipt?.selected === 'boolean'
    && typeof receipt?.capability_selected === 'boolean'
    && Array.isArray(selectedConnectors)
    && receipt.capability_selected === selectedByReadback
    && interaction.expected_state_observed === receipt.selected
    && Array.isArray(receipt?.tools)
    && receipt?.health !== null
    && typeof receipt?.health === 'object'
    && typeof receipt?.visible_text === 'string'
    && publicStateValid
    && taskGuard?.valid === true
    && Object.entries(expectedTaskGuard).every(([field, value]) => taskGuard?.[field] === value)
    && coreBetaMcpReceiptScreenshotValid(receipt?.screenshot)
  );
}

export function coreBetaMcpCrossSurfaceOutcome(receipts, expectedCount = 5) {
  const normalized = Array.isArray(receipts) ? receipts : [];
  const keys = normalized.map((item) => String(item?.key || '').trim()).filter(Boolean);
  const evidenceValid = normalized.length === expectedCount
    && keys.length === expectedCount
    && new Set(keys).size === expectedCount
    && normalized.every((item, index) => item?.index === index)
    && new Set(normalized.map((item) => String(item?.case_id || ''))).size === 1
    && normalized.every(coreBetaMcpCrossSurfaceReceiptEvidenceValid);
  const oracleValid = evidenceValid && normalized.every((item) => (
    item.selected
    && item.capability_selected
    && item.tools.length > 0
  ));
  return {
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: oracleValid,
    expected_count: expectedCount,
    observed_count: normalized.length,
    unique_key_count: new Set(keys).size,
    receipts: normalized,
  };
}

export function safeNativeAttachmentInfoDialog({ message = '', buttons = [] } = {}) {
  const labels = Array.isArray(buttons)
    ? buttons.map((item) => String(item || '').trim()).filter(Boolean)
    : [];
  return SAFE_NATIVE_ATTACHMENT_INFO_MESSAGE.test(String(message || '').replace(/\s+/g, ' ').trim())
    && labels.length === 1
    && SAFE_NATIVE_ACKNOWLEDGEMENT_LABEL.test(labels[0]);
}

export function safeNativeRecoverableInfoDialog({ message = '', buttons = [] } = {}) {
  const normalizedMessage = String(message || '').replace(/\s+/g, ' ').trim();
  const labels = Array.isArray(buttons)
    ? buttons.map((item) => String(item || '').trim()).filter(Boolean)
    : [];
  return Boolean(
    SAFE_NATIVE_ATTACHMENT_INFO_MESSAGE.test(normalizedMessage)
    || SAFE_NATIVE_ARTIFACT_PREVIEW_INFO_MESSAGE.test(normalizedMessage)
  )
    && labels.length === 1
    && SAFE_NATIVE_ACKNOWLEDGEMENT_LABEL.test(labels[0]);
}

export function nativeDialogClosedOrAdvanced(before = {}, after = {}) {
  if (after?.observed !== true) return true;
  const beforeMessage = String(before?.message || '').replace(/\s+/g, ' ').trim();
  const afterMessage = String(after?.message || '').replace(/\s+/g, ' ').trim();
  return Boolean(beforeMessage && afterMessage && beforeMessage !== afterMessage);
}

export function managedAttachmentDialogEvidenceVerdict(result = {}) {
  const message = normalizedNativeDialogText(result.dialogMessage);
  const capturedMessage = normalizedNativeDialogText(result.capturedDialogMessage);
  const validFile = (file) => Boolean(
    file
    && fs.existsSync(file)
    && fs.statSync(file).isFile()
    && fs.statSync(file).size >= 128
  );
  let artifact = {};
  if (validFile(result.dialogEvidenceArtifact)) {
    try {
      artifact = JSON.parse(fs.readFileSync(result.dialogEvidenceArtifact, 'utf8'));
    } catch {
      artifact = {};
    }
  }
  const artifactBindsPlaywrightMessage = Boolean(
    normalizedNativeDialogText(artifact.expected_dialog_message) === message
    && normalizedNativeDialogText(artifact.playwright_dialog_message) === message
  );
  const commonEvidence = Boolean(
    message
    && SAFE_NATIVE_ATTACHMENT_INFO_MESSAGE.test(message)
    && capturedMessage === message
    && SAFE_NATIVE_ACKNOWLEDGEMENT_LABEL.test(String(result.dialogConfirmationLabel || ''))
    && result.dialogHandled === true
    && result.dialogClosed === true
    && result.pageResponsiveAfterDialog === true
    && !String(result.dialogCloseError || '')
    && validFile(result.beforeDispatchScreenshot)
    && validFile(result.dialogEvidenceScreenshot)
    && validFile(result.dialogEvidenceArtifact)
    && validFile(result.postDismissalScreenshot)
    && artifactBindsPlaywrightMessage
  );
  const accessibilityEvidence = Boolean(
    result.dialogAccessibilityRole === 'AXSheet'
    && result.dialogAccessibilityMessageMatched === true
    && result.dialogAccessibilityConfirmationClicked === true
    && result.dialogAccessibilitySheetClosed === true
    && artifact.confirmation_clicked === true
    && artifact.sheet_closed_after_confirmation === true
  );
  const fallbackRecord = artifact.playwright_dialog || {};
  const playwrightFallbackEvidence = Boolean(
    result.dialogAction === 'playwright_accept_fallback'
    && result.dialogType === 'alert'
    && result.dialogPlaywrightObservedBeforeAccept === true
    && result.dialogPlaywrightAllowlisted === true
    && result.dialogPlaywrightAccepted === true
    && result.dialogEvidenceCapturedBeforeAccept === true
    && result.dialogFallbackEvidenceRecorded === true
    && fallbackRecord.observed_before_confirmation === true
    && fallbackRecord.type === 'alert'
    && normalizedNativeDialogText(fallbackRecord.message) === message
    && fallbackRecord.allowlisted_attachment_info === true
    && fallbackRecord.action === 'playwright_accept_fallback'
    && fallbackRecord.accepted === true
    && fallbackRecord.evidence_captured_before_accept === true
    && fallbackRecord.page_responsive_after === true
    && !String(fallbackRecord.close_error || '')
  );
  return commonEvidence && (accessibilityEvidence || playwrightFallbackEvidence);
}

export function coreBetaAttachmentRejectionProbeVerdict(probe = {}) {
  const composer = probe.composer_state || {};
  const noTaskNoSend = probe.no_task_no_send_state || {};
  const dialogObserved = Boolean(String(probe.dialog_message || '').trim());
  return Boolean(
    probe.expected_pattern_matched === true
    && probe.visible_rejection_evidence === true
    && Number(composer.count) === 0
    && Array.isArray(composer.names)
    && composer.names.length === 0
    && noTaskNoSend.valid === true
    && (!dialogObserved || (
      probe.dialog_settled === true
      && (!probe.managed_teams_ax_required || probe.managed_dialog_evidence === true)
    ))
  );
}

export function coreBetaAttachmentRejectionMatrixVerdict(probes = []) {
  const requiredLabels = new Set(['unsupported_type', 'single_file_oversize', 'aggregate_oversize']);
  return Array.isArray(probes)
    && probes.length === requiredLabels.size
    && probes.every((probe) => requiredLabels.delete(String(probe?.label || ''))
      && coreBetaAttachmentRejectionProbeVerdict(probe))
    && requiredLabels.size === 0;
}

