export function isQworkDailyRegressionCasePlan(cases = []) {
  if (cases.length !== QWORK_DAILY_REGRESSION_TOP_LEVEL_CASE_IDS.length) return false;
  return cases.every((testCase, index) => (
    String(testCase?.id || '').trim() === QWORK_DAILY_REGRESSION_TOP_LEVEL_CASE_IDS[index]
    && String(testCase?.contract_version || '').trim() === 'qbot-core-beta/v2'
    && (index < 70
      ? String(testCase?.case_type || '').trim() === 'compound'
      : String(testCase?.case_type || '').trim() !== 'compound')
  ));
}

export async function runUiAgentCasebookCommand({ options = {}, root = process.cwd() } = {}) {
  const startedAt = new Date();
  const casebook = resolveCasebook(root, options.casebook);
  const runStamp = timestampMinute();
  const outDir = path.resolve(options.out || createRunDir(path.join(root, 'autoTest'), `${runStamp}_自动化测试结果`));
  const casesFile = path.join(outDir, 'casebook-cases.json');
  const progressFile = path.join(outDir, 'automation-progress.json');
  const cdpUrl = String(options.cdp || process.env.QBOT_CDP_URL || DEFAULT_CDP_URL);
  const timeoutMs = Number(options['timeout-ms'] || DEFAULT_TIMEOUT_MS);
  const modelTier = String(options['model-tier'] || process.env.QBOT_MODEL_TIER || '').trim().toUpperCase();
  const profile = String(options.profile || 'mandatory');
  const fixturesDir = path.resolve(options.fixtures || path.join(root, 'testflies'));
  const python = String(options.python || process.env.PYTHON || 'python3');
  const resultExcel = path.join(outDir, `${runStamp}_自动化测试结果.xlsx`);
  const scopedExecution = /^(?:1|true|yes)$/i.test(String(options['scoped-execution'] || ''));

  ensureDir(outDir);
  ensureDir(path.join(outDir, 'logs'));
  ensureDir(fixturesDir);
  if (!options['qbot-stderr-log']) {
    const inferredLog = inferQbotExternalLogFile(outDir);
    if (inferredLog) options['qbot-stderr-log'] = inferredLog;
  }

  const exportCommand = runPython({
    python,
    args: [
      path.join(root, 'skills', 'qbot-execute-automation-tests', 'scripts', 'casebook_io.py'),
      'export-cases',
      '--casebook',
      casebook,
      '--output',
      casesFile,
      '--profile',
      profile,
      ...(options.sheet ? ['--sheet', String(options.sheet)] : []),
      ...(options.case ? ['--case', String(options.case)] : []),
      ...(options.offset ? ['--offset', String(options.offset)] : []),
      ...(options.limit ? ['--limit', String(options.limit)] : []),
    ],
    cwd: root,
  });
  writeTextFile(path.join(outDir, 'logs', 'export-cases.stdout.log'), exportCommand.stdout || '');
  writeTextFile(path.join(outDir, 'logs', 'export-cases.stderr.log'), exportCommand.stderr || '');
  if (exportCommand.status !== 0) {
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results: [],
      reason: `导出测试用例失败：${exportCommand.stderr || exportCommand.error || 'unknown error'}`,
    });
    writeRunArtifacts(outDir, summary);
    return summary;
  }

  const casePlan = JSON.parse(fs.readFileSync(casesFile, 'utf8'));
  const selectedCases = casePlan.cases || [];
  writeTextFile(path.join(outDir, 'casebook-source.txt'), casebook);
  copyIfExists(casebook, path.join(outDir, `source-${path.basename(casebook)}`));
  if (!selectedCases.length) {
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results: [],
      reason: '测试用例文档中没有匹配本次 profile/case/limit 的可执行用例。',
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }

  let scopeAudit = null;
  if (scopedExecution) {
    const fullCasesFile = path.join(outDir, 'casebook-full-cases.json');
    const fullExport = runPython({
      python,
      args: [
        path.join(root, 'skills', 'qbot-execute-automation-tests', 'scripts', 'casebook_io.py'),
        'export-cases',
        '--casebook',
        casebook,
        '--output',
        fullCasesFile,
        '--profile',
        profile,
        ...(options.sheet ? ['--sheet', String(options.sheet)] : []),
      ],
      cwd: root,
    });
    writeTextFile(path.join(outDir, 'logs', 'export-full-cases.stdout.log'), fullExport.stdout || '');
    writeTextFile(path.join(outDir, 'logs', 'export-full-cases.stderr.log'), fullExport.stderr || '');
    const fullCases = fullExport.status === 0
      ? (JSON.parse(fs.readFileSync(fullCasesFile, 'utf8')).cases || [])
      : [];
    const excludedCaseIds = String(options['excluded-case'] || '')
      .split(/[,，\s]+/).map((item) => item.trim()).filter(Boolean);
    scopeAudit = validateCoreBetaScopedSelection({
      fullCases,
      selectedCases,
      excludedCaseIds,
      reason: options['scope-reason'] || '',
    });
    const fullFixtureReadiness = fullCases.length
      ? await inspectCoreBetaFixtureReadiness({
        options: {
          ...options,
          'core-beta-fixture-control-url': '',
        },
        cases: fullCases,
      })
      : null;
    const unavailableFixtureIds = Array.isArray(fullFixtureReadiness?.missing_case_ids)
      ? fullFixtureReadiness.missing_case_ids
      : [];
    const fixtureExclusionCoverage = classifyCoreBetaScopedFixtureExclusions({
      unavailableCaseIds: unavailableFixtureIds,
      excludedCaseIds: scopeAudit.excluded_case_ids,
    });
    if (!fixtureExclusionCoverage.ok) {
      scopeAudit.errors.push(
        'excluded Case 必须覆盖当前环境全部不可用 fixture Case；'
        + `missing=${fixtureExclusionCoverage.missing_unavailable_fixture_case_ids.join(',')}; `
        + `actual=${scopeAudit.excluded_case_ids.join(',')}`,
      );
      scopeAudit.ok = false;
    }
    Object.assign(scopeAudit, fixtureExclusionCoverage);
    scopeAudit.full_fixture_readiness = fullFixtureReadiness;
    writeJsonFile(path.join(outDir, 'scoped-execution.json'), scopeAudit);
    if (fullExport.status !== 0 || !scopeAudit.ok) {
      const reason = `scoped execution 合同失败：${fullExport.status !== 0
        ? fullExport.stderr || fullExport.error || '完整 Casebook 导出失败'
        : scopeAudit.errors.join('；')}`;
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'automation_error',
        reason,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason,
        precheck: { scoped_execution: scopeAudit },
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
  } else if (options['excluded-case'] || options['scope-reason']) {
    const reason = 'scoped options require --scoped-execution true';
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results: [],
      reason,
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }

  const coreBetaCases = selectedCases.filter(isCoreBetaCase);
  if (coreBetaCases.length) {
    const protocolAudit = validateCoreBetaCasePlan(coreBetaCases, {
      fixtureRoot: fixturesDir,
      allowPartialInitialization: scopedExecution && scopeAudit?.ok === true,
      allowDependencyGaps: scopedExecution && scopeAudit?.ok === true,
    });
    writeJsonFile(path.join(outDir, 'core-beta-protocol-preflight.json'), protocolAudit);
    if (!protocolAudit.ok || coreBetaCases.length !== selectedCases.length) {
      const extra = coreBetaCases.length !== selectedCases.length
        ? [`同一执行批次不得混用 Core Beta v2 与旧协议：v2=${coreBetaCases.length}, total=${selectedCases.length}`]
        : [];
      const reason = `Core Beta v2 执行协议预检失败：${[...extra, ...protocolAudit.errors].slice(0, 30).join('；')}`;
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'automation_error',
        reason,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason,
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
    const fixtureAudit = await inspectCoreBetaFixtureReadiness({
      options,
      cases: coreBetaCases,
    });
    writeJsonFile(path.join(outDir, 'core-beta-fixture-readiness.json'), fixtureAudit);
    if (!fixtureAudit.ok) {
      const reason = `Core Beta 受控执行能力预检失败：${fixtureAudit.reason}`;
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'automation_error',
        reason,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason,
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
  }

  let runOwnedSkillCleanupSeed = null;
  if (options['core-beta-cleanup-from']) {
    try {
      runOwnedSkillCleanupSeed = seedCoreBetaRunOwnedSkillCleanupLedger({
        sourceOut: options['core-beta-cleanup-from'],
        currentOut: outDir,
        casebook,
        selectedCases,
        allowReleaseMigration: /^(?:1|true|yes)$/i.test(String(
          options['core-beta-cleanup-release-migration'] || '',
        )),
      });
    } catch (error) {
      const reason = `Core Beta run-owned Skill 清理源验证失败：${error.message}`;
      const diagnostic = {
        schema_version: 'qbot-core-beta-run-owned-skill-cleanup-source/v2',
        valid: false,
        generated_at: new Date().toISOString(),
        source_out: String(options['core-beta-cleanup-from'] || ''),
        current_out: outDir,
        reason,
      };
      writeJsonFile(path.join(outDir, 'core-beta-run-owned-skill-cleanup-source.json'), diagnostic);
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results: [],
        reason,
        precheck: { run_owned_skill_cleanup_source: diagnostic },
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
  }

  const productionGateEnabled = options['production-gate'] === true
    || options['production-gate'] === 'true'
    || String(options['gate-profile'] || '').toLowerCase() === 'release';
  if (productionGateEnabled) {
    const audit = validateProductionCasePlan(selectedCases, {
      backendVersion: options['backend-version'] || process.env.QBOT_BACKEND_VERSION || '',
      promptPolicyVersion: options['prompt-policy-version'] || process.env.QBOT_PROMPT_POLICY_VERSION || '',
      featureFlagsHash: options['feature-flags-hash'] || process.env.QBOT_FEATURE_FLAGS_HASH || '',
    });
    writeJsonFile(path.join(outDir, 'production-casebook-preflight.json'), audit);
    if (!audit.ok) {
      const reason = `生产门禁前置检查失败：${audit.errors.slice(0, 20).join('；')}`;
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'automation_error',
        reason,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason,
        precheck: { production_casebook: audit },
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
  }

  if (options['skip-run'] === true) {
    const results = selectedCases.map((testCase, index) => buildSyntheticResult({
      outDir,
      testCase,
      index,
      status: 'blocked',
      resultCategory: 'blocked',
      reason: 'skip-run 模式：仅验证用例读取和结果文件生成，不执行 QBot UI。',
    }));
    const summary = buildSummary({
      status: 'dry-run',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results,
      reason: 'skip-run',
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }

  const requestedParallelism = Number(options.parallel || (options['worker-cdps'] ? DEFAULT_CASE_PARALLELISM : 1));
  const requestedSingleHostPipelineSize = parseSingleHostPipelineSize(options['single-host-pipeline']);
  const concurrencyPolicy = coreBetaExecutionConcurrencyPolicy({
    selectedCases,
    requestedParallelism,
    requestedSingleHostPipelineSize,
  });
  const parallelism = concurrencyPolicy.effective_parallelism;
  const singleHostPipelineSize = concurrencyPolicy.effective_single_host_pipeline_size;
  if (parallelism > 1 && singleHostPipelineSize > 1) {
    const reason = '单宿主会话流水线与多 CDP --parallel 不能同时启用；请选择一种并发模型。';
    const results = selectedCases.map((testCase, index) => buildSyntheticResult({
      outDir,
      testCase,
      index,
      status: 'blocked',
      resultCategory: 'automation_error',
      reason,
    }));
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results,
      reason,
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }
  if (options['parallel-child'] !== true && options['parallel-child'] !== 'true' && parallelism > 1) {
    return runParallelUiAgentCasebook({
      options,
      root,
      startedAt,
      casebook,
      outDir,
      progressFile,
      resultExcel,
      profile,
      modelTier,
      python,
      selectedCases,
      parallelism,
    });
  }

  const loaded = await loadPlaywright();
  if (loaded.error) {
    const results = selectedCases.map((testCase, index) => buildSyntheticResult({
      outDir,
      testCase,
      index,
      status: 'blocked',
      resultCategory: 'blocked',
      reason: `Playwright 未安装或无法加载：${loaded.error.message}`,
    }));
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results,
      reason: `Playwright 未安装或无法加载：${loaded.error.message}`,
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }

  let browser;
  try {
    browser = await loaded.chromium.connectOverCDP(cdpUrl);
    let page = await findQbotPage(browser);
    if (!page) {
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'blocked',
        reason: `已连接 CDP ${cdpUrl}，但没有找到 QBot 页面。`,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason: `已连接 CDP ${cdpUrl}，但没有找到 QBot 页面。`,
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }

    page.setDefaultTimeout(12000);
    page.setDefaultNavigationTimeout(30000);
    // Do not install a blanket dialog handler here. Playwright dismisses dialogs by
    // default when no listener exists, while case-specific confirmation flows use
    // captureDialogDuringWithAction(). A permanent dismiss listener races those
    // handlers and previously made delete/confirm cases look like product bugs.
    const runtime = { browser, page, playwright: loaded, cdpUrl };
    const precheck = await inspectPrecheck(page, outDir);
    if (runOwnedSkillCleanupSeed) {
      precheck.run_owned_skill_cleanup_source = runOwnedSkillCleanupSeed;
    }
    precheck.single_host_pipeline = {
      enabled: singleHostPipelineSize > 1,
      requested_size: requestedSingleHostPipelineSize,
      effective_size: singleHostPipelineSize,
      max_size: MAX_SINGLE_HOST_PIPELINE_SIZE,
      eligible_cases: selectedCases.filter((testCase) => singleHostPipelineEligibility(testCase).eligible).map((testCase) => testCase.id),
      policy: concurrencyPolicy.forced_serial
        ? 'core-beta-v2-forced-serial'
        : '仅连续、单轮、无附件、无技能/MCP、无HITL、无重启、无共享状态的白名单会话进入流水线；其余自动串行。',
    };
    precheck.execution_concurrency = concurrencyPolicy;
    const modelTierRecoveryPrefix = selectedCases.length > 0
      && !caseRequiresModelTier(selectedCases[0]);
    precheck.model_tier = modelTier
      ? (precheck.login_required
        ? { requested: modelTier, status: 'deferred', reason: '当前仍在登录前置阶段，模型档位检查延后到登录后每条 case 执行前。' }
        : await inspectModelTierAvailability(page, modelTier))
      : { requested: '', status: 'skipped', reason: '未请求固定模型档位。' };
    if (
      modelTier
      && modelTierRecoveryPrefix
      && ['unavailable', 'error'].includes(precheck.model_tier.status)
    ) {
      precheck.model_tier = {
        ...precheck.model_tier,
        status: 'deferred',
        reason: `初始化维护 Case 不依赖模型连接；先执行真实初始化恢复，首个需要模型的 Case 发送前仍强制锁定 ${modelTier}。原始检查：${precheck.model_tier.reason || 'unknown'}`,
        deferred_by_initialization_recovery: true,
      };
    }
    if (modelTier && ['unavailable', 'error'].includes(precheck.model_tier.status)) {
      const results = selectedCases.map((testCase, index) => buildSyntheticResult({
        outDir,
        testCase,
        index,
        status: 'blocked',
        resultCategory: 'blocked',
        reason: `模型档位前置阻塞：未找到可用 ${modelTier} 连接，停止本轮功能用例执行。${precheck.model_tier.reason || ''}`,
      }));
      const summary = buildSummary({
        status: 'blocked',
        startedAt,
        outDir,
        casebook,
        resultExcel,
        profile,
        cdpUrl,
        modelTier,
        results,
        reason: `模型档位前置阻塞：未找到可用 ${modelTier} 连接。`,
        precheck,
      });
      writeRunArtifacts(outDir, summary);
      await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
      return summary;
    }
    const resume = loadResumeProgress(progressFile, selectedCases, options.resume === true || options.resume === 'true');
    const results = resume.results;
    let frameworkStop = null;
    for (let index = resume.startIndex; index < selectedCases.length; index += 1) {
      const testCase = selectedCases[index];
      const caseDir = path.join(outDir, 'cases', `${String(index + 1).padStart(3, '0')}-${testCase.id}-${slugify(testCase.scenario)}`);
      ensureDir(caseDir);
      if (!isLiveCdpPage(browser, page)) {
        const reason = `自动化框架检测到 QBot CDP/page 已断开，停止本批次，避免把后续用例误判为产品 Bug。CDP=${cdpUrl}`;
        frameworkStop = stopRemainderWithoutSynthetic({
          outDir,
          selectedCases,
          startIndex: index,
          results,
          progressFile,
          status: 'blocked',
          resultCategory: 'automation_error',
          reason,
        });
        break;
      }
      const pipelineBatch = singleHostPipelineSize > 1
        ? buildSingleHostPipelineBatch(selectedCases, index, singleHostPipelineSize)
        : [];
      if (pipelineBatch.length > 1) {
        const pipelineExecution = await executeSingleHostPipelineBatch({
          page,
          batch: pipelineBatch,
          outDir,
          timeoutMs,
          fixturesDir,
          precheck,
          modelTier,
          options,
          playwright: loaded,
          runtime,
        });
        const batchResults = pipelineExecution.results;
        const executedPipelineBatch = pipelineExecution.batch;
        browser = runtime.browser;
        page = runtime.page;
        let pipelineStopped = false;
        for (let batchOffset = 0; batchOffset < batchResults.length; batchOffset += 1) {
          const result = batchResults[batchOffset];
          const batchEntry = executedPipelineBatch[batchOffset];
          const batchCase = batchEntry?.testCase;
          const completionBlock = coreBetaCompletionBlockReason(batchCase, result);
          if (completionBlock) {
            frameworkStop = stopRemainderWithoutSynthetic({
              outDir,
              selectedCases,
              startIndex: batchEntry?.index ?? (index + batchOffset),
              results,
              progressFile,
              status: 'stopped',
              resultCategory: 'automation_error',
              reason: completionBlock,
              failedResult: result,
            });
            pipelineStopped = true;
            break;
          }
          results.push(result);
          writeJsonFile(progressFile, {
            updated_at: new Date().toISOString(),
            completed: results.length,
            total: selectedCases.length,
            current_case: result.id,
            execution_mode: 'single-host-pipeline',
            pipeline_size: executedPipelineBatch.length,
            results,
          });
          const hardStopReason = coreBetaBatchStopReason(batchCase, result);
          if (hardStopReason) {
            frameworkStop = stopRemainderWithoutSynthetic({
              outDir,
              selectedCases,
              startIndex: batchEntry?.index ?? (index + batchOffset),
              results,
              progressFile,
              status: 'blocked',
              resultCategory: 'automation_error',
              reason: hardStopReason,
              failedResult: result,
            });
            pipelineStopped = true;
            break;
          }
        }
        if (pipelineStopped) break;
        index += executedPipelineBatch.length - 1;
        const disconnected = batchResults.find(isCdpDisconnectedResult);
        if (disconnected || !isLiveCdpPage(browser, page)) {
          const reason = `单宿主流水线执行后 QBot CDP/page 已断开，停止本批次，避免把剩余用例误判为产品 Bug。${disconnected ? `原始现象：${clip(disconnected.actual_result || disconnected.conclusion || '', 260)}` : ''}`;
          frameworkStop = stopRemainderWithoutSynthetic({
            outDir,
            selectedCases,
            startIndex: index + 1,
            results,
            progressFile,
            status: 'blocked',
            resultCategory: 'automation_error',
            reason,
          });
          break;
        }
        continue;
      }
      const result = await executeCasebookCase({
        page,
        testCase,
        caseDir,
        order: index + 1,
        timeoutMs,
        fixturesDir,
        precheck,
        modelTier,
        options,
        playwright: loaded,
        runtime,
      });
      browser = runtime.browser;
      page = runtime.page;
      const completionBlock = coreBetaCompletionBlockReason(testCase, result);
      if (completionBlock) {
        frameworkStop = stopRemainderWithoutSynthetic({
          outDir,
          selectedCases,
          startIndex: index,
          results,
          progressFile,
          status: 'stopped',
          resultCategory: 'automation_error',
          reason: completionBlock,
          failedResult: result,
        });
        break;
      }
      results.push(result);
      writeJsonFile(progressFile, {
        updated_at: new Date().toISOString(),
        completed: results.length,
        total: selectedCases.length,
        results,
      });
      const hardStopReason = coreBetaBatchStopReason(testCase, result);
      if (hardStopReason) {
        frameworkStop = stopRemainderWithoutSynthetic({
          outDir,
          selectedCases,
          startIndex: index,
          results,
          progressFile,
          status: 'blocked',
          resultCategory: 'automation_error',
          reason: hardStopReason,
          failedResult: result,
        });
        break;
      }
      if (isCdpDisconnectedResult(result) || !isLiveCdpPage(browser, page)) {
        const resultDisconnected = isCdpDisconnectedResult(result);
        const reason = `用例 ${testCase.id} 执行后 QBot CDP/page 已断开，停止本批次，避免把剩余用例误判为产品 Bug。原始现象：${clip(result.actual_result || result.conclusion || '', 260)}`;
        frameworkStop = stopRemainderWithoutSynthetic({
          outDir,
          selectedCases,
          startIndex: resultDisconnected ? index : index + 1,
          results,
          progressFile,
          status: 'blocked',
          resultCategory: 'automation_error',
          reason,
          failedResult: resultDisconnected ? result : null,
        });
        break;
      }
    }

    const summary = buildSummary({
      status: frameworkStop?.status || statusFromResults(results),
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results,
      precheck,
      expectedTotal: selectedCases.length,
      frameworkStop,
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  } catch (error) {
    const results = selectedCases.map((testCase, index) => buildSyntheticResult({
      outDir,
      testCase,
      index,
      status: 'blocked',
      resultCategory: 'blocked',
      reason: `自动化框架异常：${error.message}`,
    }));
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl,
      modelTier,
      results,
      reason: error.message,
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  } finally {
    if (browser) await browser.close().catch(() => {});
  }
}

function automationErrorFailureItems(result = {}) {
  return [
    ...(Array.isArray(result?.steps) ? result.steps : []),
    ...(Array.isArray(result?.assertions) ? result.assertions : []),
  ].filter((item) => item?.status === 'failed' && item?.category === 'automation_error');
}

export function resultHasAutomationError(result = {}) {
  return result?.result_category === 'automation_error'
    || automationErrorFailureItems(result).length > 0;
}

export function applyBlockedOutcome(state, reason) {
  if (resultHasAutomationError(state)) {
    const failures = automationErrorFailureItems(state);
    const evidenceReason = failures
      .map((item) => `${item.name || item.action || '自动化步骤'}：${item.actual || 'failed'}`)
      .join('；');
    const existingReason = state.result_category === 'automation_error'
      ? String(state.actual_result || '').trim()
      : '';
    state.status = 'failed';
    state.result_category = 'automation_error';
    state.actual_result = existingReason || evidenceReason || '自动化链路存在失败证据。';
    state.conclusion = `失败：${state.actual_result}`;
    state.problem_description = '';
    state.secondary_blockers = Array.from(new Set([
      ...(Array.isArray(state.secondary_blockers) ? state.secondary_blockers : []),
      String(reason || '').trim(),
    ].filter(Boolean)));
    return { preserved_automation_error: true };
  }
  state.status = 'blocked';
  state.result_category = 'blocked';
  state.blocked_reason = reason;
  state.actual_result = reason;
  state.conclusion = `阻塞：${reason}`;
  return { preserved_automation_error: false };
}

export function coreBetaBatchStopReason(testCase, result) {
  if (!isCoreBetaCase(testCase)) return '';
  const id = String(testCase?.id || '');
  if (resultHasAutomationError(result)) {
    return `框架硬门禁 ${id} 发生 automation_error，停止后续 Case；`
      + '必须修复执行、取证、manifest、断言或清理能力后新建不可变批次。';
  }
  if (String(testCase?.case_type || '') === 'run_initialization' && result?.status !== 'passed') {
    const continuation = result?.initialization_continuation;
    if (
      result?.result_category === 'bug'
      && continuation?.eligible === true
      && continuation?.safe === true
    ) {
      return '';
    }
    return `初始化执行门禁 ${id} 未通过（${result?.status || 'unknown'}/${result?.result_category || 'unknown'}），`
      + '且未证明产品失败后的公开工作台可安全继续；停止后续 Case。';
  }
  return '';
}

export function coreBetaInitializationContinuation({
  testCase,
  terminalReadback = {},
  afterReadback = {},
  continuationSurface = {},
} = {}) {
  const id = String(testCase?.id || '');
  const eligible = ['BETA-INIT-001', 'BETA-INIT-002', 'BETA-INIT-003', 'BETA-INIT-004'].includes(id);
  const recoveredSurfaceValid = continuationSurface?.valid === true;
  const terminalComposerReady = terminalReadback?.composer_ready === true;
  const recoveredComposerReady = recoveredSurfaceValid && continuationSurface?.composer_ready === true;
  const terminalWorkbenchReady = terminalReadback?.workbench_ready === true;
  const recoveredWorkbenchReady = recoveredSurfaceValid && continuationSurface?.workbench_ready === true;
  const signals = {
    terminal_pending: terminalReadback?.pending === true,
    terminal_failed: terminalReadback?.failed === true,
    runtime_loaded: terminalReadback?.loaded === true,
    sdk_ready: terminalReadback?.sdk_ready === true,
    button_enabled: terminalReadback?.button_enabled === true,
    composer_ready: terminalComposerReady || recoveredComposerReady,
    composer_ready_source: terminalComposerReady
      ? 'maintenance_terminal'
      : recoveredComposerReady ? 'recovered_workbench_surface' : 'unavailable',
    workbench_ready: terminalWorkbenchReady || recoveredWorkbenchReady,
    workbench_ready_source: terminalWorkbenchReady
      ? 'maintenance_terminal'
      : recoveredWorkbenchReady ? 'recovered_workbench_surface' : 'unavailable',
    continuation_surface_valid: recoveredSurfaceValid,
    capabilities_readable: terminalReadback?.capabilities_readable === true,
    after_page_readable: Number(
      afterReadback?.page?.body_text_length
      || afterReadback?.body_text_length
      || 0,
    ) > 0,
  };
  const safe = eligible
    && signals.terminal_failed
    && !signals.terminal_pending
    && signals.runtime_loaded
    && signals.sdk_ready
    && signals.button_enabled
    && signals.composer_ready
    && signals.workbench_ready
    && signals.capabilities_readable
    && signals.after_page_readable;
  return {
    schema_version: 'qbot-core-beta-initialization-continuation/v1',
    case_id: id,
    eligible,
    safe,
    release_gate_eligible: false,
    reason: safe
      ? '初始化维护动作存在可信产品失败，但运行时、SDK、工作台、输入区、按钮和 capabilities 均已确认可用；允许继续收集独立 Case 证据，整轮仍为发布 NO-GO。'
      : eligible
        ? '初始化失败后的公开可用性信号不完整，禁止继续执行。'
        : '该初始化 Case 不允许降级继续。',
    signals,
  };
}

export function coreBetaCompletionBlockReason(testCase, result) {
  if (!isCoreBetaCase(testCase)) return '';
  const id = String(testCase?.id || result?.id || 'unknown');
  if (result?.synthetic === true) {
    return `框架发布门禁 ${id} 拒绝 synthetic 结果进入 completed。`;
  }
  const manifest = result?.evidence_manifest;
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    return `框架发布门禁 ${id} 拒绝缺失的内嵌 evidence manifest 进入 completed。`;
  }
  if (!Array.isArray(manifest.missing_roles) || !Array.isArray(manifest.invalid_roles)) {
    return `框架发布门禁 ${id} 拒绝结构异常的 manifest 进入 completed：missing_roles/invalid_roles 必须为数组。`;
  }
  if (
    manifest.complete !== true
    || manifest.missing_roles.length > 0
    || manifest.invalid_roles.length > 0
  ) {
    return `框架发布门禁 ${id} 拒绝不完整 manifest 进入 completed：`
      + `complete=${String(manifest.complete)}；missing=${manifest.missing_roles.join(',')}；invalid=${manifest.invalid_roles.join(',')}。`;
  }
  if (!Array.isArray(manifest.evidence) || manifest.evidence.some((item) => (
    item?.missing === true
    || item?.valid !== true
    || !/^[a-f0-9]{64}$/i.test(String(item?.sha256 || ''))
  ))) {
    return `框架发布门禁 ${id} 拒绝缺失、无效或 SHA 不完整的 evidence 进入 completed。`;
  }
  const compoundEvidenceBlock = coreBetaCompoundCompletionBlockReason(testCase, result);
  if (compoundEvidenceBlock) return compoundEvidenceBlock;
  const batchEvidenceBlock = coreBetaDispatchCollect20CompletionBlockReason(testCase, result);
  if (batchEvidenceBlock) return batchEvidenceBlock;
  return '';
}

function coreBetaCompoundCompletionBlockReason(testCase, result) {
  if (String(testCase?.case_type || '') !== 'compound') return '';
  const id = String(testCase?.id || result?.id || 'unknown');
  const declared = Array.isArray(testCase?.compound_subcases) ? testCase.compound_subcases : [];
  const caseDir = path.resolve(String(result?.case_dir || ''));
  const manifestFile = path.resolve(String(
    result?.artifacts?.compound_evidence_manifest
    || (caseDir ? path.join(caseDir, 'compound-evidence-manifest.json') : ''),
  ));
  const relativeManifest = caseDir ? path.relative(caseDir, manifestFile) : '..';
  if (
    !caseDir
    || !manifestFile
    || relativeManifest === '..'
    || relativeManifest.startsWith(`..${path.sep}`)
    || path.isAbsolute(relativeManifest)
    || !fs.existsSync(manifestFile)
    || !fs.statSync(manifestFile).isFile()
    || fs.statSync(manifestFile).size <= 0
  ) {
    return `框架发布门禁 ${id} 拒绝缺失、为空或越界的 compound evidence manifest 进入 completed。`;
  }
  let compoundManifest;
  try {
    compoundManifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
  } catch (error) {
    return `框架发布门禁 ${id} 拒绝无法解析的 compound evidence manifest 进入 completed：${String(error?.message || error)}。`;
  }
  const rows = Array.isArray(compoundManifest?.subcases) ? compoundManifest.subcases : [];
  if (
    compoundManifest?.schema_version !== 'qbot-core-beta-compound-evidence/v1'
    || compoundManifest?.parent_case_id !== id
    || compoundManifest?.parent_contract_sha256 !== coreBetaCaseContractSha256(testCase)
    || compoundManifest?.execution_policy !== 'strict_serial'
    || Number(compoundManifest?.expected_subcase_count) !== declared.length
    || Number(compoundManifest?.observed_subcase_count) !== declared.length
    || compoundManifest?.complete !== true
    || rows.length !== declared.length
  ) {
    return `框架发布门禁 ${id} 拒绝结构异常或 incomplete 的 compound evidence manifest 进入 completed。`;
  }
  for (const [index, subcase] of declared.entries()) {
    const row = rows[index];
    const expectedContract = coreBetaCaseContractSha256(subcase);
    if (
      Number(row?.order) !== index + 1
      || String(row?.case_id || '') !== String(subcase?.id || '')
      || String(row?.case_contract_sha256 || '') !== expectedContract
      || row?.evidence_complete !== true
      || row?.valid !== true
    ) {
      return `框架发布门禁 ${id} 拒绝第 ${index + 1} 个子 Case 身份、顺序、合同或完整性不一致的 compound evidence manifest。`;
    }
    for (const [label, fileRecord] of [
      ['case-result', row?.case_result],
      ['evidence-manifest', row?.evidence_manifest],
    ]) {
      const file = path.resolve(String(fileRecord?.path || ''));
      const relative = path.relative(caseDir, file);
      const validFile = Boolean(
        fileRecord?.valid === true
        && relative
        && relative !== '..'
        && !relative.startsWith(`..${path.sep}`)
        && !path.isAbsolute(relative)
        && fs.existsSync(file)
        && fs.statSync(file).isFile()
        && fs.statSync(file).size > 0
        && Number(fileRecord?.bytes) === fs.statSync(file).size
        && /^[a-f0-9]{64}$/i.test(String(fileRecord?.sha256 || ''))
        && createHash('sha256').update(fs.readFileSync(file)).digest('hex') === fileRecord.sha256
      );
      if (!validFile) {
        return `框架发布门禁 ${id} 拒绝第 ${index + 1} 个子 Case 缺失、越界或 SHA 不一致的 ${label} 证据。`;
      }
    }
  }
  return '';
}

export function aggregateCompoundOutcome(subcaseResults = []) {
  const rows = Array.isArray(subcaseResults) ? subcaseResults : [];
  if (rows.some((item) => resultHasAutomationError(item))) {
    return { status: 'failed', result_category: 'automation_error' };
  }
  if (rows.some((item) => item?.result_category === 'bug' || item?.status === 'failed')) {
    return { status: 'failed', result_category: 'bug' };
  }
  if (rows.some((item) => item?.status === 'blocked' || item?.result_category === 'blocked')) {
    return { status: 'blocked', result_category: 'blocked' };
  }
  return { status: 'passed', result_category: 'pass' };
}

export function compoundBlockedReason(subcaseResults = []) {
  const blocked = (Array.isArray(subcaseResults) ? subcaseResults : []).find((item) => (
    item?.status === 'blocked' || item?.result_category === 'blocked'
  ));
  return String(
    blocked?.blocked_reason
    || blocked?.actual_result
    || blocked?.conclusion
    || '',
  ).trim();
}

export function coreBetaDispatchCollect20CompletionBlockReason(testCase, result) {
  const id = String(testCase?.id || result?.id || '');
  if (id !== 'BETA-CHAT-008') return '';
  const expected = Number(testCase?.batch_size || result?.batch_size || 20);
  const artifacts = result?.artifacts && typeof result.artifacts === 'object'
    ? result.artifacts
    : {};
  if (expected !== 20) return `框架发布门禁 ${id} 要求 batch_size=20，actual=${expected}。`;
  if (artifacts.core_beta_scenario_driver !== 'conversation_dispatch_collect_20') {
    return `框架发布门禁 ${id} 拒绝错误 scenario driver：${artifacts.core_beta_scenario_driver || 'missing'}。`;
  }
  const dispatch = artifacts.core_beta_batch_dispatch;
  if (!Array.isArray(dispatch) || dispatch.length !== expected) {
    return `框架发布门禁 ${id} 拒绝缺失的 20 条批量派发账本：actual=${Array.isArray(dispatch) ? dispatch.length : 'missing'}。`;
  }
  const taskIds = dispatch.map((entry) => String(entry?.task_id || ''));
  if (
    taskIds.some((taskId) => !taskId)
    || new Set(taskIds).size !== expected
    || dispatch.some((entry) => (
      entry?.send_receipt?.confirmed !== true
      || !String(entry?.send_receipt?.confirmed_at || '')
      || !String(entry?.marker || '')
      || !String(entry?.prompt || '').includes(String(entry?.marker || ''))
      || !coreBetaBatchEvidenceFilePresent(entry?.dispatch_screenshot)
    ))
  ) {
    return `框架发布门禁 ${id} 拒绝 taskId、marker、确认发送回执或逐任务发送后截图不完整的派发账本。`;
  }
  const pending = artifacts.core_beta_batch_pending_pool;
  const pendingTaskIds = Array.isArray(pending?.observations)
    ? pending.observations.map((entry) => String(entry?.task_id || ''))
    : [];
  if (
    !pending
    || Number(pending.expected_task_count || 0) !== expected
    || Number(pending.minimum_pending_required || 0) !== 5
    || pendingTaskIds.length !== expected
    || new Set(pendingTaskIds).size !== expected
    || pendingTaskIds.some((taskId) => !taskIds.includes(taskId))
    || !coreBetaBatchEvidenceFilePresent(pending.screenshot)
  ) {
    return `框架发布门禁 ${id} 拒绝缺失或结构不完整的末条派发后待回复池读回。`;
  }
  const collected = artifacts.core_beta_batch_collect;
  if (
    !Array.isArray(collected)
    || collected.length !== expected
    || collected.some((entry) => (
      !taskIds.includes(String(entry?.task_id || ''))
      || !String(entry?.terminal_outcome || '')
      || !String(entry?.terminal_at || '')
      || Number(entry?.observation_count || 0) < 1
      || !entry?.last_observation
      || !coreBetaBatchEvidenceFilePresent(entry?.terminal_screenshot)
    ))
  ) {
    return `框架发布门禁 ${id} 拒绝缺失逐 taskId 终态观察或终态截图的批量回收账本。`;
  }
  const terminal = artifacts.core_beta_batch_collection_summary?.terminal_evidence;
  if (
    !terminal
    || terminal.available !== true
    || terminal.task_ids_unique !== true
    || terminal.dispatch_receipts_complete !== true
    || terminal.terminal_rows_complete !== true
    || Number(terminal.dispatched || 0) !== expected
  ) {
    return `框架发布门禁 ${id} 拒绝缺失或不完整的批量共享截止时间终态证据。`;
  }
  const caseDir = String(result?.case_dir || '');
  const requiredFiles = [
    'batch-dispatch-ledger.json',
    'batch-pending-pool.json',
    'batch-collect-observations.ndjson',
    'batch-collect-ledger.json',
    'batch-collection-summary.json',
  ];
  if (!caseDir || requiredFiles.some((name) => !coreBetaBatchEvidenceFilePresent(path.join(caseDir, name)))) {
    return `框架发布门禁 ${id} 拒绝缺失的不可变批量证据文件：${requiredFiles.join(',')}。`;
  }
  return '';
}

export function caseRequiresModelTier(testCase) {
  return !/^BETA-INIT-00[1-4]$/.test(String(testCase?.id || '').trim().toUpperCase());
}

function normalizeProductionRiskDomain(value) {
  const aliases = new Map([
    ['功能', 'functional'], ['安全', 'security_privacy'], ['安全隐私', 'security_privacy'],
    ['可靠性', 'reliability_recovery'], ['稳定性', 'reliability_recovery'], ['恢复', 'reliability_recovery'],
    ['性能', 'performance_capacity'], ['容量', 'performance_capacity'], ['兼容', 'compatibility_upgrade'],
    ['升级', 'compatibility_upgrade'], ['数据', 'data_integrity_isolation'], ['隔离', 'data_integrity_isolation'],
    ['外链', 'external_navigation'], ['webview', 'external_navigation'], ['发布', 'release_rollback'], ['回滚', 'release_rollback'],
  ]);
  const normalized = String(value || '').trim().toLowerCase().replace(/[\s/-]+/g, '_');
  return aliases.get(normalized) || normalized;
}

export function validateProductionCasePlan(cases = [], {
  backendVersion = '',
  promptPolicyVersion = '',
  featureFlagsHash = '',
} = {}) {
  const errors = [];
  const warnings = [];
  if (!cases.length) errors.push('生产门禁 Case 集为空。');
  const ids = cases.map((item) => String(item.id || '').trim()).filter(Boolean);
  if (ids.length !== cases.length || new Set(ids).size !== ids.length) errors.push('Case ID 为空或重复。');
  const qworkDailyRegression = isQworkDailyRegressionCasePlan(cases);
  const coveredDomains = new Set();
  const hardGateDomains = new Set();
  for (const testCase of cases) {
    const missing = PRODUCTION_CASE_METADATA_FIELDS.filter((field) => !String(testCase[field] || '').trim());
    if (missing.length) errors.push(`${testCase.id || 'unknown'} 缺少 ${missing.join(',')}`);
    const domains = String(testCase.risk_domain || '').split(/[,，;；|、\n]+/).map(normalizeProductionRiskDomain).filter(Boolean);
    domains.forEach((domain) => coveredDomains.add(domain));
    const isHardGate = /^(是|true|yes|p0|阻断上线)$/i.test(String(testCase.hard_gate || '').trim());
    if (isHardGate) {
      domains.forEach((domain) => hardGateDomains.add(domain));
    } else {
      warnings.push(`${testCase.id || 'unknown'} 未声明为硬门禁；该 Case 仍会执行，但不能承担风险域放行。`);
    }
    if (testCase.deterministic && !/^(是|否|true|false|yes|no|deterministic|stochastic)$/i.test(String(testCase.deterministic).trim())) {
      errors.push(`${testCase.id || 'unknown'} deterministic 必须明确为是/否。`);
    }
    if (testCase.repeat_policy && !/\d+/.test(String(testCase.repeat_policy))) {
      errors.push(`${testCase.id || 'unknown'} repeat_policy 必须包含明确执行次数。`);
    }
  }
  if (!qworkDailyRegression) {
    const missingDomains = PRODUCTION_REQUIRED_RISK_DOMAINS.filter((domain) => !coveredDomains.has(domain));
    if (missingDomains.length) errors.push(`缺少生产风险域 ${missingDomains.join(',')}`);
    const domainsWithoutHardGate = PRODUCTION_REQUIRED_RISK_DOMAINS.filter((domain) => !hardGateDomains.has(domain));
    if (domainsWithoutHardGate.length) errors.push(`以下生产风险域没有一票否决 Case：${domainsWithoutHardGate.join(',')}`);
  }
  if (!String(backendVersion || '').trim()) errors.push('缺少 backend version。');
  if (!String(promptPolicyVersion || '').trim()) errors.push('缺少 prompt/policy version。');
  if (!/^[a-f0-9]{64}$/i.test(String(featureFlagsHash || ''))) errors.push('feature flags hash 必须是 64 位 SHA-256。');
  return {
    schema_version: 1,
    generated_at: new Date().toISOString(),
    ok: errors.length === 0,
    case_count: cases.length,
    unique_case_ids: new Set(ids).size,
    covered_risk_domains: [...coveredDomains].sort(),
    hard_gate_risk_domains: [...hardGateDomains].sort(),
    required_risk_domains: PRODUCTION_REQUIRED_RISK_DOMAINS,
    gate_contract: qworkDailyRegression ? 'qwork-daily-regression/v1' : 'production-risk-gate/v1',
    production_risk_domain_coverage_required: !qworkDailyRegression,
    release_inputs: {
      backend_version: String(backendVersion || ''),
      prompt_policy_version: String(promptPolicyVersion || ''),
      feature_flags_hash: String(featureFlagsHash || ''),
    },
    errors,
    warnings,
  };
}

async function runParallelUiAgentCasebook({
  options,
  root,
  startedAt,
  casebook,
  outDir,
  progressFile,
  resultExcel,
  profile,
  modelTier,
  python,
  selectedCases,
  parallelism,
}) {
  let pool;
  let plan;
  try {
    const workerCdps = parseWorkerCdpUrls(options['worker-cdps']);
    pool = validateParallelWorkerPool({ workerCdps, parallelism });
    const duplicateIds = [...new Set(selectedCases
      .map((testCase) => String(testCase.id || ''))
      .filter((id, index, values) => id && values.indexOf(id) !== index))];
    if (duplicateIds.length) {
      throw new Error(`并行执行要求用例 ID 唯一，当前重复：${duplicateIds.join(', ')}`);
    }
    plan = buildCaseExecutionPlan(selectedCases, options);
  } catch (error) {
    const reason = `并行调度前置阻塞：${error.message}`;
    const results = selectedCases.map((testCase, index) => buildSyntheticResult({
      outDir,
      testCase,
      index,
      status: 'blocked',
      resultCategory: 'automation_error',
      reason,
    }));
    const summary = buildSummary({
      status: 'blocked',
      startedAt,
      outDir,
      casebook,
      resultExcel,
      profile,
      cdpUrl: '',
      modelTier,
      results,
      reason,
      precheck: {
        parallel_scheduler: {
          status: 'blocked',
          requested_parallelism: parallelism,
          supplied_workers: String(options['worker-cdps'] || '').split(/[,，\s]+/).filter(Boolean).length,
          reason,
        },
      },
    });
    writeRunArtifacts(outDir, summary);
    await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
    return summary;
  }

  ensureDir(path.join(outDir, 'case-runs'));
  const resultsByIndex = new Map();
  let progressWrite = Promise.resolve();
  const scheduling = {
    mode: 'multi-cdp',
    parallelism: pool.parallelism,
    workers: pool.workers,
    parallel_cases: plan.parallel.map((entry) => entry.testCase.id),
    shared_state_serial_cases: plan.shared_state_serial.map((entry) => entry.testCase.id),
    restart_serial_cases: plan.restart_serial.map((entry) => entry.testCase.id),
    phase_order: ['parallel', 'shared_state_serial', 'restart_serial'],
  };

  await executeCaseExecutionPlan({
    plan,
    workers: pool.workers,
    parallelism: pool.parallelism,
    execute: async ({ testCase, index, worker, workerIndex, phase }) => {
      const childOut = path.join(
        outDir,
        'case-runs',
        `${String(index + 1).padStart(3, '0')}-${testCase.id}-${slugify(testCase.scenario)}-worker-${String(workerIndex + 1).padStart(2, '0')}`,
      );
      const childOptions = {
        ...options,
        case: testCase.id,
        cdp: worker,
        out: childOut,
        'parallel-child': true,
      };
      for (const key of ['worker-cdps', 'parallel', 'offset', 'limit', 'resume']) delete childOptions[key];
      try {
        const childSummary = await runUiAgentCasebookCommand({ options: childOptions, root });
        const result = (childSummary.results || []).find((candidate) => (
          candidate.id === testCase.id
          && String(candidate.sheet || '') === String(testCase.sheet || '')
          && String(candidate.row_number || '') === String(testCase.row_number || '')
        )) || childSummary.results?.[0];
        if (!result) {
          return buildSyntheticResult({
            outDir: childOut,
            testCase,
            index,
            status: 'blocked',
            resultCategory: 'automation_error',
            reason: `并行 worker ${workerIndex + 1} 未返回 ${testCase.id} 的执行结果。`,
          });
        }
        return {
          ...result,
          order: index + 1,
          execution_lane: phase,
          worker_index: workerIndex + 1,
          worker_cdp: worker,
          child_run_dir: childSummary.out_dir || childOut,
        };
      } catch (error) {
        return {
          ...buildSyntheticResult({
            outDir: childOut,
            testCase,
            index,
            status: 'blocked',
            resultCategory: 'automation_error',
            reason: `并行 worker ${workerIndex + 1} 执行异常：${error.message}`,
          }),
          order: index + 1,
          execution_lane: phase,
          worker_index: workerIndex + 1,
          worker_cdp: worker,
          child_run_dir: childOut,
        };
      }
    },
    onResult: async ({ index, result }) => {
      resultsByIndex.set(index, result);
      progressWrite = progressWrite.then(() => {
        const observedResults = [...resultsByIndex.entries()]
          .sort(([left], [right]) => left - right)
          .map(([, value]) => value);
        const partition = partitionCasebookResults(observedResults);
        const completedResults = partition.completed;
        writeJsonFile(progressFile, {
          updated_at: new Date().toISOString(),
          completed: completedResults.length,
          total: selectedCases.length,
          result_accounting: {
            observed: observedResults.length,
            completed: completedResults.length,
            synthetic_diagnostics: partition.syntheticDiagnostics.length,
          },
          non_executed_diagnostics: partition.syntheticDiagnostics.map((diagnostic) => ({
            id: diagnostic?.id || '',
            status: diagnostic?.status || 'blocked',
            result_category: diagnostic?.result_category || 'blocked',
            reason: diagnostic?.actual_result || diagnostic?.conclusion || '',
            case_report: diagnostic?.case_report || '',
          })),
          parallel_scheduler: scheduling,
          results: completedResults,
        });
      });
      await progressWrite;
    },
  });
  await progressWrite;

  const results = [...resultsByIndex.entries()]
    .sort(([left], [right]) => left - right)
    .map(([, value]) => value);
  const summary = buildSummary({
    status: statusFromResults(results),
    startedAt,
    outDir,
    casebook,
    resultExcel,
    profile,
    cdpUrl: pool.workers.join(','),
    modelTier,
    results,
    precheck: { parallel_scheduler: { status: 'ready', ...scheduling } },
    expectedTotal: selectedCases.length,
  });
  summary.parallel_scheduler = scheduling;
  writeRunArtifacts(outDir, summary);
  await writeResultExcel({ python, root, casebook, outDir, summary, resultExcel });
  return summary;
}

function loadResumeProgress(progressFile, selectedCases, enabled) {
  if (!enabled || !fs.existsSync(progressFile)) return { results: [], startIndex: 0 };
  try {
    const progress = JSON.parse(fs.readFileSync(progressFile, 'utf8'));
    const existing = Array.isArray(progress.results) ? progress.results : [];
    const aligned = existing.every((result, index) => {
      const expected = selectedCases[index];
      return expected
        && result?.id === expected.id
        && String(result?.sheet || '') === String(expected.sheet || '')
        && String(result?.row_number || '') === String(expected.row_number || '');
    });
    if (!aligned) return { results: [], startIndex: 0 };
    return { results: existing, startIndex: Math.min(existing.length, selectedCases.length) };
  } catch {
    return { results: [], startIndex: 0 };
  }
}

function isLiveCdpPage(browser, page) {
  if (!browser || !page) return false;
  if (typeof browser.isConnected === 'function' && !browser.isConnected()) return false;
  if (typeof page.isClosed === 'function' && page.isClosed()) return false;
  return true;
}

export function stopRemainderWithoutSynthetic({
  outDir,
  selectedCases,
  startIndex,
  results,
  progressFile,
  status,
  resultCategory,
  reason,
  failedResult = null,
}) {
  const diagnosticFile = path.join(outDir, 'framework-stop-diagnostic.json');
  const diagnostic = {
    schema_version: 'qbot-core-beta-framework-stop/v1',
    generated_at: new Date().toISOString(),
    status,
    result_category: resultCategory,
    reason,
    completed: results.length,
    total: selectedCases.length,
    stopped_at_index: startIndex,
    stopped_case_id: String(failedResult?.id || selectedCases[startIndex]?.id || ''),
    failed_result: failedResult || null,
    unexecuted_case_ids: selectedCases.slice(startIndex + (failedResult ? 1 : 0)).map((item) => item.id),
  };
  writeJsonFile(diagnosticFile, diagnostic);
  writeJsonFile(progressFile, {
    updated_at: new Date().toISOString(),
    completed: results.length,
    total: selectedCases.length,
    stopped: true,
    synthetic: false,
    stop_reason: reason,
    current_case: diagnostic.stopped_case_id,
    framework_stop_diagnostic: diagnosticFile,
    results,
  });
  return diagnostic;
}

function isCdpDisconnectedResult(result) {
  const text = `${result?.actual_result || ''}\n${result?.conclusion || ''}`;
  return result?.result_category === 'automation_error' && isCdpDisconnectedMessage(text);
}

function resolveCasebook(root, explicit) {
  if (explicit) return path.resolve(explicit);
  const prd = path.join(root, 'PRD');
  const preferred = path.join(prd, 'Qbot_自动化可执行测试用例_精确执行版_2026-07-03.xlsx');
  if (fs.existsSync(preferred)) return preferred;
  const precise = fs.existsSync(prd)
    ? fs.readdirSync(prd)
      .filter((name) => /精确执行版.*\.xlsx$/i.test(name))
      .sort()
      .reverse()
    : [];
  if (precise.length) return path.join(prd, precise[0]);
  return path.join(prd, 'Qbot_TestCase.xlsx');
}

function timestampMinute(date = new Date()) {
  const pad = (value) => String(value).padStart(2, '0');
  return `${date.getFullYear()}${pad(date.getMonth() + 1)}${pad(date.getDate())}${pad(date.getHours())}${pad(date.getMinutes())}`;
}

function createRunDir(root, baseName) {
  ensureDir(root);
  let candidate = path.join(root, baseName);
  if (!fs.existsSync(candidate)) return candidate;
  for (let i = 1; i < 100; i += 1) {
    candidate = path.join(root, `${baseName}-${String(i).padStart(2, '0')}`);
    if (!fs.existsSync(candidate)) return candidate;
  }
  return path.join(root, `${baseName}-${Date.now()}`);
}

function inferQbotExternalLogFile(outDir) {
  const logsDir = path.join(outDir, 'logs');
  const candidates = [
    path.join(logsDir, 'electron-clean.log'),
    path.join(logsDir, 'electron.log'),
    path.join(logsDir, 'qbot-electron.log'),
  ];
  return candidates.find((file) => fs.existsSync(file)) || '';
}

function runPython({ python, args, cwd }) {
  const result = spawnSync(python, args, { cwd, encoding: 'utf8', maxBuffer: 1000 * 1000 * 80 });
  return {
    status: result.status,
    stdout: result.stdout,
    stderr: result.stderr,
    error: result.error?.message || '',
  };
}

function isAuthWorkflowCase(testCase) {
  const id = String(testCase?.id || '');
  const module = String(testCase?.module || '');
  const sheet = String(testCase?.sheet || '');
  const kind = String(testCase?.kind || '');
  return kind === 'auth' || /^SIT-AUTH-/i.test(id) || /登录鉴权|认证|auth/i.test(`${module}\n${sheet}`);
}

async function isLoginRequiredNow(page) {
  const loginVisible = await page.locator('[data-testid="auth-login"]').first().isVisible({ timeout: 500 }).catch(() => false);
  if (loginVisible) return true;
  const text = await bodyText(page).catch(() => '');
  return /登录工作台|OAuth2 登录|使用 Lingxi|使用 Mock OAuth2 登录/.test(text);
}

async function restoreAuthFromSessionSeed({ page, state, options, caseDir }) {
  const seedFile = String(options['auth-session-file'] || process.env.QBOT_AUTH_SESSION_FILE || '').trim();
  const qbotHome = String(options['qbot-home'] || process.env.QBOT_TEST_DEEPBANK_HOME || process.env.DEEPBANK_HOME || '').trim();
  if (!seedFile || !qbotHome) {
    return {
      ok: false,
      status: 'blocked',
      reason: '未配置 --auth-session-file 与 --qbot-home，无法通过 dev session seed 恢复登录态。',
    };
  }
  const source = path.resolve(seedFile);
  const target = path.join(path.resolve(qbotHome), 'auth', 'desktop-session.json');
  if (!fs.existsSync(source)) {
    return {
      ok: false,
      status: 'blocked',
      reason: `dev session seed 文件不存在：${source}`,
    };
  }
  try {
    ensureDir(path.dirname(target));
    fs.copyFileSync(source, target);
    fs.chmodSync(target, 0o600);
    recordStep(state, '注入 dev 登录态', '自动化前置可使用既有 dev session seed 恢复登录，但不能污染源文件。', `已复制 dev session seed 到本轮临时 HOME：${target}`, 'passed');
    await page.reload({ waitUntil: 'domcontentloaded', timeout: 30000 }).catch(() => {});
    await page.waitForTimeout(2500);
    const workbench = await waitForQbotWorkbench(page, 15000);
    const screenshot = await shot(page, caseDir, '02-session-seed-restore');
    state.screenshots.session_seed_restore = screenshot;
    return {
      ok: workbench.ok,
      status: workbench.ok ? 'passed' : 'blocked',
      reason: workbench.ok ? workbench.reason : `dev session seed 注入后仍未进入工作台：${workbench.reason}`,
      screenshot,
    };
  } catch (error) {
    return {
      ok: false,
      status: 'blocked',
      reason: `dev session seed 恢复失败：${error.message}`,
    };
  }
}

async function inspectModelTierAvailability(page, modelTier) {
  return page.evaluate(async (requestedTier) => {
    const tier = String(requestedTier || '').toUpperCase();
    const bridge = window.__qbotE2E || window.__deepbankE2E;
    const getConnectionView = async () => {
      const candidates = [];
      if (window.agent?.getConnections) {
        try {
          candidates.push({ source: 'agent.getConnections', view: await window.agent.getConnections() });
        } catch (error) {
          candidates.push({ source: 'agent.getConnections', error: error?.message || String(error) });
        }
      }
      if (bridge?.getConnectionView) {
        try {
          candidates.push({ source: 'e2e.getConnectionView', view: await bridge.getConnectionView() });
        } catch (error) {
          candidates.push({ source: 'e2e.getConnectionView', error: error?.message || String(error) });
        }
      }
      const usable = candidates
        .filter((candidate) => Array.isArray(candidate.view?.runtimeOptions?.options))
        .sort((left, right) => right.view.runtimeOptions.options.length - left.view.runtimeOptions.options.length);
      return {
        ...(usable[0]?.view || candidates.find((candidate) => candidate.view)?.view || null),
        __connectionViewSource: usable[0]?.source || candidates.find((candidate) => candidate.view)?.source || '',
        __connectionViewCandidates: candidates.map((candidate) => ({
          source: candidate.source,
          options_count: Array.isArray(candidate.view?.runtimeOptions?.options) ? candidate.view.runtimeOptions.options.length : 0,
          authenticated: candidate.view?.authenticated ?? candidate.view?.auth?.authenticated ?? null,
          error: candidate.error || '',
        })),
      };
    };
    const view = await getConnectionView();
    const options = Array.isArray(view?.runtimeOptions?.options) ? view.runtimeOptions.options : [];
    const matches = options.filter((option) => String(option?.complianceTier || '').toUpperCase() === tier);
    const selectable = matches.find((option) => !option?.disabled);
    return {
      requested: tier,
      status: selectable ? 'available' : 'unavailable',
      reason: selectable
        ? `找到可用 ${tier} 模型连接：${selectable.connectionLabel || selectable.connectionId}/${selectable.modelLabel || selectable.modelId}`
        : `未找到可用 ${tier} 模型连接；匹配数=${matches.length}；可选档位=${[...new Set(options.map((option) => String(option?.complianceTier || 'unknown').toUpperCase()))].join(', ') || 'none'}`,
      selected: view?.runtimeOptions?.selected || null,
      runtime_family: view?.runtimeOptions?.runtimeFamily || null,
      options_count: options.length,
      matching_count: matches.length,
      connection_view_source: view?.__connectionViewSource || '',
      connection_view_candidates: view?.__connectionViewCandidates || [],
    };
  }, modelTier).catch((error) => ({
    requested: modelTier,
    status: 'error',
    reason: `读取模型连接失败：${error.message}`,
  }));
}

async function ensureModelTier(page, state, caseDir, modelTier, { captureScreenshot = true } = {}) {
  const requestedTier = String(modelTier || '').trim().toUpperCase();
  if (!requestedTier) return { ok: true, status: 'skipped', reason: '未请求固定模型档位。' };
  const result = await page.evaluate(async (tier) => {
    const bridge = window.__qbotE2E || window.__deepbankE2E;
    const getConnectionView = async () => {
      const candidates = [];
      if (window.agent?.getConnections) {
        try {
          candidates.push({ source: 'agent.getConnections', view: await window.agent.getConnections() });
        } catch (error) {
          candidates.push({ source: 'agent.getConnections', error: error?.message || String(error) });
        }
      }
      if (bridge?.getConnectionView) {
        try {
          candidates.push({ source: 'e2e.getConnectionView', view: await bridge.getConnectionView() });
        } catch (error) {
          candidates.push({ source: 'e2e.getConnectionView', error: error?.message || String(error) });
        }
      }
      const usable = candidates
        .filter((candidate) => Array.isArray(candidate.view?.runtimeOptions?.options))
        .sort((left, right) => right.view.runtimeOptions.options.length - left.view.runtimeOptions.options.length);
      return {
        ...(usable[0]?.view || candidates.find((candidate) => candidate.view)?.view || null),
        __connectionViewSource: usable[0]?.source || candidates.find((candidate) => candidate.view)?.source || '',
        __connectionViewCandidates: candidates.map((candidate) => ({
          source: candidate.source,
          options_count: Array.isArray(candidate.view?.runtimeOptions?.options) ? candidate.view.runtimeOptions.options.length : 0,
          authenticated: candidate.view?.authenticated ?? candidate.view?.auth?.authenticated ?? null,
          error: candidate.error || '',
        })),
      };
    };
    const setConnection = async (selection) => {
      if (window.agent?.setConnection) return window.agent.setConnection(selection);
      if (bridge?.setConnection) return bridge.setConnection(selection);
      throw new Error('setConnection unavailable');
    };
    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const sameSelection = (selected, selection) => String(selected?.connectionId || '') === String(selection?.connectionId || '')
      && String(selected?.modelId || '') === String(selection?.modelId || '');
    const selectedTier = (selected) => String(selected?.complianceTier || '').toUpperCase();
    const before = await getConnectionView();
    if (!before?.runtimeOptions) {
      return {
        ok: false,
        status: 'blocked',
        reason: '当前页面未暴露 runtimeOptions，无法切换模型档位。',
        before: before || null,
      };
    }
    const options = Array.isArray(before.runtimeOptions.options) ? before.runtimeOptions.options : [];
    const selectedBefore = before.runtimeOptions.selected || null;
    const currentTier = selectedTier(selectedBefore);
    let target = options.find((option) => String(option?.complianceTier || '').toUpperCase() === tier && !option?.disabled);
    if (!target && currentTier === tier && selectedBefore?.connectionId && selectedBefore?.modelId) {
      target = {
        ...selectedBefore,
        runtimeFamily: selectedBefore.runtimeFamily || before.runtimeOptions.runtimeFamily,
      };
    }
    if (!target) {
      return {
        ok: false,
        status: 'blocked',
        reason: `未找到可用 ${tier} 模型连接；可选档位=${[...new Set(options.map((option) => String(option?.complianceTier || 'unknown').toUpperCase()))].join(', ') || 'none'}`,
        before,
        options_count: options.length,
      };
    }
    const selection = {
      source: target.source || selectedBefore?.source || 'platform',
      connectionId: target.connectionId,
      modelId: target.modelId,
      runtimeFamily: target.runtimeFamily || before.runtimeOptions.runtimeFamily || selectedBefore?.runtimeFamily,
    };
    if (currentTier === tier && sameSelection(selectedBefore, selection)) {
      return {
        ok: true,
        status: 'passed',
        reason: `当前已选中 ${tier}：${selectedBefore?.connectionLabel || target.connectionLabel || selection.connectionId}/${selectedBefore?.modelLabel || target.modelLabel || selection.modelId}`,
        requested: tier,
        selection,
        before_selected: selectedBefore,
        after_selected: selectedBefore,
        after_runtime_family: before.runtimeOptions.runtimeFamily || null,
        connection_view_source: before?.__connectionViewSource || '',
        connection_view_candidates: before?.__connectionViewCandidates || [],
      };
    }
    await setConnection(selection);
    const attempts = [];
    let after = null;
    let selectedAfter = null;
    let afterTier = '';
    let ok = false;
    for (let index = 0; index < 6; index += 1) {
      await sleep(index === 0 ? 250 : 750);
      after = await getConnectionView();
      selectedAfter = after?.runtimeOptions?.selected || null;
      afterTier = selectedTier(selectedAfter);
      ok = afterTier === tier && sameSelection(selectedAfter, selection);
      attempts.push({
        index: index + 1,
        complianceTier: afterTier || 'unknown',
        connectionId: selectedAfter?.connectionId || '',
        modelId: selectedAfter?.modelId || '',
      });
      if (ok) break;
    }
    return {
      ok,
      status: ok ? 'passed' : 'blocked',
      reason: ok
        ? `已切换到 ${tier}：${selectedAfter?.connectionLabel || target.connectionLabel || selection.connectionId}/${selectedAfter?.modelLabel || target.modelLabel || selection.modelId}`
        : `调用 setConnection 后未确认选中 ${tier}；当前档位=${afterTier || 'unknown'}；读回次数=${attempts.length}`,
      requested: tier,
      selection,
      before_selected: selectedBefore,
      after_selected: selectedAfter,
      readback_attempts: attempts,
      after_runtime_family: after?.runtimeOptions?.runtimeFamily || null,
      connection_view_source: before?.__connectionViewSource || '',
      connection_view_candidates: before?.__connectionViewCandidates || [],
    };
  }, requestedTier).catch((error) => ({
    ok: false,
    status: 'blocked',
    requested: requestedTier,
    reason: `切换模型档位失败：${error.message}`,
  }));
  state.artifacts.model_tier = result;
  const screenshot = captureScreenshot
    ? await shot(page, caseDir, `model-tier-${slugify(requestedTier)}-selected`).catch(() => '')
    : '';
  if (screenshot) state.screenshots[`model_tier_${slugify(requestedTier)}`] = screenshot;
  recordStep(
    state,
    `切换模型档位：${requestedTier}`,
    `每条 case 开始前必须选中 ${requestedTier}，并保存模型档位证据。`,
    result.reason || JSON.stringify(result),
    result.ok ? 'passed' : 'blocked',
    screenshot,
  );
  return result;
}

