async function dismissCoreBetaV2RuntimeUpdateObstruction(page, state = null) {
  const dedicatedToast = page.locator('[data-testid="runtime-update-ready-toast"]').filter({
    hasText: /新版本(?:已就绪|可用|可以更新)|发现新版本/i,
  }).first();
  let toast = null;
  let text = '';
  let skip = null;
  let buttonText = '';
  if (await visible(dedicatedToast, 500)) {
    toast = dedicatedToast;
    text = await toast.innerText({ timeout: 1000 }).catch(() => '');
    skip = toast.locator('button, [role="button"]').filter({
      hasText: /^(?:稍后|跳过(?:更新)?|暂不更新|以后再说)$/,
    }).first();
    buttonText = await skip.innerText({ timeout: 1000 }).catch(() => '');
  } else {
    const statuses = page.locator('[role="status"]').filter({
      hasText: /新版本(?:已就绪|可用|可以更新)|发现新版本/i,
    });
    const count = Math.min(await statuses.count(), 20);
    for (let index = 0; index < count; index += 1) {
      const candidate = statuses.nth(index);
      if (!(await visible(candidate, 100))) continue;
      const candidateText = await candidate.innerText({ timeout: 1000 }).catch(() => '');
      const candidateSkip = candidate.locator('button, [role="button"]').filter({
        hasText: /^(?:稍后|跳过(?:更新)?|暂不更新|以后再说)$/,
      }).first();
      const candidateButtonText = await candidateSkip.innerText({ timeout: 1000 }).catch(() => '');
      if (!coreBetaV2RuntimeUpdateSkipAction(candidateText, candidateButtonText)) continue;
      toast = candidate;
      text = candidateText;
      skip = candidateSkip;
      buttonText = candidateButtonText;
      break;
    }
  }
  if (!toast) {
    return { observed: false, ok: true, dismissed: false, text: '', button_text: '' };
  }

  const safeAction = coreBetaV2RuntimeUpdateSkipAction(text, buttonText);
  const count = state
    ? (state._runtimeUpdateSkipCount = Number(state._runtimeUpdateSkipCount || 0) + 1)
    : 1;
  const base = `runtime-update-prompt-skip-${String(count).padStart(2, '0')}`;
  const beforeScreenshot = state?.case_dir
    ? await shot(page, state.case_dir, `${base}-before`).catch(() => '')
    : '';
  let clickError = '';
  let clicked = false;
  if (safeAction && (!state?.case_dir || beforeScreenshot)) {
    try {
      await skip.click({ timeout: 5000 });
      clicked = true;
    } catch (error) {
      clickError = clip(error?.message || error, 320);
    }
  }
  const hidden = clicked
    ? await toast.waitFor({ state: 'hidden', timeout: 5000 }).then(() => true).catch(() => false)
    : false;
  const afterScreenshot = hidden && state?.case_dir
    ? await shot(page, state.case_dir, `${base}-after`).catch(() => '')
    : '';
  const evidenceComplete = !state?.case_dir || Boolean(beforeScreenshot && afterScreenshot);
  const valid = safeAction && clicked && hidden && evidenceComplete;
  const reason = !safeAction
    ? `更新提示没有精确安全的“稍后/跳过更新”动作：prompt=${clip(text, 180)}；button=${clip(buttonText, 80) || '未找到'}`
    : !beforeScreenshot && state?.case_dir
      ? '点击“稍后”前无法保存更新提示截图，拒绝无证据操作。'
      : clickError
        ? `更新提示“稍后”点击失败：${clickError}`
        : !hidden
          ? '点击“稍后”后更新提示仍可见。'
          : !afterScreenshot && state?.case_dir
            ? '更新提示消失后无法保存页面截图。'
            : '';
  let ledger = '';
  if (state?.case_dir) {
    ledger = path.join(state.case_dir, `${base}.json`);
    writeJsonFile(ledger, {
      schema_version: 'qbot-core-beta-runtime-update-prompt-skip/v1',
      captured_at: new Date().toISOString(),
      valid,
      prompt_text: text,
      safe_action: safeAction,
      button_text: buttonText,
      clicked,
      hidden_after_click: hidden,
      before_screenshot: beforeScreenshot,
      after_screenshot: afterScreenshot,
      error: reason,
    });
    state.screenshots[`${base}_before`] = beforeScreenshot;
    if (afterScreenshot) state.screenshots[`${base}_after`] = afterScreenshot;
    if (!Array.isArray(state.artifacts.runtime_update_prompt_skips)) {
      state.artifacts.runtime_update_prompt_skips = [];
    }
    state.artifacts.runtime_update_prompt_skips.push({
      valid,
      prompt_text: text,
      button_text: buttonText,
      clicked,
      hidden_after_click: hidden,
      before_screenshot: beforeScreenshot,
      after_screenshot: afterScreenshot,
      ledger,
      error: reason,
    });
    recordStep(
      state,
      '跳过遮挡操作区的 QWork 版本更新提示',
      '自动化批次必须保持冻结发布身份；只允许点击“稍后/跳过更新”，禁止在测试中安装新版本。',
      valid
        ? `已点击“${buttonText}”并确认提示消失：${clip(text, 180)}`
        : reason,
      valid ? 'passed' : 'failed',
      afterScreenshot || beforeScreenshot,
      valid ? '' : 'automation_error',
    );
  }
  return {
    observed: true,
    ok: valid,
    dismissed: valid,
    text,
    button_text: buttonText,
    before_screenshot: beforeScreenshot,
    after_screenshot: afterScreenshot,
    ledger,
    reason,
  };
}

async function dismissCoreBetaV2SettingsObstruction(page, state) {
  const workspaceCreation = await dismissCoreBetaV2WorkspaceCreationObstruction(page, state);
  if (!workspaceCreation.ok) return workspaceCreation;
  const expertCreation = await dismissCoreBetaV2ExpertCreationObstruction(page, state);
  if (!expertCreation.ok) return expertCreation;
  const runtimeUpdate = await dismissCoreBetaV2RuntimeUpdateObstruction(page, state);
  if (!runtimeUpdate.ok) return runtimeUpdate;
  const feedback = page.locator('[data-testid="skill-operation-feedback"]').first();
  if (!(await visible(feedback, 500))) {
    return {
      ok: true,
      dismissed: workspaceCreation.dismissed || expertCreation.dismissed || runtimeUpdate.dismissed,
      text: runtimeUpdate.text || expertCreation.text || workspaceCreation.text,
      workspace_creation: workspaceCreation,
      expert_creation: expertCreation,
      runtime_update: runtimeUpdate,
    };
  }
  const text = await feedback.innerText({ timeout: 1000 }).catch(() => '');
  const dismiss = feedback.locator('[aria-label="关闭操作提示"], .skill-operation-dismiss').first();
  if (!(await visible(dismiss, 800))) {
    const becameTerminal = await visible(dismiss, 30_000);
    if (!becameTerminal) {
      return {
        ok: false,
        dismissed: false,
        text,
        reason: `技能操作提示仍处于不可关闭状态，不能绕过遮挡点击设置：${clip(text, 220)}`,
      };
    }
  }
  try {
    await dismiss.click({ timeout: 5000 });
  } catch (error) {
    return {
      ok: false,
      dismissed: false,
      text,
      reason: `无法关闭遮挡设置入口的技能操作提示：${clip(error?.message || error, 220)}`,
    };
  }
  const closed = await feedback.waitFor({ state: 'hidden', timeout: 3000 })
    .then(() => true)
    .catch(() => false);
  if (state) {
    recordStep(
      state,
      '关闭遮挡设置入口的终态技能提示',
      '进入系统设置前必须关闭可安全关闭的上一轮终态提示，不能 force 点击被遮挡的入口。',
      closed ? `已关闭：${clip(text, 180)}` : `关闭后提示仍可见：${clip(text, 180)}`,
      closed ? 'passed' : 'failed',
      '',
      closed ? '' : 'automation_error',
    );
  }
  return {
    ok: closed,
    dismissed: closed || workspaceCreation.dismissed || expertCreation.dismissed || runtimeUpdate.dismissed,
    text,
    workspace_creation: workspaceCreation,
    expert_creation: expertCreation,
    runtime_update: runtimeUpdate,
    reason: closed ? '' : '关闭技能操作提示后仍检测到遮挡。',
  };
}

async function openCoreBetaV2SystemSettings(page, state) {
  const maintenance = page.locator('[data-testid="assistant-runtime-maintenance"]').first();
  if (await visible(maintenance, 800)) return { ok: true, reason: '运行时维护区已打开。' };
  const settingsSurface = page.locator('[data-testid="assistant-config-view"], [role="dialog"], .modal').filter({
    hasText: /系统设置|个人设置/,
  }).first();
  const waitForOpenSettingsMaintenance = async (
    timeoutMs = coreBetaV2SettingsLoadTimeoutMs(),
  ) => {
    if (!(await visible(settingsSurface, 500))) return { open: false, text: '', error: '' };
    const deadline = Date.now() + timeoutMs;
    let surfaceText = '';
    while (Date.now() < deadline) {
      if (await visible(maintenance, 500)) return { open: true, text: surfaceText, error: '' };
      surfaceText = await settingsSurface.innerText({ timeout: 700 }).catch(() => '');
      const surfaceState = coreBetaV2SettingsSurfaceState(surfaceText);
      if (surfaceState.error) return { open: true, text: surfaceText, error: surfaceState.error };
      await page.waitForTimeout(250);
    }
    surfaceText = await settingsSurface.innerText({ timeout: 700 }).catch(() => surfaceText);
    return {
      open: true,
      text: surfaceText,
      error: `系统设置已打开，但运行时维护区在 ${timeoutMs}ms 内未完成加载。`,
    };
  };
  const initialSettings = await waitForOpenSettingsMaintenance();
  if (initialSettings.error) {
    return { ok: false, reason: `${initialSettings.error} 页面=${clip(initialSettings.text, 300)}` };
  }
  if (await visible(maintenance, 800)) return { ok: true, reason: '已打开的系统设置完成加载。' };
  const obstruction = await dismissCoreBetaV2SettingsObstruction(page, state);
  if (!obstruction.ok) return { ok: false, reason: obstruction.reason };
  await ensureSidebarExpanded(page, state);
  const menu = page.locator('[data-testid="nav-settings-menu"]').first();
  if (!(await visible(menu, 2500))) return { ok: false, reason: '未找到设置菜单。' };
  try {
    await menu.scrollIntoViewIfNeeded({ timeout: 2500 });
    await menu.click({ timeout: 5000 });
  } catch (error) {
    return { ok: false, reason: `设置入口无法按真实可命中状态点击：${clip(error?.message || error, 260)}` };
  }
  if (!(await visible(maintenance, 1200))) {
    const directlyOpened = await waitForOpenSettingsMaintenance();
    if (directlyOpened.error) {
      return { ok: false, reason: `${directlyOpened.error} 页面=${clip(directlyOpened.text, 300)}` };
    }
    if (!(await visible(maintenance, 800))) {
      const settings = page.locator('[data-testid="nav-settings"]').first();
      if (!(await visible(settings, 2500))) {
        return { ok: false, reason: '设置菜单未展示个人设置入口，且系统设置维护区未直接打开。' };
      }
      try {
        await settings.click({ timeout: 5000 });
      } catch (error) {
        return { ok: false, reason: `个人设置子菜单无法按真实可命中状态点击：${clip(error?.message || error, 260)}` };
      }
      const selectedSettings = await waitForOpenSettingsMaintenance();
      if (selectedSettings.error) {
        return { ok: false, reason: `${selectedSettings.error} 页面=${clip(selectedSettings.text, 300)}` };
      }
    }
  }
  const ready = await visible(maintenance, 5000);
  return {
    ok: ready,
    reason: ready ? '已进入运行时维护区。' : '个人设置打开后未进入运行时维护区。',
  };
}

async function acceptCoreBetaV2MaintenanceConfirmation(page, action, {
  testId,
  state,
  caseDir,
  timeoutMs = 5000,
} = {}) {
  const contract = coreBetaV2MaintenanceConfirmationContract(testId);
  if (!contract) {
    await action();
    return { message: '', source: 'not-required', accepted: true, confirmation_label: '', screenshot: '' };
  }

  let nativeResult = null;
  const listener = async (dialog) => {
    const message = dialog.message();
    const expected = contract.prompt.test(message);
    nativeResult = {
      message,
      source: 'native-dialog',
      accepted: expected,
      confirmation_label: expected ? 'dialog.accept' : 'dialog.dismiss',
      screenshot: '',
    };
    if (expected) await dialog.accept().catch(() => dialog.dismiss().catch(() => {}));
    else await dialog.dismiss().catch(() => {});
  };
  page.once('dialog', listener);
  await action();
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (nativeResult) {
      page.off('dialog', listener);
      return nativeResult;
    }
    const dialogs = page.locator('[role="dialog"], .modal');
    const count = await dialogs.count().catch(() => 0);
    for (let index = count - 1; index >= 0; index -= 1) {
      const dialog = dialogs.nth(index);
      if (!(await visible(dialog, 200))) continue;
      const message = await dialog.innerText({ timeout: 600 }).catch(() => '');
      if (!contract.prompt.test(message)) continue;
      const controls = dialog.locator('button, [role="button"]');
      const controlCount = await controls.count().catch(() => 0);
      let confirmation = null;
      let confirmationLabel = '';
      for (let controlIndex = 0; controlIndex < controlCount; controlIndex += 1) {
        const candidate = controls.nth(controlIndex);
        if (!(await visible(candidate, 150))) continue;
        const label = String(await candidate.innerText({ timeout: 300 }).catch(() => '')).trim();
        if (!contract.confirm.test(label)) continue;
        confirmation = candidate;
        confirmationLabel = label;
        break;
      }
      const sequence = Number(state?._coreBetaV2MaintenanceConfirmationCount || 0) + 1;
      if (state) state._coreBetaV2MaintenanceConfirmationCount = sequence;
      const screenshot = caseDir
        ? await shot(page, caseDir, `maintenance-confirm-${String(sequence).padStart(2, '0')}-${slugify(testId)}`)
        : '';
      if (state && screenshot) {
        state.screenshots[`maintenance_confirmation_${String(sequence).padStart(2, '0')}`] = screenshot;
      }
      if (!confirmation) {
        page.off('dialog', listener);
        return {
          message,
          source: 'custom-dialog-missing-confirm',
          accepted: false,
          confirmation_label: '',
          screenshot,
        };
      }
      await confirmation.click({ force: true }).catch(async () => confirmation.evaluate((element) => element.click()));
      const closed = await dialog.waitFor({ state: 'hidden', timeout: 5000 }).then(() => true).catch(() => false);
      page.off('dialog', listener);
      return {
        message,
        source: 'custom-dialog',
        accepted: closed,
        confirmation_label: confirmationLabel,
        screenshot,
      };
    }
    await page.waitForTimeout(100).catch(() => {});
  }
  page.off('dialog', listener);
  return { message: '', source: 'none', accepted: false, confirmation_label: '', screenshot: '' };
}

async function clickCoreBetaV2MaintenanceAction({
  page,
  state,
  caseDir,
  testId,
  destructive,
  attempt = 1,
}) {
  const button = page.locator(`[data-testid="${testId}"]`).first();
  if (!(await visible(button, 3000))) return { ok: false, reason: `未找到维护按钮 ${testId}。` };
  const maintenance = page.locator('[data-testid="assistant-runtime-maintenance"]').first();
  const beforeText = await maintenance.innerText({ timeout: 1500 }).catch(() => '');
  // 清空会话的成功路径会在短暂完成回执后主动刷新 renderer。刷新可能早于
  // Playwright 对 busy/完成文案的下一次采样，因此必须在点击确认前订阅主框架
  // 导航，避免把真实成功误判成“无动作”。该信号只用于明确约定会刷新的 purge
  // 动作，并且外层仍强制要求匹配确认弹窗与连续稳定空会话终态。
  let navigationObserved = false;
  let navigationUrl = '';
  const mainFrame = page.mainFrame();
  const navigationListener = (frame) => {
    if (frame !== mainFrame) return;
    navigationObserved = true;
    navigationUrl = frame.url();
  };
  if (testId === 'assistant-sessions-purge') page.on('framenavigated', navigationListener);
  const click = async () => button.click({ force: true }).catch(async () => button.evaluate((element) => element.click()));
  let confirmation;
  try {
    confirmation = destructive
      ? await acceptCoreBetaV2MaintenanceConfirmation(page, click, {
        testId,
        state,
        caseDir,
        timeoutMs: 5000,
      })
      : await acceptCoreBetaV2MaintenanceConfirmation(page, click, {
        testId: '',
        state,
        caseDir,
        timeoutMs: 0,
      });
  } catch (error) {
    if (testId === 'assistant-sessions-purge') page.off('framenavigated', navigationListener);
    throw error;
  }
  if (!confirmation.accepted) {
    if (testId === 'assistant-sessions-purge') page.off('framenavigated', navigationListener);
    return { ok: false, reason: `${testId} 未出现可验证的预期确认弹窗。`, confirmation };
  }
  const busyObserved = await page.waitForFunction(({ id }) => {
    const target = document.querySelector(`[data-testid="${id}"]`);
    const region = document.querySelector('[data-testid="assistant-runtime-maintenance"]');
    return Boolean(
      target?.getAttribute('aria-busy') === 'true'
      || target?.hasAttribute('disabled')
      || /检查中|重置中|重装中|清空中|处理中|准备中|正在|下载中|安装中/.test(
        `${target?.textContent || ''}\n${region?.textContent || ''}`,
      )
    );
  }, { id: testId }, { timeout: 8000 }).then(() => true).catch(() => false);
  const actionText = await maintenance.innerText({ timeout: 1500 }).catch(() => '');
  if (testId === 'assistant-sessions-purge') page.off('framenavigated', navigationListener);
  const actionObservation = coreBetaV2MaintenanceActionObservation({
    testId,
    busyObserved,
    navigationObserved,
    beforeText,
    actionText,
  });
  const attemptSuffix = Number(attempt) > 1 ? `-retry-${String(attempt).padStart(2, '0')}` : '';
  const busyScreenshot = await shot(page, caseDir, `${slugify(testId)}${attemptSuffix}-busy`).catch(() => '');
  if (busyScreenshot) {
    state.screenshots[`${testId.replaceAll('-', '_')}${attemptSuffix.replaceAll('-', '_')}_busy`] = busyScreenshot;
  }
  return {
    ok: true,
    testid: testId,
    before_text: clip(beforeText, 1600),
    action_text: clip(actionText, 1600),
    confirmation,
    busy_observed: busyObserved,
    navigation_observed: navigationObserved,
    navigation_url: navigationUrl,
    action_observed: actionObservation.observed,
    action_observation_source: actionObservation.source,
    completion_transition: actionObservation.completion_transition,
    busy_screenshot: busyScreenshot,
  };
}

export function coreBetaV2MaintenanceActionObservation({
  testId = '',
  busyObserved = false,
  navigationObserved = false,
  beforeText = '',
  actionText = '',
} = {}) {
  if (busyObserved === true) {
    return {
      observed: true,
      source: 'busy',
      completion_transition: '',
    };
  }
  if (String(testId || '') === 'assistant-sessions-purge' && navigationObserved === true) {
    return {
      observed: true,
      source: 'causal-main-frame-reload',
      completion_transition: '',
    };
  }
  const completionPatterns = {
    'assistant-prepare-python-runtimes': /(?:完成[：:][^。\n]*(?:Python\s*\d+\s*个就绪[^。\n]*Node\s*\d+\s*个就绪|运行时|runtime)|(?:就绪|无需更新|已是最新|同版本)[^。\n]*(?:运行时|runtime))/i,
    'assistant-runtime-reset-all': /完成[：:][^。\n]*(?:运行时|环境|重初始化)/i,
    'assistant-skills-reinstall': /完成[：:][^。\n]*技能运行环境已清理/i,
    'assistant-sessions-purge': /完成[：:][^。\n]*(?:会话|任务)[^。\n]*(?:清空|清理|删除)/i,
  };
  const pattern = completionPatterns[String(testId || '')];
  if (!pattern) {
    return {
      observed: false,
      source: 'none',
      completion_transition: '',
    };
  }
  const before = String(beforeText || '');
  const after = String(actionText || '');
  const match = after.match(pattern)?.[0] || '';
  const changed = Boolean(match) && !before.includes(match);
  return {
    observed: changed,
    source: changed ? 'explicit-completion-transition' : 'none',
    completion_transition: changed ? match : '',
  };
}

export function coreBetaV2MaintenanceActiveSessionRejection(text = '') {
  return /有会话正在运行[，,]?请先停止或等它结束再操作|active-session/i.test(String(text || ''));
}

export function coreBetaV2RunningSessionQuiescenceVerdict({
  inventoryReadable = false,
  cancelFailures = [],
  runningAfter = [],
  stableIdleObservations = 0,
  minimumIdleObservations = 3,
} = {}) {
  const failures = Array.isArray(cancelFailures) ? cancelFailures.filter(Boolean) : [];
  const remaining = Array.isArray(runningAfter) ? runningAfter.filter(Boolean) : [];
  const minimum = Math.max(1, Number(minimumIdleObservations) || 3);
  const stable = Math.max(0, Number(stableIdleObservations) || 0);
  const ok = inventoryReadable === true
    && failures.length === 0
    && remaining.length === 0
    && stable >= minimum;
  return {
    ok,
    inventory_readable: inventoryReadable === true,
    cancel_failures: failures,
    running_after: remaining,
    stable_idle_observations: stable,
    minimum_idle_observations: minimum,
    reason: ok
      ? `全部公开会话已连续 ${stable} 次读回 idle。`
      : inventoryReadable !== true
        ? '无法读取公开会话与运行态，禁止执行会话清空。'
        : failures.length > 0
          ? `停止运行会话失败：${failures.map((item) => item.session_id || item.error || 'unknown').join(',')}`
          : remaining.length > 0
            ? `仍有 ${remaining.length} 个会话处于运行态。`
            : `idle 稳定读回不足：${stable}/${minimum}。`,
  };
}

async function quiesceCoreBetaV2RunningSessions({
  page,
  state,
  caseDir,
  reason,
  attempt = 1,
  timeoutMs = 60_000,
}) {
  const startedAt = Date.now();
  const suffix = Number(attempt) > 1 ? `-retry-${String(attempt).padStart(2, '0')}` : '';
  const beforeScreenshot = await shot(page, caseDir, `sessions-purge-quiescence${suffix}-before`).catch(() => '');
  const initial = await page.evaluate(async () => {
    const withTimeout = async (promise, label) => await Promise.race([
      promise,
      new Promise((_, reject) => window.setTimeout(
        () => reject(new Error(`${label} timed out`)),
        5000,
      )),
    ]);
    try {
      const sessions = await withTimeout(window.agent?.listSessions?.(), 'listSessions');
      if (!Array.isArray(sessions)) return { readable: false, error: 'listSessions did not return an array', sessions: [] };
      const inspected = [];
      for (const session of sessions) {
        try {
          const running = await withTimeout(window.agent?.getRunning?.(session.id), `getRunning:${session.id}`);
          inspected.push({
            id: String(session.id || ''),
            title: String(session.title || ''),
            running: running?.running === true,
          });
        } catch (error) {
          inspected.push({
            id: String(session.id || ''),
            title: String(session.title || ''),
            running: null,
            error: String(error?.message || error),
          });
        }
      }
      return {
        readable: inspected.every((item) => typeof item.running === 'boolean'),
        error: '',
        sessions: inspected,
      };
    } catch (error) {
      return { readable: false, error: String(error?.message || error), sessions: [] };
    }
  }).catch((error) => ({ readable: false, error: String(error?.message || error), sessions: [] }));

  const runningBefore = initial.sessions.filter((item) => item.running === true);
  const cancellationAttempts = [];
  if (initial.readable) {
    for (const session of runningBefore) {
      const attempt = await page.evaluate(async (sessionId) => {
        try {
          await Promise.race([
            window.agent.cancel(sessionId),
            new Promise((_, reject) => window.setTimeout(
              () => reject(new Error('cancel timed out')),
              5000,
            )),
          ]);
          return { ok: true, error: '' };
        } catch (error) {
          return { ok: false, error: String(error?.message || error) };
        }
      }, session.id).catch((error) => ({ ok: false, error: String(error?.message || error) }));
      cancellationAttempts.push({
        session_id: session.id,
        title: session.title,
        ...attempt,
      });
    }
  }

  const observations = [];
  const minimumIdleObservations = 3;
  let stableIdleObservations = 0;
  let runningAfter = runningBefore;
  let inventoryReadable = initial.readable;
  const deadline = startedAt + Math.max(10_000, Number(timeoutMs) || 60_000);
  while (initial.readable && Date.now() < deadline && stableIdleObservations < minimumIdleObservations) {
    const observation = await page.evaluate(async () => {
      const withTimeout = async (promise, label) => await Promise.race([
        promise,
        new Promise((_, reject) => window.setTimeout(
          () => reject(new Error(`${label} timed out`)),
          5000,
        )),
      ]);
      try {
        const sessions = await withTimeout(window.agent?.listSessions?.(), 'listSessions');
        if (!Array.isArray(sessions)) return { readable: false, error: 'listSessions did not return an array', running: [] };
        const inspected = [];
        for (const session of sessions) {
          try {
            const result = await withTimeout(window.agent?.getRunning?.(session.id), `getRunning:${session.id}`);
            inspected.push({
              id: String(session.id || ''),
              title: String(session.title || ''),
              running: result?.running === true,
            });
          } catch (error) {
            inspected.push({
              id: String(session.id || ''),
              title: String(session.title || ''),
              running: null,
              error: String(error?.message || error),
            });
          }
        }
        const readable = inspected.every((item) => typeof item.running === 'boolean');
        return { readable, error: '', running: inspected.filter((item) => item.running === true) };
      } catch (error) {
        return { readable: false, error: String(error?.message || error), running: [] };
      }
    }).catch((error) => ({ readable: false, error: String(error?.message || error), running: [] }));
    inventoryReadable = observation.readable === true;
    runningAfter = observation.running;
    stableIdleObservations = inventoryReadable && runningAfter.length === 0
      ? stableIdleObservations + 1
      : 0;
    observations.push({
      captured_at: new Date().toISOString(),
      readable: inventoryReadable,
      error: observation.error || '',
      running: runningAfter,
      stable_idle_observations: stableIdleObservations,
    });
    if (!inventoryReadable) break;
    if (stableIdleObservations < minimumIdleObservations) await page.waitForTimeout(500);
  }

  const cancelFailures = cancellationAttempts.filter((item) => item.ok !== true);
  const verdict = coreBetaV2RunningSessionQuiescenceVerdict({
    inventoryReadable,
    cancelFailures,
    runningAfter,
    stableIdleObservations,
    minimumIdleObservations,
  });
  const afterScreenshot = await shot(page, caseDir, `sessions-purge-quiescence${suffix}-after`).catch(() => '');
  const evidenceValid = Boolean(beforeScreenshot && afterScreenshot);
  const valid = verdict.ok && evidenceValid;
  const file = path.join(caseDir, `sessions-purge-quiescence${suffix}.json`);
  writeJsonFile(file, {
    schema_version: 'qbot-core-beta-session-quiescence/v1',
    captured_at: new Date().toISOString(),
    valid,
    reason: String(reason || ''),
    elapsed_ms: Date.now() - startedAt,
    initial,
    running_before: runningBefore,
    cancellation_attempts: cancellationAttempts,
    observations,
    verdict,
    before_screenshot: beforeScreenshot,
    after_screenshot: afterScreenshot,
    evidence_valid: evidenceValid,
  });
  if (!Array.isArray(state.artifacts.sessions_purge_quiescence)) {
    state.artifacts.sessions_purge_quiescence = [];
  }
  state.artifacts.sessions_purge_quiescence.push(file);
  if (beforeScreenshot) state.screenshots[`sessions_purge_quiescence${suffix.replaceAll('-', '_')}_before`] = beforeScreenshot;
  if (afterScreenshot) state.screenshots[`sessions_purge_quiescence${suffix.replaceAll('-', '_')}_after`] = afterScreenshot;
  recordStep(
    state,
    '清空会话前停止并读回全部活动会话',
    '必须枚举公开会话，仅停止真实 running 会话，并连续 3 次读回全部 idle 后才能点击清空。',
    valid
      ? `${verdict.reason} runningBefore=${runningBefore.length}；cancelled=${cancellationAttempts.filter((item) => item.ok).length}`
      : `${verdict.reason}${evidenceValid ? '' : '；前后截图证据不完整'}`,
    valid ? 'passed' : 'failed',
    afterScreenshot || beforeScreenshot,
    valid ? '' : 'automation_error',
  );
  return { valid, file, verdict, running_before: runningBefore, cancellation_attempts: cancellationAttempts };
}

export function coreBetaV2RuntimeMaintenanceState({
  text = '',
  composerReady = false,
  workbenchReady = false,
  buttonEnabled = false,
  capabilitiesReadable = false,
  sdkStatuses = [],
  stableReadyObservations = 0,
  minimumReadyObservations = 2,
} = {}) {
  const normalized = String(text || '').replace(/\s+/g, ' ').trim();
  const statuses = Array.isArray(sdkStatuses) ? sdkStatuses : [];
  const families = new Set(statuses.map((item) => String(item?.family || '').toLowerCase()));
  const familiesPresent = families.has('codex') && [...families].some((family) => family.startsWith('claude'));
  const sdkReady = familiesPresent
    && statuses.every((item) => String(item?.phase || '').toLowerCase() === 'ready');
  const sdkFailed = statuses.some((item) => ['error', 'failed'].includes(String(item?.phase || '').toLowerCase()));
  const sdkPending = statuses.length === 0
    || statuses.some((item) => !['ready', 'error', 'failed'].includes(String(item?.phase || '').toLowerCase()));
  const visibleActivity = /检查中|初始化中|重置中|重装中|清空中|处理中|准备中|下载中|安装中|\b(?:pending|provisioning|installing|downloading)\b/i.test(normalized);
  const failed = sdkFailed || /失败|不可用|ENOTEMPTY|exception|runtime[^。\n]*(?:error|failed)/i.test(normalized);
  const loaded = /本进程已加载并校验|Claude Code SDK[^。；\n]*就绪|Codex SDK[^。；\n]*就绪|运行时[^。；\n]*(?:完成|就绪|ready)/i.test(normalized);
  const stable = Number(stableReadyObservations) >= Math.max(1, Number(minimumReadyObservations) || 1);
  const authoritativeReady = Boolean(
    normalized
    && loaded
    && composerReady
    && workbenchReady
    && buttonEnabled
    && capabilitiesReadable
    && sdkReady
    && !failed
  );
  const ready = Boolean(
    authoritativeReady
    && stable
    && !visibleActivity
  );
  return {
    ready,
    pending: visibleActivity || sdkPending || !buttonEnabled,
    failed,
    authoritative_ready: authoritativeReady,
    visible_activity: visibleActivity,
    loaded,
    sdk_ready: sdkReady,
    sdk_status_count: statuses.length,
    stable_ready_observations: Number(stableReadyObservations) || 0,
    minimum_ready_observations: Math.max(1, Number(minimumReadyObservations) || 1),
    button_enabled: Boolean(buttonEnabled),
    composer_ready: Boolean(composerReady),
    workbench_ready: Boolean(workbenchReady),
    capabilities_readable: Boolean(capabilitiesReadable),
    reason: ready
      ? '运行时维护区、Claude/Codex SDK、工作台、输入区与 capabilities 已连续稳定就绪。'
      : failed
        ? '运行时维护区或 SDK 状态出现明确失败终态。'
        : sdkPending
          ? 'Claude/Codex SDK 尚未全部达到 ready。'
          : !familiesPresent
            ? '缺少 Claude/Codex 两类 SDK 的完整状态读回。'
            : visibleActivity || !buttonEnabled
              ? '运行时维护动作仍在处理中。'
              : !loaded
                ? '尚未读到已加载并校验的运行时终态。'
                : !workbenchReady || !composerReady
                  ? '工作台或输入区尚未恢复。'
                  : !capabilitiesReadable
                    ? '公开 capabilities 尚不可读。'
                    : !stable
                      ? '就绪状态尚未达到连续稳定采样下限。'
                      : '运行时尚未达到稳定终态。',
  };
}

export function coreBetaV2MaintenanceProductStateConflict({
  maintenanceState = {},
  stableObservations = 0,
  elapsedMs = 0,
  minimumStableObservations = 3,
  minimumElapsedMs = 5000,
} = {}) {
  const stableRequired = Math.max(3, Number(minimumStableObservations) || 3);
  const elapsedRequired = Math.max(1000, Number(minimumElapsedMs) || 5000);
  const evidenceValid = Boolean(
    maintenanceState
    && typeof maintenanceState === 'object'
    && typeof maintenanceState.authoritative_ready === 'boolean'
    && typeof maintenanceState.visible_activity === 'boolean'
    && typeof maintenanceState.failed === 'boolean',
  );
  const confirmed = Boolean(
    evidenceValid
    && maintenanceState.authoritative_ready === true
    && maintenanceState?.visible_activity === true
    && maintenanceState?.failed !== true
    && Number(stableObservations) >= stableRequired
    && Number(elapsedMs) >= elapsedRequired,
  );
  return {
    confirmed,
    evidence_valid: evidenceValid,
    oracle_valid: !confirmed,
    stable_observations: Number(stableObservations) || 0,
    stable_required: stableRequired,
    elapsed_ms: Number(elapsedMs) || 0,
    minimum_elapsed_ms: elapsedRequired,
    reason: confirmed
      ? 'structured_runtime_ready_but_visible_maintenance_still_active'
      : 'visible_and_structured_runtime_state_not_yet_in_stable_conflict',
  };
}

async function reconnectCoreBetaV2Runtime({
  runtime,
  options,
  state,
  caseDir,
  timeoutMs = 120000,
  label = 'Core Beta v2 runtime maintenance',
}) {
  if (!runtime?.playwright?.chromium || !runtime?.cdpUrl) {
    return { ok: false, reason: 'runner 缺少可变 CDP runtime，无法接管 replacement renderer。' };
  }
  const startedAt = Date.now();
  const deadline = startedAt + Math.max(1000, Number(timeoutMs) || 120000);
  let lastError = '';
  while (Date.now() < deadline) {
    let nextBrowser = null;
    try {
      const reconnectHook = typeof options['restart-reconnect-hook'] === 'function'
        ? options['restart-reconnect-hook']
        : null;
      const reconnected = reconnectHook
        ? await reconnectHook({ runtime, options, state, caseDir, label })
        : null;
      nextBrowser = reconnected?.browser
        || await runtime.playwright.chromium.connectOverCDP(runtime.cdpUrl);
      const nextPage = reconnected?.page || await findQbotPage(nextBrowser);
      if (!nextPage) throw new Error('CDP 已恢复，但未找到 QWork 页面。');
      if (reconnected?.cdpUrl) runtime.cdpUrl = reconnected.cdpUrl;
      nextPage.setDefaultTimeout(12000);
      nextPage.setDefaultNavigationTimeout(30000);
      runtime.browser = nextBrowser;
      runtime.page = nextPage;
      state.artifacts.runtime_reconnects ||= [];
      state.artifacts.runtime_reconnects.push({
        label,
        elapsed_ms: Date.now() - startedAt,
        cdp_url: runtime.cdpUrl,
      });
      return { ok: true, browser: nextBrowser, page: nextPage };
    } catch (error) {
      lastError = error?.message || String(error);
      if (nextBrowser) await nextBrowser.close().catch(() => {});
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }
  }
  return { ok: false, reason: `未能在时限内重连 QWork：${clip(lastError, 320)}` };
}

async function resolveCoreBetaV2MaintenancePage({ page, runtime, options, state, caseDir, errorStreak }) {
  const candidates = [
    runtime?.page,
    page,
    ...(runtime?.browser?.contexts?.().flatMap((context) => context.pages()) || []),
  ].filter(Boolean);
  for (const candidate of candidates) {
    if (candidate.isClosed?.()) continue;
    const alive = await candidate.evaluate(() => Boolean(document?.documentElement)).then(() => true).catch(() => false);
    if (alive) {
      if (runtime) runtime.page = candidate;
      return { ok: true, page: candidate, reconnected: false };
    }
  }
  if (errorStreak < 3) return { ok: false, page, reconnected: false };
  const reconnected = await reconnectCoreBetaV2Runtime({
    runtime,
    options,
    state,
    caseDir,
    timeoutMs: Number(options['restart-reconnect-timeout-ms'] || 120000),
  });
  return reconnected.ok
    ? { ok: true, page: reconnected.page, reconnected: true }
    : { ok: false, page, reconnected: false, reason: reconnected.reason };
}

async function waitForCoreBetaV2MaintenanceTerminal({
  page,
  runtime,
  options,
  state,
  caseDir,
  testCase,
  maintenance,
  timeoutMs,
}) {
  const startedAt = Date.now();
  const deadline = startedAt + Math.max(30_000, Number(timeoutMs) || 0);
  const observations = [];
  let activePage = page;
  let stableReadyObservations = 0;
  let authoritativeReadyObservations = 0;
  let errorStreak = 0;
  let lastReadback = { ready: false, reason: '尚未开始终态采样。' };
  while (Date.now() < deadline) {
    const resolved = await resolveCoreBetaV2MaintenancePage({
      page: activePage,
      runtime,
      options,
      state,
      caseDir,
      errorStreak,
    });
    if (!resolved.ok) {
      errorStreak += 1;
      lastReadback = {
        ...lastReadback,
        ready: false,
        reason: resolved.reason || 'QWork renderer 暂时不可读，等待导航或 replacement renderer。',
      };
      await new Promise((resolve) => setTimeout(resolve, 1000));
      continue;
    }
    activePage = resolved.page;
    try {
      const body = await bodyText(activePage);
      const workbenchReady = /新建任务/.test(body) && /专家|连接器|知识/.test(body);
      const composerReady = await visible(
        activePage.locator('[data-testid="composer-input"], .aui-composer-input').first(),
        800,
      );
      let maintenanceRegion = activePage.locator('[data-testid="assistant-runtime-maintenance"]').first();
      if (!(await visible(maintenanceRegion, 800))) {
        await openCoreBetaV2SystemSettings(activePage, state);
        maintenanceRegion = activePage.locator('[data-testid="assistant-runtime-maintenance"]').first();
      }
      const text = await maintenanceRegion.innerText({ timeout: 2000 }).catch(() => '');
      const button = activePage.locator(`[data-testid="${maintenance.testId}"]`).first();
      const buttonEnabled = await button.isEnabled({ timeout: 800 }).catch(() => false);
      const runtimeData = await activePage.evaluate(async () => {
        const withTimeout = async (promise, label) => await Promise.race([
          promise,
          new Promise((_, reject) => setTimeout(() => reject(new Error(`${label} timed out`)), 5000)),
        ]);
        let sdkStatuses = [];
        let capabilities = null;
        let sessions = null;
        try {
          sdkStatuses = typeof window.agent?.runtimeStatus === 'function'
            ? await withTimeout(window.agent.runtimeStatus(), 'runtimeStatus')
            : [];
        } catch (error) {
          sdkStatuses = [{ family: 'readback', phase: 'error', error: String(error?.message || error) }];
        }
        try {
          capabilities = typeof window.agent?.capabilities === 'function'
            ? await withTimeout(window.agent.capabilities(), 'capabilities')
            : null;
        } catch (error) {
          capabilities = { __error: String(error?.message || error) };
        }
        try {
          sessions = typeof window.agent?.listSessions === 'function'
            ? await withTimeout(window.agent.listSessions(), 'listSessions')
            : null;
        } catch (error) {
          sessions = { __error: String(error?.message || error) };
        }
        return { sdkStatuses, capabilities, sessions };
      });
      const capabilitiesReadable = Boolean(
        runtimeData.capabilities
        && typeof runtimeData.capabilities === 'object'
        && !runtimeData.capabilities.__error,
      );
      const elapsedMs = Date.now() - startedAt;
      const baseState = coreBetaV2RuntimeMaintenanceState({
        text,
        composerReady,
        workbenchReady,
        buttonEnabled,
        capabilitiesReadable,
        sdkStatuses: runtimeData.sdkStatuses,
        stableReadyObservations: 1,
        minimumReadyObservations: 1,
      });
      const activeSessionRejected = maintenance.terminal === 'sessions-empty'
        && coreBetaV2MaintenanceActiveSessionRejection(text);
      authoritativeReadyObservations = baseState.authoritative_ready
        ? authoritativeReadyObservations + 1
        : 0;
      const visibleStateConflict = coreBetaV2MaintenanceProductStateConflict({
        maintenanceState: baseState,
        stableObservations: authoritativeReadyObservations,
        elapsedMs,
      });
      const terminalState = activeSessionRejected
        ? {
          ...baseState,
          ready: false,
          pending: false,
          failed: true,
          active_session_rejected: true,
          reason: '全部公开会话已确认 idle 后，产品仍以 active-session 拒绝清空会话。',
        }
        : visibleStateConflict.confirmed
        ? {
          ...baseState,
          ready: false,
          pending: false,
          failed: true,
          product_ui_state_conflict: true,
          product_ui_state_conflict_evidence: visibleStateConflict,
          reason: '结构化 SDK、capabilities、工作台、输入区和按钮已连续稳定 ready，但可见维护区仍显示处理中。',
        }
        : baseState;
      const updateReady = maintenance.terminal === 'update'
        && elapsedMs >= 1000
        && buttonEnabled
        && capabilitiesReadable
        && !terminalState.pending
        && !terminalState.failed
        && /当前|完成|就绪|ready|已开始|远端|同版本|无需更新/i.test(text);
      const sessionsEmpty = maintenance.terminal === 'sessions-empty'
        && elapsedMs >= 1500
        && workbenchReady
        && capabilitiesReadable
        && Array.isArray(runtimeData.sessions)
        && runtimeData.sessions.length === 0;
      const runtimeReady = maintenance.terminal === 'runtime-ready'
        && elapsedMs >= 5000
        && terminalState.ready;
      const sampleReady = updateReady || sessionsEmpty || runtimeReady;
      stableReadyObservations = sampleReady ? stableReadyObservations + 1 : 0;
      const stableRequired = maintenance.terminal === 'update' ? 2 : 3;
      const stable = stableReadyObservations >= stableRequired;
      lastReadback = {
        ...terminalState,
        ready: stable,
        reason: stable
          ? maintenance.terminal === 'sessions-empty'
            ? '工作台已恢复，公开会话列表连续稳定为空。'
            : maintenance.terminal === 'update'
              ? '检查更新动作已收敛，维护按钮与公开 capabilities 连续稳定可用。'
              : '运行时维护区、SDK、工作台、输入区与 capabilities 连续稳定就绪。'
          : terminalState.failed
            ? terminalState.reason
            : `终态尚未达到连续 ${stableRequired} 次稳定采样：current=${stableReadyObservations}`,
        elapsed_ms: elapsedMs,
        terminal_kind: maintenance.terminal,
        stable_ready_observations: stableReadyObservations,
        authoritative_ready_observations: authoritativeReadyObservations,
        stable_required: stableRequired,
        maintenance_text: clip(text, 1800),
        sdk_statuses: runtimeData.sdkStatuses,
        capabilities: runtimeData.capabilities,
        sessions: runtimeData.sessions,
        reconnected: resolved.reconnected,
      };
      observations.push({
        captured_at: new Date().toISOString(),
        elapsed_ms: elapsedMs,
        ready: lastReadback.ready,
        pending: lastReadback.pending,
        failed: lastReadback.failed,
        stable_ready_observations: stableReadyObservations,
        authoritative_ready_observations: authoritativeReadyObservations,
        product_ui_state_conflict: lastReadback.product_ui_state_conflict === true,
        maintenance_text: clip(text, 500),
        sdk_statuses: runtimeData.sdkStatuses,
        session_count: Array.isArray(runtimeData.sessions) ? runtimeData.sessions.length : null,
      });
      if (observations.length > 60) observations.shift();
      errorStreak = 0;
      if (lastReadback.failed || stable) break;
    } catch (error) {
      errorStreak += 1;
      lastReadback = {
        ...lastReadback,
        ready: false,
        reason: `终态采样暂时失败：${clip(error?.message || String(error), 320)}`,
      };
    }
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  const screenshot = await shot(activePage, caseDir, `${slugify(maintenance.testId)}-terminal`).catch(() => '');
  if (screenshot) state.screenshots[`${maintenance.testId.replaceAll('-', '_')}_terminal`] = screenshot;
  const diagnosticFile = path.join(caseDir, `${slugify(maintenance.method)}-terminal-observations.json`);
  writeJsonFile(diagnosticFile, {
    case_id: testCase.id,
    method: maintenance.method,
    terminal_kind: maintenance.terminal,
    timeout_ms: timeoutMs,
    completed_at: new Date().toISOString(),
    final: lastReadback,
    observations,
  });
  state.artifacts.core_beta_runtime_maintenance_observations = diagnosticFile;
  return {
    ok: lastReadback.ready === true,
    page: activePage,
    readback: lastReadback,
    screenshot,
    observations_file: diagnosticFile,
  };
}

async function verifyCoreBetaInitializationContinuationSurface({ page, state, caseDir, testCase }) {
  const beforeScreenshot = await shot(page, caseDir, 'initialization-continuation-surface-before').catch(() => '');
  let error = '';
  try {
    await openNewTask(page, state);
  } catch (caught) {
    error = String(caught?.message || caught);
  }
  const composerReady = !error && await visible(
    page.locator('[data-testid="composer-input"], .aui-composer-input').first(),
    5000,
  );
  const body = await bodyText(page).catch(() => '');
  const workbenchReady = /新建任务/.test(body) && /专家|连接器|知识/.test(body);
  const cleanDraftState = !error
    ? await qbotE2EState(page)
    : { available: false, reason: 'open_new_task_failed' };
  const cleanDraftSurface = !error
    ? await draftSurfaceState(page)
    : { ok: false, reason: 'open_new_task_failed' };
  const cleanDraftIsolated = cleanDraftSurface.ok === true
    && (
      cleanDraftState.available !== true
      || (!cleanDraftState.activeId && Number(cleanDraftState.messageCount || 0) === 0)
    );
  const publicState = await captureCoreBetaPublicState(page, testCase).catch((caught) => {
    error ||= String(caught?.message || caught);
    return null;
  });
  const afterScreenshot = await shot(page, caseDir, 'initialization-continuation-surface-after').catch(() => '');
  const valid = !error
    && composerReady
    && workbenchReady
    && cleanDraftIsolated
    && Number(publicState?.page?.body_text_length || 0) > 0
    && Boolean(beforeScreenshot)
    && Boolean(afterScreenshot);
  const readback = {
    schema_version: 'qbot-core-beta-initialization-continuation-surface/v1',
    case_id: testCase.id,
    valid,
    composer_ready: Boolean(composerReady),
    workbench_ready: workbenchReady,
    clean_draft_isolated: cleanDraftIsolated,
    clean_draft_state: cleanDraftState,
    clean_draft_surface: cleanDraftSurface,
    public_state_readable: Number(publicState?.page?.body_text_length || 0) > 0,
    before_screenshot: beforeScreenshot,
    after_screenshot: afterScreenshot,
    error,
    public_state: publicState,
  };
  const file = path.join(caseDir, 'initialization-continuation-surface.json');
  writeJsonFile(file, readback);
  state.artifacts.initialization_continuation_surface = file;
  return { ...readback, file };
}

async function executeCoreBetaInitializationCase(context) {
  let {
    page,
    state,
    testCase,
    caseDir,
    timeoutMs,
    options = {},
    runtime,
  } = context;
  const maintenanceByCase = {
    'BETA-INIT-001': {
      method: 'preparePythonRuntimes',
      testId: 'assistant-prepare-python-runtimes',
      destructive: false,
      terminal: 'update',
    },
    'BETA-INIT-002': {
      method: 'runtimeResetAll',
      testId: 'assistant-runtime-reset-all',
      destructive: true,
      terminal: 'runtime-ready',
    },
    'BETA-INIT-003': {
      method: 'skillsReinstall',
      testId: 'assistant-skills-reinstall',
      destructive: true,
      terminal: 'runtime-ready',
    },
    'BETA-INIT-004': {
      method: 'sessionsPurgeAllEnvs',
      testId: 'assistant-sessions-purge',
      destructive: true,
      terminal: 'sessions-empty',
    },
  };
  const maintenance = maintenanceByCase[testCase.id];
  if (maintenance) {
    const before = await captureCoreBetaPublicState(page, testCase);
    const startedAt = Date.now();
    const opened = await openCoreBetaV2SystemSettings(page, state);
    if (!opened.ok) {
      throw new Error(`${maintenance.method} 无法进入系统设置：${opened.reason}`);
    }
    const actionAttempts = [];
    if (maintenance.terminal === 'sessions-empty') {
      const quiescence = await quiesceCoreBetaV2RunningSessions({
        page,
        state,
        caseDir,
        reason: '清空全部会话前置',
        attempt: 1,
        timeoutMs: 60_000,
      });
      if (!quiescence.valid) {
        throw new Error(`sessionsPurgeAllEnvs 无法建立全部会话 idle 前置：${quiescence.verdict?.reason || 'unknown'}`);
      }
    }
    let clicked = await clickCoreBetaV2MaintenanceAction({
      page,
      state,
      caseDir,
      ...maintenance,
      attempt: 1,
    });
    if (!clicked.ok) {
      throw new Error(`${maintenance.method} 真实 UI 动作失败：${clicked.reason}`);
    }
    actionAttempts.push(clicked);
    if (
      maintenance.terminal === 'sessions-empty'
      && coreBetaV2MaintenanceActiveSessionRejection(clicked.action_text)
    ) {
      const retryQuiescence = await quiesceCoreBetaV2RunningSessions({
        page,
        state,
        caseDir,
        reason: '首次清空被 active-session 拒绝后的唯一重试前置',
        attempt: 2,
        timeoutMs: 60_000,
      });
      if (!retryQuiescence.valid) {
        throw new Error(`sessionsPurgeAllEnvs 首次被 active-session 拒绝，且重试前无法建立全部会话 idle：${retryQuiescence.verdict?.reason || 'unknown'}`);
      }
      clicked = await clickCoreBetaV2MaintenanceAction({
        page,
        state,
        caseDir,
        ...maintenance,
        attempt: 2,
      });
      if (!clicked.ok) {
        throw new Error(`${maintenance.method} 唯一 UI 重试失败：${clicked.reason}`);
      }
      actionAttempts.push(clicked);
    }
    const terminal = await waitForCoreBetaV2MaintenanceTerminal({
      page,
      runtime,
      options,
      state,
      caseDir,
      testCase,
      maintenance,
      timeoutMs: Math.max(Number(timeoutMs || 0), maintenance.terminal === 'update' ? 90_000 : 600_000),
    });
    page = terminal.page || runtime?.page || page;
    context.page = page;
    if (runtime) runtime.page = page;
    const continuationSurface = !terminal.ok && terminal.readback?.failed === true
      ? await verifyCoreBetaInitializationContinuationSurface({ page, state, caseDir, testCase })
      : null;
    const after = continuationSurface?.public_state
      || await captureCoreBetaPublicState(page, testCase);
    const file = path.join(caseDir, `${slugify(maintenance.method)}-readback.json`);
    const readback = {
      valid: terminal.ok,
      method: maintenance.method,
      testid: maintenance.testId,
      elapsed_ms: Date.now() - startedAt,
      before,
      action: clicked,
      action_attempts: actionAttempts,
      terminal: terminal.readback,
      after,
    };
    if (!terminal.ok) {
      state.initialization_continuation = coreBetaInitializationContinuation({
        testCase,
        terminalReadback: terminal.readback,
        afterReadback: after,
        continuationSurface,
      });
      readback.continuation_surface = continuationSurface;
      readback.initialization_continuation = state.initialization_continuation;
    }
    writeJsonFile(file, readback);
    state.artifacts.capability_execution_event = file;
    state.artifacts.core_beta_runtime_maintenance = file;
    const productTerminalFailure = terminal.readback?.failed === true;
    const terminalFailureCategory = productTerminalFailure ? 'bug' : 'automation_error';
    recordStep(
      state,
      `${maintenance.method} 真实 UI 操作与终态采样`,
      '必须从系统设置点击真实维护按钮；破坏性操作须捕获并确认弹窗，随后等待公开状态连续稳定。',
      `testid=${maintenance.testId}；confirmation=${clicked.confirmation?.source || 'none'}；`
        + `attempts=${actionAttempts.length}；`
        + `action_observed=${clicked.action_observed}(${clicked.action_observation_source || 'none'})；`
        + `busy=${clicked.busy_observed}；terminal=${terminal.ok}；${terminal.readback?.reason || ''}`,
      terminal.ok ? 'passed' : 'failed',
      terminal.screenshot || clicked.busy_screenshot || '',
      terminal.ok ? '' : terminalFailureCategory,
    );
    if (maintenance.destructive) {
      recordAssertion(
        state,
        `${maintenance.method} 确认弹窗证据`,
        '破坏性初始化操作必须通过真实 UI 触发，并捕获与动作匹配的确认弹窗后才能继续。',
        clicked.confirmation?.accepted === true && Boolean(clicked.confirmation?.message),
        JSON.stringify(clicked.confirmation),
        'automation_error',
      );
    }
    recordAssertion(
      state,
      `${maintenance.method} 动作状态转换可见`,
      '点击后必须读到按钮 busy/disabled、维护区处理中状态，或相对动作前新增且与该动作精确匹配的完成回执。',
      clicked.action_observed === true,
      JSON.stringify({
        action_observed: clicked.action_observed,
        source: clicked.action_observation_source,
        busy_observed: clicked.busy_observed,
        navigation_observed: clicked.navigation_observed,
        navigation_url: clicked.navigation_url,
        completion_transition: clicked.completion_transition,
        before_text: clicked.before_text,
        action_text: clicked.action_text,
      }),
      productTerminalFailure ? 'bug' : 'automation_error',
    );
    recordAssertion(
      state,
      `${maintenance.method} 稳定终态`,
      maintenance.terminal === 'sessions-empty'
        ? '页面刷新后工作台应恢复，且公开会话列表必须为空。'
        : '维护区、SDK 状态、输入区与公开 capabilities 必须连续稳定就绪。',
      terminal.ok,
      JSON.stringify(terminal.readback),
      terminalFailureCategory,
    );
    return;
  }
  if (testCase.id === 'BETA-INIT-005') {
    const scenario = coreBetaScenarioSpec(testCase);
    await openNewTask(page, state);
    const before = await page.evaluate(async () => ({
      before: await window.__qbotE2E?.getConnectionView?.(),
      capabilities: await window.agent.capabilities(),
    }));
    const injected = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'inject',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        fault: 'warming_or_empty_remote_catalog',
      },
    });
    const during = await page.evaluate(async () => ({
      connection_view: await window.__qbotE2E?.getConnectionView?.(),
      capabilities: await window.agent.capabilities(),
    }));
    const file = path.join(caseDir, 'connection-view-snapshot.json');
    const sameSelection = JSON.stringify(before.before?.runtimeOptions?.selected || null)
      === JSON.stringify(during.connection_view?.runtimeOptions?.selected || null);
    writeJsonFile(file, {
      valid: nonEmptyObject(before.before) && sameSelection,
      before,
      injected,
      during,
      same_selection: sameSelection,
    });
    state.artifacts.connection_view_snapshot = file;
    state.artifacts.core_beta_connection_snapshot_diagnostics = {
      before: before.before?.diagnostics || before.before,
      during: during.connection_view?.diagnostics || during.connection_view,
      injected,
    };
    await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
    const after = await captureCoreBetaPublicState(page, testCase);
    recordAssertion(
      state,
      'connection-view last-good与首发绑定',
      'warming/空远端目录不得覆盖last-good；首条发送的runtime/connection选择必须与注入前一致。',
      sameSelection && Boolean(after.task?.id) && after.task?.send_count > 0,
      JSON.stringify({ sameSelection, after: { task: after.task, runtime: after.runtime } }),
    );
    return;
  }
  await executeUiCase({ page, state, testCase, caseDir, selectors });
}

export function coreBetaSuiteRoot(caseDir) {
  let cursor = path.resolve(caseDir);
  while (true) {
    if (fs.existsSync(path.join(cursor, 'casebook-cases.json'))) return cursor;
    if (path.basename(cursor) === 'cases') return path.dirname(cursor);
    const parent = path.dirname(cursor);
    if (parent === cursor) break;
    cursor = parent;
  }
  return path.dirname(path.dirname(path.resolve(caseDir)));
}

export function coreBetaSuiteLedgerPath(caseDir) {
  return path.join(coreBetaSuiteRoot(caseDir), 'core-beta-suite-ledger.json');
}

function coreBetaCleanupReleaseIdentity(metadata = {}) {
  return {
    host: {
      product: String(metadata.host?.product || ''),
      version: String(metadata.host?.version || ''),
      build: String(metadata.host?.build || ''),
      app_path: String(metadata.host?.app_path || ''),
    },
    qwork: {
      version: String(metadata.qwork?.version || ''),
      url: String(metadata.qwork?.url || ''),
    },
    control_plane: {
      origin: String(metadata.control_plane?.origin || ''),
    },
    artifacts: {
      host_info_plist_sha256: String(metadata.artifacts?.host_info_plist_sha256 || ''),
      host_main_binary_sha256: String(metadata.artifacts?.host_main_binary_sha256 || ''),
      qwork_index_sha256: String(metadata.artifacts?.qwork_index_sha256 || ''),
      qwork_install_metadata_sha256: String(metadata.artifacts?.qwork_install_metadata_sha256 || ''),
      casebook_sha256: String(metadata.artifacts?.casebook_sha256 || ''),
    },
    release_inputs: {
      backend_version: String(metadata.release_inputs?.backend_version || ''),
      prompt_policy_version: String(metadata.release_inputs?.prompt_policy_version || ''),
      feature_flags_hash: String(metadata.release_inputs?.feature_flags_hash || ''),
      qwork_ui_git_commit: String(metadata.release_inputs?.qwork_ui_git_commit || ''),
      qwork_build_id: String(metadata.release_inputs?.qwork_build_id || ''),
      qwork_release_manifest_sha256: String(metadata.release_inputs?.qwork_release_manifest_sha256 || ''),
    },
    model_tier: String(metadata.model_tier || ''),
  };
}

function coreBetaCleanupQworkReleaseRoot(qworkUrl = '') {
  try {
    const parsed = new URL(String(qworkUrl || ''));
    if (parsed.protocol !== 'file:') return '';
    const indexFile = fileURLToPath(parsed);
    if (path.basename(indexFile) !== 'index.html') return '';
    return path.dirname(path.dirname(indexFile));
  } catch {
    return '';
  }
}

function coreBetaCleanupQworkVersionFromUrl(qworkUrl = '') {
  try {
    const parsed = new URL(String(qworkUrl || ''));
    if (parsed.protocol !== 'file:') return '';
    return path.basename(path.dirname(fileURLToPath(parsed)));
  } catch {
    return '';
  }
}

function coreBetaCleanupIdentityDiff(sourceIdentity = {}, currentIdentity = {}) {
  const changes = [];
  const visit = (source, current, prefix = '') => {
    const keys = [...new Set([
      ...Object.keys(source && typeof source === 'object' ? source : {}),
      ...Object.keys(current && typeof current === 'object' ? current : {}),
    ])].sort();
    for (const key of keys) {
      const field = prefix ? `${prefix}.${key}` : key;
      const before = source?.[key];
      const after = current?.[key];
      if (
        before && after
        && typeof before === 'object'
        && typeof after === 'object'
        && !Array.isArray(before)
        && !Array.isArray(after)
      ) {
        visit(before, after, field);
      } else if (JSON.stringify(before) !== JSON.stringify(after)) {
        changes.push({ field, source: before ?? null, current: after ?? null });
      }
    }
  };
  visit(sourceIdentity, currentIdentity);
  return changes;
}

export function coreBetaCleanupReleaseMigrationVerdict(sourceMetadata = {}, currentMetadata = {}) {
  const sourceIdentity = coreBetaCleanupReleaseIdentity(sourceMetadata);
  const currentIdentity = coreBetaCleanupReleaseIdentity(currentMetadata);
  const sourceProfile = sourceMetadata?.profile || {};
  const currentProfile = currentMetadata?.profile || {};
  const sourceQworkRoot = coreBetaCleanupQworkReleaseRoot(sourceIdentity.qwork?.url);
  const currentQworkRoot = coreBetaCleanupQworkReleaseRoot(currentIdentity.qwork?.url);
  const hashFields = [
    'host_info_plist_sha256',
    'host_main_binary_sha256',
    'qwork_index_sha256',
    'qwork_install_metadata_sha256',
    'casebook_sha256',
  ];
  const checks = {
    identity_changed: JSON.stringify(sourceIdentity) !== JSON.stringify(currentIdentity),
    host_product_same: sourceIdentity.host?.product === '360Teams'
      && currentIdentity.host?.product === sourceIdentity.host.product,
    host_app_path_same: Boolean(sourceIdentity.host?.app_path)
      && currentIdentity.host?.app_path === sourceIdentity.host.app_path,
    control_plane_same: Boolean(sourceIdentity.control_plane?.origin)
      && currentIdentity.control_plane?.origin === sourceIdentity.control_plane.origin,
    live_profile_same: sourceProfile.mode === 'live'
      && currentProfile.mode === 'live'
      && Boolean(sourceProfile.alias)
      && currentProfile.alias === sourceProfile.alias,
    qwork_release_root_same: Boolean(sourceQworkRoot)
      && currentQworkRoot === sourceQworkRoot,
    qwork_versions_bound_to_urls: coreBetaCleanupQworkVersionFromUrl(sourceIdentity.qwork?.url)
      === sourceIdentity.qwork?.version
      && coreBetaCleanupQworkVersionFromUrl(currentIdentity.qwork?.url)
        === currentIdentity.qwork?.version,
    model_tier_same: Boolean(sourceIdentity.model_tier)
      && currentIdentity.model_tier === sourceIdentity.model_tier,
    artifact_hashes_complete: hashFields.every((field) => (
      /^[a-f0-9]{64}$/i.test(String(sourceIdentity.artifacts?.[field] || ''))
      && /^[a-f0-9]{64}$/i.test(String(currentIdentity.artifacts?.[field] || ''))
    )),
  };
  return {
    schema_version: 'qbot-core-beta-cleanup-release-migration/v1',
    valid: Object.values(checks).every(Boolean),
    explicitly_authorized: true,
    checks,
    source_release_identity_sha256: sha256Text(JSON.stringify(sourceIdentity)),
    current_release_identity_sha256: sha256Text(JSON.stringify(currentIdentity)),
    source_qwork_release_root: sourceQworkRoot,
    current_qwork_release_root: currentQworkRoot,
    changed_fields: coreBetaCleanupIdentityDiff(sourceIdentity, currentIdentity),
  };
}

function coreBetaCleanupSourceResult(sourceOut, progress, caseId) {
  const result = (Array.isArray(progress?.results) ? progress.results : [])
    .find((item) => String(item?.id || '') === caseId);
  if (!result || result.synthetic === true || result.execution_provenance !== 'executed') {
    throw new Error(`${caseId} 缺少真实 executed 源结果。`);
  }
  const declaredCaseDir = path.resolve(String(result.case_dir || ''));
  if (!result.case_dir || !fs.existsSync(declaredCaseDir)) {
    throw new Error(`${caseId} 源 Case 目录缺失。`);
  }
  const sourceCaseDir = fs.realpathSync(declaredCaseDir);
  const sourceRelative = path.relative(sourceOut, sourceCaseDir);
  if (sourceRelative.startsWith('..') || path.isAbsolute(sourceRelative)) {
    throw new Error(`${caseId} 源 Case 目录越出冻结批次。`);
  }
  const resultFile = path.join(sourceCaseDir, 'case-result.json');
  const manifestFile = path.join(sourceCaseDir, 'evidence-manifest.json');
  if (!fs.existsSync(resultFile) || !fs.existsSync(manifestFile)) {
    throw new Error(`${caseId} 源结果或 manifest 文件缺失。`);
  }
  const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
  if (
    manifest.complete !== true
    || (manifest.missing_roles || []).length > 0
    || (manifest.invalid_roles || []).length > 0
  ) {
    throw new Error(`${caseId} 源 manifest 不完整。`);
  }
  return {
    case_id: caseId,
    status: String(result.status || ''),
    result_category: String(result.result_category || ''),
    case_result_sha256: createHash('sha256').update(fs.readFileSync(resultFile)).digest('hex'),
    evidence_manifest_sha256: createHash('sha256').update(fs.readFileSync(manifestFile)).digest('hex'),
  };
}

export function seedCoreBetaRunOwnedSkillCleanupLedger({
  sourceOut,
  currentOut,
  casebook,
  selectedCases = [],
  allowReleaseMigration = false,
} = {}) {
  const sourceDirectory = fs.realpathSync(path.resolve(String(sourceOut || '')));
  const currentDirectory = fs.realpathSync(path.resolve(String(currentOut || '')));
  if (sourceDirectory === currentDirectory || path.dirname(sourceDirectory) !== path.dirname(currentDirectory)) {
    throw new Error('清理源必须是当前输出目录的冻结同级批次。');
  }
  if (
    selectedCases.length !== 1
    || String(selectedCases[0]?.id || '') !== 'BETA-SKILL-001'
    || String(selectedCases[0]?.case_type || '') !== 'skill_lifecycle'
  ) {
    throw new Error('--core-beta-cleanup-from 只允许单独执行 BETA-SKILL-001。');
  }

  const sourceLedgerFile = path.join(sourceDirectory, 'core-beta-suite-ledger.json');
  const sourceProgressFile = path.join(sourceDirectory, 'automation-progress.json');
  const sourceMetadataFile = path.join(sourceDirectory, 'run-metadata.json');
  const currentMetadataFile = path.join(currentDirectory, 'run-metadata.json');
  const currentLedgerFile = path.join(currentDirectory, 'core-beta-suite-ledger.json');
  for (const file of [sourceLedgerFile, sourceProgressFile, sourceMetadataFile, currentMetadataFile]) {
    if (!fs.existsSync(file) || !fs.statSync(file).isFile() || fs.statSync(file).size === 0) {
      throw new Error(`清理源合同文件缺失或为空：${file}`);
    }
  }
  if (fs.existsSync(currentLedgerFile)) {
    throw new Error(`当前清理输出已存在 suite ledger，禁止覆盖：${currentLedgerFile}`);
  }

  const sourceMetadata = JSON.parse(fs.readFileSync(sourceMetadataFile, 'utf8'));
  const currentMetadata = JSON.parse(fs.readFileSync(currentMetadataFile, 'utf8'));
  const casebookFile = fs.realpathSync(path.resolve(String(casebook || '')));
  const casebookSha256 = createHash('sha256').update(fs.readFileSync(casebookFile)).digest('hex');
  if (
    sourceMetadata.artifacts?.casebook_sha256 !== casebookSha256
    || currentMetadata.artifacts?.casebook_sha256 !== casebookSha256
  ) {
    throw new Error('清理源、当前批次与 Casebook SHA-256 不一致。');
  }
  const sourceIdentity = coreBetaCleanupReleaseIdentity(sourceMetadata);
  const currentIdentity = coreBetaCleanupReleaseIdentity(currentMetadata);
  const releaseIdentityEqual = JSON.stringify(sourceIdentity) === JSON.stringify(currentIdentity);
  let releaseMigration = null;
  if (!releaseIdentityEqual && allowReleaseMigration === true) {
    releaseMigration = coreBetaCleanupReleaseMigrationVerdict(sourceMetadata, currentMetadata);
    if (!releaseMigration.valid) {
      const failedChecks = Object.entries(releaseMigration.checks)
        .filter(([, valid]) => !valid)
        .map(([check]) => check);
      throw new Error(`跨发布清理安全门禁未通过：${failedChecks.join(',')}`);
    }
  } else if (!releaseIdentityEqual) {
    throw new Error('清理源与当前受管宿主发布身份不一致。');
  }

  const sourceProgress = JSON.parse(fs.readFileSync(sourceProgressFile, 'utf8'));
  const sourceResults = ['BETA-SKILL-002', 'BETA-SKILL-003', 'BETA-SKILL-004']
    .map((caseId) => coreBetaCleanupSourceResult(sourceDirectory, sourceProgress, caseId));
  const ledger = JSON.parse(fs.readFileSync(sourceLedgerFile, 'utf8'));
  const selected = Array.isArray(ledger.skills?.selected) ? ledger.skills.selected : [];
  const selectedIdentities = selected.map((item) => String(item?.qualified_identity || '')).filter(Boolean);
  if (selected.length !== 10 || selectedIdentities.length !== 10 || new Set(selectedIdentities).size !== 10) {
    throw new Error('清理源必须包含10个唯一的 QA Skill qualified identity。');
  }
  const baseline = new Set(Array.isArray(ledger.skills?.baseline_installed)
    ? ledger.skills.baseline_installed.map(String)
    : []);
  const baselineOverlap = selectedIdentities.filter((identity) => baseline.has(identity));
  if (baselineOverlap.length > 0) {
    throw new Error(`清理目标与安装前基线重叠：${baselineOverlap.join(',')}`);
  }
  const prerequisite = coreBetaSkillInstallPrerequisiteBlocker(ledger, {
    expectedCount: 10,
    dependentCaseId: 'BETA-SKILL-012',
  });
  if (!prerequisite.valid) {
    throw new Error(`清理源安装尝试账本无效：${prerequisite.reason}`);
  }

  const temporary = `${currentLedgerFile}.tmp-${process.pid}`;
  fs.copyFileSync(sourceLedgerFile, temporary);
  fs.renameSync(temporary, currentLedgerFile);
  const record = {
    schema_version: 'qbot-core-beta-run-owned-skill-cleanup-source/v2',
    valid: true,
    seeded_at: new Date().toISOString(),
    source_out: sourceDirectory,
    current_out: currentDirectory,
    source_ledger: sourceLedgerFile,
    source_ledger_sha256: createHash('sha256').update(fs.readFileSync(sourceLedgerFile)).digest('hex'),
    imported_ledger: currentLedgerFile,
    imported_ledger_sha256: createHash('sha256').update(fs.readFileSync(currentLedgerFile)).digest('hex'),
    source_progress: sourceProgressFile,
    source_progress_sha256: createHash('sha256').update(fs.readFileSync(sourceProgressFile)).digest('hex'),
    casebook_sha256: casebookSha256,
    release_identity_equal: releaseIdentityEqual,
    release_identity_sha256: releaseIdentityEqual
      ? sha256Text(JSON.stringify(currentIdentity))
      : '',
    source_release_identity_sha256: sha256Text(JSON.stringify(sourceIdentity)),
    current_release_identity_sha256: sha256Text(JSON.stringify(currentIdentity)),
    release_migration: releaseMigration,
    selected_identities: selectedIdentities,
    baseline_overlap: baselineOverlap,
    install_attempts_sha256: prerequisite.receipts_sha256,
    source_results: sourceResults,
    cleanup_case_id: 'BETA-SKILL-001',
  };
  writeJsonFile(path.join(currentDirectory, 'core-beta-run-owned-skill-cleanup-source.json'), record);
  return record;
}

function readCoreBetaSuiteLedger(caseDir) {
  const file = coreBetaSuiteLedgerPath(caseDir);
  if (!fs.existsSync(file)) return { schema_version: 1, skills: {}, experts: {}, mcps: {} };
  try {
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
    return parsed && typeof parsed === 'object'
      ? parsed
      : { schema_version: 1, skills: {}, experts: {}, mcps: {} };
  } catch {
    return { schema_version: 1, skills: {}, experts: {}, mcps: {} };
  }
}

function writeCoreBetaSuiteLedger(caseDir, ledger) {
  const file = coreBetaSuiteLedgerPath(caseDir);
  writeJsonFile(file, { ...ledger, schema_version: 1, updated_at: new Date().toISOString() });
  return file;
}

function skillQualifiedIdentity(skill) {
  return [
    skill?.namespace || 'global',
    skill?.slug || skill?.name || '',
    skill?.latestVersion || skill?.version || skill?.installedVersion || 'unknown',
  ].join('/');
}

export function coreBetaSkillUninstallRequestName(skill = {}) {
  const name = String(skill?.name || skill?.slug || '').trim();
  if (!name) throw new Error('Skill 卸载目标缺少产品 API 要求的字符串 name。');
  return name;
}

async function openCoreBetaSkillSurface(page, state) {
  await page.locator('[data-testid="nav-experts"]').click({ timeout: 15_000 });
  await returnFromExpertBuilderIfNeeded(page, state);
  await page.locator('[data-testid="skills-tab"]').click({ timeout: 15_000 });
  await expectVisibleCoreLocator(page, '[data-testid="skills-view"]', '技能页');
}

async function selectCoreBetaSkillTab(page, name) {
  const tab = page.getByRole('tab', { name: new RegExp(`^${escapeRegExp(name)}$`) }).first();
  if (!await visible(tab, 2_000)) throw new Error(`技能分区不可见：${name}`);
  await tab.click({ force: true });
  await page.waitForTimeout(500);
  const selected = await tab.getAttribute('aria-selected').catch(() => '');
  if (selected !== 'true') throw new Error(`技能分区未进入选中态：${name}`);
}

async function readCoreBetaSkillCatalog(page) {
  return await page.evaluate(async () => {
    const catalog = await window.agent.getSkillsCatalog();
    return {
      ...catalog,
      observed_at: new Date().toISOString(),
      installed: Array.isArray(catalog?.installed) ? catalog.installed : [],
      market: Array.isArray(catalog?.market) ? catalog.market : [],
      history: Array.isArray(catalog?.history) ? catalog.history : [],
    };
  });
}

async function waitForCoreBetaSkillIdentitiesAbsent(page, targetIdentities, {
  timeoutMs = 60_000,
  stableRequired = 2,
  pollMs = 1_000,
} = {}) {
  const targets = new Set((Array.isArray(targetIdentities) ? targetIdentities : []).map(String).filter(Boolean));
  const startedAt = Date.now();
  const observations = [];
  let stableAbsentObservations = 0;
  let catalog = null;
  while (Date.now() - startedAt <= timeoutMs) {
    try {
      catalog = await readCoreBetaSkillCatalog(page);
      const remainingIdentities = catalog.installed
        .map(skillQualifiedIdentity)
        .filter((identity) => targets.has(identity));
      stableAbsentObservations = remainingIdentities.length === 0
        ? stableAbsentObservations + 1
        : 0;
      observations.push({
        captured_at: new Date().toISOString(),
        elapsed_ms: Date.now() - startedAt,
        installed_count: catalog.installed.length,
        remaining_identities: remainingIdentities,
        stable_absent_observations: stableAbsentObservations,
      });
      if (stableAbsentObservations >= stableRequired) {
        return {
          valid: true,
          timeout_ms: timeoutMs,
          elapsed_ms: Date.now() - startedAt,
          stable_required: stableRequired,
          stable_absent_observations: stableAbsentObservations,
          remaining_identities: [],
          observations,
          catalog,
        };
      }
    } catch (error) {
      stableAbsentObservations = 0;
      observations.push({
        captured_at: new Date().toISOString(),
        elapsed_ms: Date.now() - startedAt,
        error: String(error?.message || error),
        stable_absent_observations: 0,
      });
    }
    await page.waitForTimeout(pollMs);
  }
  const remainingIdentities = (catalog?.installed || [])
    .map(skillQualifiedIdentity)
    .filter((identity) => targets.has(identity));
  return {
    valid: false,
    timeout_ms: timeoutMs,
    elapsed_ms: Date.now() - startedAt,
    stable_required: stableRequired,
    stable_absent_observations: stableAbsentObservations,
    remaining_identities: remainingIdentities,
    observations,
    catalog,
  };
}

export async function uninstallCoreBetaRunOwnedSkillTargets(page, installedTargets, {
  maxAttempts = 3,
  timeoutMs = 60_000,
  stableRequired = 2,
  pollMs = 1_000,
} = {}) {
  const targets = (Array.isArray(installedTargets) ? installedTargets : []).map((skill) => ({
    qualified_identity: skillQualifiedIdentity(skill),
    request_name: coreBetaSkillUninstallRequestName(skill),
  }));
  const identities = targets.map((item) => item.qualified_identity);
  const requestNames = targets.map((item) => item.request_name);
  if (new Set(identities).size !== identities.length || new Set(requestNames).size !== requestNames.length) {
    throw new Error('Skill 清理目标的 qualified identity 或 API request name 不唯一。');
  }

  const attemptLimit = Math.max(1, Math.min(3, Number(maxAttempts) || 1));
  const attemptsByIdentity = new Map(targets.map((item) => [item.qualified_identity, []]));
  const waves = [];
  let remainingIdentities = [...identities];
  let absenceReadback = null;

  for (let attempt = 1; attempt <= attemptLimit; attempt += 1) {
    const remainingSet = new Set(remainingIdentities);
    const waveTargets = targets.filter((item) => remainingSet.has(item.qualified_identity));
    const waveReceipts = [];
    for (const target of waveTargets) {
      const result = await page.evaluate((name) => window.agent.uninstallSkill(name), target.request_name)
        .catch((error) => ({ ok: false, error: String(error?.message || error) }));
      const receipt = {
        attempt,
        qualified_identity: target.qualified_identity,
        request_name: target.request_name,
        result,
      };
      attemptsByIdentity.get(target.qualified_identity).push(receipt);
      waveReceipts.push(receipt);
    }
    absenceReadback = await waitForCoreBetaSkillIdentitiesAbsent(page, identities, {
      timeoutMs,
      stableRequired,
      pollMs,
    });
    remainingIdentities = Array.isArray(absenceReadback.remaining_identities)
      ? absenceReadback.remaining_identities.map(String)
      : [];
    waves.push({
      attempt,
      target_identities: waveTargets.map((item) => item.qualified_identity),
      receipts: waveReceipts,
      absence_readback: { ...absenceReadback, catalog: undefined },
    });
    if (absenceReadback.valid === true || remainingIdentities.length === 0) break;
  }

  const receipts = targets.map((target) => {
    const attempts = attemptsByIdentity.get(target.qualified_identity) || [];
    const accepted = attempts.find((item) => item?.result?.ok === true) || attempts.at(-1) || null;
    return {
      qualified_identity: target.qualified_identity,
      request_name: target.request_name,
      result: accepted?.result || { ok: false, error: '未执行 Skill 卸载动作。' },
      attempts,
    };
  });
  return {
    max_attempts: attemptLimit,
    attempt_count: waves.length,
    waves,
    receipts,
    absence_readback: absenceReadback || {
      valid: false,
      timeout_ms: timeoutMs,
      stable_required: stableRequired,
      stable_absent_observations: 0,
      remaining_identities: identities,
      observations: [],
      catalog: null,
    },
  };
}

export function coreBetaRunOwnedSkillCleanupVerdict({
  attemptedIdentities = [],
  receipts = [],
  remainingIdentities = [],
  untouchedBefore = [],
  untouchedAfter = [],
  absenceReadback = {},
} = {}) {
  const attempted = (Array.isArray(attemptedIdentities) ? attemptedIdentities : []).map(String).filter(Boolean);
  const normalizedReceipts = Array.isArray(receipts) ? receipts : [];
  const remaining = (Array.isArray(remainingIdentities) ? remainingIdentities : []).map(String).filter(Boolean);
  const unrelatedPreserved = JSON.stringify(untouchedBefore) === JSON.stringify(untouchedAfter);
  const receiptIdentities = normalizedReceipts
    .map((item) => String(item?.qualified_identity || ''))
    .filter(Boolean);
  const receiptRequestNames = normalizedReceipts
    .map((item) => String(item?.request_name || '').trim())
    .filter(Boolean);
  const stableAbsenceValid = absenceReadback?.valid === true
    && Number(absenceReadback?.stable_absent_observations || 0)
      >= Number(absenceReadback?.stable_required || 2);
  const remainingSet = new Set(remaining);
  const receiptOutcomes = normalizedReceipts.map((item) => {
    const identity = String(item?.qualified_identity || '');
    const error = String(item?.result?.error || item?.result?.message || item?.result?.msg || '');
    const apiOk = item?.result?.ok === true;
    const ambiguousControlPlaneTimeout = item?.result?.ok === false
      && /control-plane request timed out/i.test(error);
    const terminalReconciled = !apiOk
      && ambiguousControlPlaneTimeout
      && stableAbsenceValid
      && identity.length > 0
      && !remainingSet.has(identity);
    return {
      qualified_identity: identity,
      request_name: String(item?.request_name || ''),
      api_ok: apiOk,
      ambiguous_control_plane_timeout: ambiguousControlPlaneTimeout,
      terminal_reconciled: terminalReconciled,
      valid: apiOk || terminalReconciled,
    };
  });
  const receiptsValid = normalizedReceipts.length === attempted.length
    && new Set(attempted).size === attempted.length
    && new Set(receiptIdentities).size === receiptIdentities.length
    && receiptRequestNames.length === normalizedReceipts.length
    && new Set(receiptRequestNames).size === receiptRequestNames.length
    && attempted.every((identity) => receiptIdentities.includes(identity))
    && receiptOutcomes.every((item) => item.request_name.trim().length > 0 && item.valid);
  return {
    valid: receiptsValid
      && remaining.length === 0
      && stableAbsenceValid
      && unrelatedPreserved,
    attempted_count: attempted.length,
    receipt_count: normalizedReceipts.length,
    receipts_valid: receiptsValid,
    remaining_identities: remaining,
    absence_readback_valid: absenceReadback?.valid === true,
    unrelated_preserved: unrelatedPreserved,
    reconciled_timeout_count: receiptOutcomes.filter((item) => item.terminal_reconciled).length,
    receipt_outcomes: receiptOutcomes,
  };
}

function chooseCoreBetaMarketSkills(catalog, count = 10) {
  return (catalog.market || [])
    .filter((skill) => !skill.installed
      && skill.usable !== false
      && skill.installStatus !== 'rejected'
      && (skill.slug || skill.name))
    .sort((left, right) => skillQualifiedIdentity(left).localeCompare(skillQualifiedIdentity(right), 'en'))
    .slice(0, count);
}

export function coreBetaSkillInstallBatchAssessment(receipts = [], expectedCount = 5) {
  const normalized = Array.isArray(receipts) ? receipts : [];
  const identities = normalized.map((item) => String(item?.qualified_identity || '')).filter(Boolean);
  const terminalEvidenceValid = (item) => {
    const status = String(item?.terminal_feedback?.status || '');
    const feedbackTerminal = ['success', 'error'].includes(status)
      && (
        item?.terminal_feedback?.action_bound === true
        || item?.terminal_feedback?.observed === true
      );
    const terminalTimeoutMs = Number(item?.terminal_timeout_ms || 0);
    const terminalWaitedMs = Number(item?.terminal_waited_ms || 0);
    const timedOut = item?.terminal_outcome === 'timed_out'
      && terminalTimeoutMs >= 60_000
      && terminalWaitedMs >= terminalTimeoutMs;
    return feedbackTerminal || timedOut;
  };
  const evidenceValid = normalized.length === expectedCount
    && identities.length === expectedCount
    && new Set(identities).size === expectedCount
    && normalized.every((item) => (
      item.clicked === true
      && typeof item?.installed === 'boolean'
      && item.catalog_installed_checked === true
      && typeof item.before === 'string' && item.before.length > 0
      && typeof item.pending === 'string' && item.pending.length > 0
      && typeof item.after === 'string' && item.after.length > 0
      && typeof item.pending_observed === 'boolean'
      && terminalEvidenceValid(item)
      && typeof item.api_receipt?.install_ok !== 'undefined'
      && typeof item.reconcile_receipt?.ok !== 'undefined'
      && (!item.installed || Boolean(item.installed_readback))
    ));
  const installedReceipts = normalized.filter((item) => item?.installed === true);
  const successfulReceipts = normalized.filter((item) => (
    item?.installed === true
    && item.pending_observed === true
    && item.terminal_feedback?.status === 'success'
    && item.api_receipt?.install_ok === true
    && item.reconcile_receipt?.ok === true
  ));
  const failedReceipts = normalized.filter((item) => !successfulReceipts.includes(item));
  return {
    valid: evidenceValid,
    oracle_valid: evidenceValid && successfulReceipts.length === expectedCount,
    expected_count: expectedCount,
    attempted_count: normalized.length,
    installed_count: installedReceipts.length,
    failed_count: failedReceipts.length,
    installed_identities: installedReceipts.map((item) => item.qualified_identity),
    failed_identities: failedReceipts.map((item) => item.qualified_identity),
  };
}

export function coreBetaSkillInstallPrerequisiteBlocker(ledger = {}, {
  expectedCount = 10,
  targetIdentity = '',
  dependentCaseId = '',
} = {}) {
  const selected = Array.isArray(ledger?.skills?.selected) ? ledger.skills.selected : [];
  const attempts = Array.isArray(ledger?.skills?.install_attempt_receipts)
    ? ledger.skills.install_attempt_receipts
    : [];
  const selectedIdentities = selected.map((item) => String(item?.qualified_identity || '')).filter(Boolean);
  const attemptIdentities = attempts.map((item) => String(item?.qualified_identity || '')).filter(Boolean);
  const sourceCaseIds = [...new Set(attempts.map((item) => String(item?.source_case_id || '')).filter(Boolean))];
  const target = targetIdentity
    ? attempts.find((item) => item?.qualified_identity === targetIdentity) || null
    : null;
  const expected = Number(expectedCount);
  const batchEvidenceValid = expected === 10
    && coreBetaSkillInstallBatchAssessment(attempts.slice(0, 5), 5).valid
    && coreBetaSkillInstallBatchAssessment(attempts.slice(5, 10), 5).valid;
  const valid = Number.isInteger(expected)
    && expected > 0
    && selected.length === expected
    && attempts.length === expected
    && selectedIdentities.length === expected
    && attemptIdentities.length === expected
    && new Set(selectedIdentities).size === expected
    && new Set(attemptIdentities).size === expected
    && selectedIdentities.every((identity, index) => identity === attemptIdentities[index])
    && attempts.every((item) => typeof item?.oracle_passed === 'boolean')
    && attempts.slice(0, 5).every((item) => item?.source_case_id === 'BETA-SKILL-003')
    && attempts.slice(5, 10).every((item) => item?.source_case_id === 'BETA-SKILL-004')
    && sourceCaseIds.length === 2
    && sourceCaseIds[0] === 'BETA-SKILL-003'
    && sourceCaseIds[1] === 'BETA-SKILL-004'
    && (!targetIdentity || Boolean(target && selectedIdentities.includes(targetIdentity)))
    && batchEvidenceValid;
  const successful = attempts.filter((item) => item?.oracle_passed === true);
  const applicable = valid && (targetIdentity
    ? Boolean(target && target.oracle_passed !== true)
    : successful.length < expected);
  const failedIdentities = attempts
    .filter((item) => item?.oracle_passed !== true)
    .map((item) => item.qualified_identity);
  const reason = !valid
    ? 'Skill 安装尝试账本不完整，不能传播上游前置阻塞。'
    : targetIdentity
      ? applicable
        ? `指定 Skill 安装前置失败：${targetIdentity}；依赖该身份的 Case 不得发送或随机替换。`
        : `指定 Skill 安装前置已满足：${targetIdentity}。`
      : applicable
        ? `技能安装前置未完成：要求 ${expected} 个，真实成功 ${successful.length} 个；依赖完整安装集的 Case 不得重复归因为自身产品 Bug。`
        : `技能安装前置已满足：${successful.length}/${expected}。`;
  return {
    schema_version: 'qbot-core-beta-upstream-prerequisite/v1',
    valid,
    oracle_valid: valid && !applicable,
    applicable,
    kind: 'skill_install_terminal_shortage',
    source: 'exact_run_owned_install_attempt_ledger',
    dependent_case_id: String(dependentCaseId || ''),
    reason,
    expected_count: expected,
    attempted_count: attempts.length,
    successful_count: successful.length,
    failed_count: failedIdentities.length,
    target_identity: String(targetIdentity || ''),
    failed_identities: failedIdentities,
    source_case_ids: sourceCaseIds,
    receipts_sha256: createHash('sha256').update(JSON.stringify(attempts)).digest('hex'),
  };
}

const CORE_BETA_SKILL_PROMPT_SOURCE_FIELDS = Object.freeze([
  ['skill_detail_markdown', (sample) => sample?.detail?.markdown],
  ['skill_detail_body', (sample) => sample?.detail?.body],
  ['skill_detail_readme', (sample) => sample?.detail?.readme],
  ['catalog_market_description', (sample) => sample?.market?.description],
  ['catalog_market_desc', (sample) => sample?.market?.desc],
  ['sample_description', (sample) => sample?.description],
  ['sample_desc', (sample) => sample?.desc],
]);

export function coreBetaSkillPromptSource(sample = {}) {
  const frozen = sample?.prompt_source;
  if (frozen && typeof frozen === 'object') {
    const content = String(frozen.content || '').trim();
    const sha256 = content
      ? createHash('sha256').update(content).digest('hex')
      : '';
    const declaredSha256 = String(frozen.sha256 || '');
    const valid = frozen.schema_version === 'qbot-core-beta-skill-prompt-source/v1'
      && frozen.valid === true
      && content.length > 0
      && /^[a-f0-9]{64}$/i.test(declaredSha256)
      && declaredSha256 === sha256;
    const declaredMissing = frozen.schema_version === 'qbot-core-beta-skill-prompt-source/v1'
      && frozen.valid === false
      && content.length === 0
      && declaredSha256 === '';
    return {
      schema_version: 'qbot-core-beta-skill-prompt-source/v1',
      valid,
      integrity_valid: valid || declaredMissing,
      kind: String(frozen.kind || 'frozen_prompt_source'),
      content,
      bytes: Buffer.byteLength(content),
      sha256,
      checked_fields: Array.isArray(frozen.checked_fields)
        ? frozen.checked_fields.map(String)
        : CORE_BETA_SKILL_PROMPT_SOURCE_FIELDS.map(([field]) => field),
      reason: valid
        ? ''
        : declaredMissing
          ? String(frozen.reason || 'Skill README/body/description 均为空。')
          : '冻结 Skill prompt source 的 schema、内容或 SHA-256 不一致。',
    };
  }

  for (const [kind, read] of CORE_BETA_SKILL_PROMPT_SOURCE_FIELDS) {
    const content = String(read(sample) || '').trim();
    if (!content) continue;
    return {
      schema_version: 'qbot-core-beta-skill-prompt-source/v1',
      valid: true,
      integrity_valid: true,
      kind,
      content,
      bytes: Buffer.byteLength(content),
      sha256: createHash('sha256').update(content).digest('hex'),
      checked_fields: CORE_BETA_SKILL_PROMPT_SOURCE_FIELDS.map(([field]) => field),
      reason: '',
    };
  }

  return {
    schema_version: 'qbot-core-beta-skill-prompt-source/v1',
    valid: false,
    integrity_valid: true,
    kind: 'missing',
    content: '',
    bytes: 0,
    sha256: '',
    checked_fields: CORE_BETA_SKILL_PROMPT_SOURCE_FIELDS.map(([field]) => field),
    reason: 'Skill README/body/description 均为空。',
  };
}

export function coreBetaSkillPromptSourcePrerequisiteBlocker(selectedSkill = {}, {
  dependentCaseId = '',
} = {}) {
  const promptSource = coreBetaSkillPromptSource(selectedSkill);
  const targetIdentity = String(selectedSkill?.qualified_identity || '');
  const identityValid = Boolean(targetIdentity);
  const sampleSha256 = identityValid
    ? createHash('sha256').update(JSON.stringify({
        qualified_identity: targetIdentity,
        namespace: selectedSkill?.namespace || '',
        slug: selectedSkill?.slug || '',
        version: selectedSkill?.version || '',
        prompt_source: selectedSkill?.prompt_source || null,
        detail: selectedSkill?.detail || null,
        market_description: selectedSkill?.market?.description || selectedSkill?.market?.desc || '',
      })).digest('hex')
    : '';
  const valid = identityValid && promptSource.integrity_valid === true;
  const applicable = valid && promptSource.valid !== true;
  return {
    schema_version: 'qbot-core-beta-upstream-prerequisite/v1',
    valid,
    oracle_valid: valid && !applicable,
    applicable,
    outcome: applicable ? 'blocked' : 'passed',
    kind: 'skill_prompt_source_unavailable',
    source: 'frozen_skill_sample_ledger',
    source_case_id: 'BETA-SKILL-002',
    source_case_ids: ['BETA-SKILL-002'],
    dependent_case_id: String(dependentCaseId || ''),
    target_identity: targetIdentity,
    prompt_source: {
      schema_version: promptSource.schema_version,
      valid: promptSource.valid,
      integrity_valid: promptSource.integrity_valid,
      kind: promptSource.kind,
      bytes: promptSource.bytes,
      sha256: promptSource.sha256,
      checked_fields: promptSource.checked_fields,
      reason: promptSource.reason,
    },
    sample_sha256: sampleSha256,
    reason: !valid
      ? `Skill 冻结说明来源账本不可验证：${targetIdentity || 'missing_identity'}；${promptSource.reason}`
      : applicable
        ? `指定 Skill 缺少可派生任务与 Oracle 的冻结 README/body/description：${targetIdentity}。`
        : `指定 Skill 已具备冻结说明来源：${targetIdentity}；${promptSource.kind}；sha256=${promptSource.sha256}`,
  };
}

export function coreBetaSkillUsePrerequisiteDecision(testCase = {}, ledger = {}) {
  const id = String(testCase?.id || '');
  if (!/^BETA-SKILL-0(?:06|07|08|09|10|11)$/.test(id)) {
    return {
      applies: false,
      valid: true,
      selected_skill: null,
      blocker: null,
      reason: '',
    };
  }
  const deepUseIndex = id === 'BETA-SKILL-011'
    ? 0
    : Number(id.split('-').at(-1)) - 6;
  const selectedSkill = ledger.skills?.deep_use?.[deepUseIndex] || null;
  if (!selectedSkill?.qualified_identity) {
    return {
      applies: true,
      valid: false,
      selected_skill: selectedSkill,
      blocker: null,
      reason: `${id} 缺少可验证的 deep_use[${deepUseIndex}] Skill 账本身份。`,
    };
  }
  const blocker = coreBetaSkillInstallPrerequisiteBlocker(ledger, {
    expectedCount: 10,
    targetIdentity: selectedSkill.qualified_identity,
    dependentCaseId: id,
  });
  if (!blocker.valid || blocker.applicable) {
    return {
      applies: true,
      valid: blocker.valid === true,
      selected_skill: selectedSkill,
      blocker,
      install_blocker: blocker,
      prompt_source_blocker: null,
      reason: blocker.reason,
    };
  }
  const promptSourceBlocker = coreBetaSkillPromptSourcePrerequisiteBlocker(selectedSkill, {
    dependentCaseId: id,
  });
  return {
    applies: true,
    valid: promptSourceBlocker.valid === true,
    selected_skill: selectedSkill,
    blocker: promptSourceBlocker,
    install_blocker: blocker,
    prompt_source_blocker: promptSourceBlocker,
    reason: promptSourceBlocker.reason,
  };
}

const CORE_BETA_SKILL_PREREQUISITE_NA_ROLES = Object.freeze([
  'prompt',
  'task_id',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

function applyCoreBetaSkillPrerequisiteBlocker({ state, testCase, caseDir, blocker, extra = {} }) {
  const notApplicableRoles = (testCase.evidence_roles || [])
    .filter((role) => CORE_BETA_SKILL_PREREQUISITE_NA_ROLES.includes(role));
  const file = path.join(caseDir, 'upstream-skill-install-prerequisite.json');
  writeJsonFile(file, {
    ...blocker,
    dependent_case_id: testCase.id,
    not_applicable_roles: notApplicableRoles,
    ...extra,
  });
  state.artifacts.capability_inventory = file;
  state.artifacts.capability_selection = file;
  state.artifacts.capability_execution_event = file;
  state.artifacts.core_beta_not_applicable_roles = notApplicableRoles.map((role) => ({
    role,
    blocker_path: file,
  }));
  recordAssertion(
    state,
    'Skill 上游前置账本',
    '只有安装终态或冻结 README/body/description 来源证据完整且目标依赖确实不可用时，才允许阻塞后续发送并将发送后证据标为不适用。',
    true,
    blocker.reason,
  );
  markBlocked(state, blocker.reason);
  return file;
}

async function readCoreBetaSkillOperationFeedback(page, targetLabel) {
  return await page.locator('[data-testid="skill-operation-feedback"]').first().evaluate((node, label) => {
    const text = String(node.textContent || '').trim();
    const status = node.classList.contains('success')
      ? 'success'
      : node.classList.contains('error')
        ? 'error'
        : node.classList.contains('pending') ? 'pending' : 'unknown';
    return {
      surface_observed: true,
      observed: text.includes(label),
      matches_target_label: text.includes(label),
      target_label: label,
      status,
      message: text,
      role: node.getAttribute('role') || '',
      captured_at: new Date().toISOString(),
    };
  }, targetLabel).catch(() => ({
    surface_observed: false,
    observed: false,
    matches_target_label: false,
    target_label: targetLabel,
    status: 'missing',
    message: '',
    role: '',
    captured_at: new Date().toISOString(),
  }));
}

function coreBetaSkillInstallReceiptsFromFeedback(feedback = {}, installed = null) {
  const message = String(feedback.message || '');
  const installFailed = feedback.status === 'error' && /^安装失败[：:]/.test(message);
  const installSucceeded = feedback.status === 'success'
    || (feedback.status === 'error' && !installFailed)
    || Boolean(installed);
  const reconcileFailed = /对账失败|运行时未就绪|未安装[：:]/.test(message);
  return {
    api_receipt: {
      source: 'skill-operation-feedback',
      derived_from_product_feedback: true,
      install_ok: installFailed ? false : installSucceeded ? true : null,
      message,
    },
    reconcile_receipt: {
      source: 'skill-operation-feedback+catalog.installed',
      derived_from_product_feedback: true,
      attempted: !installFailed,
      ok: installFailed
        ? null
        : feedback.status === 'success' && Boolean(installed)
          ? true
          : reconcileFailed || feedback.status === 'error' ? false : null,
      message,
    },
  };
}

const CORE_BETA_SKILL_CREATOR_IDENTITY = 'skillhub:global/skill-creator-qwork';

function coreBetaPathInside(root, target) {
  const relative = path.relative(path.resolve(root), path.resolve(target));
  return Boolean(relative && relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative));
}

export function coreBetaQbotHomeFromUiUrl(uiUrl = '') {
  try {
    const parsed = new URL(String(uiUrl || ''));
    if (parsed.protocol !== 'file:') return '';
    let current = path.dirname(fileURLToPath(parsed));
    while (current && current !== path.dirname(current)) {
      if (path.basename(current) === 'ui') return path.dirname(current);
      current = path.dirname(current);
    }
  } catch {}
  return '';
}

export function coreBetaProductHomeForUi({ uiUrl = '', options = {} } = {}) {
  return coreBetaQbotHomeFromUiUrl(uiUrl)
    || inferQbotHomeForElectronRestart(options);
}

export function coreBetaSkillCreatorFixtureSlug(caseDir = '', attempt = 0) {
  const seed = `${path.resolve(String(caseDir || '.'))}\n${Math.max(0, Number(attempt || 0))}`;
  const digest = createHash('sha256').update(seed).digest('hex').slice(0, 12);
  return `qa-meeting-minutes-${digest}`;
}

function coreBetaSkillCreatorProjectionPaths(qbotHome, slug) {
  if (!path.isAbsolute(String(qbotHome || ''))) throw new Error('Skill Creator 缺少绝对 QWork home');
  if (!/^[a-z0-9][a-z0-9-]{0,63}$/.test(String(slug || ''))) throw new Error(`Skill Creator fixture slug 非法：${slug}`);
  const home = path.resolve(qbotHome);
  return [
    { runtime: 'claude', directory: path.join(home, '.claude', 'skills', slug) },
    { runtime: 'codex', directory: path.join(home, '.agents', 'skills', slug) },
  ].map((item) => ({ ...item, file: path.join(item.directory, 'SKILL.md') }));
}

function readCoreBetaSkillCreatorProjection(item, slug) {
  const directoryExists = fs.existsSync(item.directory);
  const fileExists = fs.existsSync(item.file);
  if (!directoryExists || !fileExists) {
    return {
      ...item,
      observed: true,
      exists: false,
      directory_exists: directoryExists,
      file_exists: fileExists,
      regular_file: false,
      symlink_free: true,
      bytes: 0,
      sha256: '',
      frontmatter_name: '',
      agent_created: false,
      description_present: false,
      content: '',
    };
  }
  try {
    const directoryStat = fs.lstatSync(item.directory);
    const fileStat = fs.lstatSync(item.file);
    const content = fs.readFileSync(item.file, 'utf8');
    const frontmatter = content.match(/^---\s*\n([\s\S]*?)\n---(?:\s*\n|$)/)?.[1] || '';
    const name = frontmatter.match(/^name:\s*["']?([^\n"']+)["']?\s*$/m)?.[1]?.trim() || '';
    const agentCreated = /^agent_created:\s*true\s*$/mi.test(frontmatter);
    const descriptionPresent = /^description:\s*\S+/mi.test(frontmatter);
    return {
      ...item,
      observed: true,
      exists: true,
      directory_exists: true,
      file_exists: true,
      regular_file: fileStat.isFile(),
      symlink_free: !directoryStat.isSymbolicLink() && !fileStat.isSymbolicLink(),
      bytes: fileStat.size,
      sha256: createHash('sha256').update(fs.readFileSync(item.file)).digest('hex'),
      frontmatter_name: name,
      expected_name: slug,
      agent_created: agentCreated,
      description_present: descriptionPresent,
      content,
    };
  } catch (error) {
    return {
      ...item,
      observed: false,
      exists: true,
      error: String(error?.message || error),
    };
  }
}

function coreBetaSkillCreatorMemoryReadback(qbotHome, slug) {
  const home = path.resolve(qbotHome);
  const projectsRoot = path.join(home, 'runtime-homes', 'claude', 'projects');
  if (!fs.existsSync(projectsRoot)) return { observed: true, files: [] };
  try {
    const rootStat = fs.lstatSync(projectsRoot);
    if (!rootStat.isDirectory() || rootStat.isSymbolicLink()) {
      return { observed: false, files: [], error: 'projects_root_not_real_directory' };
    }
    const files = [];
    for (const entry of fs.readdirSync(projectsRoot, { withFileTypes: true })) {
      if (!entry.isDirectory() || entry.isSymbolicLink()) continue;
      const projectDir = path.join(projectsRoot, entry.name);
      const memoryDir = path.join(projectDir, 'memory');
      if (!fs.existsSync(memoryDir)) continue;
      const projectStat = fs.lstatSync(projectDir);
      const memoryStat = fs.lstatSync(memoryDir);
      if (
        !projectStat.isDirectory()
        || projectStat.isSymbolicLink()
        || !memoryStat.isDirectory()
        || memoryStat.isSymbolicLink()
      ) {
        return { observed: false, files, error: 'memory_path_not_real_directory' };
      }
      const file = path.join(memoryDir, `${slug}.md`);
      if (!fs.existsSync(file)) continue;
      const fileStat = fs.lstatSync(file);
      const content = fileStat.isFile() && !fileStat.isSymbolicLink()
        ? fs.readFileSync(file, 'utf8')
        : '';
      files.push({
        path: file,
        observed: true,
        exists: true,
        regular_file: fileStat.isFile(),
        symlink_free: !fileStat.isSymbolicLink(),
        bytes: fileStat.size,
        sha256: fileStat.isFile() && !fileStat.isSymbolicLink()
          ? createHash('sha256').update(fs.readFileSync(file)).digest('hex')
          : '',
        slug_present: content.includes(slug),
      });
    }
    return { observed: true, files };
  } catch (error) {
    return { observed: false, files: [], error: String(error?.message || error) };
  }
}

export function coreBetaSkillCreatorProjectionReadback({ qbotHome, slug, baseline = null } = {}) {
  if (!path.isAbsolute(String(qbotHome || ''))) throw new Error('Skill Creator 投影读回缺少绝对 QWork home');
  const home = path.resolve(String(qbotHome || '.'));
  const projectionPaths = coreBetaSkillCreatorProjectionPaths(home, slug);
  const projections = projectionPaths.map((item) => readCoreBetaSkillCreatorProjection(item, slug));
  const memoryReadback = coreBetaSkillCreatorMemoryReadback(home, slug);
  const baselineByRuntime = new Map(
    (Array.isArray(baseline?.projections) ? baseline.projections : [])
      .map((item) => [item.runtime, item]),
  );
  const baselineClean = projections.every((item) => baselineByRuntime.get(item.runtime)?.exists !== true);
  const created = projections.filter((item) => (
    item.exists === true && baselineByRuntime.get(item.runtime)?.exists !== true
  ));
  const evidenceValid = projections.every((item) => item.observed === true)
    && projectionPaths.every((item) => coreBetaPathInside(home, item.file))
    && memoryReadback.observed === true
    && memoryReadback.files.every((item) => coreBetaPathInside(home, item.path));
  const hashes = projections.filter((item) => item.exists).map((item) => item.sha256);
  const projectionOracleValid = projections.length === 2
    && projections.every((item) => (
      item.exists === true
      && item.regular_file === true
      && item.symlink_free === true
      && item.bytes > 0
      && item.sha256
      && item.frontmatter_name === slug
      && item.agent_created === true
      && item.description_present === true
    ))
    && new Set(hashes).size === 1;
  return {
    schema_version: 'qbot-core-beta-skill-creator-projection/v1',
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: Boolean(evidenceValid && baseline && baselineClean && projectionOracleValid),
    qbot_home: home,
    slug,
    baseline_clean: baseline ? baselineClean : null,
    projection_sha256_equal: hashes.length === 2 && new Set(hashes).size === 1,
    created_runtimes: created.map((item) => item.runtime),
    projections,
    memory_readback: memoryReadback,
  };
}

export function coreBetaSkillCreatorFixture({ qbotHome, caseDir } = {}) {
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const slug = coreBetaSkillCreatorFixtureSlug(caseDir, attempt);
    const baseline = coreBetaSkillCreatorProjectionReadback({ qbotHome, slug });
    if (!baseline.evidence_valid) throw new Error(`Skill Creator fixture 基线不可读：${slug}`);
    if (
      baseline.projections.every((item) => item.exists !== true)
      && baseline.memory_readback.files.every((item) => item.exists !== true)
    ) {
      return { qbot_home: baseline.qbot_home, slug, attempt, baseline };
    }
  }
  throw new Error('Skill Creator 无法分配无冲突的唯一 QA slug');
}

export function coreBetaSkillCreatorConversationCase(testCase = {}, slug = '') {
  const turns = Array.isArray(testCase.conversation_turns) ? testCase.conversation_turns : [];
  const uniqueContract = `本轮唯一 Skill 名称必须是 ${slug}；必须新建该名称，不得复用、覆盖或更新任何已有 Skill。`;
  return {
    ...testCase,
    conversation_turns: turns.map((turn, index) => ({
      ...turn,
      prompt: `${String(turn.prompt || '').trim()}\n\n${index === 0 ? uniqueContract : `继续完成 ${slug} 的创建；${uniqueContract}`}`,
    })),
  };
}

function coreBetaSkillCreatorStateSummary(snapshot = {}) {
  return {
    captured_at: snapshot.captured_at || null,
    task: snapshot.task || null,
    selected_skills: snapshot.capabilities?.selectedSkills || snapshot.skills?.selected || null,
    visible_testids: snapshot.visible?.testids || [],
  };
}

function coreBetaSelectedSkillIdentities(snapshot = {}) {
  const values = snapshot.capabilities?.selectedSkills || snapshot.skills?.selected || [];
  return (Array.isArray(values) ? values : []).map((item) => (
    typeof item === 'string' ? item : String(item?.qualified_identity || item?.id || item?.key || item?.slug || '')
  )).filter(Boolean);
}

export function coreBetaSkillCreatorSelectionEvidence({ before = {}, postSend = [], after = {}, prompts = [] } = {}) {
  const snapshots = Array.isArray(postSend) ? postSend : [];
  const taskIds = snapshots.map((item) => String(item?.task?.id || '')).filter(Boolean);
  const selectedBefore = coreBetaSelectedSkillIdentities(before);
  const selectedPostSend = snapshots.flatMap(coreBetaSelectedSkillIdentities);
  const evidenceValid = Boolean(
    before && typeof before === 'object'
    && snapshots.length >= 1
    && taskIds.length >= 1
    && after?.task?.id
    && Array.isArray(prompts)
    && prompts.length >= 1
  );
  const taskId = String(after?.task?.id || taskIds[0] || '');
  const oracleValid = Boolean(
    evidenceValid
    && selectedBefore.includes(CORE_BETA_SKILL_CREATOR_IDENTITY)
    && taskIds.every((value) => value === taskId)
    && Number(after?.task?.send_count || 0) >= Number(before?.task?.send_count || 0) + prompts.length
    && prompts.every((item) => String(item?.prompt || '').includes('qa-meeting-minutes-'))
    && (
      selectedPostSend.includes(CORE_BETA_SKILL_CREATOR_IDENTITY)
      || selectedBefore.includes(CORE_BETA_SKILL_CREATOR_IDENTITY)
    )
  );
  return {
    schema_version: 'qbot-core-beta-skill-creator-selection/v1',
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: oracleValid,
    exact_creator_expected: CORE_BETA_SKILL_CREATOR_IDENTITY,
    task_id: taskId,
    selected_before: selectedBefore,
    selected_post_send: selectedPostSend,
    before: coreBetaSkillCreatorStateSummary(before),
    post_send: snapshots.map(coreBetaSkillCreatorStateSummary),
    after: coreBetaSkillCreatorStateSummary(after),
    prompts,
  };
}

export function coreBetaSkillCreatorCleanup(plan = {}) {
  const { qbot_home: qbotHome, slug, baseline } = plan;
  const expected = coreBetaSkillCreatorProjectionPaths(qbotHome, slug);
  const baselineByRuntime = new Map(
    (Array.isArray(baseline?.projections) ? baseline.projections : [])
      .map((item) => [item.runtime, item]),
  );
  const baselineMemoryFiles = new Set(
    (Array.isArray(baseline?.memory_readback?.files) ? baseline.memory_readback.files : [])
      .filter((item) => item?.exists === true)
      .map((item) => path.resolve(String(item.path || ''))),
  );
  const actions = [];
  for (const item of expected) {
    const baselineItem = baselineByRuntime.get(item.runtime);
    const exactTarget = coreBetaPathInside(qbotHome, item.directory)
      && path.basename(item.directory) === slug
      && item.directory === path.join(path.resolve(qbotHome), item.runtime === 'claude' ? '.claude' : '.agents', 'skills', slug);
    if (!exactTarget || baselineItem?.exists === true) {
      actions.push({ runtime: item.runtime, directory: item.directory, removed: false, safe: false, reason: 'unsafe_or_preexisting_target' });
      continue;
    }
    if (!fs.existsSync(item.directory)) {
      actions.push({ runtime: item.runtime, directory: item.directory, removed: false, safe: true, reason: 'already_absent' });
      continue;
    }
    try {
      const stats = fs.lstatSync(item.directory);
      if (!stats.isDirectory() || stats.isSymbolicLink()) {
        actions.push({ runtime: item.runtime, directory: item.directory, removed: false, safe: false, reason: 'target_not_real_directory' });
        continue;
      }
      fs.rmSync(item.directory, { recursive: true, force: false });
      actions.push({ runtime: item.runtime, directory: item.directory, removed: true, safe: true, reason: 'removed_run_owned_fixture' });
    } catch (error) {
      actions.push({
        runtime: item.runtime,
        directory: item.directory,
        removed: false,
        safe: false,
        reason: 'cleanup_io_error',
        error: String(error?.message || error),
      });
    }
  }
  const memoryReadback = coreBetaSkillCreatorMemoryReadback(qbotHome, slug);
  if (!memoryReadback.observed) {
    actions.push({ runtime: 'claude-memory', removed: false, safe: false, reason: memoryReadback.error || 'memory_readback_failed' });
  } else {
    for (const item of memoryReadback.files) {
      const target = path.resolve(item.path);
      const safe = coreBetaPathInside(qbotHome, target)
        && path.basename(target) === `${slug}.md`
        && !baselineMemoryFiles.has(target)
        && item.regular_file === true
        && item.symlink_free === true
        && item.slug_present === true;
      if (!safe) {
        actions.push({ runtime: 'claude-memory', file: target, removed: false, safe: false, reason: 'unsafe_or_preexisting_memory' });
        continue;
      }
      try {
        fs.unlinkSync(target);
        actions.push({ runtime: 'claude-memory', file: target, removed: true, safe: true, reason: 'removed_run_owned_fixture_memory' });
      } catch (error) {
        actions.push({
          runtime: 'claude-memory',
          file: target,
          removed: false,
          safe: false,
          reason: 'cleanup_io_error',
          error: String(error?.message || error),
        });
      }
    }
  }
  const remaining = [
    ...expected.filter((item) => fs.existsSync(item.directory)).map((item) => item.directory),
    ...coreBetaSkillCreatorMemoryReadback(qbotHome, slug).files
      .filter((item) => fs.existsSync(item.path))
      .map((item) => item.path),
  ];
  const valid = actions.length >= 2 && actions.every((item) => item.safe) && remaining.length === 0;
  return {
    schema_version: 'qbot-core-beta-skill-creator-cleanup/v1',
    valid,
    slug,
    qbot_home: path.resolve(qbotHome),
    actions,
    remaining,
  };
}

function writeCoreBetaSkillCreatorCleanupEvidence({ state, caseDir }) {
  const existing = state.artifacts.skill_creator_fixture_cleanup;
  if (typeof existing === 'string' && fs.existsSync(existing)) {
    return JSON.parse(fs.readFileSync(existing, 'utf8'));
  }
  const cleanup = coreBetaSkillCreatorCleanup(state.artifacts.core_beta_skill_creator_cleanup_plan);
  const cleanupFile = path.join(caseDir, 'skill-creator-fixture-cleanup.json');
  writeJsonFile(cleanupFile, cleanup);
  state.artifacts.skill_creator_fixture_cleanup = cleanupFile;
  recordAssertion(
    state,
    'Skill Creator本轮唯一QA产物清理',
    '只允许删除本 Case 基线中不存在、由唯一 fixture slug 新建的 Claude/Codex 投影，并证明两个目录均已消失。',
    cleanup.valid,
    JSON.stringify(cleanup),
    'automation_error',
  );
  return cleanup;
}

async function executeCoreBetaSkillCase({ page, state, testCase, caseDir, timeoutMs, options = {} }) {
  if (testCase.case_type === 'skill_lifecycle') {
    await openCoreBetaSkillSurface(page, state);
    const ledger = readCoreBetaSuiteLedger(caseDir);
    ledger.skills ||= {};
    if (testCase.id === 'BETA-SKILL-001') {
      await selectCoreBetaSkillTab(page, '已安装');
      const before = await readCoreBetaSkillCatalog(page);
      const qaSkills = Array.isArray(ledger.skills.selected) ? ledger.skills.selected : [];
      const qaKeys = new Set(qaSkills.map((item) => item.qualified_identity));
      const attemptedIdentities = before.installed
        .map(skillQualifiedIdentity)
        .filter((identity) => qaKeys.has(identity));
      const untouchedBefore = before.installed
        .filter((item) => !qaKeys.has(skillQualifiedIdentity(item)))
        .map(skillQualifiedIdentity).sort();
      const cleanupTargets = before.installed.filter((item) => qaKeys.has(skillQualifiedIdentity(item)));
      const uninstall = await uninstallCoreBetaRunOwnedSkillTargets(page, cleanupTargets);
      const removed = uninstall.receipts;
      const absenceReadback = uninstall.absence_readback;
      const after = absenceReadback.catalog || { installed: [], market: [], history: [] };
      const remaining = after.installed.map(skillQualifiedIdentity).filter((identity) => qaKeys.has(identity));
      const untouchedAfter = after.installed.map(skillQualifiedIdentity).filter((key) => !qaKeys.has(key)).sort();
      const cleanupVerdict = coreBetaRunOwnedSkillCleanupVerdict({
        attemptedIdentities,
        receipts: removed,
        remainingIdentities: remaining,
        untouchedBefore,
        untouchedAfter,
        absenceReadback,
      });
      await selectCoreBetaSkillTab(page, '技能市场');
      const file = path.join(caseDir, 'capability-inventory.json');
      writeJsonFile(file, {
        valid: cleanupVerdict.valid,
        source: 'catalog.installed',
        active_tab_before: 'installed',
        active_tab_after: 'market',
        before,
        attempted_identities: attemptedIdentities,
        removed,
        uninstall_attempt_waves: uninstall.waves,
        after,
        remaining,
        absence_readback: { ...absenceReadback, catalog: undefined },
        cleanup_verdict: cleanupVerdict,
        untouched_before: untouchedBefore,
        untouched_after: untouchedAfter,
      });
      state.artifacts.capability_inventory = file;
      state.artifacts.capability_selection = file;
      state.artifacts.capability_execution_event = file;
      recordAssertion(
        state,
        'QA Skill 精确清理不影响用户技能',
        '只允许卸载上一轮QA账本精确命中的qualified identity；目标必须连续两次从已安装目录消失，其他identity/version必须保持。',
        cleanupVerdict.valid,
        `attempted=${attemptedIdentities.length}; removed=${removed.length}; remaining=${remaining.length}; stableAbsent=${absenceReadback.stable_absent_observations}; untouched=${untouchedAfter.length}`,
        cleanupVerdict.valid ? '' : 'automation_error',
      );
      return;
    }
    if (testCase.id === 'BETA-SKILL-002') {
      await selectCoreBetaSkillTab(page, '技能市场');
      const refresh = page.locator('[data-testid="skills-catalog-refresh"]').first();
      if (await visible(refresh, 1_000)) await refresh.click({ force: true });
      await page.waitForTimeout(1_000);
      const catalog = await readCoreBetaSkillCatalog(page);
      const selected = chooseCoreBetaMarketSkills(catalog, 10);
      const withDetail = [];
      for (const skill of selected) {
        const detailLookup = await page.evaluate(async (item) => {
          const candidates = [...new Set([
            item.upstreamId,
            item.resourceId,
            item.id,
            item.namespace && (item.slug || item.name)
              ? `${item.namespace}/${item.slug || item.name}`
              : '',
            item.slug,
            item.name,
          ].map((value) => String(value || '').trim()).filter(Boolean))];
          const attempts = [];
          for (const candidate of candidates) {
            try {
              const raw = await window.agent.getSkillDetail(candidate);
              const value = raw?.detail || raw?.data || raw || null;
              attempts.push({
                candidate,
                returned: Boolean(value),
                keys: value && typeof value === 'object' ? Object.keys(value).sort() : [],
              });
              if (value) return { value, selected_candidate: candidate, attempts };
            } catch (error) {
              attempts.push({
                candidate,
                returned: false,
                keys: [],
                error: String(error?.message || error),
              });
            }
          }
          return { value: null, selected_candidate: '', attempts };
        }, skill);
        const detail = detailLookup.value;
        const frozenSample = {
          qualified_identity: skillQualifiedIdentity(skill),
          namespace: skill.namespace || 'global',
          slug: skill.slug || skill.name,
          label: skill.label || skill.displayName || skill.name,
          version: skill.latestVersion || skill.version || null,
          market: skill,
          detail: detail ? {
            markdown: detail.markdown || detail.body || '',
            body: detail.body || '',
            readme: detail.readme || detail.content || '',
            frontmatter: detail.frontmatter || {},
          } : null,
          detail_lookup: {
            selected_candidate: detailLookup.selected_candidate,
            attempts: detailLookup.attempts,
          },
        };
        frozenSample.prompt_source = coreBetaSkillPromptSource(frozenSample);
        withDetail.push(frozenSample);
      }
      if (withDetail.length < 10) {
        markBlocked(state, `技能市场真实可安装样本不足10个：catalog.market eligible=${withDetail.length}`);
        return;
      }
      ledger.skills.selected = withDetail;
      ledger.skills.deep_use = withDetail.slice(0, 5);
      ledger.skills.baseline_installed = catalog.installed.map(skillQualifiedIdentity).sort();
      ledger.skills.selection_seed = String(testCase.version_scope || testCase.id);
      const ledgerFile = writeCoreBetaSuiteLedger(caseDir, ledger);
      const file = path.join(caseDir, 'capability-selection.json');
      const identitiesUnique = withDetail.length === 10
        && new Set(withDetail.map((item) => item.qualified_identity)).size === 10;
      const deepUsePromptSourcesValid = withDetail.slice(0, 5)
        .every((item) => coreBetaSkillPromptSource(item).valid === true);
      writeJsonFile(file, {
        valid: true,
        evidence_valid: true,
        oracle_valid: identitiesUnique && deepUsePromptSourcesValid,
        source: 'catalog.market',
        active_tab: 'market',
        market_status: catalog.marketStatus || catalog.marketSource || null,
        eligible_market_count: chooseCoreBetaMarketSkills(catalog, Number.MAX_SAFE_INTEGER).length,
        deep_use_prompt_source_valid_count: withDetail.slice(0, 5)
          .filter((item) => coreBetaSkillPromptSource(item).valid === true).length,
        selected: withDetail,
        ledger_file: ledgerFile,
      });
      state.artifacts.capability_inventory = file;
      state.artifacts.capability_selection = file;
      state.artifacts.capability_execution_event = file;
      recordAssertion(state, '技能市场10个确定性样本', '必须从catalog.market选择10个未安装且qualified identity唯一的样本。', identitiesUnique, `selected=${withDetail.length}`);
      recordAssertion(
        state,
        '深度使用样本冻结说明来源',
        'deep_use前5个固定样本必须冻结可校验的README/body/市场description内容与SHA；来源缺失是产品负向结果，不能拖到使用Case抛异常。',
        deepUsePromptSourcesValid,
        `valid=${withDetail.slice(0, 5).filter((item) => coreBetaSkillPromptSource(item).valid === true).length}/5`,
        'bug',
      );
      return;
    }
    if (['BETA-SKILL-003', 'BETA-SKILL-004'].includes(testCase.id)) {
      await selectCoreBetaSkillTab(page, '技能市场');
      const selected = Array.isArray(ledger.skills.selected) ? ledger.skills.selected : [];
      const offset = testCase.id.endsWith('003') ? 0 : 5;
      const targets = selected.slice(offset, offset + 5);
      if (targets.length !== 5) throw new Error(`${testCase.id} 缺少BETA-SKILL-002生成的5个确定性样本`);
      const receipts = [];
      for (const target of targets) {
        const card = page.locator('.skill-card').filter({ hasText: target.label }).first();
        if (!await visible(card, 5_000)) throw new Error(`技能市场卡不可见：${target.qualified_identity}`);
        const button = card.locator('.skill-install').first();
        if (!await visible(button, 2_000)) throw new Error(`安装技能按钮不可见：${target.qualified_identity}`);
        const before = await shot(page, caseDir, `skill-install-${slugify(target.slug)}-before`);
        const startedAt = new Date().toISOString();
        await button.click({ force: true });
        const feedback = page.locator('[data-testid="skill-operation-feedback"]').first();
        await feedback.waitFor({ state: 'visible', timeout: 15_000 }).catch(() => {});
        await page.waitForFunction((label) => {
          const node = document.querySelector('[data-testid="skill-operation-feedback"]');
          return Boolean(node && (node.textContent || '').includes(label));
        }, target.label, { timeout: 5_000 }).catch(() => {});
        const pendingFeedback = await readCoreBetaSkillOperationFeedback(page, target.label);
        const pending = await shot(page, caseDir, `skill-install-${slugify(target.slug)}-pending`);
        const terminalTimeoutMs = 120_000;
        const terminalWaitStartedAt = Date.now();
        let terminalWaitTimedOut = false;
        await page.waitForFunction(({ label, allowUnlabeledTerminal }) => {
          const feedbackNode = document.querySelector('[data-testid="skill-operation-feedback"]');
          if (!feedbackNode) return false;
          const text = String(feedbackNode.textContent || '');
          const terminal = feedbackNode.classList.contains('success')
            || feedbackNode.classList.contains('error');
          return terminal && (text.includes(label) || allowUnlabeledTerminal);
        }, {
          label: target.label,
          allowUnlabeledTerminal: pendingFeedback.observed === true
            && pendingFeedback.status === 'pending',
        }, { timeout: terminalTimeoutMs }).catch(() => {
          terminalWaitTimedOut = true;
        });
        let terminalWaitedMs = Date.now() - terminalWaitStartedAt;
        if (terminalWaitTimedOut && terminalWaitedMs < terminalTimeoutMs) {
          await new Promise((resolve) => setTimeout(resolve, terminalTimeoutMs - terminalWaitedMs));
          terminalWaitedMs = Date.now() - terminalWaitStartedAt;
        }
        const terminalFeedback = await readCoreBetaSkillOperationFeedback(page, target.label);
        const terminalStatus = ['success', 'error'].includes(terminalFeedback.status);
        terminalFeedback.action_bound = terminalFeedback.observed === true
          || (
            pendingFeedback.observed === true
            && pendingFeedback.status === 'pending'
            && terminalFeedback.surface_observed === true
            && terminalStatus
          );
        const terminalOutcome = terminalStatus && terminalFeedback.action_bound
          ? 'feedback_terminal'
          : terminalWaitTimedOut ? 'timed_out' : 'unbound_terminal';
        const catalog = await readCoreBetaSkillCatalog(page);
        const installed = catalog.installed.find((item) => (
          (item.slug || item.name) === target.slug
          && (!target.namespace || !item.namespace || item.namespace === target.namespace)
        ));
        const after = await shot(page, caseDir, `skill-install-${slugify(target.slug)}-after`);
        const operationReceipts = coreBetaSkillInstallReceiptsFromFeedback(terminalFeedback, installed);
        const receipt = {
          qualified_identity: target.qualified_identity,
          before,
          pending,
          after,
          started_at: startedAt,
          ended_at: new Date().toISOString(),
          clicked: true,
          pending_observed: pendingFeedback.observed && pendingFeedback.status === 'pending',
          pending_feedback: pendingFeedback,
          terminal_feedback: terminalFeedback,
          terminal_outcome: terminalOutcome,
          terminal_timeout_ms: terminalTimeoutMs,
          terminal_waited_ms: terminalWaitedMs,
          catalog_installed_checked: true,
          installed: Boolean(installed),
          installed_readback: installed || null,
          feedback: terminalFeedback.message,
          ...operationReceipts,
        };
        receipt.oracle_passed = Boolean(
          receipt.installed
          && receipt.pending_observed
          && receipt.terminal_feedback.status === 'success'
          && receipt.api_receipt.install_ok === true
          && receipt.reconcile_receipt.ok === true
        );
        receipt.status = receipt.oracle_passed ? 'passed' : 'failed';
        receipt.failure_category = receipt.oracle_passed ? '' : 'bug';
        receipt.failure_reason = receipt.oracle_passed
          ? ''
          : !receipt.installed
            ? `技能安装未进入catalog.installed终态：${target.qualified_identity}`
            : !receipt.pending_observed
              ? `技能安装未观察到pending终态：${target.qualified_identity}`
              : `技能安装或本机reconcile未成功：${target.qualified_identity}；feedback=${receipt.feedback}`;
        receipts.push(receipt);
        recordStep(
          state,
          `安装固定 Skill 样本：${target.qualified_identity}`,
          '必须从市场卡点击安装并保存 pending、终态反馈和 catalog.installed 读回。',
          receipt.oracle_passed
            ? `安装成功并进入 catalog.installed；feedback=${receipt.feedback}`
            : `${receipt.failure_reason}；feedback=${receipt.feedback}`,
          receipt.oracle_passed ? 'passed' : 'failed',
          after,
          receipt.oracle_passed ? '' : 'bug',
        );
      }
      const assessment = coreBetaSkillInstallBatchAssessment(receipts, 5);
      const persistedReceipts = receipts.map((item) => ({
        ...item,
        source_case_id: testCase.id,
      }));
      ledger.skills.install_receipts = [
        ...(ledger.skills.install_receipts || []),
        ...persistedReceipts.filter((item) => item.oracle_passed),
      ];
      ledger.skills.install_attempt_receipts = [
        ...(ledger.skills.install_attempt_receipts || []),
        ...persistedReceipts,
      ];
      writeCoreBetaSuiteLedger(caseDir, ledger);
      const file = path.join(caseDir, 'capability-execution-event.json');
      writeJsonFile(file, { ...assessment, receipts });
      state.artifacts.capability_inventory = file;
      state.artifacts.capability_selection = file;
      state.artifacts.capability_execution_event = file;
      recordAssertion(
        state,
        '5个Skill逐项安装终态',
        '每个固定样本必须有UI按钮动作、before/pending/terminal截图及catalog.installed读回；产品失败项不得写入成功账本。',
        assessment.oracle_valid,
        `evidence_valid=${assessment.valid}; installed=${assessment.installed_count}/5; failed=${assessment.failed_identities.join(',')}`,
      );
      return;
    }
    if (testCase.id === 'BETA-SKILL-005') {
      const prerequisite = coreBetaSkillInstallPrerequisiteBlocker(ledger, {
        expectedCount: 10,
        dependentCaseId: testCase.id,
      });
      if (!prerequisite.valid) {
        throw new Error(`${testCase.id} 无法验证上游10个Skill安装终态账本：${prerequisite.reason}`);
      }
      if (prerequisite.applicable) {
        applyCoreBetaSkillPrerequisiteBlocker({ state, testCase, caseDir, blocker: prerequisite });
        return;
      }
      await selectCoreBetaSkillTab(page, '技能市场');
      const catalog = await readCoreBetaSkillCatalog(page);
      const selected = Array.isArray(ledger.skills.selected) ? ledger.skills.selected : [];
      const installedKeys = new Set(catalog.installed.map(skillQualifiedIdentity));
      const present = selected.filter((item) => installedKeys.has(item.qualified_identity));
      const marketByIdentity = new Map(catalog.market.map((item) => [skillQualifiedIdentity(item), item]));
      const marketInstalled = selected.filter((item) => marketByIdentity.get(item.qualified_identity)?.installed === true);
      await selectCoreBetaSkillTab(page, '历史');
      const historyCatalog = await readCoreBetaSkillCatalog(page);
      const historyText = JSON.stringify(historyCatalog.history || []);
      const historyPresent = selected.filter((item) => (
        historyText.includes(item.qualified_identity)
        || historyText.includes(item.slug)
      ));
      await openNewTask(page, state);
      const manualMenuOpened = await setSkillMode(page, state, caseDir, 'manual');
      const menuText = await activeMenuText(page, 'skill');
      const composerVisible = selected.filter((item) => menuText.includes(item.label));
      const file = path.join(caseDir, 'capability-inventory.json');
      const oracleValid = marketInstalled.length === 10
        && present.length === 10
        && historyPresent.length === 10
        && manualMenuOpened
        && composerVisible.length === 10;
      writeJsonFile(file, {
        valid: true,
        oracle_valid: oracleValid,
        selected,
        market_installed: marketInstalled.map((item) => item.qualified_identity),
        installed: present.map((item) => item.qualified_identity),
        history: historyCatalog.history,
        history_present: historyPresent.map((item) => item.qualified_identity),
        composer_menu_opened: manualMenuOpened,
        composer_menu_text: menuText,
        composer_visible: composerVisible.map((item) => item.qualified_identity),
      });
      state.artifacts.capability_inventory = file;
      state.artifacts.capability_selection = file;
      state.artifacts.capability_execution_event = file;
      recordAssertion(
        state,
        '10个Skill市场/已安装/历史/Composer闭环',
        '同一10个qualified identity必须在市场、已安装、历史和Composer手动列表中一致。',
        oracleValid,
        `marketInstalled=${marketInstalled.length}; installed=${present.length}; history=${historyPresent.length}; composerMenu=${manualMenuOpened}; composer=${composerVisible.length}`,
      );
      return;
    }
    if (testCase.id === 'BETA-SKILL-012') {
      await selectCoreBetaSkillTab(page, '已安装');
      const selected = Array.isArray(ledger.skills.selected) ? ledger.skills.selected : [];
      if (selected.length !== 10) throw new Error('BETA-SKILL-012 缺少10个QA安装账本样本');
      const prerequisite = coreBetaSkillInstallPrerequisiteBlocker(ledger, {
        expectedCount: 10,
        dependentCaseId: testCase.id,
      });
      if (!prerequisite.valid) {
        throw new Error(`${testCase.id} 无法验证上游10个Skill安装终态账本：${prerequisite.reason}`);
      }
      const before = await readCoreBetaSkillCatalog(page);
      const installedTargets = selected.filter((target) => (
        before.installed.some((item) => skillQualifiedIdentity(item) === target.qualified_identity)
      ));
      const first = installedTargets[0] || null;
      const cancelReceipt = {
        target_identity: first?.qualified_identity || '',
        card_visible: false,
        menu_visible: false,
        delete_visible: false,
        dialog_visible: false,
        cancel_visible: false,
        clicked: false,
      };
      if (first) {
        const firstCard = page.locator('.skill-card').filter({ hasText: first.label }).first();
        cancelReceipt.card_visible = await visible(firstCard, 2_000);
        const more = firstCard.locator('.skill-card-more-trigger').first();
        cancelReceipt.menu_visible = cancelReceipt.card_visible && await visible(more, 1_000);
        if (cancelReceipt.menu_visible) {
          await more.click({ force: true }).catch(() => {});
          const remove = firstCard.locator('.skill-card-more-delete').first();
          cancelReceipt.delete_visible = await visible(remove, 1_000);
          if (cancelReceipt.delete_visible) {
            await remove.click({ force: true }).catch(() => {});
            const dialog = page.locator('[data-testid="skill-uninstall-dialog"]').first();
            cancelReceipt.dialog_visible = await visible(dialog, 2_000);
            const cancel = page.locator('[data-testid="skill-uninstall-cancel"]').first();
            cancelReceipt.cancel_visible = cancelReceipt.dialog_visible && await visible(cancel, 1_000);
            if (cancelReceipt.cancel_visible) {
              await cancel.click({ force: true }).catch(() => {});
              cancelReceipt.clicked = true;
            }
          }
        }
      }
      cancelReceipt.screenshot = await shot(page, caseDir, 'skill-uninstall-cancel-terminal');
      const afterCancel = await readCoreBetaSkillCatalog(page);
      const cancelKept = Boolean(first && cancelReceipt.clicked && afterCancel.installed.some(
        (item) => skillQualifiedIdentity(item) === first.qualified_identity,
      ));
      const cleanupTargets = installedTargets
        .map((target) => afterCancel.installed.find((item) => skillQualifiedIdentity(item) === target.qualified_identity))
        .filter(Boolean);
      const uninstall = await uninstallCoreBetaRunOwnedSkillTargets(page, cleanupTargets);
      const receipts = uninstall.receipts;
      const absenceReadback = uninstall.absence_readback;
      const after = absenceReadback.catalog || { installed: [], market: [], history: [] };
      const remaining = after.installed.filter((item) => selected.some((target) => target.qualified_identity === skillQualifiedIdentity(item)));
      const baseline = new Set(ledger.skills.baseline_installed || []);
      const unrelatedAfter = after.installed.map(skillQualifiedIdentity).filter((key) => baseline.has(key)).sort();
      const unrelatedBefore = before.installed.map(skillQualifiedIdentity).filter((key) => baseline.has(key)).sort();
      const cleanupVerdict = coreBetaRunOwnedSkillCleanupVerdict({
        attemptedIdentities: installedTargets.map((item) => item.qualified_identity),
        receipts,
        remainingIdentities: remaining.map(skillQualifiedIdentity),
        untouchedBefore: unrelatedBefore,
        untouchedAfter: unrelatedAfter,
        absenceReadback,
      });
      const cleanupValid = cleanupVerdict.valid;
      const oracleValid = !prerequisite.applicable
        && installedTargets.length === 10
        && cancelKept
        && cleanupValid
        && receipts.every((item) => item.result.ok === true);
      const file = path.join(caseDir, 'capability-execution-event.json');
      writeJsonFile(file, {
        valid: true,
        oracle_valid: oracleValid,
        before,
        installed_target_count: installedTargets.length,
        cancel_receipt: cancelReceipt,
        cancel_kept: cancelKept,
        receipts,
        uninstall_attempt_waves: uninstall.waves,
        after,
        remaining: remaining.map(skillQualifiedIdentity),
        absence_readback: { ...absenceReadback, catalog: undefined },
        cleanup_verdict: cleanupVerdict,
        unrelated_before: unrelatedBefore,
        unrelated_after: unrelatedAfter,
        cleanup_valid: cleanupValid,
      });
      state.artifacts.capability_inventory = file;
      state.artifacts.capability_selection = file;
      state.artifacts.capability_execution_event = file;
      recordAssertion(
        state,
        '本轮成功安装 Skill 定向清理',
        '不论上游安装是否全量成功，都必须清理本轮真实安装成功的identity且不影响基线技能。',
        cleanupValid,
        `installedTargets=${installedTargets.length}; receipts=${receipts.length}; remaining=${remaining.length}; unrelatedPreserved=${JSON.stringify(unrelatedBefore) === JSON.stringify(unrelatedAfter)}`,
        cleanupValid ? 'bug' : 'automation_error',
      );
      if (prerequisite.applicable) {
        applyCoreBetaSkillPrerequisiteBlocker({
          state,
          testCase,
          caseDir,
          blocker: prerequisite,
          extra: {
            cleanup_evidence: file,
            cleanup_valid: cleanupValid,
          },
        });
        return;
      }
      recordAssertion(
        state,
        'Skill取消卸载与确认卸载闭环',
        '取消必须保留样本，确认后10个样本全部移除且不影响基线技能。',
        oracleValid,
        `cancelKept=${cancelKept}; removed=${receipts.length}; remaining=${remaining.length}`,
      );
      return;
    }
    if (testCase.id === 'BETA-SKILL-014') {
      const beforeCatalog = await readCoreBetaSkillCatalog(page);
      const create = page.locator('[data-testid="create-skill-top"]').first();
      if (!await visible(create, 2_000)) throw new Error('创建技能入口不可见');
      await create.click({ force: true });
      await expectVisibleCoreLocator(page, '[data-testid="composer-input"]', 'Skill Creator任务输入区');
      const qbotHome = coreBetaProductHomeForUi({
        uiUrl: page.url(),
        options,
      });
      if (!qbotHome) throw new Error(`无法从 QWork UI URL 推断 Skill Creator home：${page.url()}`);
      const fixture = coreBetaSkillCreatorFixture({ qbotHome, caseDir });
      state.artifacts.core_beta_skill_creator_cleanup_plan = {
        qbot_home: fixture.qbot_home,
        slug: fixture.slug,
        baseline: fixture.baseline,
      };
      const fixtureCase = coreBetaSkillCreatorConversationCase(testCase, fixture.slug);
      const identityBeforeSend = await captureCoreBetaPublicState(page, fixtureCase);
      await executeConversationTurns({ page, state, testCase: fixtureCase, caseDir, timeoutMs });
      const identityAfter = await captureCoreBetaPublicState(page, fixtureCase);
      const selectionEvidence = coreBetaSkillCreatorSelectionEvidence({
        before: identityBeforeSend,
        postSend: state.artifacts.core_beta_skill_creator_post_send_snapshots || [],
        after: identityAfter,
        prompts: state.artifacts.sent_prompts || [],
      });
      const selectionFile = path.join(caseDir, 'capability-selection.json');
      writeJsonFile(selectionFile, selectionEvidence);
      state.artifacts.capability_selection = selectionFile;
      state.artifacts.core_beta_capability_selection = selectionEvidence;
      const afterCatalog = await readCoreBetaSkillCatalog(page);
      const beforeKeys = new Set([
        ...beforeCatalog.installed,
        ...beforeCatalog.market,
      ].map(skillQualifiedIdentity));
      const catalogCreated = [...afterCatalog.installed, ...afterCatalog.market]
        .filter((item) => !beforeKeys.has(skillQualifiedIdentity(item)));
      const projection = coreBetaSkillCreatorProjectionReadback({
        qbotHome: fixture.qbot_home,
        slug: fixture.slug,
        baseline: fixture.baseline,
      });
      const creatorHidden = ![...afterCatalog.installed, ...afterCatalog.market]
        .some((item) => JSON.stringify(item).includes(CORE_BETA_SKILL_CREATOR_IDENTITY));
      const catalogIsolated = catalogCreated.every((item) => (
        String(item?.slug || item?.name || '') === fixture.slug
      ));
      const evidenceValid = Boolean(selectionEvidence.evidence_valid && projection.evidence_valid);
      const oracleValid = Boolean(
        evidenceValid
        && selectionEvidence.oracle_valid
        && projection.oracle_valid
        && creatorHidden
        && catalogIsolated
      );
      const output = {
        schema_version: 'qbot-core-beta-skill-creator-readback/v2',
        valid: evidenceValid,
        evidence_valid: evidenceValid,
        oracle_valid: oracleValid,
        fixture_slug: fixture.slug,
        exact_creator_expected: CORE_BETA_SKILL_CREATOR_IDENTITY,
        selection: selectionEvidence,
        projection,
        creator_hidden_from_catalog: creatorHidden,
        catalog_isolated: catalogIsolated,
        catalog_created: catalogCreated,
        before_counts: { installed: beforeCatalog.installed.length, market: beforeCatalog.market.length },
        after_counts: { installed: afterCatalog.installed.length, market: afterCatalog.market.length },
      };
      const contentFile = path.join(caseDir, 'skill-creator-content-readback.json');
      writeJsonFile(contentFile, output);
      const shaFile = path.join(caseDir, 'skill-creator-artifact-sha256.json');
      writeJsonFile(shaFile, {
        schema_version: 'qbot-core-beta-skill-creator-artifact-sha256/v2',
        valid: projection.evidence_valid,
        evidence_valid: projection.evidence_valid,
        oracle_valid: projection.oracle_valid,
        fixture_slug: fixture.slug,
        projections: projection.projections.map((item) => ({
          runtime: item.runtime,
          path: item.file,
          exists: item.exists,
          bytes: item.bytes || 0,
          sha256: item.sha256 || '',
        })),
      });
      state.artifacts.content_readback = contentFile;
      state.artifacts.artifact_path_sha256 = shaFile;
      state.artifacts.core_beta_content_readback = output;
      state.artifacts.core_beta_artifact_path_sha256 = {
        valid: projection.evidence_valid,
        oracle_valid: projection.oracle_valid,
        projections: projection.projections.map((item) => ({
          runtime: item.runtime,
          path: item.file,
          sha256: item.sha256 || '',
        })),
      };
      state.artifacts.core_beta_capability_execution = selectionEvidence;
      state.artifacts.core_beta_skill_execution_trace = {
        valid: evidenceValid,
        oracle_valid: oracleValid,
        fixture_slug: fixture.slug,
        selection: selectionEvidence,
        projection: {
          evidence_valid: projection.evidence_valid,
          oracle_valid: projection.oracle_valid,
          created_runtimes: projection.created_runtimes,
        },
      };
      state.artifacts.skill_runtime_readiness = contentFile;
      recordAssertion(
        state,
        'Skill Creator task-bound与双投影取证完整',
        '必须保存发送前 exact creator、发送后 taskId、实际 prompt、双投影存在/缺失终态和 SHA 读回；产品未创建产物不能让证据本身失效。',
        evidenceValid,
        JSON.stringify({ selection: selectionEvidence, projection_evidence_valid: projection.evidence_valid }),
        'automation_error',
      );
      recordAssertion(
        state,
        'Skill Creator真实产物读回',
        '唯一QA名称必须在Claude/Codex双投影中新建、内容与SHA一致，exact creator绑定当前task，且内部creator未混入普通市场库存。',
        oracleValid,
        JSON.stringify(output),
        'bug',
      );
      return;
    }
    const inventory = await readCoreBetaSkillCatalog(page);
    const file = path.join(caseDir, 'capability-inventory.json');
    writeJsonFile(file, { valid: true, source: 'catalog', inventory });
    state.artifacts.capability_inventory = file;
    state.artifacts.capability_selection = file;
    state.artifacts.capability_execution_event = file;
    recordAssertion(state, 'Skill 生命周期入口', '技能页必须可见且公开库存可读取。', Boolean(inventory.installed && inventory.market), `installed=${inventory.installed.length}; market=${inventory.market.length}`);
    return;
  }
  const ledger = readCoreBetaSuiteLedger(caseDir);
  const prerequisiteDecision = coreBetaSkillUsePrerequisiteDecision(testCase, ledger);
  const selectedSkill = prerequisiteDecision.applies
    ? prerequisiteDecision.selected_skill
    : ledger.skills?.deep_use?.[0];
  if (prerequisiteDecision.applies) {
    if (!prerequisiteDecision.valid) {
      throw new Error(`${testCase.id} 无法验证目标 Skill 安装终态账本：${prerequisiteDecision.reason}`);
    }
    if (prerequisiteDecision.blocker.applicable) {
      applyCoreBetaSkillPrerequisiteBlocker({
        state,
        testCase,
        caseDir,
        blocker: prerequisiteDecision.blocker,
      });
      return;
    }
  }
  if (testCase.id === 'BETA-SKILL-011') {
    return await executeCoreBetaSkillIsolationCase({ page, state, testCase, caseDir, timeoutMs, ledger });
  }
  if (testCase.id === 'BETA-SKILL-013') {
    return await executeCoreBetaBuiltinSkillCase({ page, state, testCase, caseDir, timeoutMs, ledger, options });
  }
  if (testCase.id === 'BETA-SKILL-015') {
    return await executeCoreBetaSkillConnectorBoundaryCase({ page, state, testCase, caseDir, timeoutMs, ledger, options });
  }
  await openNewTask(page, state);
  const beforeSelection = await captureCoreBetaPublicState(page, testCase);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'manual', connectorMode: 'disabled' })) {
    if (state.artifacts.core_beta_composer_control_reset?.failure_category === 'bug') {
      await materializeCoreBetaPreSendCapabilityFailure({
        page,
        state,
        testCase,
        caseDir,
        capabilityKind: 'skill',
        expectedIdentity: selectedSkill?.qualified_identity || selectedSkill?.slug || selectedSkill?.label || 'first_available_skill',
        before: beforeSelection,
      });
    }
    return;
  }
  if (selectedSkill) {
    if (!await selectManualSkillByName(page, state, caseDir, selectedSkill.label, { ensureMode: false })) {
      if (state.artifacts.core_beta_capability_interaction?.stage === 'manual_skill_selection'
        && state.artifacts.core_beta_capability_interaction?.category === 'bug') {
        await materializeCoreBetaPreSendCapabilityFailure({
          page,
          state,
          testCase,
          caseDir,
          capabilityKind: 'skill',
          expectedIdentity: selectedSkill.qualified_identity || selectedSkill.slug || selectedSkill.label,
          before: beforeSelection,
        });
      }
      return;
    }
    state.artifacts.core_beta_capability_selection = selectedSkill;
  } else if (!await selectFirstManualSkill(page, state, caseDir)) return;
  const selectionFile = path.join(caseDir, 'capability-selection.json');
  writeJsonFile(selectionFile, {
    valid: true,
    selected_skill: selectedSkill || null,
    state: await captureCoreBetaPublicState(page, testCase),
  });
  state.artifacts.capability_selection = selectionFile;
  await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
  const execution = await captureCoreBetaPublicState(page, testCase);
  state.artifacts.core_beta_capability_execution = execution;
  state.artifacts.core_beta_skill_execution_trace = {
    selected_skill: selectedSkill || null,
    task: execution.task,
    selected_skills: execution.skills?.selected || [],
    reply_records: state.artifacts.reply_records || [],
  };
  state.artifacts.capability_execution_event = state.artifacts.reply_completion || state.artifacts.transcript || selectionFile;
}

async function executeCoreBetaSkillIsolationCase({ page, state, testCase, caseDir, timeoutMs, ledger }) {
  const selectedSkill = ledger.skills?.deep_use?.[0];
  if (!selectedSkill) throw new Error(`${testCase.id} 缺少deep_use Skill账本`);
  await openNewTask(page, state);
  const beforeSelection = await captureCoreBetaPublicState(page, testCase);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'manual', connectorMode: 'disabled' })) {
    if (state.artifacts.core_beta_composer_control_reset?.failure_category === 'bug') {
      await materializeCoreBetaPreSendCapabilityFailure({
        page,
        state,
        testCase,
        caseDir,
        capabilityKind: 'skill',
        expectedIdentity: selectedSkill.qualified_identity || selectedSkill.slug || selectedSkill.label,
        before: beforeSelection,
      });
    }
    return;
  }
  if (!await selectManualSkillByName(page, state, caseDir, selectedSkill.label, { ensureMode: false })) {
    if (state.artifacts.core_beta_capability_interaction?.stage === 'manual_skill_selection'
      && state.artifacts.core_beta_capability_interaction?.category === 'bug') {
      await materializeCoreBetaPreSendCapabilityFailure({
        page,
        state,
        testCase,
        caseDir,
        capabilityKind: 'skill',
        expectedIdentity: selectedSkill.qualified_identity || selectedSkill.slug || selectedSkill.label,
        before: beforeSelection,
      });
    }
    return;
  }
  await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
  const taskA = await captureCoreBetaPublicState(page, testCase);
  const taskAId = taskA.task?.id;
  await page.reload({ waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(800);
  const reopened = await reopenSessionAndReadback(page, taskAId);
  const taskAAfterRefresh = await captureCoreBetaPublicState(page, testCase);
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const taskB = await captureCoreBetaPublicState(page, testCase);
  const connectorCalls = await captureCoreBetaToolTrace(page, '__connector_disabled__');
  const trace = {
    valid: Boolean(
      reopened.ok
      && taskAId
      && taskAAfterRefresh.task?.id === taskAId
      && JSON.stringify(taskAAfterRefresh.skills?.selected || []).includes(selectedSkill.slug)
      && (taskB.skills?.selected || []).length === 0
      && (taskB.connectors?.selected || []).length === 0
      && connectorCalls.calls.every((call) => !call.connector)
    ),
    selected_skill: selectedSkill,
    task_a: taskA,
    task_a_after_refresh: taskAAfterRefresh,
    reopened,
    task_b: taskB,
    connector_calls: connectorCalls,
  };
  state.artifacts.core_beta_skill_execution_trace = trace;
  state.artifacts.core_beta_negative_tool_trace = {
    valid: connectorCalls.calls.every((call) => !call.connector),
    calls: connectorCalls.calls,
  };
  state.artifacts.core_beta_capability_selection = { selected_skill: selectedSkill, task_id: taskAId };
  state.artifacts.core_beta_capability_execution = trace;
  recordAssertion(state, 'Skill按task隔离且Connector禁用硬关', '刷新同task保持Skill；新task清空Skill/Connector；禁用Connector不得出现connector tools/call。', trace.valid, JSON.stringify(trace));
}

async function materializeCoreBetaPreSendCapabilityFailure({
  page,
  state,
  testCase,
  caseDir,
  capabilityKind,
  expectedIdentity,
  before,
  interactionSnapshot = null,
}) {
  const after = await captureCoreBetaPublicState(page, testCase);
  const declaredRoles = Array.isArray(testCase.evidence_roles) ? testCase.evidence_roles : [];
  const notApplicableRoles = CORE_BETA_PRE_SEND_CAPABILITY_FAILURE_NA_ROLES
    .filter((role) => declaredRoles.includes(role));
  const noPromptRecorded = !state.artifacts.prompt
    && (!Array.isArray(state.artifacts.sent_prompts) || state.artifacts.sent_prompts.length === 0);
  const noSendReceiptRecorded = !state.artifacts.send_receipt
    && (!Array.isArray(state.artifacts.send_receipts) || state.artifacts.send_receipts.length === 0);
  const interaction = {
    ...(interactionSnapshot || state.artifacts.core_beta_capability_interaction || {}),
    expected_identity: String(expectedIdentity || ''),
  };
  state.artifacts.core_beta_capability_interaction = interaction;
  const evidence = coreBetaPreSendCapabilityFailureEvidence({
    testCaseId: testCase.id,
    capabilityKind,
    expectedIdentity,
    before,
    after,
    interaction,
    noPromptRecorded,
    noSendReceiptRecorded,
    notApplicableRoles,
  });
  const file = path.join(caseDir, 'pre-send-capability-failure.json');
  writeJsonFile(file, evidence);
  state.artifacts.core_beta_pre_send_capability_failure = file;
  if (!evidence.valid) {
    recordAssertion(
      state,
      '发送前能力失败负向证据闭环',
      '产品能力控件点击后未生效时，必须证明任务为空、消息数为0、发送计数未变化且截图完整。',
      false,
      evidence.reason,
      'automation_error',
    );
    return false;
  }
  state.artifacts.capability_selection = file;
  state.artifacts.core_beta_capability_selection = evidence;
  state.artifacts.core_beta_not_applicable_roles = notApplicableRoles.map((role) => ({
    role,
    blocker_path: file,
  }));
  recordAssertion(
    state,
    '发送前能力失败负向证据闭环',
    '产品能力控件点击后未生效时，必须证明任务为空、消息数为0、发送计数未变化且截图完整。',
    true,
    evidence.reason,
  );
  return true;
}

async function executeCoreBetaBuiltinSkillCase({ page, state, testCase, caseDir, timeoutMs, options }) {
  const scenario = coreBetaScenarioSpec(testCase);
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'auto', connectorMode: 'disabled' })) return;
  await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
  const normal = await captureCoreBetaPublicState(page, testCase);
  const normalTrace = await captureCoreBetaToolTrace(page, 'skill-creator-qwork');
  const injected = await invokeCoreBetaFixtureControl({
    options,
    testCase,
    scenario,
    phase: 'inject',
    payload: {
      lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
      fault: 'builtin_guidance_skill_missing',
    },
  });
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'auto', connectorMode: 'disabled' })) return;
  await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
  const missingTrace = await captureCoreBetaToolTrace(page, '__builtin_missing__');
  const replyText = state.artifacts.reply_delta && fs.existsSync(state.artifacts.reply_delta)
    ? fs.readFileSync(state.artifacts.reply_delta, 'utf8')
    : '';
  const noExternalTools = missingTrace.calls.every((call) => !call.connector && !/web|search|mcp/i.test(String(call.name || '')));
  const trace = {
    valid: Boolean(
      injected.ok
      && /skill|guidance|qbot/i.test(JSON.stringify(normal))
      && noExternalTools
      && /不可用|缺失|无法|未安装|未就绪/.test(replyText)
    ),
    normal,
    normal_trace: normalTrace,
    injected,
    missing_trace: missingTrace,
    missing_reply: clip(replyText, 1_000),
  };
  state.artifacts.core_beta_skill_execution_trace = trace;
  state.artifacts.core_beta_negative_tool_trace = { valid: noExternalTools, calls: missingTrace.calls };
  state.artifacts.core_beta_capability_selection = normal;
  state.artifacts.core_beta_capability_execution = trace;
  recordAssertion(state, '内置权威Skill正常命中/缺失fail-closed', '正常时命中发布内置权威Skill；缺失时明确不可用且不得Web/MCP猜测。', trace.valid, JSON.stringify(trace));
}

async function executeCoreBetaSkillConnectorBoundaryCase({ page, state, testCase, caseDir, timeoutMs, ledger, options }) {
  const scenario = coreBetaScenarioSpec(testCase);
  const selectedSkill = ledger.skills?.deep_use?.[0];
  if (!selectedSkill) throw new Error(`${testCase.id} 缺少deep_use Skill账本`);
  const catalog = await captureCoreBetaConnectorCatalog(page);
  const connector = chooseCoreBetaConnectors(catalog.items, 1)[0];
  if (!connector) throw new Error(`${testCase.id} 缺少健康只读Connector样本`);
  const states = ['healthy', 'delivery_unconfirmed', 'disabled', 'permission_denied'];
  const matrix = [];
  for (const connectorState of states) {
    const control = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'state',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        connector_key: connector.key,
        state: connectorState,
      },
    });
    await openNewTask(page, state);
    if (!await resetComposerControls(page, state, caseDir, {
      skillMode: 'manual',
      connectorMode: connectorState === 'disabled' ? 'disabled' : 'manual',
    })) return;
    if (!await selectManualSkillByName(page, state, caseDir, selectedSkill.label, { ensureMode: false })) return;
    if (connectorState !== 'disabled' && !await selectManualConnectorByKey(page, state, caseDir, connector.key)) return;
    await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
    const snapshot = await captureCoreBetaPublicState(page, testCase);
    const toolTrace = await captureCoreBetaToolTrace(page, connector.key);
    const forbiddenCall = ['disabled', 'permission_denied'].includes(connectorState) && toolTrace.calls.some((call) => call.connector || /mcp|connector/i.test(String(call.name || '')));
    matrix.push({
      state: connectorState,
      control,
      task_id: snapshot.task?.id,
      selected_skill: snapshot.skills?.selected || [],
      selected_connector: snapshot.connectors?.selected || [],
      tool_trace: toolTrace,
      valid: !forbiddenCall
        && JSON.stringify(snapshot.skills?.selected || []).includes(selectedSkill.slug),
    });
  }
  const valid = matrix.length === 4
    && new Set(matrix.map((item) => item.task_id)).size === 4
    && matrix.every((item) => item.valid);
  const trace = { valid, selected_skill: selectedSkill, connector, matrix };
  state.artifacts.core_beta_skill_execution_trace = trace;
  state.artifacts.core_beta_connector_prompt_layers = trace;
  state.artifacts.core_beta_negative_tool_trace = {
    valid: matrix.filter((item) => ['disabled', 'permission_denied'].includes(item.state))
      .every((item) => item.tool_trace.calls.every((call) => !call.connector)),
    matrix,
  };
  state.artifacts.core_beta_capability_selection = { selected_skill: selectedSkill, connector };
  state.artifacts.core_beta_capability_execution = trace;
  recordAssertion(state, 'Skill+Connector四状态严格边界', '四个task必须隔离；disabled/permission-denied无调用，delivery-unconfirmed不冒充成功，Skill意图始终保留。', valid, JSON.stringify(trace));
}

const CORE_BETA_EXPERT_AUTHORING_TOOLS = Object.freeze([
  'create_expert_draft',
  'get_expert_draft',
  'update_expert_draft',
  'search_expert_skill_dependencies',
  'resolve_and_bind_expert_skill_dependency',
  'search_expert_mcp_dependencies',
  'resolve_and_bind_expert_mcp_dependency',
  'create_draft_skill_asset',
  'get_draft_skill_asset',
  'update_draft_skill_asset',
  'put_draft_skill_asset_file',
  'resolve_and_bind_draft_skill_dependency',
  'validate_draft_skill_asset',
  'validate_expert_draft',
  'prepare_expert_debug_snapshot',
  'prepare_expert_publish',
  'publish_expert_draft',
]);

function coreBetaExpertEvidenceScreenshotsValid(items, requiredRoles = [], { caseDir = '', state = null } = {}) {
  const screenshots = Array.isArray(items) ? items : [];
  if (screenshots.length < requiredRoles.length) return false;
  const byRole = new Map(screenshots.map((item) => [String(item?.role || ''), item]));
  return requiredRoles.every((role) => {
    const item = byRole.get(role);
    const file = String(item?.path || '').trim();
    if (!item || !path.isAbsolute(file) || !fs.existsSync(file)) return false;
    const resolvedFile = path.resolve(file);
    const resolvedCaseDir = path.resolve(caseDir || path.dirname(file));
    if (resolvedFile !== resolvedCaseDir && !resolvedFile.startsWith(`${resolvedCaseDir}${path.sep}`)) return false;
    const stat = fs.statSync(resolvedFile);
    const declaredSha = String(item.sha256 || '').toLowerCase();
    const declaredBytes = Number(item.bytes || 0);
    if (
      !stat.isFile()
      || stat.size < 2_048
      || declaredBytes !== stat.size
      || !/^[a-f0-9]{64}$/i.test(declaredSha)
      || !/\.(?:png|jpe?g|webp)$/i.test(resolvedFile)
    ) return false;
    const actualSha = createHash('sha256').update(fs.readFileSync(resolvedFile)).digest('hex');
    if (actualSha !== declaredSha) return false;
    if (state?.screenshots) state.screenshots[`fixture_${slugify(role)}`] = resolvedFile;
    return true;
  });
}

function coreBetaExpertTypedFailureValid(value, expectedCode) {
  return String(value?.code || '') === expectedCode
    && Number(value?.mutation_count || value?.mutations || 0) === 0
    && value?.no_partial_state !== false;
}

const CORE_BETA_RUNTIME_PREREQUISITE_NA_ROLES = Object.freeze([
  'expert_draft_lifecycle',
  'expert_builder_trace',
  'capability_selection',
  'capability_execution_event',
  'task_id',
  'prompt',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

function coreBetaRuntimePrerequisiteSnapshot(value = {}) {
  const task = value?.task || {};
  const draftFingerprints = (Array.isArray(value?.expert_drafts) ? value.expert_drafts : [])
    .map((item) => ({
      id: String(item?.id || ''),
      revision: Number(item?.revision || 0),
      etag: String(item?.etag || ''),
      status: String(item?.status || ''),
      sha256: createHash('sha256').update(JSON.stringify(item || null)).digest('hex'),
    }))
    .sort((left, right) => left.id.localeCompare(right.id));
  return {
    task: {
      id: task?.id || null,
      running: Boolean(task?.running),
      send_count: Number(task?.send_count || 0),
      message_count: Number(task?.message_count || 0),
    },
    runtime_family: String(value?.runtime?.family || ''),
    expert: value?.expert || null,
    draft_fingerprints: draftFingerprints,
  };
}

export function coreBetaRuntimeFamilyPrerequisiteBlocker({
  testCase = {},
  targetRuntimeFamily = '',
  error = {},
  before = {},
  after = {},
} = {}) {
  const targetFamily = String(targetRuntimeFamily || '');
  const message = String(error?.message || error || '');
  const reportedCode = String(error?.code || '');
  const beforeView = before?.connection_view || null;
  const afterView = after?.connection_view || null;
  const options = Array.isArray(beforeView?.runtimeOptions?.options)
    ? beforeView.runtimeOptions.options
    : [];
  const afterOptions = Array.isArray(afterView?.runtimeOptions?.options)
    ? afterView.runtimeOptions.options
    : [];
  const targetMatches = options.filter((item) => (
    String(item?.runtimeFamily || '') === targetFamily && item?.disabled !== true
  ));
  const afterTargetMatches = afterOptions.filter((item) => (
    String(item?.runtimeFamily || '') === targetFamily && item?.disabled !== true
  ));
  const beforeSnapshot = coreBetaRuntimePrerequisiteSnapshot(before);
  const afterSnapshot = coreBetaRuntimePrerequisiteSnapshot(after);
  const same = (left, right) => JSON.stringify(left) === JSON.stringify(right);
  const mutationGuard = {
    no_user_action: beforeSnapshot.task.id == null
      && afterSnapshot.task.id == null
      && beforeSnapshot.task.message_count === 0
      && afterSnapshot.task.message_count === 0
      && beforeSnapshot.task.running === false
      && afterSnapshot.task.running === false
      && beforeSnapshot.task.send_count === afterSnapshot.task.send_count,
    task_stable: same(beforeSnapshot.task, afterSnapshot.task),
    runtime_stable: beforeSnapshot.runtime_family === afterSnapshot.runtime_family,
    expert_absent: beforeSnapshot.expert == null && afterSnapshot.expert == null,
    expert_stable: same(beforeSnapshot.expert, afterSnapshot.expert),
    drafts_stable: same(beforeSnapshot.draft_fingerprints, afterSnapshot.draft_fingerprints),
  };
  mutationGuard.valid = Object.values(mutationGuard).every(Boolean);
  const recognized = targetFamily === 'codex'
    && /没有匹配协议的\s*LLM connection/i.test(message);
  const connectionEvidenceValid = options.length > 0
    && afterOptions.length > 0
    && targetMatches.length === 0
    && afterTargetMatches.length === 0
    && same(beforeView?.runtimeOptions?.selected || null, afterView?.runtimeOptions?.selected || null);
  const applicable = Boolean(recognized && connectionEvidenceValid && mutationGuard.valid);
  const declaredRoles = Array.isArray(testCase?.evidence_roles) ? testCase.evidence_roles : [];
  const notApplicableRoles = CORE_BETA_RUNTIME_PREREQUISITE_NA_ROLES
    .filter((role) => declaredRoles.includes(role));
  const viewHash = (view) => createHash('sha256').update(JSON.stringify(view)).digest('hex');
  return {
    schema_version: 'qbot-core-beta-runtime-prerequisite/v1',
    valid: applicable,
    oracle_valid: !applicable,
    applicable,
    kind: 'runtime_family_connection_unavailable',
    source: 'public_connection_view_and_typed_runtime_switch_error',
    dependent_case_id: String(testCase?.id || ''),
    target_runtime_family: targetFamily,
    normalized_error_code: recognized ? 'runtime_connection_protocol_unavailable' : 'unrecognized_runtime_switch_error',
    error: {
      name: String(error?.name || ''),
      reported_code: reportedCode,
      message,
    },
    connection_view: {
      before_options_count: options.length,
      after_options_count: afterOptions.length,
      target_match_count: targetMatches.length,
      after_target_match_count: afterTargetMatches.length,
      selection_stable: same(beforeView?.runtimeOptions?.selected || null, afterView?.runtimeOptions?.selected || null),
      observed_runtime_families: [...new Set(options.map((item) => String(item?.runtimeFamily || '')).filter(Boolean))],
      observed_protocols: [...new Set(options.map((item) => String(item?.protocol || '')).filter(Boolean))],
      before_sha256: viewHash(beforeView),
      after_sha256: viewHash(afterView),
      before: beforeView,
      after: afterView,
    },
    mutation_guard: {
      ...mutationGuard,
      before: beforeSnapshot,
      after: afterSnapshot,
    },
    not_applicable_roles: notApplicableRoles,
    reason: applicable
      ? `运行时前置不可用：${targetFamily} 没有匹配协议的 LLM connection；已确认未发送、未选择专家且未创建草稿。`
      : `运行时切换失败未满足可信前置阻塞合同：${message || 'missing_error_message'}`,
  };
}

function applyCoreBetaRuntimePrerequisiteBlocker({ state, testCase, caseDir, blocker }) {
  const file = path.join(caseDir, 'runtime-family-prerequisite.json');
  writeJsonFile(file, blocker);
  state.artifacts.connection_view_snapshot = file;
  state.artifacts.core_beta_runtime_prerequisite = blocker;
  state.artifacts.core_beta_connection_snapshot_diagnostics = blocker.connection_view;
  state.artifacts.core_beta_not_applicable_roles = blocker.not_applicable_roles.map((role) => ({
    role,
    blocker_path: file,
  }));
  recordAssertion(
    state,
    '目标 runtime connection 前置',
    '只有公开 connection view、精确协议错误与零状态变更同时成立时，才允许在发送前阻塞并标记后续证据不适用。',
    blocker.valid === true && blocker.applicable === true,
    blocker.reason,
    'automation_error',
  );
  markBlocked(state, blocker.reason);
  return file;
}

const CORE_BETA_EXPERT_PREREQUISITE_NA_ROLES = new Set([
  'task_id',
  'prompt',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
  'expert_runtime_trace',
  'capability_selection',
  'capability_execution_event',
  'attachment_name_size_sha256',
  'attachment_readback',
  'artifact_path_sha256',
  'content_readback',
  'preview',
  'credential_redaction_scan',
  'expert_history_readback',
  'negative_ui_trace',
  'expert_publish_operation',
  'restart_trace',
]);

const CORE_BETA_EXPERT_PUBLISH_DRAFT_REQUIREMENTS = Object.freeze([
  { ledger_key: 'claude-code_draft', source_case_id: 'BETA-EXPERT-002', kind: 'research' },
  { ledger_key: 'codex_draft', source_case_id: 'BETA-EXPERT-003', kind: 'data' },
  { ledger_key: 'manual_draft', source_case_id: 'BETA-EXPERT-004', kind: 'delivery' },
]);

export function coreBetaExpertDraftConcurrencyIdentity(value = {}) {
  const id = String(value?.id || value?.draftId || '').trim();
  const etag = String(value?.etag || '').trim();
  const revision = Number(value?.revision);
  const hasRevision = Number.isInteger(revision) && revision > 0;
  return {
    id,
    etag,
    revision: hasRevision ? revision : null,
    cas_kind: etag ? 'etag' : hasRevision ? 'revision' : '',
    cas_value: etag || (hasRevision ? revision : null),
    complete: Boolean(id && (etag || hasRevision)),
  };
}

export function coreBetaExpertPublishPrerequisiteBlocker({
  testCase = {},
  ledgerExperts = {},
  availableDrafts = [],
  publicState = null,
} = {}) {
  const caseId = String(testCase?.id || '');
  if (caseId !== 'BETA-EXPERT-007') {
    return {
      applies: false,
      ready: true,
      valid: true,
      not_applicable_roles: [],
    };
  }
  const requirements = CORE_BETA_EXPERT_PUBLISH_DRAFT_REQUIREMENTS.map((item) => {
    const entry = ledgerExperts?.[item.ledger_key] || null;
    const identity = coreBetaExpertDraftConcurrencyIdentity(entry);
    return {
      ...item,
      present: Boolean(entry),
      ...identity,
    };
  });
  const missingDraftKeys = requirements
    .filter((item) => !item.present)
    .map((item) => item.ledger_key);
  const incompleteDraftKeys = requirements
    .filter((item) => item.present && !item.complete)
    .map((item) => item.ledger_key);
  const ready = requirements.every((item) => item.complete);
  const availableDraftIdentities = (Array.isArray(availableDrafts) ? availableDrafts : [])
    .map((item) => ({
      ...coreBetaExpertDraftConcurrencyIdentity(item),
      status: String(item?.status || ''),
    }))
    .filter((item) => item.id)
    .sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
  if (ready) {
    return {
      schema_version: 'qbot-core-beta-expert-prerequisite/v1',
      applies: true,
      ready: true,
      valid: true,
      applicable: false,
      outcome: 'ready',
      kind: 'run_owned_draft_set_ready',
      dependent_case_id: caseId,
      requirements,
      not_applicable_roles: [],
    };
  }
  const task = publicState?.task || {};
  const selectedSkills = Array.isArray(publicState?.skills?.selected) ? publicState.skills.selected : [];
  const selectedConnectors = Array.isArray(publicState?.connectors?.selected) ? publicState.connectors.selected : [];
  const mutationGuard = {
    case_bound: publicState?.case_id === caseId,
    task_absent: task?.id == null,
    no_messages: Number(task?.message_count || 0) === 0,
    not_running: task?.running !== true,
    send_count_observed: Number.isFinite(Number(task?.send_count)),
    expert_absent: publicState?.expert == null,
    skills_absent: selectedSkills.length === 0,
    connectors_absent: selectedConnectors.length === 0,
  };
  mutationGuard.valid = Boolean(publicState) && Object.values(mutationGuard).every(Boolean);
  const outcome = incompleteDraftKeys.length > 0 ? 'automation_error' : 'blocked';
  const notApplicableRoles = (Array.isArray(testCase?.evidence_roles) ? testCase.evidence_roles : [])
    .filter((role) => CORE_BETA_EXPERT_PREREQUISITE_NA_ROLES.has(role));
  const reason = outcome === 'blocked'
    ? `BETA-EXPERT-007 的本轮草稿前置缺失：${missingDraftKeys.join(',')}；已忽略账号中 ${availableDraftIdentities.length} 个非本轮草稿，未发布且未随机替换。`
    : `BETA-EXPERT-007 的本轮草稿账本身份不完整：${incompleteDraftKeys.join(',')} 缺少 draftId/CAS（etag 或 revision）。`;
  return {
    schema_version: 'qbot-core-beta-expert-prerequisite/v1',
    applies: true,
    ready: false,
    valid: outcome === 'blocked' && mutationGuard.valid,
    oracle_valid: false,
    applicable: true,
    outcome,
    kind: outcome === 'blocked'
      ? 'run_owned_draft_set_missing'
      : 'run_owned_draft_set_identity_incomplete',
    source: 'exact_run_suite_ledger_and_live_draft_inventory',
    dependent_case_id: caseId,
    source_case_ids: requirements.map((item) => item.source_case_id),
    required_draft_keys: requirements.map((item) => item.ledger_key),
    missing_draft_keys: missingDraftKeys,
    incomplete_draft_keys: incompleteDraftKeys,
    requirements,
    ledger_snapshot_sha256: createHash('sha256').update(JSON.stringify(requirements)).digest('hex'),
    available_draft_count: availableDraftIdentities.length,
    available_draft_identities: availableDraftIdentities,
    available_draft_identities_sha256: createHash('sha256')
      .update(JSON.stringify(availableDraftIdentities)).digest('hex'),
    historical_draft_fallback_forbidden: true,
    selected_draft_ids: [],
    mutation_guard: mutationGuard,
    not_applicable_roles: notApplicableRoles,
    reason,
  };
}

function applyCoreBetaExpertPublishPrerequisite({ state, testCase, caseDir, blocker }) {
  const file = path.join(caseDir, 'run-owned-expert-publish-prerequisite.json');
  writeJsonFile(file, blocker);
  if (blocker?.valid !== true || blocker?.applicable !== true || blocker?.outcome !== 'blocked') {
    recordAssertion(
      state,
      '三类本轮 Expert 草稿发布前置',
      '只有精确上游草稿键缺失、账本身份未残缺且空任务零能力状态成立时，才允许阻塞发布并继续后续独立 Case。',
      false,
      blocker?.reason || 'expert publish prerequisite evidence invalid',
      'automation_error',
    );
    return file;
  }
  state.artifacts.core_beta_expert_publish_prerequisite = blocker;
  state.artifacts.core_beta_not_applicable_roles = blocker.not_applicable_roles.map((role) => ({
    role,
    blocker_path: file,
  }));
  recordAssertion(
    state,
    '三类本轮 Expert 草稿发布前置',
    '缺少任一本轮研究、数据或交付草稿时必须阻止发布，忽略账号中的历史草稿并生成完整 blocker manifest。',
    true,
    blocker.reason,
  );
  markBlocked(state, blocker.reason);
  return file;
}

function coreBetaPublishedExpertIdentity(value = {}) {
  return {
    expert_id: String(value?.id || value?.expertId || ''),
    release_id: String(value?.activeReleaseId || value?.releaseId || value?.release?.id || ''),
    version_id: String(
      value?.activeVersionId
      || value?.versionId
      || value?.version?.id
      || value?.release?.versionId
      || '',
    ),
  };
}

export function coreBetaRunOwnedExpertPrerequisiteBlocker({
  testCase = {},
  ledgerExperts = {},
  availableExperts = [],
  publicState = null,
} = {}) {
  const id = String(testCase?.id || '');
  const requirement = CORE_BETA_RUN_OWNED_EXPERT_REQUIREMENTS.get(id);
  if (!requirement) {
    return {
      applies: false,
      ready: true,
      valid: true,
      selected_expert: null,
      not_applicable_roles: [],
    };
  }
  const ledgerEntry = ledgerExperts?.[requirement.ledger_key] || null;
  const expectedIdentity = coreBetaPublishedExpertIdentity(ledgerEntry || {});
  const ledgerIdentityComplete = Boolean(
    expectedIdentity.expert_id
    && expectedIdentity.release_id
    && expectedIdentity.version_id
  );
  const inventory = (Array.isArray(availableExperts) ? availableExperts : [])
    .map((item) => ({ item, identity: coreBetaPublishedExpertIdentity(item) }));
  const exactMatches = ledgerIdentityComplete
    ? inventory.filter(({ identity }) => (
      identity.expert_id === expectedIdentity.expert_id
      && identity.release_id === expectedIdentity.release_id
      && identity.version_id === expectedIdentity.version_id
    ))
    : [];
  if (exactMatches.length === 1) {
    return {
      applies: true,
      ready: true,
      valid: true,
      selected_expert: exactMatches[0].item,
      required_ledger_key: requirement.ledger_key,
      source_case_ids: requirement.source_case_ids,
      expected_identity: expectedIdentity,
      not_applicable_roles: [],
    };
  }
  const task = publicState?.task || {};
  const selectedSkills = Array.isArray(publicState?.skills?.selected) ? publicState.skills.selected : [];
  const selectedConnectors = Array.isArray(publicState?.connectors?.selected) ? publicState.connectors.selected : [];
  const mutationGuard = {
    task_absent: task?.id == null,
    no_messages: Number(task?.message_count || 0) === 0,
    not_running: task?.running !== true,
    expert_absent: publicState?.expert == null,
    skills_absent: selectedSkills.length === 0,
    connectors_absent: selectedConnectors.length === 0,
  };
  mutationGuard.valid = Boolean(publicState) && Object.values(mutationGuard).every(Boolean);
  const outcome = !ledgerEntry
    ? 'blocked'
    : !ledgerIdentityComplete ? 'automation_error' : 'bug';
  const kind = outcome === 'blocked'
    ? 'run_owned_published_expert_missing'
    : outcome === 'bug'
      ? 'run_owned_published_expert_not_visible'
      : 'run_owned_published_expert_identity_incomplete';
  const notApplicableRoles = (Array.isArray(testCase?.evidence_roles) ? testCase.evidence_roles : [])
    .filter((role) => CORE_BETA_EXPERT_PREREQUISITE_NA_ROLES.has(role));
  const activeIdentities = inventory.map(({ identity }) => identity)
    .filter((identity) => identity.expert_id && identity.release_id && identity.version_id)
    .sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
  const reason = outcome === 'blocked'
    ? `${id} 的本轮精确已发布专家前置缺失：ledger.experts.${requirement.ledger_key} 不存在；已忽略账号中 ${activeIdentities.length} 个非本轮 active expert，未发送且未随机替换。`
    : outcome === 'bug'
      ? `${id} 的本轮已发布专家存在于运行账本，但产品专家目录没有相同 expert/release/version；未发送且未随机替换。`
      : `${id} 的本轮发布账本身份不完整：ledger.experts.${requirement.ledger_key} 缺少 expert/release/version。`;
  return {
    schema_version: 'qbot-core-beta-expert-prerequisite/v1',
    applies: true,
    ready: false,
    valid: outcome !== 'automation_error' && mutationGuard.valid,
    oracle_valid: false,
    applicable: true,
    outcome,
    kind,
    source: 'exact_run_suite_ledger_and_live_expert_inventory',
    dependent_case_id: id,
    required_ledger_key: requirement.ledger_key,
    source_case_ids: requirement.source_case_ids,
    ledger_entry_present: Boolean(ledgerEntry),
    ledger_identity_complete: ledgerIdentityComplete,
    expected_identity: expectedIdentity,
    exact_live_match_count: exactMatches.length,
    active_expert_count: activeIdentities.length,
    active_expert_identities_sha256: createHash('sha256')
      .update(JSON.stringify(activeIdentities)).digest('hex'),
    arbitrary_active_expert_fallback_forbidden: true,
    mutation_guard: mutationGuard,
    selected_expert: null,
    not_applicable_roles: notApplicableRoles,
    reason,
  };
}

function applyCoreBetaRunOwnedExpertPrerequisite({ state, testCase, caseDir, blocker }) {
  if (blocker?.valid !== true || blocker?.applicable !== true) {
    recordAssertion(
      state,
      '本轮精确已发布 Expert 前置',
      '只有本轮账本身份缺失或产品目录与本轮精确身份不一致，且空任务零能力状态成立时，才允许停止当前 Case 发送。',
      false,
      blocker?.reason || 'expert prerequisite evidence invalid',
      'automation_error',
    );
    return '';
  }
  const file = path.join(caseDir, 'run-owned-expert-prerequisite.json');
  writeJsonFile(file, blocker);
  state.artifacts.core_beta_expert_prerequisite = blocker;
  state.artifacts.core_beta_not_applicable_roles = blocker.not_applicable_roles.map((role) => ({
    role,
    blocker_path: file,
  }));
  if (blocker.outcome === 'blocked') {
    recordAssertion(
      state,
      '本轮精确已发布 Expert 前置',
      '缺少本轮账本的精确已发布身份时必须阻止发送，忽略账号中任意非本轮 active expert，并生成完整 blocker manifest。',
      true,
      blocker.reason,
    );
    markBlocked(state, blocker.reason);
  } else {
    recordAssertion(
      state,
      '本轮精确已发布 Expert 目录一致性',
      '本轮账本中的 expert/release/version 必须在产品目录精确可见；禁止回退到其他 active expert。',
      false,
      blocker.reason,
      'bug',
    );
  }
  return file;
}

export function coreBetaExpertBuilderOutcomeEvidence({
  runtimeFamily = '',
  observedRuntimeFamily = '',
  builderIdentity = '',
  beforeDrafts = null,
  afterDrafts = null,
  createdDrafts = null,
  createdDetail = null,
  taskId = '',
  replyRecords = null,
  authoringToolTrace = null,
} = {}) {
  const normalizedRuntimeFamily = String(runtimeFamily || '').trim();
  const normalizedObservedRuntimeFamily = String(observedRuntimeFamily || '').trim();
  const normalizedBuilderIdentity = String(builderIdentity || '').trim();
  const normalizedTaskId = String(taskId || '').trim();
  const baselineCaptured = Array.isArray(beforeDrafts);
  const afterCaptured = Array.isArray(afterDrafts);
  const repliesCaptured = Array.isArray(replyRecords) && replyRecords.length > 0
    && replyRecords.every((item) => (
      String(item?.label || '').trim()
      && typeof item?.assistant_reply_present === 'boolean'
      && String(item?.terminal_outcome || '').trim()
    ));
  const toolTraceCaptured = Boolean(
    authoringToolTrace
    && typeof authoringToolTrace === 'object'
    && String(authoringToolTrace.task_id || '').trim()
    && Number.isFinite(Number(authoringToolTrace.call_count))
    && Array.isArray(authoringToolTrace.calls),
  );
  const taskBound = Boolean(
    normalizedTaskId
    && toolTraceCaptured
    && String(authoringToolTrace.task_id || '').trim() === normalizedTaskId,
  );
  const evidenceValid = Boolean(
    normalizedRuntimeFamily
    && normalizedObservedRuntimeFamily
    && normalizedBuilderIdentity
    && baselineCaptured
    && afterCaptured
    && repliesCaptured
    && taskBound,
  );
  const before = baselineCaptured ? beforeDrafts : [];
  const after = afterCaptured ? afterDrafts : [];
  const beforeIds = new Set(before.map((item) => String(item?.id || '')).filter(Boolean));
  const observedCreated = Array.isArray(createdDrafts)
    ? createdDrafts
    : after.filter((item) => !beforeIds.has(String(item?.id || '')));
  const createdIds = observedCreated.map((item) => String(item?.id || '')).filter(Boolean);
  const replyText = (Array.isArray(replyRecords) ? replyRecords : [])
    .map((item) => `${item?.fullText || ''}\n${item?.deltaText || ''}`)
    .join('\n');
  const reusedExistingDraftIds = before
    .map((item) => String(item?.id || ''))
    .filter((id) => id && after.some((item) => String(item?.id || '') === id) && replyText.includes(id));
  const serializedDraft = observedCreated.length
    ? JSON.stringify(createdDetail?.draft || observedCreated[0])
    : '';
  const dependencyGraph = createdDetail?.dependencies ?? null;
  const dependencyItems = Array.isArray(dependencyGraph)
    ? dependencyGraph
    : Array.isArray(dependencyGraph?.dependencies) ? dependencyGraph.dependencies : [];
  const stagedSkillValid = normalizedRuntimeFamily !== 'claude-code'
    || dependencyItems.some((item) => (
      String(item?.kind || '') === 'skill'
      && String(item?.source || '') === 'skillhub-draft'
      && String(item?.assetId || '').trim()
      && /^[a-f0-9]{64}$/i.test(String(item?.packageDigest || ''))
    ));
  const createdDraftDetailValid = Boolean(
    createdIds.length > 0
    && String(createdDetail?.draft?.id || observedCreated[0]?.id || '').trim()
    && serializedDraft.length >= 20,
  );
  const oracleValid = Boolean(
    evidenceValid
    && normalizedObservedRuntimeFamily === normalizedRuntimeFamily
    && normalizedBuilderIdentity === 'qwork.builtin.expert-authoring'
    && createdDraftDetailValid
    && stagedSkillValid
    && Number(authoringToolTrace.call_count) > 0,
  );
  const reason = !evidenceValid
    ? 'expert_builder_negative_readback_incomplete'
    : !createdIds.length
      ? 'no_run_owned_draft_created'
      : normalizedObservedRuntimeFamily !== normalizedRuntimeFamily
        ? 'expert_builder_runtime_family_mismatch'
        : normalizedBuilderIdentity !== 'qwork.builtin.expert-authoring'
          ? 'expert_builder_identity_mismatch'
          : Number(authoringToolTrace.call_count) <= 0
            ? 'expert_authoring_tool_call_missing'
            : !stagedSkillValid
              ? 'staged_skill_dependency_missing'
            : !createdDraftDetailValid
                ? 'created_draft_detail_incomplete'
                : 'run_owned_draft_created';
  const common = {
    schema_version: 'qbot-core-beta-expert-builder-outcome/v1',
    evidence_valid: evidenceValid,
    oracle_valid: oracleValid,
    reason,
    runtime_family: normalizedRuntimeFamily,
    observed_runtime_family: normalizedObservedRuntimeFamily,
    builder_identity: normalizedBuilderIdentity,
    task_binding: {
      valid: taskBound,
      task_id: normalizedTaskId || null,
      tool_trace_task_id: String(authoringToolTrace?.task_id || '').trim() || null,
    },
    baseline_draft_inventory: before,
    after_draft_inventory: after,
    created_draft_ids: createdIds,
    reused_existing_draft_ids: reusedExistingDraftIds,
    reply_records: Array.isArray(replyRecords) ? replyRecords : [],
    authoring_tool_trace: authoringToolTrace || null,
  };
  return {
    evidence_valid: evidenceValid,
    oracle_valid: oracleValid,
    reason,
    expert_builder_trace: {
      ...common,
      created_drafts: observedCreated,
      created_detail: createdDetail,
    },
    expert_authoring_mcp_trace: {
      ...common,
      call_count: Number(authoringToolTrace?.call_count || 0),
      calls: Array.isArray(authoringToolTrace?.calls) ? authoringToolTrace.calls : [],
    },
    expert_draft_lifecycle: {
      ...common,
      created_drafts: observedCreated,
      created_detail: createdDetail,
    },
    expert_dependency_graph: {
      ...common,
      draft_id: String(createdDetail?.draft?.id || observedCreated[0]?.id || '').trim() || null,
      dependencies: dependencyGraph,
      staged_skill_valid: stagedSkillValid,
    },
    content_readback: {
      ...common,
      draft: createdDetail?.draft || observedCreated[0] || null,
    },
    artifact_path_sha256: {
      ...common,
      logical_path: createdDraftDetailValid
        ? `expert-draft://${createdDetail?.draft?.id || observedCreated[0].id}`
        : null,
      sha256: createdDraftDetailValid
        ? createHash('sha256').update(serializedDraft).digest('hex')
        : null,
      baseline_inventory_sha256: baselineCaptured
        ? createHash('sha256').update(JSON.stringify(before)).digest('hex')
        : null,
      after_inventory_sha256: afterCaptured
        ? createHash('sha256').update(JSON.stringify(after)).digest('hex')
        : null,
    },
  };
}

async function executeCoreBetaExpertCase({ page, state, testCase, caseDir, timeoutMs, fixturesDir, options = {} }) {
  await page.locator('[data-testid="nav-experts"]').click({ timeout: 15_000 });
  await returnFromExpertBuilderIfNeeded(page, state);
  await expectVisibleCoreLocator(page, '[data-testid="experts-view"]', 'Expert v2 专家中心');
  const bridge = await page.evaluate(async () => {
    const lifecycle = window.agent?.expertLifecycle;
    if (!lifecycle) return { available: false };
    if (typeof window.agent?.capabilities !== 'function') {
      return { available: false, error: 'missing window.agent.capabilities' };
    }
    const [capabilities, experts, drafts] = await Promise.all([
      window.agent.capabilities(),
      lifecycle.list(),
      lifecycle.listDrafts(),
    ]);
    return {
      available: true,
      methods: Object.keys(lifecycle),
      capabilities,
      experts,
      drafts,
    };
  });
  if (!bridge.available) throw new Error('Expert v2 bridge unavailable');
  const identityFile = path.join(caseDir, 'expert-identity.json');
  writeJsonFile(identityFile, { valid: true, ...bridge });
  state.artifacts.expert_identity_snapshot = identityFile;
  state.artifacts.capability_inventory = identityFile;
  state.artifacts.core_beta_expert_identity = bridge;
  recordAssertion(
    state,
    'Expert v2 真实桥接契约',
    'expertLifecycle bridge、capabilities、list、listDrafts 必须可读。',
    bridge.methods.includes('createDraft') && bridge.methods.includes('publish') && bridge.methods.includes('listVersions'),
    JSON.stringify({ methods: bridge.methods, expertCount: bridge.experts.length, draftCount: bridge.drafts.length }),
  );
  const ledger = readCoreBetaSuiteLedger(caseDir);
  ledger.experts ||= {};
  let runOwnedExpert = null;
  const initialExpertPrerequisite = coreBetaRunOwnedExpertPrerequisiteBlocker({
    testCase,
    ledgerExperts: ledger.experts,
    availableExperts: bridge.experts,
  });
  if (initialExpertPrerequisite.applies) {
    if (initialExpertPrerequisite.ready) {
      runOwnedExpert = initialExpertPrerequisite.selected_expert;
    } else {
      await openNewTask(page, state);
      await page.evaluate(async () => {
        if (typeof window.agent?.setExpert === 'function') await window.agent.setExpert(null);
      });
      if (!await resetComposerControls(page, state, caseDir, {
        skillMode: 'disabled',
        connectorMode: 'disabled',
      })) {
        throw new Error(`${testCase.id} 精确 Expert 前置阻塞前无法建立空任务零能力状态`);
      }
      const blocker = coreBetaRunOwnedExpertPrerequisiteBlocker({
        testCase,
        ledgerExperts: ledger.experts,
        availableExperts: bridge.experts,
        publicState: await captureCoreBetaPublicState(page, testCase),
      });
      applyCoreBetaRunOwnedExpertPrerequisite({ state, testCase, caseDir, blocker });
      return;
    }
  }
  const writeExpertArtifact = (role, data, valid = nonEmptyObject(data)) => {
    const file = path.join(caseDir, `${role.replace(/_/g, '-')}.json`);
    writeJsonFile(file, { valid, case_id: testCase.id, captured_at: new Date().toISOString(), data });
    if (valid) state.artifacts[role] = file;
    state.artifacts[`core_beta_${role}`] = data;
    return file;
  };

  if (['BETA-EXPERT-002', 'BETA-EXPERT-003'].includes(testCase.id)) {
    const runtimeFamily = testCase.id.endsWith('002') ? 'claude-code' : 'codex';
    const beforeDrafts = bridge.drafts;
    const beforeDraftIds = new Set(beforeDrafts.map((item) => item.id));
    await openNewTask(page, state);
    const runtimeBefore = await captureCoreBetaPublicState(page, testCase);
    state.screenshots.runtime_family_precondition_before = await shot(
      page,
      caseDir,
      'runtime-family-precondition-before',
    );
    const runtimeSwitch = await page.evaluate(async ({ family }) => {
      try {
        await window.agent.setRuntimeFamily(family);
        return { ok: true, error: null };
      } catch (error) {
        return {
          ok: false,
          error: {
            name: String(error?.name || ''),
            code: String(error?.code || ''),
            message: String(error?.message || error),
          },
        };
      }
    }, { family: runtimeFamily });
    if (!runtimeSwitch.ok) {
      const runtimeAfter = await captureCoreBetaPublicState(page, testCase);
      state.screenshots.runtime_family_precondition_after = await shot(
        page,
        caseDir,
        'runtime-family-precondition-after',
      );
      const blocker = coreBetaRuntimeFamilyPrerequisiteBlocker({
        testCase,
        targetRuntimeFamily: runtimeFamily,
        error: runtimeSwitch.error,
        before: runtimeBefore,
        after: runtimeAfter,
      });
      if (blocker.applicable) {
        applyCoreBetaRuntimePrerequisiteBlocker({ state, testCase, caseDir, blocker });
        return;
      }
      const runtimeError = new Error(runtimeSwitch.error?.message || `setRuntimeFamily(${runtimeFamily}) failed`);
      runtimeError.code = runtimeSwitch.error?.code || '';
      throw runtimeError;
    }
    await page.evaluate(async () => {
      await window.agent.setExpert('qwork.builtin.expert-authoring');
    });
    const beforeIdentity = await captureCoreBetaPublicState(page, testCase);
    await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
    const afterDrafts = await page.evaluate(async () => window.agent.expertLifecycle.listDrafts());
    const created = afterDrafts.filter((item) => !beforeDraftIds.has(item.id));
    const createdDetail = created[0]?.id
      ? await page.evaluate(async (draftId) => {
        const lifecycle = window.agent.expertLifecycle;
        return {
          draft: await lifecycle.getDraft(draftId),
          dependencies: await lifecycle.listDraftDependencies(draftId),
        };
      }, created[0].id)
      : null;
    const authoringToolTrace = await captureCoreBetaToolTrace(page, '');
    const afterIdentity = await captureCoreBetaPublicState(page, testCase);
    const builderIdentity = String(
      beforeIdentity.expert?.id
      || beforeIdentity.expert?.expertId
      || beforeIdentity.expert?.slug
      || '',
    );
    const builderOutcome = coreBetaExpertBuilderOutcomeEvidence({
      runtimeFamily,
      observedRuntimeFamily: beforeIdentity.runtime?.family || '',
      builderIdentity,
      beforeDrafts,
      afterDrafts,
      createdDrafts: created,
      createdDetail,
      taskId: afterIdentity.task?.id || authoringToolTrace.task_id || '',
      replyRecords: state.artifacts.reply_records || [],
      authoringToolTrace,
    });
    writeExpertArtifact(
      'expert_builder_trace',
      builderOutcome.expert_builder_trace,
      builderOutcome.evidence_valid,
    );
    if (testCase.id === 'BETA-EXPERT-002') {
      writeExpertArtifact(
        'expert_authoring_mcp_trace',
        builderOutcome.expert_authoring_mcp_trace,
        builderOutcome.evidence_valid,
      );
    }
    for (const role of ['expert_draft_lifecycle', 'expert_dependency_graph', 'content_readback', 'artifact_path_sha256']) {
      writeExpertArtifact(role, builderOutcome[role], builderOutcome.evidence_valid);
    }
    recordAssertion(
      state,
      `${runtimeFamily} Expert Builder结构化handoff`,
      '两轮Builder对话后必须通过精确 builtin Expert Builder 工具产生本轮 owner draft，禁止复用历史草稿或用文本声称代替。',
      builderOutcome.oracle_valid,
      builderOutcome.oracle_valid
        ? `created=${builderOutcome.expert_draft_lifecycle.created_draft_ids.join(',')}`
        : `${builderOutcome.reason}；created=${builderOutcome.expert_draft_lifecycle.created_draft_ids.length}；reused=${builderOutcome.expert_draft_lifecycle.reused_existing_draft_ids.join(',') || 'none'}；toolCalls=${authoringToolTrace.call_count}`,
      'bug',
    );
    if (!builderOutcome.oracle_valid) return;
    const ledgerDraft = {
      ...(created[0] || {}),
      ...(createdDetail?.draft || {}),
    };
    const ledgerDraftIdentity = coreBetaExpertDraftConcurrencyIdentity(ledgerDraft);
    recordAssertion(
      state,
      `${runtimeFamily} Expert Builder草稿并发身份`,
      '写入本轮成功账本的草稿必须同时具有 draftId 和公开 CAS（旧版 etag 或新版正整数 revision）。',
      ledgerDraftIdentity.complete,
      JSON.stringify(ledgerDraftIdentity),
      'bug',
    );
    if (!ledgerDraftIdentity.complete) return;
    ledger.experts[`${runtimeFamily}_draft`] = ledgerDraft;
    writeCoreBetaSuiteLedger(caseDir, ledger);
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.reply_completion;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-004') {
    const result = await page.evaluate(async (suffix) => {
      const lifecycle = window.agent.expertLifecycle;
      const created = await lifecycle.createDraft({
        label: `QA交付专家-${suffix}`,
        summary: 'QA最严格门禁创建的交付专家，只用于本轮可逆验证。',
        personaBody: '你是交付质量专家。仅输出可验证事实、负责人、截止日期与风险。',
        audience: 'owner',
        category: '交付质量',
        domains: ['质量门禁', '发布复核'],
        examples: ['请输出发布复核清单。'],
        dependencies: [],
      });
      const [skills, mcps] = await Promise.all([
        lifecycle.listSkillDependencyCandidates(),
        lifecycle.listMcpDependencyCandidates(),
      ]);
      let current = created;
      const added = [];
      const skill = skills.find((item) => item.exact || item.source === 'builtin') || skills[0];
      if (skill) {
        const resolved = await lifecycle.resolveSkillDependencyCandidate(skill);
        current = await lifecycle.addDraftDependency(
          current.id,
          resolved,
          current.etag || current.revision,
        );
        added.push(resolved);
      }
      const mcp = mcps[0];
      if (mcp) {
        const resolved = await lifecycle.resolveMcpDependencyCandidate(mcp);
        current = await lifecycle.addDraftDependency(
          current.id,
          resolved,
          current.etag || current.revision,
        );
        added.push(resolved);
      }
      return {
        draft: await lifecycle.getDraft(current.id),
        mutationDraft: current,
        dependencies: await lifecycle.listDraftDependencies(current.id),
        candidates: { skills: skills.length, mcps: mcps.length },
        added,
      };
    }, `${Date.now()}`);
    const manualDraft = {
      ...(result.draft || {}),
      ...(result.mutationDraft?.etag ? { etag: result.mutationDraft.etag } : {}),
      ...(Number(result.mutationDraft?.revision) > 0
        ? { revision: Number(result.mutationDraft.revision) }
        : {}),
    };
    const manualDraftIdentity = coreBetaExpertDraftConcurrencyIdentity(manualDraft);
    recordAssertion(
      state,
      '手动专家草稿并发身份',
      '写入本轮成功账本的手动草稿必须同时具有 draftId 和公开 CAS（旧版 etag 或新版正整数 revision）。',
      manualDraftIdentity.complete,
      JSON.stringify(manualDraftIdentity),
      'bug',
    );
    if (manualDraftIdentity.complete) ledger.experts.manual_draft = manualDraft;
    else delete ledger.experts.manual_draft;
    writeCoreBetaSuiteLedger(caseDir, ledger);
    writeExpertArtifact('expert_draft_lifecycle', {
      draft: result.draft,
      mutation_draft: result.mutationDraft,
      concurrency_identity: manualDraftIdentity,
      evidence_valid: true,
      oracle_valid: manualDraftIdentity.complete,
    });
    writeExpertArtifact('expert_dependency_graph', result.dependencies);
    writeExpertArtifact('credential_redaction_scan', {
      serialized_length: JSON.stringify(result).length,
      secret_pattern_matches: (JSON.stringify(result).match(/(?:Authorization:\s*Bearer|api[_-]?key|client[_-]?secret|refresh[_-]?token)/ig) || []).length,
    }, !/(?:Authorization:\s*Bearer|api[_-]?key|client[_-]?secret|refresh[_-]?token)/i.test(JSON.stringify(result)));
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_draft_lifecycle;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-005') {
    const draftId = ledger.experts?.manual_draft?.id;
    if (!draftId) throw new Error('BETA-EXPERT-005 缺少BETA-EXPERT-004创建的manual draft');
    const conflict = await page.evaluate(async (id) => {
      const lifecycle = window.agent.expertLifecycle;
      const original = await lifecycle.getDraft(id);
      const a = await lifecycle.patchDraft(
        id,
        { summary: `${original.content.summary} A` },
        original.etag || original.revision,
      );
      let staleRejected = false;
      let staleError = '';
      try {
        await lifecycle.patchDraft(
          id,
          { personaBody: `${original.content.personaBody} B` },
          original.etag || original.revision,
        );
      } catch (error) {
        staleRejected = true;
        staleError = String(error?.message || error);
      }
      const latest = await lifecycle.getDraft(id);
      const merged = await lifecycle.patchDraft(
        id,
        { personaBody: `${latest.content.personaBody} B` },
        latest.etag || latest.revision,
      );
      return { original, writer_a: a, stale_rejected: staleRejected, stale_error: staleError, merged };
    }, draftId);
    writeExpertArtifact('expert_conflict_trace', conflict, conflict.stale_rejected && conflict.merged.revision > conflict.original.revision);
    writeExpertArtifact('expert_draft_lifecycle', conflict);
    recordAssertion(state, 'Expert草稿CAS冲突fail-closed', '旧ETag写入必须拒绝；用最新ETag重试后revision单调增加。', conflict.stale_rejected && conflict.merged.revision > conflict.original.revision, JSON.stringify({ stale: conflict.stale_rejected, revisions: [conflict.original.revision, conflict.writer_a.revision, conflict.merged.revision] }));
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_conflict_trace;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-006') {
    const draftId = ledger.experts?.manual_draft?.id;
    if (!draftId) throw new Error('BETA-EXPERT-006 缺少manual draft');
    const scenario = coreBetaScenarioSpec(testCase);
    const policy = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'skill-policy-matrix',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        draft_id: draftId,
        require_staged_secret_rejection: true,
        require_published_skillhub_env_config_materialization: true,
      },
    });
    const result = await page.evaluate(async (id) => {
      const lifecycle = window.agent.expertLifecycle;
      const validation = await lifecycle.validateDraft(id);
      const debug = await lifecycle.debug(id);
      const after = await lifecycle.getDraft(id);
      const capabilities = typeof window.agent?.capabilities === 'function'
        ? await window.agent.capabilities()
        : { __error: 'missing window.agent.capabilities' };
      return { validation, debug, after, mcp_authoring: capabilities.mcpAuthoring };
    }, draftId);
    const policyValid = Boolean(
      policy.ok
      && policy.staged_expert_skill?.secret_like_rejected === true
      && String(policy.staged_expert_skill?.code || '')
      && Number(policy.staged_expert_skill?.mutation_count || 0) === 0
      && policy.published_skillhub_env_config?.install_allowed === true
      && policy.published_skillhub_env_config?.materialized === true
      && Number(policy.credential_leak_count || 0) === 0
    );
    writeExpertArtifact(
      'expert_runtime_trace',
      { ...result, skill_policy_matrix: policy },
      Boolean(result.debug?.identity?.draftId && result.mcp_authoring === false && policyValid),
    );
    writeExpertArtifact('negative_ui_trace', { mcp_authoring: result.mcp_authoring }, result.mcp_authoring === false);
    writeExpertArtifact('expert_draft_lifecycle', result.after);
    writeExpertArtifact('credential_redaction_scan', {
      credential_leak_count: policy.credential_leak_count,
      staged_secret_rejected: policy.staged_expert_skill?.secret_like_rejected,
      published_skillhub_env_config_materialized: policy.published_skillhub_env_config?.materialized,
    }, policyValid);
    recordAssertion(
      state,
      'Expert staged Skill与发布SkillHub策略边界',
      'ExpertDraft staged Skill的secret-like内容必须拒绝且0 mutation；合法已发布SkillHub包读取环境配置必须仍可安装/物化，且两路均无凭据泄漏。',
      policyValid,
      JSON.stringify(policy),
    );
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_runtime_trace;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-007') {
    const initialPublishPrerequisite = coreBetaExpertPublishPrerequisiteBlocker({
      testCase,
      ledgerExperts: ledger.experts,
      availableDrafts: bridge.drafts,
    });
    if (!initialPublishPrerequisite.ready) {
      await openNewTask(page, state);
      await page.evaluate(async () => {
        if (typeof window.agent?.setExpert === 'function') await window.agent.setExpert(null);
      });
      if (!await resetComposerControls(page, state, caseDir, {
        skillMode: 'disabled',
        connectorMode: 'disabled',
      })) {
        throw new Error('BETA-EXPERT-007 草稿前置阻塞前无法建立空任务零能力状态');
      }
      const blocker = coreBetaExpertPublishPrerequisiteBlocker({
        testCase,
        ledgerExperts: ledger.experts,
        availableDrafts: bridge.drafts,
        publicState: await captureCoreBetaPublicState(page, testCase),
      });
      applyCoreBetaExpertPublishPrerequisite({ state, testCase, caseDir, blocker });
      return;
    }
    const targets = [
      { ledger_key: 'published_research', draft: ledger.experts?.['claude-code_draft'] },
      { ledger_key: 'published_data', draft: ledger.experts?.codex_draft },
      { ledger_key: 'published_delivery', draft: ledger.experts?.manual_draft },
    ];
    const operations = await page.evaluate(async ({ entries, keyPrefix }) => {
      const lifecycle = window.agent.expertLifecycle;
      const results = [];
      for (const [index, entry] of entries.entries()) {
        const draft = await lifecycle.getDraft(entry.draft_id);
        const draftCas = String(draft?.etag || '').trim() || Number(draft?.revision);
        if (!(String(draft?.id || '').trim() && draftCas)) {
          throw new Error(`expert draft ${entry.ledger_key} missing public concurrency identity`);
        }
        const started = await lifecycle.publish(
          draft.id,
          draftCas,
          `${keyPrefix}-${entry.ledger_key}-${index + 1}`,
        );
        const states = [started];
        let current = started;
        for (let attempt = 0; attempt < 30 && !['completed', 'failed'].includes(current.state); attempt += 1) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
          current = await lifecycle.getOperation(
            started.id || started.operationId,
            draft.id,
            draftCas,
          );
          states.push(current);
        }
        const expertId = current.expertId || started.expertId || null;
        results.push({
          ledger_key: entry.ledger_key,
          draft_id: draft.id,
          draft_cas_kind: String(draft?.etag || '').trim() ? 'etag' : 'revision',
          draft_cas_value: draftCas,
          operation_id: started.id || started.operationId,
          states,
          expert: expertId ? await lifecycle.get(expertId) : null,
        });
      }
      return results;
    }, {
      entries: targets.map((item) => ({ ledger_key: item.ledger_key, draft_id: item.draft.id })),
      keyPrefix: `qbot-beta-${testCase.id}-${Date.now()}`,
    });
    const publishValid = operations.length === 3 && operations.every((item) => (
      item.operation_id
      && item.states.length > 0
      && item.expert?.id
      && ['completed', 'succeeded'].includes(String(item.states.at(-1)?.state || '').toLowerCase())
    ));
    writeExpertArtifact('expert_publish_operation', operations, publishValid);
    for (const item of operations) {
      if (item.expert?.id) ledger.experts[item.ledger_key] = item.expert;
    }
    ledger.experts.published = ledger.experts.published_delivery || operations.at(-1)?.expert || null;
    writeCoreBetaSuiteLedger(caseDir, ledger);
    writeExpertArtifact('restart_trace', {
      operations: operations.map((item) => ({
        ledger_key: item.ledger_key,
        operation_id: item.operation_id,
        state_count: item.states.length,
      })),
      resumed: operations.every((item) => item.states.length > 1),
    }, operations.every((item) => item.states.length > 1));
    writeExpertArtifact('credential_redaction_scan', {
      secret_pattern_matches: (JSON.stringify(operations).match(/(?:Authorization:\s*Bearer|api[_-]?key|client[_-]?secret|refresh[_-]?token)/ig) || []).length,
    }, !/(?:Authorization:\s*Bearer|api[_-]?key|client[_-]?secret|refresh[_-]?token)/i.test(JSON.stringify(operations)));
    recordAssertion(
      state,
      '三类本轮Expert发布闭环',
      '研究、数据、交付三类草稿必须各自产生唯一发布operation和active expert，并写入本轮账本供后续Case使用。',
      publishValid,
      JSON.stringify(operations),
    );
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_publish_operation;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-014') {
    const selected = runOwnedExpert;
    if (!selected?.id) throw new Error('BETA-EXPERT-014 需要至少一个已发布专家');
    const turns = testCase.conversation_turns || [];
    if (turns.length !== 3) throw new Error('BETA-EXPERT-014 必须声明3个身份隔离轮次');
    await openNewTask(page, state);
    await page.evaluate((expertId) => window.agent.setExpert(expertId), selected.id);
    await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt: turns[0].prompt, label: '旧release任务' });
    const expertTask = await captureCoreBetaPublicState(page, testCase);
    const expertTaskId = expertTask.task?.id;
    await openNewTask(page, state);
    await page.evaluate(async () => {
      if (typeof window.agent.setExpert === 'function') await window.agent.setExpert(null);
    });
    await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt: turns[1].prompt, label: '通用助手任务' });
    const generalTask = await captureCoreBetaPublicState(page, testCase);
    await openNewTask(page, state);
    await page.evaluate((expertId) => window.agent.setExpert(expertId), selected.id);
    await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt: turns[2].prompt, label: '新release任务' });
    const newExpertTask = await captureCoreBetaPublicState(page, testCase);
    const reopenedOld = await reopenSessionAndReadback(page, expertTaskId);
    const oldAfter = await captureCoreBetaPublicState(page, testCase);
    const matrix = {
      valid: Boolean(
        expertTaskId
        && reopenedOld.ok
        && expertTask.expert
        && !generalTask.expert
        && newExpertTask.expert
        && new Set([expertTask.task?.id, generalTask.task?.id, newExpertTask.task?.id]).size === 3
        && JSON.stringify(oldAfter.expert) === JSON.stringify(expertTask.expert)
      ),
      old_expert_task: expertTask,
      general_task: generalTask,
      new_expert_task: newExpertTask,
      old_reopened: reopenedOld,
      old_after_reopen: oldAfter,
    };
    writeExpertArtifact('expert_runtime_trace', matrix, matrix.valid);
    state.artifacts.core_beta_capability_selection = {
      old: expertTask.expert,
      general: generalTask.expert,
      current: newExpertTask.expert,
    };
    state.artifacts.core_beta_capability_execution = matrix;
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_runtime_trace;
    recordAssertion(state, 'Expert/通用助手三task身份隔离', '旧专家task、通用task、新专家task必须taskId唯一且expert identity不串。', matrix.valid, JSON.stringify(matrix));
    return;
  }

  if (testCase.case_type === 'expert_use') {
    await openNewTask(page, state);
    if (testCase.id === 'BETA-EXPERT-010'
      && !await prepareVisibleQaWorkspace(page, state, caseDir)) return;
    const selected = runOwnedExpert;
    await page.evaluate((expertId) => window.agent.setExpert(expertId), selected.id);
    const selection = await captureCoreBetaPublicState(page, testCase);
    state.artifacts.core_beta_capability_selection = selection;
    writeExpertArtifact('expert_runtime_trace', { selected, before_turn: selection }, Boolean(selection.expert));
    if (testCase.id === 'BETA-EXPERT-009') {
      const attachments = inferAttachments(testCase, fixturesDir);
      if (!attachments.length) throw new Error('BETA-EXPERT-009 缺少数据附件fixture');
      state.artifacts.attachment_sources = attachments.map((file) => ({
        path: file,
        name: path.basename(file),
        size_bytes: fs.statSync(file).size,
        sha256: createHash('sha256').update(fs.readFileSync(file)).digest('hex'),
      }));
      state.artifacts.upload = await uploadAttachmentsInComposer(page, attachments.slice(0, 1));
      if (state.artifacts.upload.status !== 'passed') throw new Error(`Expert附件上传失败：${state.artifacts.upload.reason || state.artifacts.upload.status}`);
    }
    await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
    const after = await captureCoreBetaPublicState(page, testCase);
    const toolTrace = await captureCoreBetaToolTrace(page, '');
    const replies = state.artifacts.reply_records || [];
    const replyText = replies.map((item) => `${item.fullText || ''}\n${item.deltaText || ''}`).join('\n');
    const selectedIdentity = {
      expert_id: String(selected.id || ''),
      release_id: String(selected.activeReleaseId || selected.release?.id || ''),
      version_id: String(selected.activeVersionId || selected.version?.id || ''),
    };
    const beforeIdentity = {
      expert_id: String(selection.expert?.id || selection.expert?.expertId || ''),
      release_id: String(selection.expert?.releaseId || selection.expert?.activeReleaseId || ''),
      version_id: String(selection.expert?.versionId || selection.expert?.activeVersionId || ''),
    };
    const afterIdentity = {
      expert_id: String(after.expert?.id || after.expert?.expertId || ''),
      release_id: String(after.expert?.releaseId || after.expert?.activeReleaseId || ''),
      version_id: String(after.expert?.versionId || after.expert?.activeVersionId || ''),
    };
    let domainOracle = true;
    if (testCase.id === 'BETA-EXPERT-008') {
      const sourceUrls = replyText.match(/https?:\/\/[^\s)\]}>"']+/g) || [];
      domainOracle = toolTrace.call_count > 0 && new Set(sourceUrls).size >= 2;
      recordAssertion(
        state,
        '研究专家真实工具与双官方来源',
        '三轮回复必须有至少一次真实tool call与两个不同来源URL，不能只由专家自述。',
        domainOracle,
        JSON.stringify({ tool_trace: toolTrace, source_urls: sourceUrls }),
      );
    } else if (testCase.id === 'BETA-EXPERT-009') {
      const requiredAnchors = ['100', '70', '12', '70%', '12%', '15', '15%'];
      domainOracle = requiredAnchors.every((anchor) => replyText.includes(anchor))
        && /(?:100\s*[-*/]\s*|70\s*\/\s*100|12\s*\/\s*100|15\s*\/\s*100)/.test(replyText);
      recordAssertion(
        state,
        '数据专家固定数据独立复算Oracle',
        '回复必须读回100/70/12，给出70%到场率与12%成交率，并在成交修订为15后给出15%。',
        domainOracle,
        JSON.stringify({ required_anchors: requiredAnchors, reply_excerpt: clip(replyText, 2_000) }),
      );
    } else if (testCase.id === 'BETA-EXPERT-010') {
      const workspace = state.artifacts.qa_workspace?.requested;
      const files = workspace ? listCoreBetaArtifactFiles(workspace) : [];
      const readback = files
        .filter((file) => ['.md', '.html', '.docx', '.pdf'].includes(path.extname(file).toLowerCase()))
        .map((file) => coreBetaArtifactReadback(file));
      const previewScreenshot = await shot(page, caseDir, 'expert-delivery-artifact-preview');
      const previewBytes = typeof previewScreenshot === 'string' && fs.existsSync(previewScreenshot)
        ? fs.statSync(previewScreenshot).size
        : 0;
      const secretMatches = JSON.stringify(readback).match(
        /(?:Authorization:\s*Bearer|api[_-]?key|client[_-]?secret|refresh[_-]?token)/ig,
      ) || [];
      domainOracle = readback.length > 0
        && readback.every((item) => item.valid)
        && previewBytes >= 128
        && secretMatches.length === 0;
      writeExpertArtifact('artifact_path_sha256', {
        workspace,
        files: readback.map((item) => ({ path: item.path, bytes: item.bytes, sha256: item.sha256 })),
      }, domainOracle);
      writeExpertArtifact('content_readback', { files: readback }, domainOracle);
      writeExpertArtifact('preview', { screenshot: previewScreenshot, screenshot_bytes: previewBytes }, previewBytes >= 128);
      writeExpertArtifact('credential_redaction_scan', { secret_matches: secretMatches }, secretMatches.length === 0);
      recordAssertion(
        state,
        '交付专家真实成果内容/预览/凭据闭环',
        '第三轮必须在绑定工作区生成可解析成果，SHA有效、预览非空且不含凭据。',
        domainOracle,
        JSON.stringify({ workspace, readback, previewBytes, secretMatches }),
      );
    }
    const identityStable = Boolean(selection.task?.id
      && after.task?.id === selection.task.id
      && selectedIdentity.expert_id
      && beforeIdentity.expert_id === selectedIdentity.expert_id
      && afterIdentity.expert_id === selectedIdentity.expert_id
      && (!beforeIdentity.release_id || !afterIdentity.release_id || beforeIdentity.release_id === afterIdentity.release_id)
      && (!beforeIdentity.version_id || !afterIdentity.version_id || beforeIdentity.version_id === afterIdentity.version_id));
    const runtimeTrace = {
      valid: identityStable && domainOracle,
      selected,
      before_turn: selection,
      after_turn: after,
      replies,
      tool_trace: toolTrace,
      domain_oracle: domainOracle,
      identity_stable: identityStable,
    };
    writeExpertArtifact('expert_runtime_trace', runtimeTrace, runtimeTrace.valid);
    recordAssertion(
      state,
      'Expert task-bound identity全轮稳定',
      '三轮必须保持同一taskId及exact expert/release/version identity。',
      identityStable,
      JSON.stringify({ selectedIdentity, beforeIdentity, afterIdentity, task_before: selection.task?.id, task_after: after.task?.id }),
    );
    state.artifacts.core_beta_capability_execution = after;
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.reply_completion;
    return;
  }

  if (['BETA-EXPERT-011', 'BETA-EXPERT-013'].includes(testCase.id)) {
    const tokenEnv = String(options['expert-secondary-token-env'] || 'QBOT_EXPERT_SECONDARY_ACCESS_TOKEN');
    const secondaryToken = process.env[tokenEnv];
    const published = runOwnedExpert;
    if (!published?.id || !(published.activeReleaseId || published.release?.id)) {
      markBlocked(state, `${testCase.id} 需要真实第二账号token(${tokenEnv})和QA发布专家；缺失时禁止单账号伪造授权结论。`);
      return;
    }
    const server = String(options['server-url'] || options.server || '').replace(/\/$/, '');
    const releaseId = published.activeReleaseId || published.release.id;
    const expectAllowed = testCase.id === 'BETA-EXPERT-013';
    let viewer;
    if (secondaryToken && server) {
      const response = await fetch(`${server}/api/expert-shares/${encodeURIComponent(published.id)}/${encodeURIComponent(releaseId)}`, {
        headers: { Accept: 'application/json', Authorization: `Bearer ${secondaryToken}` },
      });
      viewer = {
        status: response.status,
        payload: await response.json().catch(() => null),
        source: 'direct_secondary_account_api',
      };
    } else {
      const scenario = coreBetaScenarioSpec(testCase);
      viewer = await invokeCoreBetaFixtureControl({
        options,
        testCase,
        scenario,
        phase: 'viewer-probe',
        payload: {
          lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
          expert_id: published.id,
          release_id: releaseId,
          expected: expectAllowed ? 'authenticated_visible' : 'owner_only_404',
        },
      });
      viewer.status = Number(viewer.status || viewer.http_status || 0);
      viewer.payload = viewer.payload || null;
    }
    const valid = expectAllowed ? viewer.status === 200 : viewer.status === 404;
    writeExpertArtifact('expert_share_authorization', {
      viewer_status: viewer.status,
      viewer_payload: viewer.payload,
      source: viewer.source || 'fixture_control',
      expert_id: published.id,
      release_id: releaseId,
      expected: expectAllowed ? 'authenticated_visible' : 'owner_only_404',
    }, valid);
    writeExpertArtifact('credential_redaction_scan', { response_status: viewer.status, token_persisted: false }, true);
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_share_authorization;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-012') {
    const published = runOwnedExpert;
    const versioned = await page.evaluate(async (expertId) => {
      const lifecycle = window.agent.expertLifecycle;
      const before = {
        expert: await lifecycle.get(expertId),
        versions: await lifecycle.listVersions(expertId),
        releases: await lifecycle.listReleases(expertId),
      };
      const base = before.versions.at(-1)?.version || before.versions.at(-1);
      if (!base?.id) throw new Error('published expert has no immutable version');
      let draft = await lifecycle.createDraftFromVersion(expertId, base.id);
      draft = await lifecycle.patchDraft(
        draft.id,
        { personaBody: `${draft.content.personaBody}\n\nQA v2 revision.` },
        draft.etag || draft.revision,
      );
      const draftCas = String(draft?.etag || '').trim() || Number(draft?.revision);
      const op = await lifecycle.publish(
        draft.id,
        draftCas,
        `qbot-beta-v2-${Date.now()}`,
      );
      const operationId = op.id || op.operationId;
      let terminal = op;
      for (let index = 0; index < 30 && !['completed', 'failed'].includes(terminal.state); index += 1) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        terminal = await lifecycle.getOperation(operationId, draft.id, draftCas);
      }
      return {
        before,
        base_version_id: base.id,
        draft,
        operation: terminal,
        after: {
          expert: await lifecycle.get(expertId),
          versions: await lifecycle.listVersions(expertId),
          releases: await lifecycle.listReleases(expertId),
        },
      };
    }, published.id);
    writeExpertArtifact('expert_history_readback', versioned, versioned.after.versions.length > versioned.before.versions.length);
    writeExpertArtifact('expert_runtime_trace', { base_version_id: versioned.base_version_id, latest: versioned.after.expert });
    ledger.experts.published = versioned.after.expert;
    ledger.experts.published_versioned = versioned.after.expert;
    writeCoreBetaSuiteLedger(caseDir, ledger);
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_history_readback;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-015') {
    const published = runOwnedExpert;
    const roundtrip = await page.evaluate(async (expertId) => {
      const lifecycle = window.agent.expertLifecycle;
      const exported = await lifecycle.export(expertId);
      const source = JSON.parse(exported.document);
      const mutations = [
        { name: 'local_dependency', patch: { dependencies: [{ kind: 'skill', source: 'local', slug: 'forbidden', required: true }] } },
        { name: 'private_dependency', patch: { dependencies: [{ kind: 'skill', source: 'private', slug: 'forbidden', required: true }] } },
        { name: 'custom_dependency', patch: { dependencies: [{ kind: 'mcp', source: 'custom', serviceId: 'forbidden', required: true }] } },
        { name: 'credential', patch: { apiKey: 'SHOULD_NOT_IMPORT' } },
      ];
      const rejected = [];
      for (const mutation of mutations) {
        try {
          await lifecycle.import(JSON.stringify({ ...source, ...mutation.patch }));
          rejected.push({ name: mutation.name, rejected: false });
        } catch (error) {
          rejected.push({ name: mutation.name, rejected: true, error: String(error?.message || error) });
        }
      }
      const legal = await lifecycle.import(exported.document);
      return { exported, source, rejected, legal };
    }, published.id);
    const exportFile = path.join(caseDir, 'expert-export.json');
    writeTextFile(exportFile, roundtrip.exported.document);
    const sha = createHash('sha256').update(roundtrip.exported.document).digest('hex');
    writeExpertArtifact('artifact_path_sha256', { path: exportFile, sha256: sha }, /^[a-f0-9]{64}$/.test(sha));
    writeExpertArtifact('content_readback', roundtrip, roundtrip.rejected.every((item) => item.rejected) && Boolean(roundtrip.legal?.id));
    writeExpertArtifact('credential_redaction_scan', {
      secret_pattern_matches: (roundtrip.exported.document.match(/(?:api[_-]?key|client[_-]?secret|refresh[_-]?token|Authorization:\s*Bearer)/ig) || []).length,
    }, !/(?:api[_-]?key|client[_-]?secret|refresh[_-]?token|Authorization:\s*Bearer)/i.test(roundtrip.exported.document));
    writeExpertArtifact('expert_history_readback', { imported_draft_id: roundtrip.legal?.id, export_sha256: sha });
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.content_readback;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-016') {
    const published = runOwnedExpert;
    const retired = await page.evaluate(async (expertId) => {
      const lifecycle = window.agent.expertLifecycle;
      const before = {
        expert: await lifecycle.get(expertId),
        versions: await lifecycle.listVersions(expertId),
        releases: await lifecycle.listReleases(expertId),
      };
      const unpublish = await lifecycle.unpublish(expertId, `qbot-beta-unpublish-${Date.now()}`);
      const archive = await lifecycle.archive(expertId, `qbot-beta-archive-${Date.now()}`);
      return {
        before,
        unpublish,
        archive,
        after: {
          expert: await lifecycle.get(expertId),
          versions: await lifecycle.listVersions(expertId),
          releases: await lifecycle.listReleases(expertId),
        },
      };
    }, published.id);
    writeExpertArtifact('expert_history_readback', retired, retired.unpublish?.ok && retired.archive?.ok && retired.after.versions.length === retired.before.versions.length);
    writeExpertArtifact('negative_ui_trace', { archived_expert: retired.after.expert, active_after: retired.after.expert?.activeReleaseId || null }, !retired.after.expert?.activeReleaseId);
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_history_readback;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-017') {
    const scenario = coreBetaScenarioSpec(testCase);
    const result = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'native-product-loop',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        required_builder_expert_id: 'qwork.builtin.expert-authoring',
        runtime_family: 'claude-code',
        require_distinct_viewer_principal: true,
        require_real_first_turn: true,
      },
    });
    const owner = result.owner || {};
    const viewer = result.viewer || {};
    const confirmation = owner.confirmation || {};
    const cancel = owner.cancel || {};
    const confirm = owner.confirm || {};
    const records = Array.isArray(result.conversation_records) ? result.conversation_records : [];
    const screenshotRoles = [
      'authoring_before',
      'draft_after',
      'debug_after',
      'publish_confirmation',
      'publish_after',
      'viewer_first_turn_after',
    ];
    const valid = Boolean(
      result.ok
      && owner.runtime_family === 'claude-code'
      && owner.builder_expert_id === 'qwork.builtin.expert-authoring'
      && String(owner.authoring_task_id || '')
      && String(owner.draft_id || '')
      && Number(owner.draft_revision || 0) >= 1
      && String(owner.debug_task_id || '')
      && owner.debug_reply_complete === true
      && owner.returned_to_authoring_task === true
      && String(confirmation.label || '')
      && ['owner', 'authenticated'].includes(String(confirmation.audience || ''))
      && Array.isArray(confirmation.options)
      && confirmation.options.length === 2
      && confirmation.options.some((item) => /取消|cancel/i.test(String(item)))
      && confirmation.options.some((item) => /确认|发布|confirm/i.test(String(item)))
      && Number(cancel.version_delta || 0) === 0
      && Number(cancel.release_delta || 0) === 0
      && cancel.no_partial_state === true
      && Number(confirm.version_delta || 0) === 1
      && Number(confirm.release_delta || 0) === 1
      && ['completed', 'succeeded'].includes(String(confirm.terminal_state || '').toLowerCase())
      && String(confirm.expert_id || '') === String(owner.expert_id || '')
      && String(confirm.release_id || '')
      && viewer.distinct_principal === true
      && viewer.shared_discovery === true
      && viewer.first_turn_complete === true
      && String(viewer.expert_id || '') === String(owner.expert_id || '')
      && String(viewer.release_id || '') === String(confirm.release_id || '')
      && String(viewer.task_id || '')
      && records.length >= 3
      && records.every((item) => String(item?.prompt || '').trim() && String(item?.reply || '').trim())
      && coreBetaExpertEvidenceScreenshotsValid(
        result.screenshot_evidence,
        screenshotRoles,
        { caseDir, state },
      )
    );
    state.artifacts.sent_prompts ||= [];
    state.artifacts.send_receipts ||= [];
    for (const [index, item] of records.entries()) {
      state.artifacts.sent_prompts.push({
        label: String(item.label || `专家产品闭环第${index + 1}轮`),
        prompt: String(item.prompt || ''),
      });
      state.artifacts.send_receipts.push({
        label: String(item.label || `专家产品闭环第${index + 1}轮`),
        task_id: String(item.task_id || owner.authoring_task_id || viewer.task_id || ''),
        confirmed_at: String(item.confirmed_at || result.completed_at || new Date().toISOString()),
      });
    }
    writeReplyArtifacts(state, caseDir, records.map((item, index) => ({
      label: String(item.label || `专家产品闭环第${index + 1}轮`),
      fullText: String(item.reply || ''),
      deltaText: String(item.reply_delta || item.reply || ''),
    })));
    writeExpertArtifact('expert_draft_lifecycle', {
      draft_id: owner.draft_id,
      revision: owner.draft_revision,
      debug_task_id: owner.debug_task_id,
      authoring_task_id: owner.authoring_task_id,
      returned_to_authoring_task: owner.returned_to_authoring_task,
    }, valid);
    writeExpertArtifact('expert_publish_confirmation', {
      confirmation,
      cancel,
      confirm,
      screenshot_evidence: result.screenshot_evidence,
    }, valid);
    writeExpertArtifact('expert_publish_operation', {
      expert_id: owner.expert_id,
      release_id: confirm.release_id,
      version_id: confirm.version_id || null,
      terminal_state: confirm.terminal_state,
      version_delta: confirm.version_delta,
      release_delta: confirm.release_delta,
    }, valid);
    writeExpertArtifact('expert_share_authorization', viewer, valid);
    writeExpertArtifact('expert_runtime_trace', {
      owner,
      viewer,
      records,
      screenshot_evidence: result.screenshot_evidence,
    }, valid);
    recordAssertion(
      state,
      'Expert同会话原生发布与第二账号首轮闭环',
      '真实Claude Authoring任务必须创建同一owner draft、完成debug、回到原authoring task；取消不落版本，确认恰好落一个版本/release；不同viewer账号可发现并完成真实首轮。',
      valid,
      JSON.stringify({ owner, viewer, confirmation, cancel, confirm, screenshot_evidence: result.screenshot_evidence }),
    );
    state.artifacts.core_beta_capability_selection = {
      expert_id: owner.expert_id,
      release_id: confirm.release_id,
      authoring_task_id: owner.authoring_task_id,
      viewer_task_id: viewer.task_id,
    };
    state.artifacts.core_beta_capability_execution = result;
    state.artifacts.capability_selection = state.artifacts.expert_draft_lifecycle;
    state.artifacts.capability_execution_event = state.artifacts.expert_runtime_trace;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-018') {
    const scenario = coreBetaScenarioSpec(testCase);
    const result = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'confirmation-matrix',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        required_failures: [
          'unconfirmed',
          'cancelled',
          'expired',
          'invalid',
          'replayed',
          'draft_changed',
          'etag_stale',
          'snapshot_mismatch',
        ],
      },
    });
    const matrix = result.matrix || {};
    const valid = Boolean(
      result.ok
      && coreBetaExpertTypedFailureValid(matrix.unconfirmed, 'expert_publish_confirmation_required')
      && coreBetaExpertTypedFailureValid(matrix.cancelled, 'expert_publish_confirmation_required')
      && coreBetaExpertTypedFailureValid(matrix.expired, 'expert_publish_confirmation_expired')
      && coreBetaExpertTypedFailureValid(matrix.invalid, 'expert_publish_confirmation_invalid')
      && coreBetaExpertTypedFailureValid(matrix.replayed, 'expert_publish_confirmation_required')
      && coreBetaExpertTypedFailureValid(matrix.draft_changed, 'expert_publish_confirmation_stale')
      && coreBetaExpertTypedFailureValid(matrix.etag_stale, 'expert_publish_confirmation_stale')
      && coreBetaExpertTypedFailureValid(matrix.snapshot_mismatch, 'expert_publish_confirmation_stale')
      && Number(result.version_delta || 0) === 0
      && Number(result.release_delta || 0) === 0
      && Number(result.half_version_count || 0) === 0
      && coreBetaExpertEvidenceScreenshotsValid(
        result.screenshot_evidence,
        ['confirmation_before', 'cancelled_after', 'stale_after', 'replay_after'],
        { caseDir, state },
      )
    );
    writeExpertArtifact('expert_publish_confirmation', result, valid);
    writeExpertArtifact('expert_publish_operation', {
      matrix,
      version_delta: result.version_delta,
      release_delta: result.release_delta,
      half_version_count: result.half_version_count,
    }, valid);
    writeExpertArtifact('negative_ui_trace', {
      failure_codes: Object.fromEntries(Object.entries(matrix).map(([name, item]) => [name, item?.code || null])),
      screenshot_evidence: result.screenshot_evidence,
    }, valid);
    recordAssertion(
      state,
      'Expert发布确认一次性挑战安全矩阵',
      '未确认、取消、过期、重放、草稿/ETag/snapshot变化必须返回精确错误码并保持0 version/release/half-state。',
      valid,
      JSON.stringify(result),
    );
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_publish_confirmation;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-019') {
    const scenario = coreBetaScenarioSpec(testCase);
    const result = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'surface-matrix',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        expected_tool_names: CORE_BETA_EXPERT_AUTHORING_TOOLS,
        expected_builder_graph: ['qwork.builtin.expert-authoring', 'expert-creator', 'skill-creator-qbot'],
        runtime_families: ['claude-code', 'codex'],
      },
    });
    const claude = result.claude || {};
    const codex = result.codex || {};
    const negative = result.negative || {};
    const exactTools = (value) => (
      Array.isArray(value?.tool_names)
      && value.tool_names.length === CORE_BETA_EXPERT_AUTHORING_TOOLS.length
      && new Set(value.tool_names).size === CORE_BETA_EXPERT_AUTHORING_TOOLS.length
      && CORE_BETA_EXPERT_AUTHORING_TOOLS.every((name) => value.tool_names.includes(name))
      && Array.isArray(value.tool_digests)
      && value.tool_digests.length === CORE_BETA_EXPERT_AUTHORING_TOOLS.length
      && value.tool_digests.every((digest) => /^[a-f0-9]{64}$/i.test(String(digest)))
    );
    const valid = Boolean(
      result.ok
      && exactTools(claude)
      && exactTools(codex)
      && /^[a-f0-9]{64}$/i.test(String(claude.catalog_digest || ''))
      && claude.catalog_digest === codex.catalog_digest
      && claude.exact_builder_graph === true
      && codex.exact_builder_graph === true
      && Number(negative.ordinary_expert_tool_count || 0) === 0
      && coreBetaExpertTypedFailureValid(negative.ask_mode, 'expert_draft_authoring_read_only')
      && coreBetaExpertTypedFailureValid(negative.forged_graph, 'expert_draft_authoring_authority_invalid')
      && coreBetaExpertTypedFailureValid(negative.partial_catalog, 'expert_draft_authoring_catalog_invalid')
      && coreBetaExpertTypedFailureValid(negative.digest_drift, 'expert_draft_authoring_catalog_invalid')
      && coreBetaExpertTypedFailureValid(negative.missing_transport, 'expert_draft_authoring_transport_unavailable')
      && coreBetaExpertEvidenceScreenshotsValid(
        result.screenshot_evidence,
        ['claude_surface', 'codex_surface', 'ask_read_only', 'ordinary_expert_no_tools'],
        { caseDir, state },
      )
    );
    writeExpertArtifact('expert_authoring_mcp_trace', {
      expected_tool_names: CORE_BETA_EXPERT_AUTHORING_TOOLS,
      claude,
      codex,
      negative,
      screenshot_evidence: result.screenshot_evidence,
    }, valid);
    writeExpertArtifact('expert_builder_trace', {
      claude,
      codex,
      exact_builder_graph: ['qwork.builtin.expert-authoring', 'expert-creator', 'skill-creator-qbot'],
    }, valid);
    writeExpertArtifact('negative_tool_trace', negative, valid);
    recordAssertion(
      state,
      'Expert Authoring 17工具双runtime同构与fail-closed',
      'Claude/Codex只能在精确builtin builder图下得到同一17工具+digest；Ask、普通专家、伪造图、残缺/漂移catalog和缺失transport均不得突变。',
      valid,
      JSON.stringify({ claude, codex, negative, screenshot_evidence: result.screenshot_evidence }),
    );
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_authoring_mcp_trace;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-020') {
    const scenario = coreBetaScenarioSpec(testCase);
    const result = await invokeCoreBetaFixtureControl({
      options,
      testCase,
      scenario,
      phase: 'security-matrix',
      payload: {
        lease_id: state.artifacts.core_beta_fixture_lease?.lease_id || null,
        required_negative_probes: [
          'wrong_origin',
          'wrong_path',
          'wrong_host',
          'invalid_method',
          'oversize_request',
          'after_turn',
        ],
      },
    });
    const probes = result.probes || {};
    const forbiddenEnv = Array.isArray(result.forbidden_env_matches) ? result.forbidden_env_matches : [];
    const valid = Boolean(
      result.ok
      && result.loopback_host === '127.0.0.1'
      && String(result.random_path || '').startsWith('/qbot-expert-authoring/')
      && Number(result.safe_env_key_count || 0) >= 1
      && forbiddenEnv.length === 0
      && result.ambient_control_plane_present === false
      && result.bearer_present === false
      && result.owner_authority_present === false
      && result.turn_reuse_succeeded === false
      && coreBetaExpertTypedFailureValid(probes.wrong_origin, 'expert_authoring_bridge_origin_invalid')
      && coreBetaExpertTypedFailureValid(probes.wrong_path, 'expert_authoring_bridge_not_found')
      && coreBetaExpertTypedFailureValid(probes.wrong_host, 'expert_authoring_bridge_host_invalid')
      && coreBetaExpertTypedFailureValid(probes.invalid_method, 'expert_authoring_bridge_method_invalid')
      && coreBetaExpertTypedFailureValid(probes.oversize_request, 'expert_authoring_bridge_request_too_large')
      && coreBetaExpertTypedFailureValid(probes.after_turn, 'expert_authoring_bridge_closed')
      && coreBetaExpertEvidenceScreenshotsValid(
        result.screenshot_evidence,
        ['authoring_turn_active', 'negative_probes', 'authoring_turn_closed'],
        { caseDir, state },
      )
    );
    writeExpertArtifact('expert_authoring_security_trace', result, valid);
    writeExpertArtifact('runtime_env_redacted', {
      safe_env_keys: result.safe_env_keys || [],
      forbidden_env_matches: forbiddenEnv,
      ambient_control_plane_present: result.ambient_control_plane_present,
      bearer_present: result.bearer_present,
      owner_authority_present: result.owner_authority_present,
    }, valid);
    writeExpertArtifact('credential_redaction_scan', {
      forbidden_env_matches: forbiddenEnv,
      bearer_present: result.bearer_present,
      owner_authority_present: result.owner_authority_present,
    }, valid);
    writeExpertArtifact('negative_tool_trace', probes, valid);
    writeExpertArtifact('log_excerpt', {
      redacted_events: result.redacted_events || [],
      secret_value_count: Number(result.secret_value_count || 0),
      probe_codes: Object.fromEntries(Object.entries(probes).map(([name, item]) => [name, item?.code || null])),
    }, valid && Number(result.secret_value_count || 0) === 0);
    recordAssertion(
      state,
      'Expert Authoring turn-local loopback与ambient authority隔离',
      '子进程只能得到随机127.0.0.1 bridge和安全env；错误origin/path/host/method/大小及turn结束后复用必须精确拒绝，且无bearer/owner/control-plane泄露。',
      valid,
      JSON.stringify(result),
    );
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = state.artifacts.expert_authoring_security_trace;
    return;
  }

  if (testCase.id === 'BETA-EXPERT-001') {
    const selected = bridge.experts.find((item) => item?.owned === true && item?.activeReleaseId && item?.id)
      || bridge.experts.find((item) => item?.activeReleaseId && item?.id);
    if (!selected) {
      markBlocked(state, 'BETA-EXPERT-001 需要至少1个已发布专家用于搜索/详情/召唤。');
      return;
    }
    const selectedLabel = String(
      selected?.display?.label
      || selected?.label
      || selected?.name
      || selected?.id
      || '',
    );
    const pageTextBefore = await mainSurfaceText(page);
    const search = page.locator('[data-testid="expert-search-input"], input[placeholder*="搜索专家"]').first();
    if (await visible(search, 1_000)) {
      await search.fill(selectedLabel);
      await page.waitForTimeout(500);
    }
    const card = page.locator(`[data-testid="expert-card-${cssEscape(selected.id)}"], [data-expert-id="${cssEscape(selected.id)}"]`).first();
    const cardVisible = await visible(card, 1_500)
      || await page.locator('[data-testid^="expert-card-"]').filter({ hasText: selectedLabel }).first().isVisible({ timeout: 1_500 }).catch(() => false);
    const ownedExpertIds = bridge.experts
      .filter((item) => item?.owned === true)
      .map((item) => String(item.id || ''))
      .filter(Boolean);
    const releaseNavigation = page.locator('[data-testid="expert-v2-nav-releases"]').first();
    if (await visible(releaseNavigation, 1_500)) {
      await releaseNavigation.click();
      await page.waitForTimeout(500);
    }
    const ownedProjection = await page.evaluate((expectedIds) => {
      const rows = Array.from(document.querySelectorAll(
        '[data-testid^="expert-v2-expert-"], [data-testid^="expert-v2-archived-"]',
      ));
      const visibleIds = rows
        .filter((row) => {
          const style = getComputedStyle(row);
          return style.display !== 'none' && style.visibility !== 'hidden';
        })
        .map((row) => String(row.getAttribute('data-testid') || '')
          .replace(/^expert-v2-(?:expert|archived)-/, ''));
      const nav = document.querySelector('[data-testid="expert-v2-nav-releases"]');
      return {
        expected_owned_ids: expectedIds,
        visible_ids: visibleIds,
        nav_text: String(nav?.textContent || '').replace(/\s+/g, ' ').trim(),
      };
    }, ownedExpertIds);
    const ownedProjectionOracleValid = ownedExpertIds.every((id) => ownedProjection.visible_ids.includes(id))
      && ownedProjection.visible_ids.every((id) => ownedExpertIds.includes(id))
      && new RegExp(`发布记录\\s*${ownedExpertIds.length}(?:\\D|$)`).test(ownedProjection.nav_text);
    ownedProjection.valid = true;
    ownedProjection.evidence_valid = true;
    ownedProjection.oracle_valid = ownedProjectionOracleValid;
    const ownedProjectionFile = path.join(caseDir, 'expert-owned-release-projection.json');
    writeJsonFile(ownedProjectionFile, ownedProjection);
    state.artifacts.product_state_diff = ownedProjectionFile;

    const upstreamState = await captureCoreBetaPublicState(page, testCase);
    await openNewTask(page, state);
    const cleanDraftState = await captureCoreBetaPublicState(page, testCase);
    const detail = await page.evaluate(async (expertId) => {
      const lifecycle = window.agent.expertLifecycle;
      const item = await lifecycle.get(expertId);
      const recent = await lifecycle.recordRecent?.(expertId);
      const setExpertResult = await window.agent.setExpert(expertId);
      return { item, recent, set_expert_result: setExpertResult };
    }, selected.id);
    const capabilitiesReadback = await coreBetaCapabilitiesReadbackWithRetry(
      () => page.evaluate(async () => {
        if (typeof window.agent?.capabilities !== 'function') {
          return { __error: 'missing bridge method capabilities' };
        }
        try {
          return await window.agent.capabilities();
        } catch (error) {
          return { __error: String(error?.message || error) };
        }
      }).catch((error) => ({
        __error: `expert capabilities evaluate failed: ${String(error?.message || error)}`,
      })),
      {
        maxAttempts: 3,
        timeoutMs: 7_000,
        retryDelayMs: 250,
        delay: (ms) => page.waitForTimeout(ms),
      },
    );
    const selection = await captureCoreBetaPublicState(page, testCase);
    detail.capabilities = capabilitiesReadback.value;
    detail.capabilities_readback_ok = capabilitiesReadback.ok;
    detail.capabilities_readback_attempts = capabilitiesReadback.attempts;
    const selectedExpertId = String(selected.id || '');
    const publicExpert = selection.expert;
    const publicExpertId = String(
      publicExpert?.id
      || publicExpert?.expertId
      || (typeof publicExpert === 'string' ? publicExpert : ''),
    );
    const capabilitiesExpert = detail.capabilities?.currentExpert
      ?? detail.capabilities?.expertIdentity
      ?? null;
    const capabilitiesExpertId = String(
      capabilitiesExpert?.id
      || capabilitiesExpert?.expertId
      || (typeof capabilitiesExpert === 'string' ? capabilitiesExpert : ''),
    );
    const publicIdentityMatches = Boolean(selectedExpertId && publicExpertId === selectedExpertId);
    const capabilitiesIdentityMatches = Boolean(
      capabilitiesReadback.ok
      && selectedExpertId
      && capabilitiesExpertId === selectedExpertId,
    );
    const expertSelectionReadbackOk = publicIdentityMatches || capabilitiesIdentityMatches;
    await executeConversationTurns({ page, state, testCase, caseDir, timeoutMs });
    const conversationState = await captureCoreBetaPublicState(page, testCase);
    const taskVerdict = coreBetaExpertSummonTaskVerdict({
      selected,
      upstreamState,
      cleanDraftState,
      selectionState: selection,
      conversationState,
      recent: detail.recent,
      setExpertResult: detail.set_expert_result,
    });
    const informationArchitecture = /通用助手/.test(pageTextBefore)
      && /最近|召唤/.test(pageTextBefore)
      && /我的专家/.test(pageTextBefore)
      && /分享给我|共享/.test(pageTextBefore)
      && /专家市场|市场/.test(pageTextBefore);
    writeExpertArtifact('expert_draft_lifecycle', { drafts: bridge.drafts });
    writeExpertArtifact('expert_dependency_graph', detail.item?.version || detail.item);
    const runtimeOracleValid = informationArchitecture
      && cardVisible
      && publicIdentityMatches
      && taskVerdict.valid
      && ownedProjection.oracle_valid;
    const runtimeTraceFile = writeExpertArtifact('expert_runtime_trace', {
      valid: true,
      evidence_valid: true,
      oracle_valid: runtimeOracleValid,
      information_architecture: informationArchitecture,
      searched_card_visible: cardVisible,
      selected,
      selection,
      recent: detail.recent,
      set_expert_result: detail.set_expert_result,
      capabilities: detail.capabilities,
      capabilities_readback_ok: detail.capabilities_readback_ok,
      capabilities_readback_attempts: detail.capabilities_readback_attempts,
      public_identity_matches: publicIdentityMatches,
      capabilities_identity_matches: capabilitiesIdentityMatches,
      owned_release_projection: ownedProjection,
      task_binding: taskVerdict,
    }, true);
    state.artifacts.core_beta_capability_selection = selection;
    state.artifacts.core_beta_capability_execution = detail;
    state.artifacts.capability_selection = identityFile;
    state.artifacts.capability_execution_event = runtimeTraceFile;
    recordAssertion(
      state,
      '专家选择只读身份读回',
      'capabilities 或独立公开状态必须精确读回本次 setExpert 的 expertId；IPC 超时只允许重试只读接口。',
      expertSelectionReadbackOk,
      JSON.stringify({
        selected_expert_id: selectedExpertId,
        public_expert_id: publicExpertId,
        capabilities_expert_id: capabilitiesExpertId,
        capabilities_readback_attempts: capabilitiesReadback.attempts,
      }),
      expertSelectionReadbackOk ? '' : 'automation_error',
    );
    recordAssertion(
      state,
      '本Case独立专家任务归属',
      '召唤前必须进入taskId为空的干净草稿；发送后必须产生不同于上游Case的新taskId，并绑定本次发送和消息。',
      taskVerdict.task_binding_valid,
      JSON.stringify(taskVerdict),
      taskVerdict.task_binding_valid ? '' : 'automation_error',
    );
    recordAssertion(
      state,
      '专家召唤identity闭环',
      'expertId/versionId/releaseId必须在选择读回、发送后task、setExpert回执与最近召唤中完全一致。',
      taskVerdict.identity_binding_valid,
      JSON.stringify(taskVerdict),
      'bug',
    );
    recordAssertion(state, '专家中心分区、搜索、详情与召唤闭环', '五类分区必须可见，搜索命中exact expert，召唤后新task identity与最近召唤一致。', runtimeOracleValid, JSON.stringify({ informationArchitecture, cardVisible, selected, selection: selection.expert, task_binding: taskVerdict }));
    recordAssertion(
      state,
      '发布记录仅显示本人创建专家',
      '发布记录计数与列表必须严格等于 expertLifecycle.list() 中 owned=true 的专家集合，共享和内置专家不得混入管理面。',
      ownedProjection.oracle_valid,
      JSON.stringify(ownedProjection),
    );
    return;
  }

  writeExpertArtifact('expert_draft_lifecycle', bridge.drafts, Array.isArray(bridge.drafts));
  writeExpertArtifact('expert_dependency_graph', { experts: bridge.experts }, Array.isArray(bridge.experts));
  state.artifacts.capability_selection = identityFile;
  state.artifacts.capability_execution_event = identityFile;
}

function setCoreBetaEvidence(state, role, evidence) {
  state.artifacts.core_beta_evidence ||= {};
  state.artifacts.core_beta_evidence[role] = {
    available: true,
    captured_at: new Date().toISOString(),
    ...evidence,
  };
  return state.artifacts.core_beta_evidence[role];
}

export function coreBetaBatchSharedDeadline(
  entries = [],
  requestedTimeoutMs = DEFAULT_TIMEOUT_MS,
  collectionStartedAtMs = Date.now(),
) {
  const requested = Number(requestedTimeoutMs || DEFAULT_TIMEOUT_MS);
  const timeoutMs = Math.min(
    MAX_REPLY_WAIT_MS,
    Math.max(MIN_REPLY_WAIT_MS, Number.isFinite(requested) ? requested : DEFAULT_TIMEOUT_MS),
  );
  const startedAtMs = Number(collectionStartedAtMs || Date.now());
  const dispatchTimes = (Array.isArray(entries) ? entries : [])
    .map((entry) => Date.parse(String(entry?.dispatched_at || '')))
    .filter((value) => Number.isFinite(value) && value > 0);
  const latestDispatchAtMs = dispatchTimes.length ? Math.max(...dispatchTimes) : startedAtMs;
  // One shared deadline covers the whole batch.  It is intentionally anchored
  // to the last confirmed dispatch so the final task receives the same reply
  // budget as a serial task, while the collector revisits every task in rounds
  // instead of multiplying the timeout by the batch size.
  const deadlineAtMs = Math.max(
    latestDispatchAtMs + timeoutMs,
    startedAtMs + MIN_REPLY_WAIT_MS,
  );
  return {
    collection_started_at_ms: startedAtMs,
    latest_dispatch_at_ms: latestDispatchAtMs,
    timeout_ms: timeoutMs,
    deadline_at_ms: deadlineAtMs,
    additive_per_task_timeout: false,
  };
}

function coreBetaBatchEvidenceFilePresent(file) {
  return typeof file === 'string'
    && Boolean(file)
    && fs.existsSync(file)
    && fs.statSync(file).isFile()
    && fs.statSync(file).size > 0;
}

function coreBetaBatchScreenshotPresent(file) {
  return coreBetaBatchEvidenceFilePresent(file)
    && fs.statSync(file).size >= 128;
}

export function coreBetaBatchTerminalEvidence(entries = [], {
  deadlineAtMs = 0,
  deadlineReached = false,
} = {}) {
  const rows = Array.isArray(entries) ? entries : [];
  const taskIds = rows.map((entry) => String(entry?.task_id || ''));
  const taskIdsUnique = rows.length > 0
    && taskIds.every(Boolean)
    && new Set(taskIds).size === rows.length;
  const dispatchReceiptsComplete = rows.length > 0 && rows.every((entry) => (
    entry?.send_receipt?.confirmed === true
    && String(entry?.send_receipt?.confirmed_at || '')
    && coreBetaBatchScreenshotPresent(entry?.dispatch_screenshot)
  ));
  const terminalRowsComplete = rows.length > 0 && rows.every((entry) => (
    String(entry?.terminal_outcome || '')
    && String(entry?.terminal_at || '')
    && Number(entry?.observation_count || 0) > 0
    && entry?.last_observation
    && typeof entry.last_observation === 'object'
    && coreBetaBatchScreenshotPresent(entry?.terminal_screenshot)
  ));
  const allCompleted = terminalRowsComplete && rows.every((entry) => (
    entry?.ok === true
    && entry?.terminal_outcome === 'reply_completed'
  ));
  const allTerminalBeforeDeadline = terminalRowsComplete && rows.every((entry) => (
    !['', 'pending'].includes(String(entry?.terminal_outcome || ''))
  ));
  const available = taskIdsUnique
    && dispatchReceiptsComplete
    && terminalRowsComplete
    && (allCompleted || allTerminalBeforeDeadline || deadlineReached);
  const completedCount = rows.filter((entry) => entry?.terminal_outcome === 'reply_completed').length;
  const replyPresentCount = rows.filter((entry) => entry?.last_observation?.assistant_reply_present === true).length;
  const timeoutCount = rows.filter((entry) => (
    /batch_deadline|deadline/.test(String(entry?.terminal_outcome || ''))
  )).length;
  const terminalOutcome = allCompleted
    ? 'batch_completed'
    : deadlineReached && timeoutCount > 0
      ? 'batch_partial_timeout'
      : 'batch_terminal_failure';
  return {
    available,
    completion_observed: allCompleted,
    terminal_failure: available && !allCompleted,
    terminal_outcome: terminalOutcome,
    source: 'per-task confirmed send receipt + round-robin taskId collection + per-task terminal screenshot',
    dispatched: rows.length,
    completed: completedCount,
    reply_present: replyPresentCount,
    failed_or_timed_out: Math.max(0, rows.length - completedCount),
    timeout_count: timeoutCount,
    task_ids_unique: taskIdsUnique,
    dispatch_receipts_complete: dispatchReceiptsComplete,
    terminal_rows_complete: terminalRowsComplete,
    shared_deadline_reached: Boolean(deadlineReached),
    shared_deadline_at: Number(deadlineAtMs || 0)
      ? new Date(Number(deadlineAtMs)).toISOString()
      : '',
    reason: available
      ? ''
      : '批量终态证据必须覆盖每条唯一 taskId 的确认发送回执、发送后截图、任务状态观察和终态截图。',
  };
}

export function coreBetaBatchReplyCompletionPayload(entries = [], terminalEvidence = {}, {
  timeoutMs = MAX_REPLY_WAIT_MS,
  minWaitMs = MIN_REPLY_WAIT_MS,
} = {}) {
  const rows = Array.isArray(entries) ? entries : [];
  const terminalRowsComplete = terminalEvidence?.terminal_rows_complete === true;
  const evidenceComplete = terminalEvidence?.available === true;
  const deadlineEntry = rows.find((entry) => (
    /batch_deadline|deadline/.test(String(entry?.terminal_outcome || ''))
  ));
  const repliesReachedTerminal = rows.length > 0 && rows.every((entry) => (
    ['reply_completed', 'reply_oracle_mismatch'].includes(String(entry?.terminal_outcome || ''))
  ));
  const complete = evidenceComplete && terminalRowsComplete && repliesReachedTerminal;
  const terminalScreenshot = String(deadlineEntry?.terminal_screenshot || '');
  const terminalScreenshotSha256 = coreBetaBatchScreenshotPresent(terminalScreenshot)
    ? createHash('sha256').update(fs.readFileSync(terminalScreenshot)).digest('hex')
    : '';
  const dispatchedAtMs = Date.parse(String(deadlineEntry?.dispatched_at || ''));
  const terminalAtMs = Date.parse(String(deadlineEntry?.terminal_at || ''));
  const waitedMs = Number.isFinite(dispatchedAtMs) && Number.isFinite(terminalAtMs)
    ? Math.max(0, terminalAtMs - dispatchedAtMs)
    : 0;
  const terminalScreenshots = rows.map((entry) => {
    const file = String(entry?.terminal_screenshot || '');
    return {
      task_id: String(entry?.task_id || ''),
      terminal_outcome: String(entry?.terminal_outcome || ''),
      terminal_at: String(entry?.terminal_at || ''),
      path: file,
      sha256: coreBetaBatchScreenshotPresent(file)
        ? createHash('sha256').update(fs.readFileSync(file)).digest('hex')
        : '',
    };
  });
  return {
    complete,
    evidence_complete: evidenceComplete,
    reply_count: rows.length,
    labels: rows.map((entry) => `批量任务 ${Number(entry?.index || 0) + 1}`),
    terminal_failure: Boolean(evidenceComplete && deadlineEntry),
    terminal_outcome: deadlineEntry ? 'timed_out' : complete ? 'completed' : '',
    assistant_reply_present: Boolean(deadlineEntry?.last_observation?.assistant_reply_present),
    waited_ms: waitedMs,
    min_wait_ms: Number(minWaitMs || MIN_REPLY_WAIT_MS),
    timeout_ms: Number(timeoutMs || MAX_REPLY_WAIT_MS),
    observed_running_after_send: Boolean(deadlineEntry?.send_receipt?.running_observed),
    running_after: typeof deadlineEntry?.last_observation?.running === 'boolean'
      ? deadlineEntry.last_observation.running
      : null,
    no_reply_stable_observations: 0,
    terminal_reconciliation_performed: true,
    terminal_reconciliation_task_bound: Boolean(deadlineEntry?.task_id),
    terminal_reconciliation_prompt_bound: Boolean(deadlineEntry?.prompt),
    terminal_reconciliation_reply_present: Boolean(deadlineEntry?.last_observation?.assistant_reply_present),
    terminal_reason: deadlineEntry
      ? `批量共享截止时间终态：${deadlineEntry.terminal_outcome}；taskId=${deadlineEntry.task_id}`
      : '',
    confirmed_send_receipt: terminalEvidence?.dispatch_receipts_complete === true,
    terminal_screenshot: terminalScreenshot,
    terminal_screenshot_sha256: terminalScreenshotSha256,
    timeout_screenshot: terminalScreenshot,
    timeout_screenshot_sha256: terminalScreenshotSha256,
    batch_terminal_evidence: terminalEvidence,
    batch_terminal_screenshots: terminalScreenshots,
  };
}

export function coreBetaBatchPendingPoolEvidence(rows = [], {
  expectedTaskIds = [],
  minimumPending = 1,
  capturedAt = '',
} = {}) {
  const expected = [...new Set((Array.isArray(expectedTaskIds) ? expectedTaskIds : [])
    .map((item) => String(item || '').trim())
    .filter(Boolean))];
  const observations = Array.isArray(rows) ? rows : [];
  const byTaskId = new Map(observations.map((item) => [String(item?.task_id || ''), item]));
  const normalized = expected.map((taskId) => {
    const observed = byTaskId.get(taskId) || {};
    return {
      task_id: taskId,
      item_present: observed.item_present === true,
      running_indicator_present: observed.running_indicator_present === true,
      running_indicator_visible: observed.running_indicator_visible === true,
    };
  });
  const minimum = Number(minimumPending || 0);
  const pendingTaskIds = normalized
    .filter((item) => item.running_indicator_present)
    .map((item) => item.task_id);
  const visiblePendingTaskIds = normalized
    .filter((item) => item.running_indicator_visible)
    .map((item) => item.task_id);
  const taskItemsComplete = expected.length > 0
    && normalized.every((item) => item.item_present);
  const thresholdValid = Number.isInteger(minimum)
    && minimum >= 1
    && minimum <= expected.length;
  return {
    available: taskItemsComplete && thresholdValid,
    completion_observed: taskItemsComplete
      && thresholdValid
      && pendingTaskIds.length >= minimum,
    source: 'visible sidebar session-item + run-dot[title="正在执行"]',
    captured_at: String(capturedAt || ''),
    expected_task_count: expected.length,
    task_item_count: normalized.filter((item) => item.item_present).length,
    pending_count: pendingTaskIds.length,
    visible_pending_count: visiblePendingTaskIds.length,
    minimum_pending_required: minimum,
    pending_task_ids: pendingTaskIds,
    visible_pending_task_ids: visiblePendingTaskIds,
    observations: normalized,
    reason: taskItemsComplete && thresholdValid
      ? pendingTaskIds.length >= minimum
        ? ''
        : `末条派发后待回复会话仅 ${pendingTaskIds.length} 条，低于要求 ${minimum} 条。`
      : `待回复池证据不完整：taskItems=${normalized.filter((item) => item.item_present).length}/${expected.length}；minimum=${minimum}`,
  };
}

function coreBetaSanitizeBatchEntries(entries = []) {
  return entries.map(({ before, reply, _last_stable_reply, _last_observed_reply, ...entry }) => ({
    ...entry,
    reply_excerpt: clip(reply, 240),
  }));
}

async function coreBetaDispatchBatch(ctx) {
  const requested = Math.min(20, Math.max(1, Number(ctx.state.batch_size || 20)));
  const minimumReplyChars = Number(ctx.assertionContract?.batch_reply_min_chars || 0);
  if (!Number.isInteger(minimumReplyChars) || minimumReplyChars < 500 || minimumReplyChars > 5000) {
    throw new Error(`批量派发缺少有效 batch_reply_min_chars：${minimumReplyChars || 'missing'}`);
  }
  const prepared = Array.isArray(ctx.batch) && ctx.batch.length === requested
    ? ctx.batch
    : Array.from({ length: requested }, (_, index) => ({
      index,
      marker: coreBetaBatchTaskMarker(ctx.state.id, index),
    }));
  const entries = prepared.map((preparedEntry, index) => ({
      index,
      marker: preparedEntry.marker,
      prompt: `请为“${preparedEntry.marker}”撰写一份不少于${minimumReplyChars}字的内测风险评估。必须原样包含该标记，并使用“范围与假设、用户风险、数据与隐私风险、稳定性与恢复、上线建议”五个明确标题；每节都给出可执行检查项，不要省略任何章节。`,
      minimum_reply_chars: minimumReplyChars,
      task_id: '',
      dispatched_at: '',
      collected_at: '',
      reply_sha256: '',
      dispatch_screenshot: '',
      send_receipt: null,
      observation_count: 0,
      stable_observations: 0,
      last_observation: null,
      terminal_outcome: '',
      terminal_at: '',
      terminal_screenshot: '',
      ok: false,
    }));
  ctx.batch = entries;
  for (const entry of entries) {
    await openNewTask(ctx.page, ctx.state);
    const reset = await resetComposerControls(ctx.page, ctx.state, ctx.caseDir, {
      skillMode: 'disabled',
      connectorMode: 'disabled',
    });
    if (!reset) throw new Error(`批量派发第 ${entry.index + 1} 条能力清理失败。`);
    const before = await conversationSnapshot(ctx.page);
    if (!Array.isArray(ctx.state.artifacts.sent_prompts)) ctx.state.artifacts.sent_prompts = [];
    ctx.state.artifacts.sent_prompts.push({
      label: `批量派发 ${entry.index + 1}`,
      prompt: entry.prompt,
      recorded_at: new Date().toISOString(),
    });
    await fillComposer(ctx.page, entry.prompt, ctx.state, `批量派发 ${entry.index + 1} 输入`);
    const receipt = await send(ctx.page, ctx.state, `批量派发 ${entry.index + 1}`);
    const task = await qbotE2EState(ctx.page);
    entry.task_id = String(task?.activeId || receipt?.snapshot?.activeId || '');
    entry.dispatched_at = new Date().toISOString();
    entry.before = before;
    if (!entry.task_id) throw new Error(`批量派发第 ${entry.index + 1} 条缺少 taskId。`);
    const dispatchScreenshot = await shot(
      ctx.page,
      ctx.caseDir,
      `batch-dispatch-${String(entry.index + 1).padStart(2, '0')}-after-send`,
    );
    const screenshotKey = `batch_dispatch_${String(entry.index + 1).padStart(2, '0')}_after_send`;
    ctx.state.screenshots[screenshotKey] = dispatchScreenshot;
    const confirmedReceipt = Array.isArray(ctx.state.artifacts.send_receipts)
      ? [...ctx.state.artifacts.send_receipts].reverse().find((item) => (
        item?.action === `批量派发 ${entry.index + 1}`
        && String(item?.confirmed_at || '')
      ))
      : null;
    entry.dispatch_screenshot = dispatchScreenshot;
    entry.send_receipt = {
      confirmed: receipt?.ok === true && Boolean(confirmedReceipt),
      confirmed_at: String(confirmedReceipt?.confirmed_at || ''),
      action: String(confirmedReceipt?.action || `批量派发 ${entry.index + 1}`),
      task_id: entry.task_id,
      reasons: Array.isArray(receipt?.reasons) ? receipt.reasons : [],
      state_readback: {
        active_id: String(task?.activeId || ''),
        running: Boolean(task?.running),
        message_count: Number(task?.messageCount || 0),
      },
    };
    ctx.state.artifacts.core_beta_batch_dispatch = coreBetaSanitizeBatchEntries(entries);
    // Persist after every confirmed send.  A host/runner failure must not erase
    // proof that an individual task was accepted by the product.
    writeJsonFile(
      path.join(ctx.caseDir, 'batch-dispatch-ledger.json'),
      ctx.state.artifacts.core_beta_batch_dispatch,
    );
  }
  const ids = entries.map((item) => item.task_id);
  const unique = new Set(ids).size === entries.length;
  const receiptsComplete = entries.every((entry) => (
    entry.send_receipt?.confirmed === true
    && coreBetaBatchEvidenceFilePresent(entry.dispatch_screenshot)
  ));
  ctx.state.artifacts.core_beta_batch_dispatch = coreBetaSanitizeBatchEntries(entries);
  writeJsonFile(path.join(ctx.caseDir, 'batch-dispatch-ledger.json'), ctx.state.artifacts.core_beta_batch_dispatch);
  setCoreBetaEvidence(ctx.state, 'send_receipt', {
    available: unique && receiptsComplete,
    source: 'per-task confirmed product send receipt + after-send screenshot',
    expected_count: entries.length,
    confirmed_count: entries.filter((entry) => entry.send_receipt?.confirmed === true).length,
    screenshot_count: entries.filter((entry) => coreBetaBatchEvidenceFilePresent(entry.dispatch_screenshot)).length,
    task_ids_unique: unique,
    task_id_sha256s: entries.map((entry) => sha256Text(entry.task_id)),
  });
  return {
    ok: unique && receiptsComplete,
    selector_or_testid: 'composer-send',
    event: 'dispatch-batch',
    state_readback: {
      requested,
      dispatched: entries.length,
      unique_task_ids: new Set(ids).size,
      confirmed_send_receipts: entries.filter((entry) => entry.send_receipt?.confirmed === true).length,
      after_send_screenshots: entries.filter((entry) => coreBetaBatchEvidenceFilePresent(entry.dispatch_screenshot)).length,
    },
    actual: `dispatched=${entries.length}；uniqueTaskIds=${new Set(ids).size}；confirmedReceipts=${entries.filter((entry) => entry.send_receipt?.confirmed === true).length}；afterSendScreenshots=${entries.filter((entry) => coreBetaBatchEvidenceFilePresent(entry.dispatch_screenshot)).length}`,
  };
}

async function coreBetaAssertBatchPendingPool(ctx) {
  if (!Array.isArray(ctx.batch) || !ctx.batch.length) {
    throw new Error('待回复池取证前没有批量派发账本。');
  }
  const minimumPending = Number(ctx.assertionContract?.batch_min_pending_after_dispatch || 0);
  if (
    !Number.isInteger(minimumPending)
    || minimumPending < 1
    || minimumPending > ctx.batch.length
  ) {
    throw new Error(`批量待回复池缺少有效 batch_min_pending_after_dispatch：${minimumPending || 'missing'}`);
  }
  await ensureSidebarExpanded(ctx.page, ctx.state);
  const taskToggle = ctx.page.locator('[data-testid="sidebar-task-toggle"]').first();
  if (await visible(taskToggle, 1000)) {
    const expanded = await taskToggle.getAttribute('aria-expanded').catch(() => '');
    if (expanded !== 'true') {
      await taskToggle.click({ force: true }).catch(async () => taskToggle.evaluate((element) => element.click()));
      await ctx.page.waitForTimeout(250);
    }
  }
  const expectedTaskIds = ctx.batch.map((entry) => entry.task_id);
  const rows = await ctx.page.evaluate((taskIds) => {
    const itemById = new Map(
      Array.from(document.querySelectorAll('[data-testid^="session-item-"]')).map((item) => [
        String(item.getAttribute('data-testid') || '').replace(/^session-item-/, ''),
        item,
      ]),
    );
    return taskIds.map((taskId) => {
      const item = itemById.get(taskId) || null;
      const indicator = item?.querySelector('.run-dot[title="正在执行"]') || null;
      const rect = indicator?.getBoundingClientRect();
      const style = indicator ? getComputedStyle(indicator) : null;
      const visible = Boolean(
        indicator
        && rect
        && rect.width > 0
        && rect.height > 0
        && style?.display !== 'none'
        && style?.visibility !== 'hidden',
      );
      return {
        task_id: taskId,
        item_present: Boolean(item),
        running_indicator_present: Boolean(indicator),
        running_indicator_visible: visible,
      };
    });
  }, expectedTaskIds);
  const capturedAt = new Date().toISOString();
  const evidence = coreBetaBatchPendingPoolEvidence(rows, {
    expectedTaskIds,
    minimumPending,
    capturedAt,
  });
  const active = await qbotE2EState(ctx.page);
  const screenshot = await shot(ctx.page, ctx.caseDir, 'batch-dispatch-pending-pool');
  ctx.state.screenshots.batch_dispatch_pending_pool = screenshot;
  const record = {
    ...evidence,
    active_task_id: String(active?.activeId || ''),
    active_task_running: Boolean(active?.running),
    screenshot,
  };
  ctx.state.artifacts.core_beta_batch_pending_pool = record;
  writeJsonFile(path.join(ctx.caseDir, 'batch-pending-pool.json'), record);
  setCoreBetaEvidence(ctx.state, 'public_state_readback', record);
  recordAssertion(
    ctx.state,
    '批量派发后形成可见待回复池',
    `末条派发后、统一回收前，左侧任务列表至少 ${minimumPending} 条本批次 taskId 必须显示“正在执行”。`,
    evidence.completion_observed,
    `pending=${evidence.pending_count}/${evidence.expected_task_count}；minimum=${minimumPending}；visible=${evidence.visible_pending_count}；activeRunning=${Boolean(active?.running)}`,
    evidence.completion_observed
      ? ''
      : active?.running
        ? 'bug'
        : 'test_data',
  );
  return {
    ok: evidence.completion_observed,
    category: evidence.completion_observed
      ? ''
      : active?.running
        ? 'bug'
        : 'test_data',
    selector_or_testid: 'sidebar-task-list .run-dot[title="正在执行"]',
    event: 'readback-pending-pool',
    state_readback: record,
    screenshot,
    actual: `pending=${evidence.pending_count}/${evidence.expected_task_count}；minimum=${minimumPending}；visible=${evidence.visible_pending_count}；activeRunning=${Boolean(active?.running)}`,
  };
}

async function coreBetaObserveBatchEntry(ctx, entry, round, observationLogFile) {
  const observedAt = new Date().toISOString();
  let reopened;
  try {
    reopened = await withReplyPollHardTimeout(
      reopenSessionAndReadback(ctx.page, entry.task_id),
      15_000,
      `batch task ${entry.index + 1} reopen`,
    );
  } catch (error) {
    reopened = { ok: false, reason: error.message, activeId: '', running: false };
  }
  let snapshot = null;
  let publicState = null;
  let reply = '';
  let generating = false;
  let confirmationHandled = false;
  if (reopened.ok && String(reopened.activeId || '') === entry.task_id) {
    confirmationHandled = await withReplyPollHardTimeout(
      resolveAssistantConfirmationModal(ctx.page, {
        state: ctx.state,
        caseDir: ctx.caseDir,
        label: `批量任务 ${entry.index + 1} 回收`,
      }),
      15_000,
      `batch task ${entry.index + 1} confirmation inspection`,
    );
    if (confirmationHandled) await ctx.page.waitForTimeout(800);
    snapshot = await conversationSnapshot(ctx.page).catch(() => null);
    publicState = await qbotE2EState(ctx.page).catch(() => null);
    reply = latestAssistantReplyForPrompt(snapshot || {}, entry.prompt);
    generating = Boolean(publicState?.running)
      || await isAgentGenerating(ctx.page).catch(() => false);
  }
  const activeTaskId = String(snapshot?.activeTaskId || publicState?.activeId || reopened?.activeId || '');
  const userPromptPresent = Boolean(
    snapshot?.userTexts?.some((text) => userMessageMatchesPrompt(text, entry.prompt)),
  );
  const assistantReplyPresent = Boolean(String(reply || '').trim());
  if (assistantReplyPresent) entry._last_observed_reply = reply;
  if (
    assistantReplyPresent
    && !generating
    && activeTaskId === entry.task_id
    && userPromptPresent
  ) {
    if (entry._last_stable_reply === reply) entry.stable_observations = Number(entry.stable_observations || 0) + 1;
    else {
      entry._last_stable_reply = reply;
      entry.stable_observations = 1;
    }
  } else {
    entry.stable_observations = 0;
    if (assistantReplyPresent) entry._last_stable_reply = reply;
  }
  entry.observation_count = Number(entry.observation_count || 0) + 1;
  const observation = {
    round,
    observed_at: observedAt,
    reopen_ok: Boolean(reopened?.ok),
    reopen_reason: String(reopened?.reason || ''),
    expected_task_id: entry.task_id,
    active_task_id: activeTaskId,
    task_identity_matches: activeTaskId === entry.task_id,
    user_prompt_present: userPromptPresent,
    assistant_reply_present: assistantReplyPresent,
    running: generating,
    message_count: Number(publicState?.messageCount ?? snapshot?.bridgeMessageCount ?? 0),
    confirmation_handled: confirmationHandled,
    stable_observations: Number(entry.stable_observations || 0),
    reply_sha256: assistantReplyPresent ? sha256Text(reply) : '',
    reply_excerpt: clip(reply, 240),
  };
  entry.last_observation = observation;
  fs.appendFileSync(observationLogFile, `${JSON.stringify({ index: entry.index, marker: entry.marker, task_id: entry.task_id, ...observation })}\n`);
  const dispatchedAtMs = Date.parse(String(entry.dispatched_at || ''));
  const waitedMs = Number.isFinite(dispatchedAtMs) ? Date.now() - dispatchedAtMs : 0;
  const otherMarkerPresent = ctx.batch.some((other) => (
    other !== entry && String(reply || '').includes(other.marker)
  ));
  if (
    assistantReplyPresent
    && !generating
    && activeTaskId === entry.task_id
    && userPromptPresent
    && Number(entry.stable_observations || 0) >= 2
    && waitedMs >= MIN_REPLY_WAIT_MS
  ) {
    entry.reply = reply;
    entry.reply_sha256 = sha256Text(reply);
    entry.collected_at = observedAt;
    entry.ok = reply.includes(entry.marker)
      && !otherMarkerPresent
      && cleanAssistantText(reply).length >= Number(entry.minimum_reply_chars || 0);
    entry.terminal_outcome = entry.ok ? 'reply_completed' : 'reply_oracle_mismatch';
    entry.terminal_at = observedAt;
  }
  return observation;
}

async function coreBetaCaptureBatchTerminalScreenshot(ctx, entry) {
  if (entry.terminal_screenshot && coreBetaBatchEvidenceFilePresent(entry.terminal_screenshot)) {
    return entry.terminal_screenshot;
  }
  if (String(entry.last_observation?.active_task_id || '') !== entry.task_id) {
    await reopenSessionAndReadback(ctx.page, entry.task_id).catch(() => null);
  }
  const screenshot = await shot(
    ctx.page,
    ctx.caseDir,
    `batch-collect-${String(entry.index + 1).padStart(2, '0')}-${slugify(entry.terminal_outcome || 'terminal')}`,
  );
  const key = `batch_collect_${String(entry.index + 1).padStart(2, '0')}_terminal`;
  ctx.state.screenshots[key] = screenshot;
  entry.terminal_screenshot = screenshot;
  return screenshot;
}

async function coreBetaCollectBatch(ctx) {
  if (!Array.isArray(ctx.batch) || !ctx.batch.length) throw new Error('批量回收前没有派发账本。');
  const waitConfig = replyWaitConfig(ctx.testCase, ctx.timeoutMs);
  const collectionStartedAtMs = Date.now();
  const sharedDeadline = coreBetaBatchSharedDeadline(
    ctx.batch,
    waitConfig.timeoutMs,
    collectionStartedAtMs,
  );
  const observationLogFile = path.join(ctx.caseDir, 'batch-collect-observations.ndjson');
  writeTextFile(observationLogFile, '');
  ctx.state.artifacts.core_beta_batch_observations = observationLogFile;
  let round = 0;
  let deadlineReached = false;
  do {
    round += 1;
    for (const entry of ctx.batch.filter((item) => !item.terminal_outcome)) {
      await coreBetaObserveBatchEntry(ctx, entry, round, observationLogFile);
      if (entry.terminal_outcome) await coreBetaCaptureBatchTerminalScreenshot(ctx, entry);
    }
    const sanitized = coreBetaSanitizeBatchEntries(ctx.batch);
    ctx.state.artifacts.core_beta_batch_collect = sanitized;
    writeJsonFile(path.join(ctx.caseDir, 'batch-collect-ledger.json'), sanitized);
    if (ctx.batch.every((item) => item.terminal_outcome)) break;
    deadlineReached = Date.now() >= sharedDeadline.deadline_at_ms;
    if (!deadlineReached) await ctx.page.waitForTimeout(500);
  } while (!deadlineReached);

  deadlineReached = Date.now() >= sharedDeadline.deadline_at_ms;
  for (const entry of ctx.batch.filter((item) => !item.terminal_outcome)) {
    // Capture one final task-bound observation at/after the shared deadline.
    await coreBetaObserveBatchEntry(ctx, entry, round + 1, observationLogFile);
    if (!entry.terminal_outcome) {
      const observation = entry.last_observation || {};
      entry.reply = String(entry._last_observed_reply || '');
      entry.reply_sha256 = entry.reply ? sha256Text(entry.reply) : '';
      entry.terminal_outcome = !observation.reopen_ok
        ? 'task_reopen_failed_by_batch_deadline'
        : observation.running
          ? 'running_at_batch_deadline'
          : observation.assistant_reply_present
            ? 'reply_unstable_at_batch_deadline'
            : 'no_attributable_reply_by_batch_deadline';
      entry.terminal_at = new Date().toISOString();
      entry.ok = false;
    }
    await coreBetaCaptureBatchTerminalScreenshot(ctx, entry);
  }

  const replies = ctx.batch.map((entry) => {
    const dispatchedAtMs = Date.parse(String(entry.dispatched_at || ''));
    const terminalAtMs = Date.parse(String(entry.terminal_at || ''));
    const waitedMs = Number.isFinite(dispatchedAtMs) && Number.isFinite(terminalAtMs)
      ? Math.max(0, terminalAtMs - dispatchedAtMs)
      : Math.max(0, Date.now() - collectionStartedAtMs);
    const completedReply = ['reply_completed', 'reply_oracle_mismatch'].includes(entry.terminal_outcome);
    return {
      label: `批量任务 ${entry.index + 1}`,
      fullText: entry.reply || '',
      deltaText: entry.reply || '',
      incomplete: !completedReply,
      incomplete_reason: completedReply
        ? ''
        : `批量共享截止时间终态：${entry.terminal_outcome}；taskId=${entry.task_id}`,
      stable_observations: Number(entry.stable_observations || 0),
      waited_ms: waitedMs,
      min_wait_ms: MIN_REPLY_WAIT_MS,
      timeout_ms: waitConfig.timeoutMs,
      wait_kind: 'batch_shared_deadline',
    };
  });
  writeReplyArtifacts(ctx.state, ctx.caseDir, replies);
  for (let index = 0; index < replies.length; index += 1) {
    const entry = ctx.batch[index];
    const reply = replies[index];
    recordReplyWaitAssertion(ctx.state, reply, `批量任务 ${entry.index + 1}`);
    recordAssertion(
      ctx.state,
      `批量任务归属与回复 Oracle（${entry.index + 1}）`,
      '确认发送回执、taskId、用户 prompt 和助手回复必须归属同一任务；回复只包含本任务 marker，且在共享截止时间前稳定完成。',
      entry.ok === true,
      `taskId=${entry.task_id}；terminal=${entry.terminal_outcome}；stable=${entry.stable_observations}；reply=${clip(entry.reply, 180)}`,
    );
  }

  const terminalEvidence = coreBetaBatchTerminalEvidence(ctx.batch, {
    deadlineAtMs: sharedDeadline.deadline_at_ms,
    deadlineReached,
  });
  const replyCompletion = coreBetaBatchReplyCompletionPayload(ctx.batch, terminalEvidence, {
    timeoutMs: waitConfig.timeoutMs,
    minWaitMs: MIN_REPLY_WAIT_MS,
  });
  writeJsonFile(ctx.state.artifacts.reply_completion, replyCompletion);
  const complete = ctx.batch.every((item) => item.ok);
  const sanitized = coreBetaSanitizeBatchEntries(ctx.batch);
  ctx.state.artifacts.core_beta_batch_collect = sanitized;
  ctx.state.artifacts.core_beta_batch_collection_summary = {
    ...sharedDeadline,
    collection_started_at: new Date(collectionStartedAtMs).toISOString(),
    collection_finished_at: new Date().toISOString(),
    rounds: round,
    deadline_reached: deadlineReached,
    terminal_evidence: terminalEvidence,
  };
  writeJsonFile(path.join(ctx.caseDir, 'batch-collect-ledger.json'), sanitized);
  writeJsonFile(
    path.join(ctx.caseDir, 'batch-collection-summary.json'),
    ctx.state.artifacts.core_beta_batch_collection_summary,
  );
  setCoreBetaEvidence(ctx.state, 'reply_completion', terminalEvidence);
  setCoreBetaEvidence(ctx.state, 'public_state_readback', {
    source: 'round-robin public task state collection ledger',
    dispatched: ctx.batch.length,
    terminal_rows: ctx.batch.filter((item) => item.terminal_outcome).length,
    completed: ctx.batch.filter((item) => item.ok).length,
    shared_deadline_reached: deadlineReached,
  });
  const reopenFailure = ctx.batch.some((item) => item.terminal_outcome === 'task_reopen_failed_by_batch_deadline');
  const deadlineEntries = ctx.batch.filter((item) => (
    /batch_deadline|deadline/.test(String(item?.terminal_outcome || ''))
  ));
  if (deadlineEntries.length) {
    const cleanupRows = [];
    for (const entry of deadlineEntries) {
      const reopened = await reopenSessionAndReadback(ctx.page, entry.task_id).catch((error) => ({
        ok: false,
        reason: String(error?.message || error),
      }));
      let confirmationCount = 0;
      if (reopened?.ok) {
        while (confirmationCount < 8 && await resolveAssistantConfirmationModal(ctx.page, {
          state: ctx.state,
          caseDir: ctx.caseDir,
          label: `批量任务 ${entry.index + 1} 超时清理`,
        })) {
          confirmationCount += 1;
          await ctx.page.waitForTimeout(500);
        }
      }
      const cleanupSucceeded = reopened?.ok
        ? await cancelRunningReplyAfterTimeout(
          ctx.page,
          ctx.state,
          ctx.caseDir,
          `批量任务 ${entry.index + 1} 共享截止后的隔离清理`,
        )
        : false;
      cleanupRows.push({
        index: entry.index,
        task_id: entry.task_id,
        terminal_outcome: entry.terminal_outcome,
        cleanup_click_is_case_action: false,
        reopened: Boolean(reopened?.ok),
        reopen_reason: String(reopened?.reason || ''),
        assistant_confirmations_skipped: confirmationCount,
        cleanup_attempted: true,
        cleanup_succeeded: cleanupSucceeded,
      });
    }
    const cleanupFile = path.join(ctx.caseDir, 'batch-timeout-cleanup-readback.json');
    writeJsonFile(cleanupFile, {
      valid: cleanupRows.every((item) => item.cleanup_succeeded),
      cleanup_click_is_case_action: false,
      rows: cleanupRows,
    });
    ctx.state.artifacts.core_beta_batch_timeout_cleanup = cleanupFile;
  }
  return {
    ok: complete,
    category: reopenFailure ? 'automation_error' : 'bug',
    selector_or_testid: 'task-list',
    event: 'collect-batch',
    state_readback: {
      dispatched: ctx.batch.length,
      terminal_rows: ctx.batch.filter((item) => item.terminal_outcome).length,
      collected: ctx.batch.filter((item) => item.collected_at).length,
      passed: ctx.batch.filter((item) => item.ok).length,
      rounds: round,
      shared_deadline_reached: deadlineReached,
      terminal_evidence_available: terminalEvidence.available,
    },
    actual: `terminal=${ctx.batch.filter((item) => item.terminal_outcome).length}/${ctx.batch.length}；collected=${ctx.batch.filter((item) => item.collected_at).length}；passed=${ctx.batch.filter((item) => item.ok).length}；rounds=${round}；deadlineReached=${deadlineReached}；terminalEvidence=${terminalEvidence.available}`,
  };
}


function recordCoreBetaBatchOperation(context, action, expected, result, defaultCategory = 'bug') {
  const ok = result?.ok === true;
  const actual = String(result?.actual || JSON.stringify(result?.state_readback || {}));
  const category = ok ? '' : String(result?.category || defaultCategory);
  recordStep(
    context.state,
    action,
    expected,
    actual,
    ok ? 'passed' : 'failed',
    String(result?.screenshot || ''),
    category,
  );
  recordAssertion(context.state, action, expected, ok, actual, category || defaultCategory);
}

async function executeCoreBetaConversationDispatchCollect20(context) {
  const expected = Number(context.testCase.batch_size || 20);
  if (expected !== 20) {
    throw new Error(`${context.testCase.id} conversation_dispatch_collect_20 要求 batch_size=20，actual=${expected}`);
  }
  const batchContext = {
    ...context,
    assertionContract: context.testCase.precise_assertions || {},
    batch: Array.from({ length: expected }, (_item, index) => ({
      index,
      marker: coreBetaBatchTaskMarker(context.state.id, index),
    })),
  };
  const dispatch = await coreBetaDispatchBatch(batchContext);
  recordCoreBetaBatchOperation(
    context,
    '20 条长任务逐条确认发送并固化派发账本',
    '每条任务必须使用唯一 marker，获得唯一 taskId、确认发送回执和发送后截图，且发送后立即切换到下一新任务。',
    dispatch,
    'automation_error',
  );
  if (!dispatch.ok) return;

  const pending = await coreBetaAssertBatchPendingPool(batchContext);
  recordCoreBetaBatchOperation(
    context,
    '末条派发后读取可见待回复池',
    '统一回收前必须读回全部 20 个 taskId 的侧栏条目，且至少 5 条显示正在执行。',
    pending,
    'bug',
  );

  const collect = await coreBetaCollectBatch(batchContext);
  recordCoreBetaBatchOperation(
    context,
    '按 taskId 轮询回收 20 条批量任务',
    '共享截止时间内逐 taskId 轮询；每条都必须保存终态观察和截图，并核对 marker、长度及跨任务隔离。',
    collect,
    'bug',
  );
  context.state.artifacts.core_beta_batch_execution_summary = {
    schema_version: 'qbot-core-beta-batch-execution/v1',
    case_id: context.testCase.id,
    expected,
    dispatch: dispatch.state_readback,
    pending_pool: pending.state_readback,
    collection: collect.state_readback,
    completed_at: new Date().toISOString(),
  };
  writeJsonFile(
    path.join(context.caseDir, 'batch-execution-summary.json'),
    context.state.artifacts.core_beta_batch_execution_summary,
  );
}

async function executeCoreBetaConversationCase(context, scenario) {
  const { page, state, testCase, caseDir, timeoutMs } = context;
  switch (scenario.driver) {
    case 'conversation_dispatch_collect_20':
      return await executeCoreBetaConversationDispatchCollect20(context);
    case 'conversation_streaming_scroll':
      return await executeIssue793StreamingScrollFollow({ page, state, testCase, caseDir, timeoutMs });
    case 'conversation_stop_and_resume': {
      await executeSitHomeStopGeneration({ page, state, caseDir });
      if (state.assertions.some((item) => item.status === 'failed')) return;
      const followup = testCase.conversation_turns?.at(-1);
      if (!followup?.prompt) throw new Error(`${testCase.id} 缺少停止后的追问`);
      await runPromptInCurrentTask({
        page,
        state,
        testCase,
        caseDir,
        timeoutMs,
        prompt: followup.prompt,
        label: '停止后继续追问',
      });
      return;
    }
    case 'conversation_sidebar_persistence':
      return await executeCoreBetaSidebarPersistenceCase(context);
    case 'conversation_native_ime':
      return await executeCoreBetaImeCase(context);
    default:
      return await executeConversationCase(context);
  }
}

async function executeCoreBetaSidebarPersistenceCase(context) {
  let { page } = context;
  const {
    state,
    testCase,
    caseDir,
    timeoutMs,
    fixturesDir,
    runtime,
    options = {},
  } = context;
  await executeConversationCase({ page, state, testCase, caseDir, timeoutMs, fixturesDir });
  const session = await qbotE2EState(page);
  if (!session?.activeId || session.running) {
    recordAssertion(state, '侧栏持久化任务前置', '完成对话后必须获得稳定taskId。', false, JSON.stringify(session), 'automation_error');
    return;
  }
  const taskId = session.activeId;
  const beforeText = await currentThreadText(page);
  const beforeSha = createHash('sha256').update(beforeText).digest('hex');
  const renamed = `QA侧栏恢复-${taskId.slice(-8)}`;
  const renameResult = await page.evaluate(async ({ id, label }) => {
    const bridge = window.__qbotE2E || window.__deepbankE2E;
    if (typeof bridge?.renameSession === 'function') {
      try { await bridge.renameSession(id, label); return { ok: true, source: 'e2e.renameSession' }; }
      catch (error) { return { ok: false, reason: String(error?.message || error) }; }
    }
    if (typeof window.agent?.renameSession === 'function') {
      try { await window.agent.renameSession(id, label); return { ok: true, source: 'agent.renameSession' }; }
      catch (error) { return { ok: false, reason: String(error?.message || error) }; }
    }
    return { ok: false, reason: 'renameSession bridge unavailable' };
  }, { id: taskId, label: renamed });
  if (!renameResult.ok) throw new Error(`任务重命名执行失败：${renameResult.reason}`);
  try {
    await page.reload({ waitUntil: 'domcontentloaded', timeout: 30_000 });
  } catch (error) {
    if (!coreBetaV2NeedsRendererReconnect(error)) throw error;
    const reconnected = await reconnectCoreBetaV2Runtime({
      runtime,
      options,
      state,
      caseDir,
      timeoutMs: Number(options['restart-reconnect-timeout-ms'] || 120_000),
      label: 'Core Beta v2 sidebar persistence reload',
    });
    if (!reconnected.ok) {
      throw new Error(`刷新关闭旧 QWork renderer 后重连失败：${reconnected.reason}`);
    }
    page = reconnected.page;
    context.page = page;
    if (runtime) runtime.page = page;
    recordStep(
      state,
      '刷新后接管 replacement QWork renderer',
      '受管 Teams WebView 刷新销毁旧 target 时，必须重建 CDP 连接并继续核对同一 taskId。',
      `已重连 ${runtime.cdpUrl}，继续核对 taskId=${taskId}。`,
      'passed',
    );
  }
  await page.waitForTimeout(1_000);
  const reopened = await reopenSessionAndReadback(page, taskId);
  const afterSha = createHash('sha256').update(reopened.text || '').digest('hex');
  const selectedCount = await page.locator('[data-testid^="session-item-"][aria-selected="true"], .session-item.active, .task-item.active').count().catch(() => 0);
  const trace = {
    valid: reopened.ok && !reopened.running && beforeSha === afterSha && selectedCount <= 1,
    task_id: taskId,
    renamed,
    rename_source: renameResult.source,
    before_sha256: beforeSha,
    after_sha256: afterSha,
    selected_count: selectedCount,
    reopened,
  };
  const file = path.join(caseDir, 'sidebar-persistence-readback.json');
  writeJsonFile(file, trace);
  state.artifacts.core_beta_content_readback = trace;
  state.artifacts.sidebar_persistence_readback = file;
  recordAssertion(
    state,
    '侧栏任务重命名与刷新恢复',
    '同一taskId重命名后刷新重开，transcript SHA必须一致且选中态最多一个。',
    trace.valid,
    JSON.stringify(trace),
  );
}

export function activateCoreBetaNativeImeHost(
  rendererControlAdapter = '',
  { run = spawnSync, maxAttempts = 4 } = {},
) {
  const teamsLane = String(rendererControlAdapter || '').trim() === 'teams360';
  if (!teamsLane) {
    return {
      schema_version: 'qbot-core-beta-native-ime-host-activation/v1',
      required: false,
      ready: true,
      application: '',
      frontmost_process: '',
    };
  }
  const boundedAttempts = Math.min(8, Math.max(1, Number(maxAttempts) || 4));
  const script = [
    'tell application "360Teams" to activate',
    'delay 0.4',
    'tell application "System Events"',
    '  set frontmostProcesses to name of every application process whose frontmost is true',
    '  if (count of frontmostProcesses) is 0 then return ""',
    '  return item 1 of frontmostProcesses',
    'end tell',
  ].join('\n');
  const observations = [];
  for (let attempt = 1; attempt <= boundedAttempts; attempt += 1) {
    const result = run('osascript', ['-e', script], {
      encoding: 'utf8',
      timeout: 5_000,
    });
    const frontmostProcess = String(result?.stdout || '')
      .split(/\r?\n/)
      .map((value) => value.trim())
      .filter(Boolean)
      .at(-1) || '';
    const ready = result?.status === 0 && frontmostProcess === '360Teams';
    observations.push({
      attempt,
      ready,
      frontmost_process: frontmostProcess,
      command_status: result?.status ?? null,
      error: clip(result?.stderr || result?.error?.message || '', 300),
    });
    if (ready) {
      return {
        schema_version: 'qbot-core-beta-native-ime-host-activation/v1',
        required: true,
        ready: true,
        application: '360Teams',
        frontmost_process: frontmostProcess,
        command_status: result?.status ?? null,
        attempt_count: attempt,
        attempts: observations,
      };
    }
  }
  const last = observations.at(-1) || {};
  const activation = {
    schema_version: 'qbot-core-beta-native-ime-host-activation/v1',
    required: true,
    ready: false,
    application: '360Teams',
    frontmost_process: last.frontmost_process || '',
    command_status: last.command_status ?? null,
    attempt_count: observations.length,
    attempts: observations,
  };
  throw new Error(
    'Native IME host activation failed before Composer focus after bounded retries: '
    + JSON.stringify(activation),
  );
}

async function executeCoreBetaImeCase({ page, state, testCase, caseDir, timeoutMs, options = {} }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const prompt = String(testCase.conversation_turns?.[0]?.prompt || '').trim();
  if (!prompt) throw new Error(`${testCase.id} 缺少IME目标prompt`);
  const beforeNativeInput = await captureCoreBetaPublicState(page, testCase);
  const input = page.locator('[data-testid="composer-input"]').first();
  const hostActivation = activateCoreBetaNativeImeHost(options['renderer-control-adapter']);
  state.artifacts.core_beta_native_ime_host_activation = hostActivation;
  const focusArm = {
    ...await prepareCoreBetaNativeImeFocus(page, input),
    host_activation: hostActivation,
  };
  state.artifacts.core_beta_native_ime_focus_arm = focusArm;
  await input.evaluate((node) => {
    window.__qbotCoreBetaImeTrace = [];
    const capture = (event) => window.__qbotCoreBetaImeTrace.push({
      type: event.type,
      data: event.data ?? null,
      isComposing: Boolean(event.isComposing),
      value: 'value' in node ? node.value : node.textContent,
      captured_at: new Date().toISOString(),
    });
    for (const name of ['compositionstart', 'compositionupdate', 'compositionend', 'beforeinput', 'input']) {
      node.addEventListener(name, capture);
    }
  });
  const nativeImeCommand = String(
    options['native-ime-command']
    || process.env.QBOT_CORE_BETA_NATIVE_IME_COMMAND
    || '',
  ).trim();
  if (!nativeImeCommand) {
    throw new Error(
      `${testCase.id} 需要 --native-ime-command 或 QBOT_CORE_BETA_NATIVE_IME_COMMAND；`
      + '该命令必须通过macOS真实输入源完成候选确认并保留焦点，禁止用DOM合成事件伪造IME通过。',
    );
  }
  const nativeInput = spawnSync('/bin/zsh', ['-lc', nativeImeCommand], {
    encoding: 'utf8',
    timeout: 60_000,
    env: {
      ...process.env,
      QBOT_CORE_BETA_IME_TEXT: prompt,
      QBOT_CORE_BETA_IME_TEXT_BASE64: Buffer.from(prompt, 'utf8').toString('base64'),
      QBOT_CORE_BETA_CASE_ID: testCase.id,
    },
  });
  if (nativeInput.status !== 0) {
    throw new Error(
      `${testCase.id} native IME command failed: status=${nativeInput.status}; `
      + `${clip(nativeInput.stderr || nativeInput.stdout || '', 500)}`,
    );
  }
  await page.waitForTimeout(500);
  const trace = await page.evaluate(() => window.__qbotCoreBetaImeTrace || []);
  const readback = await input.inputValue().catch(async () => input.innerText().catch(() => ''));
  const verdict = coreBetaNativeImeTraceVerdict({
    prompt,
    readback,
    events: trace,
    focusArm,
    nativeCommandStatus: nativeInput.status,
  });
  const traceData = {
    ...verdict,
    target_utf8_sha256: createHash('sha256').update(prompt).digest('hex'),
    readback_utf8_sha256: createHash('sha256').update(readback).digest('hex'),
    readback,
    events: trace,
  };
  state.artifacts.core_beta_ime_event_trace = traceData;
  const traceFile = path.join(caseDir, 'ime-event-trace.json');
  writeJsonFile(traceFile, traceData);
  state.artifacts.ime_event_trace = traceFile;
  recordAssertion(state, 'IME组合输入字节级一致', 'composition事件闭环后Composer值必须与目标prompt字节级一致，且组合期不得发送。', traceData.oracle_valid, JSON.stringify(traceData));
  if (traceData.adapter_noop) {
    throw new Error(
      `${testCase.id} native IME command returned success but produced no composer text or composition events; `
      + 'refusing to wait for or click Send because the native focus/command adapter did not execute.',
    );
  }
  if (!traceData.oracle_valid) {
    state.screenshots.ime_input_failure = await shot(page, caseDir, 'ime-input-failure');
    const failureEvidence = coreBetaPreSendImeFailureEvidence({
      testCaseId: testCase.id,
      before: beforeNativeInput,
      after: await captureCoreBetaPublicState(page, testCase),
      focusArm,
      traceData,
      screenshot: state.screenshots.ime_input_failure,
      noPromptRecorded: !state.artifacts.prompt
        && (!Array.isArray(state.artifacts.sent_prompts) || state.artifacts.sent_prompts.length === 0),
      noSendReceiptRecorded: !state.artifacts.send_receipt
        && (!Array.isArray(state.artifacts.send_receipts) || state.artifacts.send_receipts.length === 0),
      notApplicableRoles: CORE_BETA_PRE_SEND_IME_FAILURE_NA_ROLES
        .filter((role) => (testCase.evidence_roles || []).includes(role)),
    });
    const failureFile = path.join(caseDir, 'pre-send-ime-failure.json');
    writeJsonFile(failureFile, failureEvidence);
    state.artifacts.core_beta_pre_send_ime_failure = failureFile;
    if (!failureEvidence.valid) {
      recordAssertion(
        state,
        'IME发送前产品失败负向证据闭环',
        '真实composition异常时必须证明前台焦点、原生事件、零task、零消息和零发送变更。',
        false,
        failureEvidence.reason,
        'automation_error',
      );
      throw new Error(`${testCase.id} native IME failure evidence is incomplete; refusing to send mismatched text.`);
    }
    state.artifacts.core_beta_not_applicable_roles = failureEvidence.not_applicable_roles.map((role) => ({
      role,
      blocker_path: failureFile,
    }));
    recordAssertion(
      state,
      'IME发送前产品失败负向证据闭环',
      '真实composition异常时必须证明前台焦点、原生事件、零task、零消息和零发送变更。',
      true,
      failureEvidence.reason,
    );
    return;
  }
  const before = await conversationSnapshot(page);
  await send(page, state, '发送IME组合输入');
  const waitConfig = replyWaitConfig(testCase, timeoutMs);
  const reply = await waitForReply(page, before, waitConfig.timeoutMs, {
    ignoredText: [prompt, testCase.scenario, testCase.test_data],
    expectedUserText: prompt,
    state,
    caseDir,
    label: 'IME发送回复',
    minWaitMs: waitConfig.minWaitMs,
    waitKind: waitConfig.kind,
  });
  writeReplyArtifacts(state, caseDir, [{ ...reply, label: 'IME发送回复' }]);
  recordReplyWaitAssertion(state, reply, 'IME发送回复');
  recordAssertion(state, 'IME仅创建一次发送', '目标prompt只允许出现一次且只产生一次发送receipt。', !reply.incomplete, reply.incomplete_reason || 'reply complete');
}

export async function prepareCoreBetaNativeImeFocus(page, input, { attempts = 3 } = {}) {
  const observations = [];
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    await page.bringToFront();
    await input.click({ force: true });
    await input.focus();
    const observation = await input.evaluate((node) => {
      const rect = node.getBoundingClientRect();
      const style = getComputedStyle(node);
      return {
        document_has_focus: document.hasFocus(),
        active_element_matches: document.activeElement === node,
        composer_visible: rect.width > 0
          && rect.height > 0
          && style.display !== 'none'
          && style.visibility !== 'hidden',
      };
    });
    const ready = observation.document_has_focus === true
      && observation.active_element_matches === true
      && observation.composer_visible === true;
    observations.push({ attempt, ready, ...observation });
    if (ready) {
      return {
        schema_version: 'qbot-core-beta-native-ime-focus/v1',
        ready: true,
        attempts: observations,
      };
    }
    await page.waitForTimeout(250);
  }
  throw new Error(
    `Native IME composer focus could not be armed after ${attempts} attempts: ${JSON.stringify(observations)}`,
  );
}

export function coreBetaNativeImeTraceVerdict({
  prompt = '',
  readback = '',
  events = [],
  focusArm = {},
  nativeCommandStatus = null,
} = {}) {
  const rows = Array.isArray(events) ? events : [];
  const focusReady = focusArm?.ready === true;
  const compositionStart = rows.some((item) => item?.type === 'compositionstart');
  const compositionEnd = rows.some((item) => item?.type === 'compositionend');
  const exact = String(readback) === String(prompt);
  const adapterNoop = focusReady
    && Number(nativeCommandStatus) === 0
    && String(readback) === ''
    && rows.length === 0;
  const evidenceValid = focusReady
    && Number(nativeCommandStatus) === 0
    && rows.length > 0;
  const oracleValid = focusReady && exact && compositionStart && compositionEnd;
  return {
    valid: oracleValid,
    evidence_valid: evidenceValid,
    oracle_valid: oracleValid,
    focus_ready: focusReady,
    exact_readback: exact,
    composition_start: compositionStart,
    composition_end: compositionEnd,
    event_count: rows.length,
    native_command_status: nativeCommandStatus,
    adapter_noop: adapterNoop,
    focus_arm: focusArm,
  };
}

function sameStringMultiset(left = [], right = []) {
  return JSON.stringify(left.map(String).sort()) === JSON.stringify(right.map(String).sort());
}

export function coreBetaComposerHistoryVerdict(readback = {}) {
  const prompts = Array.isArray(readback.prompts) ? readback.prompts.map(String) : [];
  const navigation = readback.navigation || {};
  return Boolean(
    prompts.length === 2
    && prompts.every(Boolean)
    && String(readback.initial_task_id || '')
    && String(readback.isolated_task_id || '') === ''
    && readback.isolated_is_draft === true
    && Number(readback.isolated_message_count) === 0
    && String(readback.isolated_draft_instance_id || '')
    && navigation.up_boundary_arm === String(readback.unsent_draft || '')
    && navigation.up_latest === prompts[1]
    && navigation.up_older === prompts[0]
    && navigation.down_newer === prompts[1]
    && navigation.down_draft === String(readback.unsent_draft || '')
    && navigation.isolated_boundary_arm === ''
    && navigation.isolated_new_task === ''
    && navigation.reopened_boundary_arm === ''
    && navigation.reopened_latest === prompts[1]
  );
}

async function executeCoreBetaComposerHistoryCase({ page, state, testCase, caseDir, timeoutMs }) {
  const prompts = (testCase.conversation_turns || [])
    .slice(0, 2)
    .map((turn) => String(turn?.prompt || '').trim());
  if (prompts.length !== 2 || prompts.some((prompt) => !prompt)) {
    throw new Error(`${testCase.id} 必须声明两个可接受的历史输入样本`);
  }
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, {
    skillMode: 'disabled',
    connectorMode: 'disabled',
  })) return;
  for (const [index, prompt] of prompts.entries()) {
    await runPromptInCurrentTask({
      page,
      state,
      testCase,
      caseDir,
      timeoutMs,
      prompt,
      label: `历史输入样本${index + 1}`,
    });
  }
  const initial = await qbotE2EState(page);
  const input = page.locator('[data-testid="composer-input"]').first();
  await input.waitFor({ state: 'visible', timeout: 15_000 });
  const composerText = async () => page.evaluate(() => String(
    window.__aui?.thread?.composer?.getState?.().text
    ?? document.querySelector('[data-testid="composer-input"]')?.textContent
    ?? '',
  ).replaceAll('\uFEFF', ''));
  const pressAndRead = async (locator, key) => {
    await locator.focus();
    await locator.press(key);
    await page.waitForTimeout(180);
    return await composerText();
  };
  const unsentDraft = 'QBOT-HISTORY-DRAFT-NOT-SENT';
  await input.fill(unsentDraft);
  await input.press('Home');
  const navigation = {
    // #1175: an idle outer-boundary arrow only arms history. The matching
    // second physical key press enters browsing; once browsing, traversal is
    // direct. Playwright locator.press emits the product's physical key path.
    up_boundary_arm: await pressAndRead(input, 'ArrowUp'),
    up_latest: await pressAndRead(input, 'ArrowUp'),
    up_older: await pressAndRead(input, 'ArrowUp'),
    down_newer: await pressAndRead(input, 'ArrowDown'),
    down_draft: await pressAndRead(input, 'ArrowDown'),
  };
  const historyScreenshot = await shot(page, caseDir, 'composer-history-draft-restored');
  await openNewTask(page, state);
  const isolated = await qbotE2EState(page);
  const isolatedInput = page.locator('[data-testid="composer-input"]').first();
  navigation.isolated_boundary_arm = await pressAndRead(isolatedInput, 'ArrowUp');
  navigation.isolated_new_task = await pressAndRead(isolatedInput, 'ArrowUp');
  const reopened = await reopenSessionAndReadback(page, initial?.activeId);
  const reopenedInput = page.locator('[data-testid="composer-input"]').first();
  await reopenedInput.fill('');
  navigation.reopened_boundary_arm = await pressAndRead(reopenedInput, 'ArrowUp');
  navigation.reopened_latest = await pressAndRead(reopenedInput, 'ArrowUp');
  const readback = {
    schema_version: 'qbot-core-beta-composer-history/v2',
    valid: true,
    oracle_valid: false,
    prompts,
    unsent_draft: unsentDraft,
    initial_task_id: String(initial?.activeId || ''),
    isolated_task_id: String(isolated?.activeId || ''),
    isolated_is_draft: isolated?.isDraft === true,
    isolated_message_count: Number(isolated?.messageCount ?? -1),
    isolated_draft_instance_id: String(isolated?.draftInstanceId || ''),
    reopened,
    navigation,
    screenshots: { history: historyScreenshot },
  };
  readback.oracle_valid = coreBetaComposerHistoryVerdict(readback);
  const file = path.join(caseDir, 'composer-history-readback.json');
  writeJsonFile(file, readback);
  state.artifacts.product_action_trace = file;
  state.artifacts.data_integrity_readback = file;
  recordAssertion(
    state,
    'Composer Up/Down历史输入与会话隔离',
    '空闲态第一下物理方向键只建立边界握手，第二下才进入历史；随后Up按当前会话从新到旧回放，Down回到未发送草稿；新任务不得继承，重开原task后仍可回放。',
    readback.oracle_valid,
    JSON.stringify(readback),
  );
}

export function coreBetaModelMenuExpectedSnapshot(source = {}) {
  const state = source.state || {};
  const view = source.view || {};
  const runtimeFamily = String(
    state.runtimeFamily
    || view?.runtimeOptions?.runtimeFamily
    || source.family
    || 'claude-code',
  );
  const protocol = runtimeFamily === 'codex' ? 'response' : 'anthropic';
  const policy = String(state?.modelPolicyState?.policy || '');
  const autoPolicySelected = state.executionScope === 'desktop-local' && policy !== 'manual';
  const autoOriginManualSelection = autoPolicySelected || (
    policy === 'manual' && state?.modelPolicyState?.reason === 'manual_override_auto'
  );
  const manualOptions = Array.isArray(view?.manualModelOptions) ? view.manualModelOptions : [];
  const runtimeOptions = Array.isArray(view?.runtimeOptions?.options) ? view.runtimeOptions.options : [];
  const candidateSource = autoOriginManualSelection && manualOptions.length
    ? 'manualModelOptions'
    : 'runtimeOptions.options';
  const candidates = candidateSource === 'manualModelOptions' ? manualOptions : runtimeOptions;
  const eligible = candidates.filter((option) => (
    !option?.disabled
    && String(option?.runtimeFamily || '') === runtimeFamily
    && String(option?.protocol || '') === protocol
    && /^M[1-4]$/.test(String(option?.complianceTier || ''))
  ));
  return {
    runtime_family: runtimeFamily,
    protocol,
    option_count: eligible.length,
    model_ids: eligible.map((option) => String(option.modelId || '')),
    options: eligible,
    candidate_source: candidateSource,
    policy: state?.modelPolicyState || null,
    execution_scope: String(state.executionScope || ''),
  };
}

export function coreBetaModelMenuSdkFilterVerdict(readback = {}) {
  const expected = readback.expected || {};
  const rendered = readback.rendered || {};
  return Boolean(
    ['claude-code', 'codex'].includes(String(expected.runtime_family || ''))
    && String(expected.protocol || '') === (expected.runtime_family === 'codex' ? 'response' : 'anthropic')
    && Number(expected.option_count || 0) > 0
    && Array.isArray(expected.model_ids)
    && expected.model_ids.length === Number(expected.option_count)
    && expected.model_ids.every((modelId) => String(modelId || ''))
    && !String(rendered.error || '')
    && sameStringMultiset(expected.model_ids, rendered.model_ids)
    && Array.isArray(rendered.tiers)
    && rendered.tiers.length === rendered.model_ids.length
    && rendered.tiers.every((tier) => /^M[1-4]$/.test(String(tier)))
  );
}

async function executeCoreBetaModelMenuSdkFilterCase({ page, state, testCase, caseDir }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, {
    skillMode: 'disabled',
    connectorMode: 'disabled',
  })) return;
  const source = await page.evaluate(async () => {
    const e2e = window.__qbotE2E || window.__deepbankE2E;
    const diagnostics = typeof e2e?.diagnostics === 'function' ? await e2e.diagnostics() : null;
    const state = typeof e2e?.state === 'function' ? e2e.state() : null;
    const family = String(
      state?.runtimeFamily
      || diagnostics?.runtimeFamily
      || diagnostics?.e2eCurrentTurnAuthorityReadiness?.runtimeFamily
      || 'claude-code',
    );
    let view = null;
    if (typeof window.agent?.getConnections === 'function') {
      try { view = await window.agent.getConnections(family, { forceRefresh: true }); }
      catch { view = await window.agent.getConnections(); }
    }
    if (!view && typeof e2e?.getConnectionView === 'function') view = await e2e.getConnectionView();
    return { family, view, diagnostics, state };
  });
  const expected = coreBetaModelMenuExpectedSnapshot(source);
  await page.locator('[data-testid="composer-safety-level-menu"]').click({ timeout: 15_000 });
  await page.locator('[aria-label="模型选择"]').waitFor({ state: 'visible', timeout: 15_000 });
  await page.locator('[data-testid="composer-models-loading"]').waitFor({ state: 'hidden', timeout: 30_000 }).catch(() => {});
  const rendered = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll('[data-testid^="composer-safety-level-option-"]'));
    return {
      model_ids: rows.map((row) => {
        const tier = String(row.closest('[data-tier]')?.getAttribute('data-tier') || '');
        const prefix = `composer-safety-level-option-${tier}-`;
        const testId = String(row.getAttribute('data-testid') || '');
        return testId.startsWith(prefix) ? testId.slice(prefix.length) : testId;
      }),
      tiers: rows.map((row) => String(row.closest('[data-tier]')?.getAttribute('data-tier') || '')),
      labels: rows.map((row) => String(row.textContent || '').trim()),
      error: String(document.querySelector('[data-testid="composer-models-error"]')?.textContent || '').trim(),
      auto_visible: Boolean(document.querySelector('[data-testid="composer-model-option-auto"]')),
    };
  });
  const readback = {
    schema_version: 'qbot-core-beta-model-menu-sdk-filter/v1',
    valid: true,
    oracle_valid: false,
    expected,
    rendered,
    source: {
      selected: source.view?.runtimeOptions?.selected || null,
      runtime_option_count: Array.isArray(source.view?.runtimeOptions?.options)
        ? source.view.runtimeOptions.options.length
        : 0,
      manual_option_count: Array.isArray(source.view?.manualModelOptions)
        ? source.view.manualModelOptions.length
        : 0,
    },
  };
  readback.oracle_valid = coreBetaModelMenuSdkFilterVerdict(readback);
  const file = path.join(caseDir, 'model-route-trace.json');
  writeJsonFile(file, readback);
  state.artifacts.model_route_trace = file;
  recordAssertion(
    state,
    '模型菜单按当前SDK协议过滤',
    'Claude Code只显示anthropic候选，Codex只显示response候选；disabled、其他runtime和其他协议模型不得进入菜单。',
    readback.oracle_valid,
    JSON.stringify(readback),
  );
}

