async function executeSitHomeExpertToGeneral({ page, state, testCase, caseDir, timeoutMs }) {
  await openNewTask(page, state);
  if (!await summonFirstExpertForCase(page, state, caseDir)) return;
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const notes = '会议纪要：活动报名目标 100 人；负责人是张三；周五前完成报名页验收；风险是短信到达率偏低。请先用当前专家身份整理成结论和待办。';
  const first = await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt: notes, label: '专家身份整理纪要' });
  if (first.incomplete) return;

  const switched = await setWorkMode(page, state, caseDir, 'craft');
  const cap = await currentCapabilities(page);
  const expertCleared = switched && !String(cap?.currentExpert || '').trim();
  state.screenshots.home_011_general = await shot(page, caseDir, 'home-011-general-assistant');
  recordAssertion(
    state,
    '同一任务切回通用助手',
    '在同一任务中选择“动手/通用助手”后，currentExpert 应清空，不能继续挂上一专家身份。',
    expertCleared,
    `workMode=${cap?.workMode || 'craft/default'}；currentExpert=${cap?.currentExpert || '空'}`,
    expertCleared ? '' : 'automation_error',
  );
  if (!expertCleared) return;

  const secondPrompt = '现在请以通用助手身份，基于同一任务中刚才的会议纪要，输出 3 条待办，只保留负责人、截止时间和风险。';
  const second = await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt: secondPrompt, label: '切回通用助手后追问' });
  recordAssertion(
    state,
    '切回通用助手后上下文和身份正确',
    '回复应保留同一任务的纪要事实，但不声称仍以原专家身份回答。',
    /张三|周五|短信|到达率|负责人|截止|风险/.test(second.deltaText) && !/仍以.*专家|继续以.*专家/.test(second.deltaText),
    clip(second.deltaText, 360),
  );
  writeReplyArtifacts(state, caseDir, [
    { label: '专家身份整理纪要', ...first },
    { label: '切回通用助手后追问', ...second },
  ]);
}

async function executeSitHomeSafetyLevelsBeforeTask({ page, state, caseDir }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const menuText = await ensureComposerToolMenu(page, state, {
    selector: '[data-testid="composer-safety-level-menu"]',
    action: '打开输入区【安全级别】菜单',
    matchPattern: /M1|M2|M3|M4|安全|当前/,
    expectedLabels: ['M1', 'M2', 'M3', 'M4'],
    menuKind: 'safety',
  });
  const levels = await page.evaluate(() => ['M1', 'M2', 'M3', 'M4'].map((level) => {
    const el = document.querySelector(`[data-testid="composer-safety-level-option-${level}"]`);
    if (!el) return { level, visible: false, text: '', disabled: true };
    const rect = el.getBoundingClientRect();
    const text = String(el.textContent || '').replace(/\s+/g, ' ').trim();
    return { level, visible: rect.width > 0 && rect.height > 0, text, disabled: 'disabled' in el ? Boolean(el.disabled) : /不可用|暂无可用/.test(text) };
  })).catch(() => []);
  state.screenshots.home_013_safety_menu = await shot(page, caseDir, 'home-013-safety-level-menu');
  const allVisible = levels.length === 4 && levels.every((item) => item.visible && item.text.includes(item.level));
  const unavailableExplained = levels.filter((item) => item.disabled).every((item) => /不可用|暂无可用|联系管理员/.test(item.text));
  recordAssertion(
    state,
    '任务创建前安全级别完整可理解',
    '安全级别菜单应展示 M1–M4；没有可用模型的档位应明确标注不可用，而不是要求用户理解模型配置。',
    allVisible && unavailableExplained,
    `levels=${JSON.stringify(levels)}；menu=${clip(menuText, 360)}`,
  );
}

async function executeSitHomeSafetyLevelAfterTask({ page, state, testCase, caseDir, timeoutMs }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const reply = await runPromptInCurrentTask({
    page,
    state,
    testCase,
    caseDir,
    timeoutMs,
    prompt: '请用一句话说明活动复盘需要关注哪些核心指标。',
    label: '创建任务并固定安全级别',
  });
  if (reply.incomplete) return;
  const before = await currentCapabilities(page);
  const menuText = await ensureComposerToolMenu(page, state, {
    selector: '[data-testid="composer-safety-level-menu"]',
    action: '任务创建后打开【安全级别】菜单',
    matchPattern: /M1|M2|M3|M4|当前/,
    expectedLabels: ['M1', 'M2', 'M3', 'M4'],
    menuKind: 'safety',
  });
  state.screenshots.home_014_safety_after_task = await shot(page, caseDir, 'home-014-safety-after-task');
  const alternatives = await page.evaluate((activeTier) => ['M1', 'M2', 'M3', 'M4'].filter((level) => level !== activeTier).map((level) => {
    const el = document.querySelector(`[data-testid="composer-safety-level-option-${level}"]`);
    const text = String(el?.textContent || '').replace(/\s+/g, ' ').trim();
    return { level, present: Boolean(el), disabled: !el || ('disabled' in el ? Boolean(el.disabled) : /不可用|暂无可用/.test(text)), text };
  }), String(state.requested_model_tier || 'M3')).catch(() => []);
  const selectableAlternative = alternatives.find((item) => item.present && !item.disabled);
  if (!selectableAlternative) {
    markBlocked(state, `任务已创建且当前档位=${state.requested_model_tier || 'M3'}；其他档位均无可用模型，无法真实验证“任务创建后切换档位应只读或提示新建任务”。菜单=${clip(menuText, 320)}`);
    return;
  }
  const option = page.locator(`[data-testid="composer-safety-level-option-${selectableAlternative.level}"]`).first();
  await option.click({ force: true });
  await page.waitForTimeout(1200);
  const after = await currentCapabilities(page);
  const activeBefore = before?.connectionView?.runtimeOptions?.selected?.complianceTier || state.requested_model_tier || 'M3';
  const activeAfter = after?.connectionView?.runtimeOptions?.selected?.complianceTier || '';
  const feedback = await bodyText(page);
  recordAssertion(
    state,
    '任务创建后安全级别不可静默切换',
    '已有任务中选择其他安全级别时，应保持原档位，或明确提示新建任务后切换。',
    activeAfter === activeBefore || /新建任务|新会话|当前任务.*不可|任务创建后.*不能|只读/.test(feedback),
    `before=${activeBefore}；after=${activeAfter || '未读取'}；页面=${clip(feedback, 280)}`,
  );
}

export function coreBetaPartialReplyReady({
  running = false,
  cancelVisible = false,
  baselineAssistantBodyText = '',
  latestAssistantBodyText = '',
  minimumChars = 4,
} = {}) {
  const baseline = String(baselineAssistantBodyText || '');
  const latest = String(latestAssistantBodyText || '');
  const delta = latest.startsWith(baseline)
    ? latest.slice(baseline.length)
    : latest === baseline
      ? ''
      : latest;
  return {
    ready: Boolean(running && cancelVisible && delta.trim().length >= Number(minimumChars || 4)),
    delta,
    delta_chars: delta.length,
  };
}

export function coreBetaStopGenerationTimeoutVerdict({
  partialReady = false,
  taskId = '',
  runningBefore = false,
  cancelVisible = false,
  waitedMs = 0,
  timeoutMs = SHORT_REPLY_WAIT_MS,
  confirmedSendReceipt = false,
  timeoutScreenshot = '',
} = {}) {
  const screenshot = String(timeoutScreenshot || '');
  let screenshotValid = false;
  try {
    screenshotValid = Boolean(
      path.isAbsolute(screenshot)
      && fs.existsSync(screenshot)
      && fs.statSync(screenshot).isFile()
      && fs.statSync(screenshot).size >= 128
    );
  } catch {
    screenshotValid = false;
  }
  const reasons = [];
  if (partialReady) reasons.push('partial_reply_already_ready');
  if (!String(taskId || '').trim()) reasons.push('task_id_missing');
  if (runningBefore !== true) reasons.push('running_state_not_observed');
  if (cancelVisible !== true) reasons.push('cancel_entry_not_observed');
  if (confirmedSendReceipt !== true) reasons.push('confirmed_send_receipt_missing');
  if (Number(timeoutMs || 0) < MIN_REPLY_WAIT_MS || Number(waitedMs || 0) < Number(timeoutMs || 0)) {
    reasons.push('full_timeout_window_not_observed');
  }
  if (!screenshotValid) reasons.push('timeout_screenshot_missing_or_invalid');
  return {
    valid: reasons.length === 0,
    reasons,
    task_id: String(taskId || ''),
    running_before: runningBefore === true,
    cancel_visible: cancelVisible === true,
    confirmed_send_receipt: confirmedSendReceipt === true,
    waited_ms: Number(waitedMs || 0),
    timeout_ms: Number(timeoutMs || 0),
    timeout_screenshot: screenshot,
    timeout_screenshot_valid: screenshotValid,
  };
}

export function coreBetaStoppedTurnTerminalEvidence({
  readback = {},
  prompt = '',
  confirmedPrompt = '',
  partialText = '',
  retainedText = '',
} = {}) {
  const taskId = String(readback?.task_id || '').trim();
  const taskIdBefore = String(readback?.task_id_before || '').trim();
  const taskIdAfter = String(readback?.task_id_after || '').trim();
  const userPrompt = String(prompt || '');
  const receiptPrompt = String(confirmedPrompt || '');
  const partial = String(partialText || '');
  const retained = String(retainedText || '');
  const beforeScreenshot = String(readback?.before_screenshot || '');
  const afterScreenshot = String(readback?.after_screenshot || '');
  const fileSha256 = (file) => {
    try {
      return path.isAbsolute(file)
        && fs.existsSync(file)
        && fs.statSync(file).isFile()
        && fs.statSync(file).size >= 128
        ? createHash('sha256').update(fs.readFileSync(file)).digest('hex')
        : '';
    } catch {
      return '';
    }
  };
  const partialPreserved = Boolean(partial && retained.startsWith(partial));
  const promptBound = Boolean(userPrompt && receiptPrompt === userPrompt);
  const taskBound = Boolean(taskId && taskIdBefore === taskId && taskIdAfter === taskId);
  const available = Boolean(
    taskBound
    && promptBound
    && readback?.confirmed_send_receipt === true
    && readback?.click_performed === true
    && readback?.running_before === true
    && readback?.running_after === false
    && readback?.partial_reply_ready_before_click === true
    && partial.length > 0
    && fileSha256(beforeScreenshot)
    && fileSha256(afterScreenshot)
  );
  return {
    complete: false,
    evidence_complete: available,
    completion_observed: false,
    terminal_failure: false,
    terminal_outcome: 'user_stopped',
    assistant_reply_present: retained.trim().length > 0,
    confirmed_send_receipt: readback?.confirmed_send_receipt === true,
    stop_click_performed: readback?.click_performed === true,
    task_id: taskId,
    task_id_before: taskIdBefore,
    task_id_after: taskIdAfter,
    prompt_sha256: createHash('sha256').update(userPrompt).digest('hex'),
    confirmed_send_prompt_sha256: createHash('sha256').update(receiptPrompt).digest('hex'),
    running_before: readback?.running_before === true,
    running_after: readback?.running_after === true,
    partial_reply_ready_before_click: readback?.partial_reply_ready_before_click === true,
    partial_chars_before_click: partial.length,
    partial_sha256_before_click: createHash('sha256').update(partial).digest('hex'),
    retained_chars: retained.length,
    retained_sha256: createHash('sha256').update(retained).digest('hex'),
    partial_preserved: partialPreserved,
    before_screenshot: beforeScreenshot,
    before_screenshot_sha256: fileSha256(beforeScreenshot),
    after_screenshot: afterScreenshot,
    after_screenshot_sha256: fileSha256(afterScreenshot),
    terminal_reason: partialPreserved
      ? '用户通过产品停止入口终止生成，停止前正文已在同一 task 的停止后读回中保留。'
      : '用户通过产品停止入口终止生成，但停止前正文未在同一 task 的停止后读回中完整保留。',
  };
}

async function executeSitHomeStopGeneration({ page, state, caseDir }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  const prompt = '请生成一份非常详细的 QBot 全量测试方案，至少包含 20 个章节，每章都说明目标、步骤、风险、证据和退出条件。';
  const conversationBefore = await conversationSnapshot(page);
  const before = await qbotE2EState(page);
  await fillComposer(page, prompt, state, '输入长任务以验证停止生成');
  if (state.requested_model_tier) {
    const tier = await ensureModelTier(page, state, caseDir, state.requested_model_tier);
    if (!tier.ok) return markBlocked(state, tier.reason);
  }
  await send(page, state, '发送长任务');
  const cancel = page.locator('[data-testid="composer-cancel"], .aui-composer-cancel, button[aria-label="停止生成"]').first();
  const partialStartedAt = Date.now();
  const partialDeadline = partialStartedAt + 90000;
  let running = false;
  let cancelVisible = false;
  let bridgeBeforeStop = null;
  let partialSnapshot = await conversationSnapshot(page);
  let partial = coreBetaPartialReplyReady({
    running,
    cancelVisible,
    baselineAssistantBodyText: conversationBefore.latestAssistantBodyText,
    latestAssistantBodyText: partialSnapshot.latestAssistantBodyText,
  });
  while (!partial.ready && Date.now() < partialDeadline) {
    const handledConfirmation = await resolveAssistantConfirmationModal(page, {
      state,
      caseDir,
      label: '停止生成前等待部分回复',
    });
    if (handledConfirmation) {
      await page.waitForTimeout(800);
      continue;
    }
    bridgeBeforeStop = await qbotE2EState(page);
    cancelVisible = await visible(cancel, 300);
    running = Boolean(bridgeBeforeStop?.running) || cancelVisible;
    partialSnapshot = await conversationSnapshot(page);
    partial = coreBetaPartialReplyReady({
      running,
      cancelVisible,
      baselineAssistantBodyText: conversationBefore.latestAssistantBodyText,
      latestAssistantBodyText: partialSnapshot.latestAssistantBodyText,
    });
    if (!running && !cancelVisible) break;
    if (!partial.ready) await page.waitForTimeout(250);
  }
  state.screenshots.home_023_running = await shot(page, caseDir, 'home-023-running-before-stop');
  state.screenshots.core_beta_partial_before_stop = state.screenshots.home_023_running;
  if (!partial.ready) {
    state.screenshots.home_023_partial_timeout = await shot(page, caseDir, 'home-023-partial-reply-timeout');
  }
  const partialWaitedMs = Date.now() - partialStartedAt;
  const confirmedSendReceipt = Array.isArray(state.artifacts.send_receipts)
    && state.artifacts.send_receipts.some((receipt) => (
      Array.isArray(receipt?.attempts)
      && receipt.attempts.some((attempt) => attempt?.clicked === true && attempt?.receipt?.ok === true)
    ));
  const partialTimeoutVerdict = !partial.ready
    ? coreBetaStopGenerationTimeoutVerdict({
      partialReady: partial.ready,
      taskId: bridgeBeforeStop?.activeId,
      runningBefore: running,
      cancelVisible,
      waitedMs: partialWaitedMs,
      timeoutMs: SHORT_REPLY_WAIT_MS,
      confirmedSendReceipt,
      timeoutScreenshot: state.screenshots.home_023_partial_timeout,
    })
    : null;
  const partialPreconditionFile = path.join(caseDir, 'partial-reply-precondition-readback.json');
  const partialPrecondition = {
    valid: partial.ready,
    assistant_body_source: 'rendered assistant body excluding reasoning, chain-of-thought, thinking status, and tool regions',
    task_id: String(bridgeBeforeStop?.activeId || ''),
    running_before: running,
    cancel_visible: cancelVisible,
    partial_reply_ready_before_click: partial.ready,
    partial_chars_before_click: partial.delta_chars,
    partial_sha256: createHash('sha256').update(partial.delta).digest('hex'),
    waited_ms: partialWaitedMs,
    before_screenshot: state.screenshots.home_023_running,
    case_stop_click_performed: false,
    timeout_evidence: partialTimeoutVerdict,
  };
  writeJsonFile(partialPreconditionFile, partialPrecondition);
  state.artifacts.core_beta_partial_reply_precondition = partialPreconditionFile;
  recordAssertion(
    state,
    '停止生成前可见部分回复',
    '只有当当前 task 仍在运行、停止入口可见且已出现非空助手正文增量时，才允许点击停止。',
    partial.ready,
    `beforeSendCount=${before?.sendCount || 0}；taskId=${partialPrecondition.task_id || '未读取'}；running=${running}；cancelVisible=${cancelVisible}；partialChars=${partial.delta_chars}；waitedMs=${partialPrecondition.waited_ms}`,
    partialTimeoutVerdict?.valid ? 'bug' : 'automation_error',
  );
  if (!partial.ready) {
    const terminalReason = `当前 task 在 ${SHORT_REPLY_WAIT_MS}ms 完整窗口内持续运行且停止入口可见，但未生成可归属助手正文；框架未执行 Case 的停止点击。`;
    if (partialTimeoutVerdict?.valid) {
      writeReplyArtifacts(state, caseDir, [{
        label: '停止生成前正文等待终态',
        deltaText: '',
        fullText: '',
        incomplete: true,
        terminal_outcome: 'timed_out',
        timeout_ms: SHORT_REPLY_WAIT_MS,
        waited_ms: partialWaitedMs,
        min_wait_ms: MIN_REPLY_WAIT_MS,
        observed_running_after_send: true,
        running_after: true,
        incomplete_reason: terminalReason,
      }]);
    }
    const cleanupSucceeded = await cancelRunningReplyAfterTimeout(
      page,
      state,
      caseDir,
      '停止生成 Case 正文超时后的隔离清理',
    );
    const cleanupFile = path.join(caseDir, 'stop-generation-timeout-cleanup-readback.json');
    writeJsonFile(cleanupFile, {
      valid: Boolean(partialTimeoutVerdict?.valid && cleanupSucceeded),
      task_id: partialPrecondition.task_id,
      terminal_outcome: partialTimeoutVerdict?.valid ? 'timed_out' : 'unverified_timeout',
      case_stop_click_performed: false,
      timeout_failure_evidence_written: Boolean(partialTimeoutVerdict?.valid),
      cleanup_click_is_case_action: false,
      cleanup_attempted: true,
      cleanup_succeeded: cleanupSucceeded,
      timeout_evidence: partialTimeoutVerdict,
    });
    state.artifacts.stop_generation_timeout_cleanup = cleanupFile;
    if (!partialTimeoutVerdict?.valid) {
      markFailed(
        state,
        `停止生成前置未成立且无法形成完整超时证据：${partialTimeoutVerdict?.reasons?.join(',') || 'unknown'}。框架未执行 Case 的停止点击。`,
        'automation_error',
      );
    } else if (!cleanupSucceeded) {
      markFailed(state, `${terminalReason} 超时失败证据已写入，但框架未能清理仍在运行的任务。`, 'automation_error');
    } else {
      markFailed(state, `${terminalReason} 超时失败证据完整，隔离清理成功。`, 'bug');
    }
    return;
  }
  await cancel.click({ force: true }).catch(async () => cancel.evaluate((el) => el.click()));
  recordStep(state, '点击停止生成', '点击停止按钮后应结束当前 Agent 运行态。', '已真实点击 composer-cancel。', 'passed', state.screenshots.home_023_running);
  const stopDeadline = Date.now() + 60000;
  let stopped = false;
  let cancelAccepted = false;
  let lastBridge = null;
  while (Date.now() < stopDeadline) {
    lastBridge = await qbotE2EState(page);
    const cancelStillVisible = await visible(cancel, 300);
    cancelAccepted = Boolean(lastBridge?.cancelPending) || !cancelStillVisible;
    if (lastBridge?.available && !lastBridge.running && !cancelStillVisible) { stopped = true; break; }
    if (!lastBridge?.available && !cancelStillVisible) { stopped = true; break; }
    await page.waitForTimeout(400);
  }
  state.screenshots.home_023_stopped = await shot(page, caseDir, 'home-023-after-stop');
  const retainedSnapshot = await conversationSnapshot(page);
  const retained = coreBetaPartialReplyReady({
    running: true,
    cancelVisible: true,
    baselineAssistantBodyText: conversationBefore.latestAssistantBodyText,
    latestAssistantBodyText: retainedSnapshot.latestAssistantBodyText,
  });
  const users = await userMessageTexts(page);
  const composerVisible = await visible(page.locator('[data-testid="composer-input"]').first(), 1000);
  const stoppedPartialFile = path.join(caseDir, 'stopped-partial-reply.txt');
  writeTextFile(stoppedPartialFile, retained.delta);
  const stopReadback = {
    click_performed: true,
    assistant_body_source: 'rendered assistant body excluding reasoning, chain-of-thought, thinking status, and tool regions',
    task_id: String(lastBridge?.activeId || bridgeBeforeStop?.activeId || ''),
    task_id_before: String(bridgeBeforeStop?.activeId || ''),
    task_id_after: String(lastBridge?.activeId || ''),
    confirmed_send_receipt: confirmedSendReceipt,
    running_before: running,
    running_after: Boolean(lastBridge?.running),
    stopped,
    cancel_accepted: cancelAccepted,
    partial_reply_ready_before_click: partial.ready,
    partial_chars_before_click: partial.delta_chars,
    partial_sha256_before_click: createHash('sha256').update(partial.delta).digest('hex'),
    retained_chars: retained.delta_chars,
    retained_sha256: createHash('sha256').update(retained.delta).digest('hex'),
    before_screenshot: state.screenshots.home_023_running,
    after_screenshot: state.screenshots.home_023_stopped,
    bridge: lastBridge,
    user_message_count: users.length,
    composer_visible: composerVisible,
  };
  const stopReadbackFile = path.join(caseDir, 'stop-generation-readback.json');
  writeJsonFile(stopReadbackFile, stopReadback);
  state.artifacts.stop_generation = stopReadback;
  state.artifacts.stop_generation_readback = stopReadbackFile;
  state.artifacts.stopped_partial_reply = stoppedPartialFile;
  const confirmedReceipt = [...(state.artifacts.send_receipts || [])].reverse().find((receipt) => (
    receipt?.prompt === prompt
    && Array.isArray(receipt?.attempts)
    && receipt.attempts.some((attempt) => attempt?.clicked === true && attempt?.receipt?.ok === true)
  ));
  const stoppedTerminal = coreBetaStoppedTurnTerminalEvidence({
    readback: stopReadback,
    prompt,
    confirmedPrompt: confirmedReceipt?.prompt || '',
    partialText: partial.delta,
    retainedText: retained.delta,
  });
  writeReplyArtifacts(state, caseDir, [{
    label: '用户停止后的保留回复',
    fullText: retainedSnapshot.latestAssistantText,
    deltaText: retained.delta,
    incomplete: true,
    terminal_outcome: 'user_stopped',
    incomplete_reason: stoppedTerminal.terminal_reason,
    completion_evidence: stoppedTerminal,
  }]);
  recordAssertion(
    state,
    '停止后部分回复保留',
    '点击停止后应结束运行态，且停止前已可见的助手正文不应消失。',
    stopped && !stopReadback.running_after && retained.delta_chars > 0,
    `stopped=${stopped}；runningAfter=${stopReadback.running_after}；partialChars=${partial.delta_chars}；retainedChars=${retained.delta_chars}`,
  );
  recordAssertion(
    state,
    '停止后问题和恢复入口保留',
    '点击停止后应观察到运行结束，或明确进入 cancelPending 且停止按钮消失；原问题仍在会话中，输入区可恢复。',
    (stopped || cancelAccepted) && users.some((text) => text.includes('QBot 全量测试方案')) && composerVisible,
    `stopped=${stopped}；cancelAccepted=${cancelAccepted}；bridgeRunning=${lastBridge?.running ?? 'unknown'}；cancelPending=${lastBridge?.cancelPending ?? 'unknown'}；userMessages=${users.length}；composer=${composerVisible}`,
    stopped || cancelAccepted ? '' : 'automation_error',
  );
}

async function executeSitHomeSkillOnly({ page, state, testCase, caseDir, timeoutMs }) {
  await openNewTask(page, state);
  if (!await resetComposerControls(page, state, caseDir, { skillMode: 'disabled', connectorMode: 'disabled' })) return;
  if (!await selectFirstManualSkill(page, state, caseDir)) return;
  await page.keyboard.press('Escape').catch(() => {});
  const chipText = await visibleSkillChipText(page);
  const toolText = await visibleComposerToolStateText(page, 'skill');
  state.screenshots.home_007_skill_selected = await shot(page, caseDir, 'home-007-skill-selected');
  const selected = Boolean(chipText.trim()) || /手动|已选|技能/.test(toolText);
  recordAssertion(
    state,
    '技能 only 前置真实生效',
    '发送前必须真实切到手动技能并选中一个已安装技能，同时保持连接器禁用。',
    selected,
    `chip=${clip(chipText, 180)}；tool=${clip(toolText, 180)}`,
    selected ? '' : 'automation_error',
  );
  if (!selected) return;
  const prompt = String(testCase.test_data || '').trim() || '请用已选技能帮我整理这段 PRD 的验收标准。';
  const reply = await runPromptInCurrentTask({ page, state, testCase, caseDir, timeoutMs, prompt, label: '技能 only 任务' });
  recordAssertion(
    state,
    '技能 only 回复有效',
    '回复应围绕验收标准处理任务，不声称使用专家身份或连接器数据。',
    /验收|标准|检查|场景|预期/.test(reply.deltaText) && !/作为.*专家|连接器返回|查询到外部/.test(reply.deltaText),
    clip(reply.deltaText, 360),
  );
}

