async function captureShellOpenPathDuring(page, action) {
  const installed = await page.evaluate(() => {
    const shell = globalThis.window?.agent?.shell;
    if (!shell || typeof shell.openPath !== 'function') return { ok: false, reason: 'window.agent.shell.openPath unavailable' };
    if (globalThis.__qbotAutomationShellOpenOriginal) return { ok: false, reason: 'shell openPath probe already installed' };
    const original = shell.openPath;
    globalThis.__qbotAutomationShellOpenOriginal = original;
    globalThis.__qbotAutomationShellOpenCalls = [];
    const wrapped = async (...args) => {
      const call = { args: structuredClone(args), at: Date.now(), result: null, error: '' };
      globalThis.__qbotAutomationShellOpenCalls.push(call);
      try {
        call.result = await original.apply(shell, args);
        return call.result;
      } catch (error) {
        call.error = error?.message || String(error);
        throw error;
      }
    };
    try { shell.openPath = wrapped; } catch (error) { return { ok: false, reason: error?.message || String(error) }; }
    return { ok: shell.openPath === wrapped, reason: shell.openPath === wrapped ? '' : 'openPath property rejected wrapper' };
  }).catch((error) => ({ ok: false, reason: error.message }));
  if (!installed.ok) return { installed: false, clicked: false, calls: [], dialogMessage: '', reason: installed.reason };
  let clicked = false;
  let dialogMessage = '';
  try {
    const dialog = await captureDialogDuring(page, async () => { clicked = Boolean(await action()); }, 1400);
    dialogMessage = dialog.message || '';
    await page.waitForTimeout(250);
    const calls = await page.evaluate(() => structuredClone(globalThis.__qbotAutomationShellOpenCalls || [])).catch(() => []);
    return { installed: true, clicked, calls, dialogMessage };
  } finally {
    await page.evaluate(() => {
      const original = globalThis.__qbotAutomationShellOpenOriginal;
      if (original && globalThis.window?.agent?.shell) globalThis.window.agent.shell.openPath = original;
      delete globalThis.__qbotAutomationShellOpenOriginal;
      delete globalThis.__qbotAutomationShellOpenCalls;
    }).catch(() => {});
  }
}

async function artifactPanelLayoutState(page) {
  return page.evaluate(() => {
    const panel = document.querySelector('[data-testid="artifact-panel"]');
    const composer = document.querySelector('[data-testid="composer-shell"], [data-testid="composer-input"]');
    const rectOf = (el) => {
      if (!el) return null;
      const rect = el.getBoundingClientRect();
      return { x: rect.x, y: rect.y, width: rect.width, height: rect.height, right: rect.right, bottom: rect.bottom };
    };
    const panelRect = rectOf(panel);
    const composerRect = rectOf(composer);
    const overlap = Boolean(panelRect && composerRect
      && panelRect.right > composerRect.x
      && panelRect.x < composerRect.right
      && panelRect.bottom > composerRect.y
      && panelRect.y < composerRect.bottom);
    return {
      panelVisible: Boolean(panelRect && panelRect.width > 20 && panelRect.height > 20),
      composerVisible: Boolean(composerRect && composerRect.width > 20 && composerRect.height > 20),
      overlap,
      panelRect,
      composerRect,
    };
  }).catch((error) => ({ error: error.message, panelVisible: false, composerVisible: false, overlap: true }));
}

async function installFirstSkillFromMarket(page, state, caseDir, { allowAlreadyInstalled = false } = {}) {
  await openSkillsPage(page, state, caseDir, { skillTab: '技能市场' });
  const install = page.locator('.skill-install:not([disabled])').first();
  if (!(await visible(install, 2500))) {
    if (allowAlreadyInstalled) {
      await clickSkillSubtab(page, '已安装', state);
      const installedCard = page.locator('.skill-card').first();
      const installed = await visible(installedCard, 2000);
      state.screenshots.skill_already_installed = await shot(page, caseDir, 'skill-installed-fallback');
      if (installed) {
        const text = await installedCard.innerText({ timeout: 1200 }).catch(() => '');
        state.artifacts.installed_skill = { name: await skillCardName(installedCard, text), terminal: true, success: true, reused: true, text };
        return true;
      }
    }
    state.screenshots.no_installable_skill = await shot(page, caseDir, 'skill-no-installable');
    markBlocked(state, '技能市场没有可安装技能，或当前账号/SkillHub 数据不满足安装测试前置条件。');
    return false;
  }
  const card = install.locator('xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " skill-card ")][1]').first();
  const cardText = await card.innerText({ timeout: 2000 }).catch(() => '');
  const skillName = await skillCardName(card, cardText);
  await install.click({ force: true }).catch(async () => install.evaluate((el) => el.click()));
  const terminal = await waitForSkillInstallTerminal(page, { skillName, marketCard: card, timeoutMs: 90000 });
  state.screenshots.after_skill_install = await shot(page, caseDir, 'skill-after-install');
  await clickSkillSubtab(page, '已安装', state);
  await page.waitForTimeout(1000);
  state.screenshots.installed_after_install = await shot(page, caseDir, 'skill-installed-after-install');
  const text = await mainSurfaceText(page);
  const sameInstalled = await visible(page.locator('.skill-card').filter({ hasText: skillName }).first(), 1500);
  const installedViewSuccess = sameInstalled && !terminal.failure;
  const observedTerminal = terminal.terminal || installedViewSuccess;
  const observedSuccess = (terminal.terminal && terminal.success) || installedViewSuccess;
  state.artifacts.installed_skill = {
    name: skillName,
    ...terminal,
    terminal: observedTerminal,
    success: observedSuccess,
    installed_view_readback: sameInstalled,
    terminal_source: terminal.source || (installedViewSuccess ? 'exact-installed-tab-card' : ''),
  };
  recordStep(
    state,
    '点击技能市场第一张可安装技能的【安装】',
    '安装必须收敛到成功或明确失败终态；安装中/准备中不能判通过。',
    `技能=${skillName}；terminal=${observedTerminal}；success=${observedSuccess}；source=${state.artifacts.installed_skill.terminal_source || 'none'}；${clip(terminal.text, 220)}`,
    observedTerminal ? 'passed' : 'failed',
    state.screenshots.after_skill_install,
  );
  recordAssertion(
    state,
    '安装后进入已安装列表',
    '安装成功后已安装列表必须展示刚安装的同一技能；失败时必须有明确终态原因。',
    observedTerminal && (observedSuccess
      ? sameInstalled
      : /失败|无权|未配置|暂不可用|超时|拒绝/.test(`${terminal.text}\n${text}`)),
    `技能=${skillName}；sameInstalled=${sameInstalled}；terminalSource=${state.artifacts.installed_skill.terminal_source || 'none'}；${clip(text, 320)}`,
  );
  return observedTerminal && observedSuccess && sameInstalled;
}

async function skillCardName(card, fallbackText = '') {
  const named = await card?.locator?.('.skill-name, [data-testid*="skill-name"]').first().innerText({ timeout: 700 }).catch(() => '');
  return firstLine(named || fallbackText).trim();
}

export function skillInstallIdentityTerminalVerdict({
  skillName = '',
  cardText = '',
  pageText = '',
} = {}) {
  const identity = String(skillName || '').trim();
  if (!identity) return { matched: false, terminal: false, success: false, failure: false, pending: false, source: '' };

  const currentCardText = String(cardText || '');
  const pageLines = String(pageText || '').split(/\n+/).map((item) => item.trim()).filter(Boolean);
  const failurePattern = /安装失败|准备失败|物化失败|失败原因|无权|未配置|暂不可用|超时|拒绝|安装错误|发生错误|错误[:：]/;
  const successPattern = /已安装|已就绪|运行时就绪|安装成功|准备完成|物化完成/;
  const pendingPattern = /安装中|准备中|物化中|待物化|处理中|正在安装|正在准备|正在同步|同步中|reconcil|materializing/i;
  const pageSignal = (signalPattern) => {
    const namedSignal = new RegExp(`(?:技能\\s*)?[「“"']?${escapeRegExp(identity)}[」”"']?\\s*(?:[:：,，-]\\s*)?(?:${signalPattern.source})`, signalPattern.flags);
    const line = pageLines.find((entry) => namedSignal.test(entry));
    return line ? { source: 'current-skill-receipt', text: line } : null;
  };
  const cardEntry = currentCardText.includes(identity) ? { source: 'current-skill-card', text: currentCardText } : null;
  const failure = (cardEntry && failurePattern.test(cardEntry.text) ? cardEntry : null) || pageSignal(failurePattern);
  if (failure) return { matched: true, terminal: true, success: false, failure: true, pending: false, ...failure };
  const success = (cardEntry && successPattern.test(cardEntry.text) ? cardEntry : null) || pageSignal(successPattern);
  if (success) return { matched: true, terminal: true, success: true, failure: false, pending: false, ...success };
  const pending = (cardEntry && pendingPattern.test(cardEntry.text) ? cardEntry : null) || pageSignal(pendingPattern);
  if (pending) return { matched: true, terminal: false, success: false, failure: false, pending: true, ...pending };
  return { matched: false, terminal: false, success: false, failure: false, pending: false, source: '' };
}

async function waitForSkillInstallTerminal(page, {
  skillName,
  skillSlug = '',
  marketCard = null,
  timeoutMs = 90000,
}) {
  const deadline = Date.now() + timeoutMs;
  let text = '';
  let combined = '';
  while (Date.now() < deadline) {
    text = marketCard ? await marketCard.innerText({ timeout: 800 }).catch(() => '') : '';
    const pageText = await mainSurfaceText(page);
    combined = `${text}\n${pageText}`;
    if (marketCard) {
      const installedAction = marketCard.locator('button, .skill-install, .skill-delete').filter({ hasText: /删除|卸载/ }).first();
      if (await visible(installedAction, 250)) {
        return { terminal: true, success: true, failure: false, pending: false, source: 'visible installed-card action', text: text || combined };
      }
    }
    const catalogInstalled = await page.evaluate(async ({ slug, name }) => {
      if (typeof window.agent?.getSkillsCatalog !== 'function') return false;
      const catalog = await window.agent.getSkillsCatalog('');
      return (catalog?.installed || []).some((item) => (
        (slug && String(item?.slug || '') === slug)
        || (name && String(item?.name || '') === name)
      ));
    }, { slug: String(skillSlug || ''), name: String(skillName || '') }).catch(() => false);
    if (catalogInstalled) {
      return { terminal: true, success: true, failure: false, pending: false, source: 'window.agent.getSkillsCatalog().installed', text: text || combined };
    }
    if (skillName) {
      const installed = page.locator('.skill-card').filter({ hasText: skillName }).filter({ hasText: /已安装|已就绪|安装成功/ }).first();
      if (await visible(installed, 250)) return { terminal: true, success: true, failure: false, pending: false, source: 'exact installed-card readback', text: await installed.innerText({ timeout: 500 }).catch(() => combined) };
    }
    const identityTerminal = skillInstallIdentityTerminalVerdict({ skillName, cardText: text, pageText });
    if (identityTerminal.terminal) {
      return { ...identityTerminal, text: identityTerminal.text || combined };
    }
    await page.waitForTimeout(1000);
  }
  return { terminal: false, success: false, failure: false, pending: true, source: '', text: combined || text };
}

function literalOccurrenceCount(text, literal) {
  if (!literal) return 0;
  return (String(text || '').match(new RegExp(escapeRegExp(literal), 'g')) || []).length;
}

async function findSkillCardByText(page, pattern) {
  const cards = page.locator('.skill-card');
  const count = await cards.count().catch(() => 0);
  for (let index = 0; index < count; index += 1) {
    const card = cards.nth(index);
    if (!(await visible(card, 250))) continue;
    const text = await card.innerText({ timeout: 500 }).catch(() => '');
    if (pattern.test(text)) return card;
  }
  return null;
}

async function longestSkillCard(page) {
  const cards = page.locator('.skill-card');
  const count = await cards.count().catch(() => 0);
  let best = null;
  for (let index = 0; index < count; index += 1) {
    const card = cards.nth(index);
    if (!(await visible(card, 250))) continue;
    const text = await card.innerText({ timeout: 500 }).catch(() => '');
    const box = await card.evaluate((el) => {
      const rect = el.getBoundingClientRect();
      return { width: rect.width, height: rect.height };
    }).catch(() => null);
    if (!best || text.length > best.text.length) best = { locator: card, text, box };
  }
  return best;
}

async function skillManualOptionCount(page) {
  const menu = await activeMenuLocator(page, 'skill');
  if (!menu) return 0;
  const options = menu.locator('.skill-list .ctool-opt, .ctool-opt, [role="option"], button')
    .filter({ hasNotText: /禁用|自动|手动|无匹配|还没安装技能|暂无可选技能|搜索技能/ });
  const count = await options.count().catch(() => 0);
  let visibleCount = 0;
  for (let index = 0; index < count; index += 1) {
    if (await visible(options.nth(index), 150)) visibleCount += 1;
  }
  return visibleCount;
}

async function selectMultipleManualSkills(page, state, caseDir, expectedCount = 2) {
  const menu = await activeMenuLocator(page, 'skill');
  if (!menu) {
    recordAssertion(state, '多技能手动菜单定位', '自动化应能定位当前打开的技能菜单。', false, '手动模式已点击，但当前技能菜单不可见。', 'automation_error');
    return 0;
  }
  let selected = 0;
  const picked = [];
  for (let attempt = 0; attempt < expectedCount + 3 && selected < expectedCount; attempt += 1) {
    const options = menu.locator('.skill-list .ctool-opt, .ctool-opt, [role="option"], button')
      .filter({ hasNotText: /禁用|自动|手动|无匹配|还没安装技能|暂无可选技能|搜索技能/ });
    const count = await options.count().catch(() => 0);
    let clicked = false;
    for (let index = 0; index < count; index += 1) {
      const option = options.nth(index);
      if (!(await visible(option, 300))) continue;
      const text = await option.innerText({ timeout: 500 }).catch(() => '');
      const key = firstLine(text);
      if (picked.includes(key)) continue;
      await option.click({ force: true }).catch(async () => option.evaluate((el) => el.click()));
      await page.waitForTimeout(500);
      picked.push(key);
      selected += 1;
      clicked = true;
      state.screenshots[`manual_skill_multi_${selected}`] = await shot(page, caseDir, `manual-skill-multi-${selected}`);
      recordStep(state, `手动选择第 ${selected} 个技能`, '多技能用例应能选择多个已安装技能。', clip(text, 180), 'passed', state.screenshots[`manual_skill_multi_${selected}`]);
      break;
    }
    if (!clicked) break;
  }
  return selected;
}

async function summonFirstExpertForCase(page, state, caseDir) {
  await openExpertsPage(page, state, caseDir);
  let expertName = 'QBot QA 产品运营专家';
  let card = await findExpertCardByName(page, expertName) || await firstSummonableExpertCard(page);
  if (!card) {
    // A stale account can report the stable name as duplicated while the
    // current catalog does not expose that expert card.  A unique QA-prefixed
    // fixture keeps the setup user-visible and avoids depending on hidden
    // server state from previous runs.
    expertName = `QBot QA 产品运营专家-${new Date().toISOString().replace(/\D/g, '').slice(4, 14)}`;
    const created = await createBasicExpert(
      page,
      state,
      caseDir,
      expertName,
      '用于 QBot 回归验证的产品运营分析与复盘专家',
      '你是一位产品运营专家，擅长活动复盘、需求分析、数据指标、权限风险、异常场景和验收标准。回答必须结构清晰、基于用户提供的数据，不虚构外部事实。',
      'qa-stable-product-expert',
    );
    if (!created) {
      state.screenshots.no_summonable_expert = await shot(page, caseDir, 'expert-no-summonable');
      recordAssertion(state, '稳定 QA 专家预置', '没有可召唤专家时，框架应通过用户可见创建流程补充 QA 前缀专家。', false, 'QA 专家创建失败，当前专家组合用例不可执行。', 'automation_error');
      return false;
    }
    await openExpertsPage(page, state, caseDir);
    card = await findExpertCardByName(page, expertName);
    if (!card) {
      recordAssertion(state, '稳定 QA 专家可定位', '创建后必须能在专家列表定位同名 QA 专家。', false, `创建成功后列表未定位到 ${expertName}。`, 'automation_error');
      return false;
    }
  }
  const cardText = await card.innerText({ timeout: 1500 }).catch(() => '');
  await card.click({ force: true });
  await page.waitForTimeout(800);
  state.screenshots.expert_detail = await shot(page, caseDir, 'expert-detail-for-combo');
  const summon = page.locator('.modal .modal-cta').first();
  if (!(await visible(summon, 1500))) {
    recordAssertion(state, '稳定 QA 专家召唤入口', '框架已创建/定位稳定 QA 专家后，其详情应提供召唤入口。', false, clip(cardText, 260));
    return false;
  }
  await summon.click({ force: true });
  await page.waitForTimeout(1500);
  state.screenshots.expert_summoned = await shot(page, caseDir, 'expert-summoned-for-combo');
  recordStep(state, '召唤第一个可用专家', '召唤后应回到首页输入区并显示专家上下文。', clip(cardText, 180), 'passed', state.screenshots.expert_summoned);
  const composer = await visible(page.locator('[data-testid="composer-input"]').first(), 3000);
  recordAssertion(state, '召唤专家后输入区可用', '专家召唤后首页输入区应可继续发起任务。', composer, `composer=${composer}`);
  return composer;
}

async function selectGeneralAssistantForCase(page, state, caseDir) {
  await openExpertsPage(page, state, caseDir);
  const general = page.locator('[data-testid="expert-general-assistant"]').first();
  if (!(await visible(general, 2500))) {
    state.screenshots.general_assistant_missing = await shot(page, caseDir, 'general-assistant-missing');
    recordAssertion(state, '通用助手入口', '专家页应展示通用助手，以便用户清理专家身份并回到纯会话。', false, clip(await mainSurfaceText(page), 360));
    return false;
  }
  await general.click({ force: true }).catch(async () => general.evaluate((el) => el.click()));
  await page.waitForTimeout(1000);
  state.screenshots.general_assistant_selected = await shot(page, caseDir, 'general-assistant-selected');
  const composer = await visible(page.locator('[data-testid="composer-input"]').first(), 3000);
  recordStep(
    state,
    '切换为通用助手',
    '纯会话场景执行前应清理上一轮专家上下文，回到通用助手输入区。',
    composer ? '已进入通用助手会话输入区。' : '点击通用助手后未回到输入区。',
    composer ? 'passed' : 'blocked',
    state.screenshots.general_assistant_selected,
  );
  if (!composer) recordAssertion(state, '通用助手切换结果', '点击通用助手后应回到会话输入区。', false, '点击后未找到 composer-input。');
  return composer;
}

async function resetComposerControls(page, state, caseDir, {
  skillMode = 'disabled',
  connectorMode = 'disabled',
  clearSkills = true,
  clearConnectors = true,
  clearScene = true,
  clearAttachments = true,
} = {}) {
  const initialStepCount = state.steps.length;
  const initialAssertionCount = state.assertions.length;
  await page.keyboard.press('Escape').catch(() => {});
  await page.waitForTimeout(150);
  await closeWorkspacePicker(page);
  const results = [];
  let failedInteractions = [];
  const recordCapabilityOperation = (operationOk) => {
    results.push(operationOk);
    failedInteractions = preserveCoreBetaFailedCapabilityInteraction(
      failedInteractions,
      state.artifacts.core_beta_capability_interaction,
      operationOk,
    );
  };

  if (clearScene) results.push(await clearSceneTag(page, state, caseDir));
  if (clearAttachments) results.push(await clearComposerAttachments(page, state, caseDir));

  if (clearSkills) {
    recordCapabilityOperation(await clearManualSkillSelections(page, state, caseDir));
    if (skillMode) {
      recordCapabilityOperation(await setSkillMode(page, state, caseDir, skillMode, {
        allowAutoEmptyIsolation: true,
      }));
    }
  }
  await page.keyboard.press('Escape').catch(() => {});
  await page.waitForTimeout(150);

  if (clearConnectors) {
    // disabled/auto 本身会覆盖上一轮的手动选择，直接切到目标模式即可。
    // 先切 manual 再切目标模式会与菜单打开时的异步 refresh 竞争，既浪费一次
    // 控制面写入，也可能让自动化读取到点击前的旧选中态。
    if (connectorMode === 'disabled' || connectorMode === 'auto') {
      recordCapabilityOperation(await setConnectorMode(page, state, caseDir, connectorMode, {
        allowAutoEmptyIsolation: true,
      }));
    } else {
      recordCapabilityOperation(await clearManualConnectorSelections(page, state, caseDir));
      if (connectorMode) {
        recordCapabilityOperation(await setConnectorMode(page, state, caseDir, connectorMode, {
          allowAutoEmptyIsolation: true,
        }));
      }
    }
  }
  await page.keyboard.press('Escape').catch(() => {});
  await page.waitForTimeout(250);

  const skillChipText = await visibleSkillChipText(page);
  const sceneTagText = await visibleSceneTagText(page);
  const attachmentText = await visibleComposerAttachmentText(page);
  const capabilityReadback = await currentCapabilities(page);
  const isolationReadback = coreBetaComposerIsolationReadback({
    capabilities: capabilityReadback,
    requireSkills: clearSkills,
    requireConnectors: clearConnectors,
  });
  results.push(isolationReadback.ok);
  state.screenshots.composer_controls_reset = await shot(page, caseDir, 'composer-controls-reset');
  const residueObserved = Boolean(skillChipText.trim() || sceneTagText.trim() || attachmentText.trim());
  const newFailures = [
    ...state.steps.slice(initialStepCount),
    ...state.assertions.slice(initialAssertionCount),
  ].filter((item) => item.status === 'failed');
  const failureCategory = coreBetaComposerResetFailureCategory({
    operationResults: results,
    residueObserved,
    failureCategories: newFailures.map((item) => item.category),
  });
  const ok = failureCategory === '';
  state.artifacts.core_beta_composer_control_reset = {
    schema_version: 'qbot-core-beta-composer-control-reset/v1',
    valid: true,
    ok,
    failure_category: failureCategory,
    operation_results: results.map(Boolean),
    residue_observed: residueObserved,
    failed_interactions: failedInteractions,
    failed_operations: newFailures.map((item) => ({
      name: item.name || item.action || '',
      category: item.category || '',
      actual: item.actual || '',
      screenshot: item.screenshot || '',
    })),
    isolation_readback: isolationReadback,
  };
  recordAssertion(
    state,
    '输入区能力状态隔离',
    '每条用例开始前必须清理上一个用例遗留的场景、附件、手动技能 chip，并按当前用例设置技能/连接器模式。',
    ok,
    [
      `skillMode=${skillMode || '未设置'}`,
      `connectorMode=${connectorMode || '未设置'}`,
      sceneTagText.trim() ? `残留场景 tag：${clip(sceneTagText, 180)}` : '未发现残留场景 tag',
      attachmentText.trim() ? `残留附件：${clip(attachmentText, 180)}` : '未发现残留附件',
      skillChipText.trim() ? `残留技能 chip：${clip(skillChipText, 180)}` : '未发现残留技能 chip',
      `公开能力隔离=${JSON.stringify(isolationReadback)}`,
    ].join('；'),
    failureCategory,
  );
  if (!ok && failureCategory === 'automation_error') {
    markFailed(state, '自动化框架未能清理输入区场景/附件/技能/连接器状态，当前用例结果不可信，已中止本用例。', 'automation_error');
  }
  return ok;
}

export function coreBetaComposerIsolationReadback({
  capabilities = null,
  requireSkills = true,
  requireConnectors = true,
} = {}) {
  const readable = capabilities !== null && typeof capabilities === 'object';
  const has = (field) => readable && Object.prototype.hasOwnProperty.call(capabilities, field);
  const emptySelection = (value) => value === null || (Array.isArray(value) && value.length === 0);
  const skillsReadable = !requireSkills || has('selectedSkills');
  const connectorsReadable = !requireConnectors || has('selectedConnectors');
  const expertReadable = has('currentExpert');
  const skillsEmpty = !requireSkills || (skillsReadable && emptySelection(capabilities.selectedSkills));
  const connectorsEmpty = !requireConnectors
    || (connectorsReadable && emptySelection(capabilities.selectedConnectors));
  const expertEmpty = expertReadable && capabilities.currentExpert === null;
  return {
    ok: readable && skillsReadable && connectorsReadable && expertReadable
      && skillsEmpty && connectorsEmpty && expertEmpty,
    readable,
    skills_readable: skillsReadable,
    connectors_readable: connectorsReadable,
    expert_readable: expertReadable,
    skills_empty: skillsEmpty,
    connectors_empty: connectorsEmpty,
    expert_empty: expertEmpty,
    selected_skills: skillsReadable ? capabilities.selectedSkills : undefined,
    selected_connectors: connectorsReadable ? capabilities.selectedConnectors : undefined,
    current_expert: expertReadable ? capabilities.currentExpert : undefined,
  };
}

export function preserveCoreBetaFailedCapabilityInteraction(
  existing = [],
  interaction = null,
  operationOk = true,
) {
  const preserved = Array.isArray(existing) ? existing.map((item) => structuredClone(item)) : [];
  if (operationOk
    || interaction?.schema_version !== 'qbot-core-beta-capability-interaction/v1'
    || !['skill', 'connector'].includes(String(interaction?.capability_kind || ''))
    || interaction?.expected_state_observed !== false
    || !['bug', 'automation_error'].includes(String(interaction?.category || ''))) return preserved;
  const snapshot = structuredClone(interaction);
  const identity = JSON.stringify(snapshot);
  if (!preserved.some((item) => JSON.stringify(item) === identity)) preserved.push(snapshot);
  return preserved;
}

export function coreBetaComposerResetFailureCategory({
  operationResults = [],
  residueObserved = false,
  failureCategories = [],
} = {}) {
  const operationsOk = (Array.isArray(operationResults) ? operationResults : []).every(Boolean);
  if (operationsOk && !residueObserved) return '';
  if (residueObserved || failureCategories.includes('automation_error')) return 'automation_error';
  return failureCategories.includes('bug') ? 'bug' : 'automation_error';
}

async function clearSceneTag(page, state, caseDir) {
  let removed = 0;
  for (let attempt = 0; attempt < 6; attempt += 1) {
    const tag = page.locator('.scene-tag').first();
    if (!(await visible(tag, 400))) break;
    const tagText = await tag.innerText({ timeout: 500 }).catch(() => '');
    const close = tag.locator('.scene-tag-x, button').first();
    if (!(await visible(close, 500))) {
      recordAssertion(state, '场景 tag 移除按钮', '残留场景 tag 应有可点击移除按钮，避免污染当前用例。', false, `scene=${clip(tagText, 120)}`, 'automation_error');
      break;
    }
    await close.click({ force: true }).catch(async () => close.evaluate((el) => el.click()));
    removed += 1;
    await page.waitForTimeout(250);
  }
  const remaining = await visibleSceneTagText(page);
  state.screenshots.scene_tag_cleared = await shot(page, caseDir, 'scene-tag-cleared');
  recordStep(
    state,
    '清理输入区场景 tag',
    '上一个用例遗留的场景 tag 必须被移除，不能污染本用例。',
    remaining.trim() ? `仍有残留：${clip(remaining, 180)}` : (removed ? `已移除 ${removed} 个场景 tag。` : '未发现场景 tag，无需清理。'),
    remaining.trim() ? 'failed' : 'passed',
    state.screenshots.scene_tag_cleared,
    remaining.trim() ? 'automation_error' : '',
  );
  return !remaining.trim();
}

async function clearComposerAttachments(page, state, caseDir) {
  let removed = 0;
  for (let attempt = 0; attempt < 12; attempt += 1) {
    const attachment = page.locator('.aui-composer-attachments .aui-attachment-root, .aui-composer-attachments .aui-attachment-chip').first();
    if (!(await visible(attachment, 400))) break;
    const text = await attachment.innerText({ timeout: 500 }).catch(() => '');
    const root = (await visible(attachment.locator('xpath=ancestor-or-self::*[contains(@class, "aui-attachment-root")]').first(), 300))
      ? attachment.locator('xpath=ancestor-or-self::*[contains(@class, "aui-attachment-root")]').first()
      : attachment;
    const close = root.locator('button[aria-label*="移除"], button[aria-label*="remove" i], button, .aui-attachment-remove').last();
    if (!(await visible(close, 500))) {
      recordAssertion(state, '附件移除按钮', '输入区残留附件应有可点击移除按钮，避免污染当前用例。', false, `attachment=${clip(text, 120)}`, 'automation_error');
      break;
    }
    await close.click({ force: true }).catch(async () => close.evaluate((el) => el.click()));
    removed += 1;
    await page.waitForTimeout(300);
  }
  const remaining = await visibleComposerAttachmentText(page);
  state.screenshots.attachments_cleared = await shot(page, caseDir, 'attachments-cleared');
  recordStep(
    state,
    '清理输入区附件',
    '上一个用例遗留的附件必须被移除，不能污染本用例。',
    remaining.trim() ? `仍有残留：${clip(remaining, 180)}` : (removed ? `已移除 ${removed} 个附件。` : '未发现附件，无需清理。'),
    remaining.trim() ? 'failed' : 'passed',
    state.screenshots.attachments_cleared,
    remaining.trim() ? 'automation_error' : '',
  );
  return !remaining.trim();
}

async function clearManualSkillSelections(page, state, caseDir) {
  await closeVisibleSkillChips(page, state, caseDir);
  const existingChipText = await visibleSkillChipText(page);
  if (!existingChipText.trim()) {
    state.screenshots.skill_selection_cleared = await shot(page, caseDir, 'skill-selection-cleared');
    recordStep(
      state,
      '清理输入区手动技能选择',
      '上一个用例遗留的手动技能必须被移除，不能污染本用例。',
      '未发现已选技能 chip，无需切到手动模式清理。',
      'passed',
      state.screenshots.skill_selection_cleared,
    );
    return true;
  }
  const menuOpened = await setSkillMode(page, state, caseDir, 'manual');
  if (!menuOpened) return false;
  const menu = await activeMenuLocator(page, 'skill');
  if (!menu) {
    recordAssertion(state, '清理手动技能选择', '切到手动技能后应能定位当前技能菜单。', false, '技能菜单不可见。', 'automation_error');
    return false;
  }
  const clicked = await clickSelectedOptions(menu, page, /技能|搜索技能|禁用|自动|手动|无匹配|还没安装技能|暂无可选技能/);
  await page.waitForTimeout(250);
  await closeVisibleSkillChips(page, state, caseDir);
  state.screenshots.skill_selection_cleared = await shot(page, caseDir, 'skill-selection-cleared');
  const remaining = await visibleSkillChipText(page);
  recordStep(
    state,
    '清理输入区手动技能选择',
    '上一个用例遗留的手动技能必须被移除，不能污染本用例。',
    remaining.trim() ? `仍有残留：${clip(remaining, 180)}` : `已清理 ${clicked} 个已选技能/技能 chip。`,
    remaining.trim() ? 'failed' : 'passed',
    state.screenshots.skill_selection_cleared,
    remaining.trim() ? 'automation_error' : '',
  );
  if (remaining.trim()) {
    recordAssertion(state, '手动技能 chip 已清空', '技能 chip 清空后，输入区不应显示上一轮技能名。', false, clip(remaining, 180), 'automation_error');
    return false;
  }
  return true;
}

async function clearManualConnectorSelections(page, state, caseDir) {
  const capabilities = await currentCapabilities(page);
  const selectedConnectors = Array.isArray(capabilities?.selectedConnectors)
    ? capabilities.selectedConnectors
    : [];
  if (!selectedConnectors.length) {
    state.screenshots.connector_selection_cleared = await shot(page, caseDir, 'connector-selection-cleared');
    recordStep(
      state,
      '清理输入区手动连接器选择',
      '上一个用例遗留的手动连接器必须被移除，不能污染本用例。',
      '能力状态未发现已选连接器，无需切到手动模式清理。',
      'passed',
      state.screenshots.connector_selection_cleared,
    );
    return true;
  }
  const menuOpened = await setConnectorMode(page, state, caseDir, 'manual');
  if (!menuOpened) return false;
  const menu = await activeMenuLocator(page, 'connector');
  if (!menu) {
    recordAssertion(state, '清理手动连接器选择', '切到手动连接器后应能定位当前连应用菜单。', false, '连应用菜单不可见。', 'automation_error');
    return false;
  }
  const clicked = await clickSelectedOptions(menu, page, /连接器|连应用|搜索连接器|禁用|自动|手动|无匹配|未接入连接器|暂无连接器/);
  await page.waitForTimeout(250);
  state.screenshots.connector_selection_cleared = await shot(page, caseDir, 'connector-selection-cleared');
  const selectedCount = await menu.locator('.composer-plus-connector.on, [data-testid^="composer-connector-option-"]:not([data-testid$="-tag"]).on, .ctool-list .ctool-opt.on').count().catch(() => 0);
  recordStep(
    state,
    '清理输入区手动连接器选择',
    '上一个用例遗留的手动连接器必须被移除，不能污染本用例。',
    selectedCount ? `仍有 ${selectedCount} 个连接器处于选中态。` : `已清理 ${clicked} 个已选连接器。`,
    selectedCount ? 'failed' : 'passed',
    state.screenshots.connector_selection_cleared,
    selectedCount ? 'automation_error' : '',
  );
  if (selectedCount) {
    recordAssertion(state, '手动连接器已清空', '连接器清空后，手动列表不应残留上一轮选中态。', false, `selectedCount=${selectedCount}`, 'automation_error');
    return false;
  }
  return true;
}

async function closeVisibleSkillChips(page, state, caseDir) {
  let removed = 0;
  for (let attempt = 0; attempt < 12; attempt += 1) {
    const chip = page.locator('.skill-chip').first();
    if (!(await visible(chip, 400))) break;
    const chipText = await chip.innerText({ timeout: 500 }).catch(() => '');
    const close = chip.locator('.skill-chip-x, button[aria-label="移除"], button[aria-label*="remove" i]').first();
    if (!(await visible(close, 500))) {
      recordAssertion(state, '技能 chip 移除按钮', '每个手动技能 chip 应有可点击的移除按钮。', false, `chip=${clip(chipText, 120)}`, 'automation_error');
      break;
    }
    await close.click({ force: true }).catch(async () => close.evaluate((el) => el.click()));
    removed += 1;
    await page.waitForTimeout(200);
  }
  if (removed) {
    state.screenshots.skill_chip_removed = await shot(page, caseDir, 'skill-chip-removed');
    recordStep(state, '移除输入区技能 chip', '点击 chip 上的移除按钮后，技能不应继续挂在本轮会话。', `已点击移除 ${removed} 个技能 chip。`, 'passed', state.screenshots.skill_chip_removed);
  }
  return removed;
}

async function clickSelectedOptions(menu, page, ignorePattern) {
  let clicked = 0;
  for (let attempt = 0; attempt < 12; attempt += 1) {
    const options = menu.locator('.ctool-list .ctool-opt.on, [data-testid^="composer-connector-option-"]:not([data-testid$="-tag"]).on, .composer-plus-skill.on, .composer-plus-connector.on');
    const count = await options.count().catch(() => 0);
    let target = null;
    for (let index = 0; index < count; index += 1) {
      const candidate = options.nth(index);
      if (!(await visible(candidate, 250))) continue;
      const text = await candidate.innerText({ timeout: 500 }).catch(() => '');
      if (ignorePattern?.test(text) && text.trim().length < 12) continue;
      target = candidate;
      break;
    }
    if (!target) break;
    await target.click({ force: true }).catch(async () => target.evaluate((el) => el.click()));
    clicked += 1;
    await page.waitForTimeout(250);
  }
  return clicked;
}

async function visibleSkillChipText(page) {
  const chips = page.locator('.skill-chip');
  const count = await chips.count().catch(() => 0);
  const texts = [];
  for (let index = 0; index < count; index += 1) {
    const chip = chips.nth(index);
    if (await visible(chip, 250)) texts.push(await chip.innerText({ timeout: 500 }).catch(() => ''));
  }
  return texts.map((item) => item.trim()).filter(Boolean).join(' / ');
}

function cleanSkillChipLabel(value) {
  return String(value || '')
    .replace(/(?:移除|删除|remove)/gi, '')
    .replace(/^\s*[✦★☆◆◇•·]+\s*/u, '')
    .replace(/[×xX]\s*$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

async function composerSkillSelectionSnapshot(page) {
  return page.evaluate(async () => {
    const composer = document.querySelector('[data-testid="composer-input"]');
    const allChips = composer
      ? Array.from(composer.querySelectorAll('[data-testid^="composer-skill-chip-"], .skill-chip'))
      : [];
    const chips = allChips.filter((chip) => {
      const rect = chip.getBoundingClientRect();
      const style = globalThis.getComputedStyle(chip);
      return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
    });
    let capabilities = null;
    if (typeof globalThis.window?.agent?.capabilities === 'function') {
      try {
        capabilities = await globalThis.window.agent.capabilities();
      } catch {
        capabilities = null;
      }
    }
    const selectedSkills = Array.isArray(capabilities?.selectedSkills) ? capabilities.selectedSkills : [];
    const composerText = String(composer?.innerText || composer?.textContent || '');
    const composerHtml = String(composer?.innerHTML || '');
    const markerText = `${composerText}\n${composerHtml}`;
    return {
      chipCount: chips.length,
      chipTexts: chips.map((chip) => String(chip.textContent || '').replace(/\s+/g, ' ').trim()),
      chipTestIds: chips.map((chip) => String(chip.getAttribute('data-testid') || '')),
      chipsInsideComposer: Boolean(composer) && chips.every((chip) => composer.contains(chip)),
      selectedSkillCount: selectedSkills.length,
      selectedSkills,
      composerText,
      composerHtml,
      hasRawMarker: /\{\{\s*skill\s*:|⟦\s*skill\s*:|\[\[\s*skill\s*:/i.test(markerText),
    };
  }).catch((error) => ({
    chipCount: 0,
    chipTexts: [],
    chipTestIds: [],
    chipsInsideComposer: false,
    selectedSkillCount: 0,
    selectedSkills: [],
    composerText: '',
    composerHtml: '',
    hasRawMarker: false,
    error: error.message,
  }));
}

async function visibleComposerToolStateText(page, tool) {
  const selector = tool === 'connector'
    ? '[data-testid="composer-connectors-menu"], [data-testid="composer-plus-menu"], .composer-plus-sub-connector, [data-testid="composer-connector-chip"], [data-testid="composer-selection-chips"]'
    : tool === 'workMode'
      ? '[data-testid="composer-shell"] .ctools > *:first-child, .composer-stack .ctools > *:first-child, .composer-plus-main .composer-plus-row'
      : '[data-testid="composer-skills-menu"], [data-testid="composer-plus-menu"], .composer-plus-sub-skill, [data-testid^="composer-skill-chip-"], .skill-chip';
  const entries = page.locator(selector);
  const count = await entries.count().catch(() => 0);
  const texts = [];
  for (let index = 0; index < count; index += 1) {
    const entry = entries.nth(index);
    if (await visible(entry, 250)) texts.push(await entry.innerText({ timeout: 500 }).catch(() => ''));
  }
  return texts.map((item) => item.replace(/\s+/g, ' ').trim()).filter(Boolean).join(' / ');
}

async function currentCapabilities(page) {
  return page.evaluate(async () => {
    if (globalThis.window?.agent?.capabilities) return globalThis.window.agent.capabilities();
    return null;
  }).catch(() => null);
}

async function unifiedComposerPlusAvailable(page) {
  return visible(page.locator('[data-testid="composer-plus-menu"]').first(), 500);
}

async function composerProductEntrySnapshot(page, { state = null, caseDir = '' } = {}) {
  const legacySkill = await visible(page.locator('[data-testid="composer-skills-menu"]').first(), 500);
  const legacyConnector = await visible(page.locator('[data-testid="composer-connectors-menu"]').first(), 500);
  if (legacySkill && legacyConnector) {
    return {
      skill: true,
      connector: true,
      surface: 'legacy-separate-controls',
      menuText: '独立技能与连接器入口均可见。',
    };
  }

  const plus = page.locator('[data-testid="composer-plus-menu"]').first();
  if (!(await visible(plus, 800))) {
    return {
      skill: legacySkill,
      connector: legacyConnector,
      surface: 'missing',
      menuText: '未找到统一“+”菜单。',
    };
  }

  await page.keyboard.press('Escape').catch(() => {});
  await closeWorkspacePicker(page);
  await plus.click({ force: true }).catch(async () => plus.evaluate((element) => element.click()));
  const main = page.locator('.composer-plus-main').first();
  const mainVisible = await visible(main, 1200);
  const menuText = mainVisible
    ? await main.innerText({ timeout: 1000 }).catch(() => '')
    : '';
  const rows = main.locator('.composer-plus-row, [role="menuitem"]');
  const skill = mainVisible && await visible(
    rows.filter({ hasText: /^\s*技能(?:\s|$)/ }).first(),
    700,
  );
  const connector = mainVisible && await visible(
    rows.filter({ hasText: /^\s*(?:连接器|连应用)(?:\s|$)/ }).first(),
    700,
  );

  if (state && caseDir && mainVisible) {
    state.screenshots.home_product_entries = await shot(page, caseDir, '03-home-product-entries');
    recordStep(
      state,
      '展开输入区统一“+”菜单并核对产品入口',
      '统一菜单中应同时提供技能与连接器/连应用入口，普通用户无需寻找旧版独立按钮。',
      `skill=${skill}；connector=${connector}；menuText=${clip(menuText, 180)}`,
      skill && connector ? 'passed' : 'failed',
      state.screenshots.home_product_entries,
      skill && connector ? '' : 'product_failure',
    );
  }
  await page.keyboard.press('Escape').catch(() => {});
  return {
    skill: legacySkill || skill,
    connector: legacyConnector || connector,
    surface: mainVisible ? 'unified-plus-menu' : 'unified-plus-menu-not-opened',
    menuText,
  };
}

const UNIFIED_COMPOSER_SUBMENUS = Object.freeze({
  workMode: {
    label: '模式',
    section: 'mode',
    selector: '.composer-plus-sub-mode',
    optionSelector: '[data-testid^="composer-work-mode-"]',
  },
  skill: {
    label: '技能',
    section: 'skill',
    selector: '.composer-plus-sub-skill',
    optionSelector: '[data-testid^="composer-skill-mode-"], [data-testid^="composer-skill-option-"]',
    emptySelector: '.composer-plus-empty',
  },
  connector: {
    label: '连接器',
    section: 'connector',
    selector: '.composer-plus-sub-connector',
    optionSelector: '[data-testid^="composer-connector-mode-"], [data-testid^="composer-connector-option-"]',
    emptySelector: '.composer-plus-empty',
  },
});

async function lastVisibleLocator(locator, timeout = 250) {
  const count = await locator.count().catch(() => 0);
  for (let index = count - 1; index >= 0; index -= 1) {
    const candidate = locator.nth(index);
    if (await visible(candidate, timeout)) return candidate;
  }
  return null;
}

export function coreBetaUnifiedSubmenuSurfaceReady({
  optionSelectorRequired = false,
  optionCount = 0,
  emptyVisible = false,
} = {}) {
  return optionSelectorRequired !== true || Number(optionCount) > 0 || emptyVisible === true;
}

async function visibleUnifiedComposerSubmenu(page, config, timeout = 250) {
  const submenu = await lastVisibleLocator(page.locator(config.selector), timeout);
  if (!submenu) return null;
  const optionCount = config.optionSelector
    ? await submenu.locator(config.optionSelector).count().catch(() => 0)
    : 0;
  const emptyVisible = config.emptySelector
    ? Boolean(await lastVisibleLocator(submenu.locator(config.emptySelector), timeout))
    : false;
  if (!coreBetaUnifiedSubmenuSurfaceReady({
    optionSelectorRequired: Boolean(config.optionSelector),
    optionCount,
    emptyVisible,
  })) return null;
  return submenu;
}

async function readManualSkillSurface(menu) {
  if (!menu) return null;
  return menu.evaluate((surface) => {
    const isVisible = (element) => {
      if (!element || !element.getClientRects().length) return false;
      const style = globalThis.getComputedStyle(element);
      return style.display !== 'none' && style.visibility !== 'hidden';
    };
    return {
      search_visible: isVisible(surface.querySelector('input[placeholder*="搜索技能"]')),
      list_visible: isVisible(surface.querySelector('.composer-plus-list, .skill-list, .ctool-list')),
      option_count: [...surface.querySelectorAll('[data-testid^="composer-skill-option-"], .composer-plus-skill, .skill-list .ctool-opt')]
        .filter(isVisible).length,
      empty_visible: isVisible(surface.querySelector('.composer-plus-empty')),
    };
  }).catch(() => null);
}

async function openUnifiedComposerSubmenuOnce(page, state, menuKind, action = '') {
  const config = UNIFIED_COMPOSER_SUBMENUS[menuKind];
  if (!config || !(await unifiedComposerPlusAvailable(page))) return '';

  let submenu = await visibleUnifiedComposerSubmenu(page, config, 150);
  if (submenu) return (await submenu.innerText({ timeout: 1000 }).catch(() => '')) || config.label;

  await page.keyboard.press('Escape').catch(() => {});
  await closeWorkspacePicker(page);
  const plus = page.locator('[data-testid="composer-plus-menu"]').first();
  if (!(await visible(plus, 1000))) return '';
  await plus.click({ force: true }).catch(async () => plus.evaluate((element) => element.click()));

  let main = await lastVisibleLocator(page.locator('.composer-plus-main'), 1200);
  if (!main) return '';
  const triggerSelector = `[data-testid="composer-plus-section-${config.section}"]`;
  const locateTrigger = async () => {
    main = await lastVisibleLocator(page.locator('.composer-plus-main'), 500);
    if (!main) return null;
    const exact = main.locator(triggerSelector).first();
    if (await visible(exact, 500)) return exact;
    const fallback = main.locator('.composer-plus-row, [role="menuitem"]')
      .filter({ hasText: new RegExp(`^\\s*${escapeRegExp(config.label)}(?:\\s|$)`) })
      .first();
    return await visible(fallback, 500) ? fallback : null;
  };
  let row = await locateTrigger();
  if (!row) return '';

  const waitForSubmenu = async (timeoutMs) => {
    let current = null;
    const deadline = Date.now() + timeoutMs;
    while (!current && Date.now() < deadline) {
      current = await visibleUnifiedComposerSubmenu(page, config, 120);
      if (!current) await page.waitForTimeout(60);
    }
    return current;
  };
  // QWork uses a real SubTrigger here. Reacquire the newest visible Portal
  // after every attempt because capability refreshes can leave hidden copies.
  await row.hover({ force: true }).catch(() => {});
  await row.dispatchEvent('pointermove', { pointerType: 'mouse' }).catch(() => {});
  submenu = await waitForSubmenu(1200);
  if (!submenu) {
    row = await locateTrigger();
    if (!row) return '';
    await row.click({ force: true }).catch(async () => row.evaluate((element) => element.click()));
    submenu = await waitForSubmenu(1800);
  }
  if (!submenu) {
    row = await locateTrigger();
    if (!row) return '';
    await row.focus().catch(() => {});
    await row.press('ArrowRight').catch(async () => page.keyboard.press('ArrowRight').catch(() => {}));
    submenu = await waitForSubmenu(2500);
  }
  if (!submenu) {
    row = await locateTrigger();
    if (!row) return '';
    await row.focus().catch(() => {});
    await row.press('Enter').catch(() => {});
    submenu = await waitForSubmenu(1800);
  }
  if (!submenu) return '';

  const text = await submenu.innerText({ timeout: 1000 }).catch(() => '');
  recordStep(
    state,
    action || `打开输入区统一“+”菜单的【${config.label}】子菜单`,
    `统一菜单必须可通过“+ > ${config.label}”进入对应能力选择区。`,
    `trigger=${triggerSelector}；submenu=${config.selector}；${clip(text, 180)}`,
    'passed',
  );
  return text || config.label;
}

async function openUnifiedComposerSubmenu(page, state, menuKind, action = '') {
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const opened = await openUnifiedComposerSubmenuOnce(
      page,
      state,
      menuKind,
      attempt === 1 ? action : `${action || `打开【${menuKind}】子菜单`}（重试 ${attempt}/3）`,
    );
    if (opened.trim()) return opened;
    await page.keyboard.press('Escape').catch(() => {});
    await closeWorkspacePicker(page);
    await page.waitForTimeout(250 * attempt);
  }
  return '';
}

async function setUnifiedSkillMode(page, state, caseDir, mode, {
  allowAutoEmptyIsolation = false,
} = {}) {
  if (!(await unifiedComposerPlusAvailable(page))) return null;
  if (mode === 'manual') {
    const menuText = await openUnifiedComposerSubmenu(page, state, 'skill', '打开输入区【技能】子菜单');
    if (!menuText.trim()) {
      state.screenshots.skill_mode_manual_menu_missing = await shot(page, caseDir, 'skill-mode-manual-menu-missing');
      state.artifacts.core_beta_capability_interaction = {
        schema_version: 'qbot-core-beta-capability-interaction/v1',
        capability_kind: 'skill',
        stage: 'manual_mode',
        control_testid: 'composer-plus-section-skill',
        control_located: false,
        click_dispatched: false,
        expected_state_observed: false,
        submenu_attempts: 3,
        screenshot: state.screenshots.skill_mode_manual_menu_missing,
        category: 'automation_error',
      };
      recordAssertion(
        state,
        '统一菜单技能子菜单可打开',
        '“+ > 技能”应在三次完整开启尝试内展示最新可见技能 Portal。',
        false,
        '依次执行 hover、click、ArrowRight、Enter 的完整开启流程并重试三次后，技能子菜单仍不可见。',
        'automation_error',
      );
      return false;
    }
    let submenu = await visibleUnifiedComposerSubmenu(page, UNIFIED_COMPOSER_SUBMENUS.skill, 500);
    let manual = submenu
      ? await lastVisibleLocator(submenu.locator('[data-testid="composer-skill-mode-manual"]'), 500)
      : null;
    if (!manual) {
      const manualSurface = await readManualSkillSurface(submenu);
      const capabilities = await currentCapabilities(page);
      const directListReadiness = coreBetaDirectSkillListReady({
        manualControlPresent: false,
        submenuOpened: Boolean(submenu && menuText.trim()),
        manualSurface,
        capabilities,
      });
      if (directListReadiness.ok) {
        state.screenshots.skill_mode_manual = await shot(page, caseDir, 'skill-manual-direct-list-ready');
        state.artifacts.core_beta_capability_interaction = {
          schema_version: 'qbot-core-beta-capability-interaction/v1',
          capability_kind: 'skill',
          stage: 'manual_selection_surface',
          control_testid: 'composer-plus-section-skill',
          control_located: true,
          click_dispatched: true,
          expected_state_observed: true,
          direct_list_contract: true,
          manual_surface: manualSurface,
          selected_skills: capabilities?.selectedSkills,
          menu_text: menuText,
          screenshot: state.screenshots.skill_mode_manual,
          category: '',
        };
        recordStep(
          state,
          '确认新版技能直接列表可选择',
          '真实打开“+ > 技能”后必须看到搜索框和可见列表/空态；具体手动态由后续技能点击及 selectedSkills 读回证明。',
          `readiness=${JSON.stringify(directListReadiness)}；selectedSkills=${JSON.stringify(capabilities?.selectedSkills)}；菜单=${clip(menuText, 220)}`,
          'passed',
          state.screenshots.skill_mode_manual,
        );
        return true;
      }
      recordAssertion(
        state,
        '统一菜单技能手动模式入口',
        '“+ > 技能”子菜单必须提供用户可见的【手动】模式，或提供可读公开状态的新版直接选择列表。',
        false,
        `子菜单未提供旧 manual 控件，且新版直接列表合同不成立：${JSON.stringify(directListReadiness)}；${clip(menuText, 220)}`,
        'automation_error',
      );
      return false;
    }
    let checked = await manual.getAttribute('aria-checked').catch(() => '');
    const beforeChecked = checked;
    let clickDispatched = checked === 'true';
    if (checked !== 'true') {
      try {
        await manual.click({ force: true }).catch(async () => manual.evaluate((element) => element.click()));
        clickDispatched = true;
      } catch (error) {
        state.artifacts.core_beta_capability_interaction = {
          schema_version: 'qbot-core-beta-capability-interaction/v1',
          capability_kind: 'skill',
          stage: 'manual_mode',
          control_testid: 'composer-skill-mode-manual',
          control_located: true,
          click_dispatched: false,
          expected_state_observed: false,
          before_aria_checked: beforeChecked,
          error: String(error?.message || error),
          category: 'automation_error',
        };
        recordAssertion(
          state,
          '统一菜单技能手动模式点击',
          '定位到用户可见的【手动】控件后必须成功派发真实点击。',
          false,
          String(error?.message || error),
          'automation_error',
        );
        return false;
      }
    }
    let afterText = '';
    let manualSurface = null;
    const deadline = Date.now() + 8000;
    while (Date.now() < deadline) {
      await page.waitForTimeout(200);
      submenu = await visibleUnifiedComposerSubmenu(page, UNIFIED_COMPOSER_SUBMENUS.skill, 150);
      if (!submenu) {
        await openUnifiedComposerSubmenu(page, state, 'skill', '技能模式切换后重新打开【技能】子菜单');
        submenu = await visibleUnifiedComposerSubmenu(page, UNIFIED_COMPOSER_SUBMENUS.skill, 350);
      }
      manual = submenu
        ? await lastVisibleLocator(submenu.locator('[data-testid="composer-skill-mode-manual"]'), 150)
        : null;
      checked = manual ? await manual.getAttribute('aria-checked').catch(() => '') : '';
      afterText = await activeMenuText(page, 'skill');
      manualSurface = await readManualSkillSurface(submenu);
      if (
        checked === 'true'
        && manualSurface?.search_visible
        && manualSurface?.list_visible
        && (manualSurface.option_count > 0 || manualSurface.empty_visible)
      ) break;
    }
    const ok = checked === 'true'
      && manualSurface?.search_visible
      && manualSurface?.list_visible
      && (manualSurface.option_count > 0 || manualSurface.empty_visible);
    state.screenshots.skill_mode_manual = await shot(page, caseDir, 'skill-mode-manual');
    const interactionCategory = coreBetaCapabilityInteractionCategory({
      controlLocated: true,
      clickDispatched,
      expectedStateObserved: ok,
    });
    state.artifacts.core_beta_capability_interaction = {
      schema_version: 'qbot-core-beta-capability-interaction/v1',
      capability_kind: 'skill',
      stage: 'manual_mode',
      control_testid: 'composer-skill-mode-manual',
      control_located: true,
      click_dispatched: clickDispatched,
      expected_state_observed: ok,
      before_aria_checked: beforeChecked,
      aria_checked: checked,
      manual_surface: manualSurface,
      menu_text: afterText,
      screenshot: state.screenshots.skill_mode_manual,
      category: interactionCategory,
    };
    recordStep(
      state,
      '通过可见 UI 切换技能模式：manual',
      '必须真实点击“+ > 技能 > 手动”，并看到手动技能列表；仅打开自动模式说明页不算完成。',
      `aria-checked=${checked || '未读取'}；manual-surface=${JSON.stringify(manualSurface)}；菜单=${clip(afterText, 220)}`,
      ok ? 'passed' : 'failed',
      state.screenshots.skill_mode_manual,
      interactionCategory,
    );
    return ok;
  }

  const method = mode === 'auto' ? 'setSkillsAuto' : 'setSkillsDisabled';
  const invoked = await page.evaluate(async ({ methodName }) => {
    const api = globalThis.window?.agent?.[methodName];
    if (typeof api !== 'function') return { ok: false, reason: `${methodName} unavailable` };
    const selection = await api();
    return {
      ok: true,
      selection: selection === null || Array.isArray(selection) ? selection : undefined,
    };
  }, { methodName: method }).catch((error) => ({ ok: false, reason: error.message }));
  if (!invoked.ok) {
    recordAssertion(
      state,
      `统一菜单技能模式 ${mode}`,
      '新版统一菜单隐藏全局三态后，框架准备阶段应通过 QWork 公共能力桥设置同等会话状态。',
      false,
      invoked.reason || `${method} 调用失败。`,
      'automation_error',
    );
    return false;
  }

  let capabilities = null;
  const deadline = Date.now() + 5000;
  while (Date.now() < deadline) {
    await page.waitForTimeout(150);
    capabilities = await currentCapabilities(page);
    if (unifiedSkillModeApplied(capabilities, mode, invoked.selection)) break;
  }
  const selected = capabilities?.selectedSkills;
  const exactModeApplied = unifiedSkillModeApplied(capabilities, mode, invoked.selection);
  const isolationApplied = allowAutoEmptyIsolation
    && mode === 'disabled'
    && capabilities?.selectedSkills === null
    && capabilities?.currentExpert === null;
  const ok = exactModeApplied || isolationApplied;
  state.screenshots[`skill_mode_${mode}`] = await shot(page, caseDir, `skill-mode-${mode}`);
  recordStep(
    state,
    `设置统一菜单技能模式：${mode}`,
    '该调用只用于隔离用例前置状态；技能选择和功能断言仍必须通过用户可见 UI 与结果证据完成。',
    `method=${method}；bridge.selection=${JSON.stringify(invoked.selection)}；capabilities.selectedSkills=${JSON.stringify(selected)}；isolation_auto_empty=${isolationApplied}`,
    ok ? 'passed' : 'failed',
    state.screenshots[`skill_mode_${mode}`],
    ok ? '' : 'automation_error',
  );
  return ok;
}

export function unifiedSkillModeApplied(capabilities, mode, bridgeSelection = undefined) {
  const selectedSkills = capabilities?.selectedSkills;
  if (mode === 'auto') {
    return selectedSkills === null || bridgeSelection === null;
  }
  if (mode === 'disabled') {
    return (Array.isArray(selectedSkills) && selectedSkills.length === 0)
      || (Array.isArray(bridgeSelection) && bridgeSelection.length === 0);
  }
  return false;
}

export function coreBetaManualConnectorModeReady({
  ariaChecked = '',
  manualSurface = null,
  capabilities = null,
} = {}) {
  const listReady = Boolean(
    manualSurface?.list_visible
    && (Number(manualSurface?.option_count || 0) > 0 || manualSurface?.empty_visible),
  );
  const publicManual = capabilities?.connectorRouting?.mode === 'manual';
  return {
    ok: listReady && (publicManual || ariaChecked === 'true'),
    list_ready: listReady,
    public_manual: publicManual,
    aria_checked: ariaChecked === 'true',
  };
}

export function coreBetaDirectConnectorListModeReady({
  manualControlPresent = false,
  submenuOpened = false,
  manualSurface = null,
  capabilities = null,
} = {}) {
  const listReady = Boolean(
    manualSurface?.list_visible
    && (Number(manualSurface?.option_count || 0) > 0 || manualSurface?.empty_visible),
  );
  const publicMode = String(capabilities?.connectorRouting?.mode || '');
  const publicStateReadable = ['auto', 'manual', 'disabled'].includes(publicMode)
    && (capabilities?.selectedConnectors === null || Array.isArray(capabilities?.selectedConnectors));
  return {
    ok: manualControlPresent !== true && submenuOpened === true
      && listReady && publicStateReadable,
    manual_control_present: manualControlPresent === true,
    submenu_opened: submenuOpened === true,
    list_ready: listReady,
    public_state_readable: publicStateReadable,
    public_mode: publicMode,
  };
}

export function coreBetaDirectSkillListReady({
  manualControlPresent = false,
  submenuOpened = false,
  manualSurface = null,
  capabilities = null,
} = {}) {
  const listReady = Boolean(
    manualSurface?.search_visible
    && manualSurface?.list_visible
    && (Number(manualSurface?.option_count || 0) > 0 || manualSurface?.empty_visible),
  );
  const publicStateReadable = capabilities !== null
    && typeof capabilities === 'object'
    && (capabilities?.selectedSkills === null || Array.isArray(capabilities?.selectedSkills));
  return {
    ok: manualControlPresent !== true && submenuOpened === true
      && listReady && publicStateReadable,
    manual_control_present: manualControlPresent === true,
    submenu_opened: submenuOpened === true,
    list_ready: listReady,
    public_state_readable: publicStateReadable,
  };
}

export function coreBetaCapabilityInteractionCategory({
  controlLocated = false,
  clickDispatched = false,
  expectedStateObserved = false,
} = {}) {
  if (!controlLocated || !clickDispatched) return 'automation_error';
  return expectedStateObserved ? '' : 'bug';
}

const CORE_BETA_PRE_SEND_CAPABILITY_FAILURE_NA_ROLES = Object.freeze([
  'capability_execution_event',
  'prompt',
  'task_id',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

const CORE_BETA_CAPABILITY_INVENTORY_PREREQUISITE_NA_ROLES = Object.freeze([
  'capability_execution_event',
  'prompt',
  'task_id',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

const CORE_BETA_PRE_SEND_IME_FAILURE_NA_ROLES = Object.freeze([
  'prompt',
  'task_id',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

const CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_NA_ROLES = Object.freeze([
  'task_id',
  'prompt',
  'send_receipt',
  'transcript',
  'reply_delta',
  'reply_completion',
]);

const CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_CASES = Object.freeze({
  'SIT-HOME-043': 'single_file_oversize',
  'SIT-HOME-044': 'aggregate_oversize',
});

function coreBetaEvidenceFileRecord(file, minimumBytes = 1) {
  const resolved = String(file || '').trim() ? path.resolve(file) : '';
  const valid = Boolean(
    resolved
    && fs.existsSync(resolved)
    && fs.statSync(resolved).isFile()
    && fs.statSync(resolved).size >= minimumBytes
  );
  return {
    path: valid ? resolved : '',
    sha256: valid
      ? createHash('sha256').update(fs.readFileSync(resolved)).digest('hex')
      : '',
  };
}

function coreBetaObservedNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

export function coreBetaPreSendAttachmentRejectionEvidence({
  testCaseId = '',
  rejectionType = '',
  before = {},
  after = {},
  probe = {},
  composerState = {},
  rejectionScreenshot = '',
  postDismissalScreenshot = '',
  dialogEvidenceArtifact = '',
  noPromptRecorded = false,
  noSendReceiptRecorded = false,
  notApplicableRoles = CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_NA_ROLES,
} = {}) {
  const caseId = String(testCaseId || '').trim();
  const expectedType = CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_CASES[caseId] || '';
  const expectedMessage = caseId === 'SIT-HOME-043'
    ? /单个文档不能超过\s*30\s*MiB|单个.*30\s*(?:MiB|MB)|文件过大/
    : /文档附件总大小不能超过\s*80\s*MiB|总大小.*80\s*(?:MiB|MB)|总量过大/;
  const roles = (Array.isArray(notApplicableRoles) ? notApplicableRoles : [])
    .map(String)
    .filter((role, index, items) => (
      CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_NA_ROLES.includes(role)
      && items.indexOf(role) === index
    ));
  const beforeState = {
    available: before?.available === true,
    active_id: before?.activeId ?? null,
    running: before?.running,
    message_count: before?.messageCount,
    send_count: before?.sendCount,
  };
  const afterState = {
    available: after?.available === true,
    active_id: after?.activeId ?? null,
    running: after?.running,
    message_count: after?.messageCount,
    send_count: after?.sendCount,
  };
  const mutationGuard = {
    public_state_available_before: beforeState.available,
    public_state_available_after: afterState.available,
    task_absent_before: !String(beforeState.active_id || ''),
    task_absent_after: !String(afterState.active_id || ''),
    not_running_before: beforeState.running === false,
    not_running_after: afterState.running === false,
    message_count_observed: coreBetaObservedNumber(beforeState.message_count)
      && coreBetaObservedNumber(afterState.message_count),
    message_count_unchanged: beforeState.message_count === afterState.message_count,
    send_count_observed: coreBetaObservedNumber(beforeState.send_count)
      && coreBetaObservedNumber(afterState.send_count),
    send_count_unchanged: beforeState.send_count === afterState.send_count,
    no_prompt_recorded: noPromptRecorded === true,
    no_send_receipt_recorded: noSendReceiptRecorded === true,
  };
  mutationGuard.valid = Object.values(mutationGuard).every(Boolean);
  const composer = {
    count: composerState?.count,
    names: Array.isArray(composerState?.names) ? composerState.names.map(String) : null,
  };
  const rejection = {
    type: String(rejectionType || ''),
    expected_pattern_matched: probe?.expected_pattern_matched === true,
    visible_rejection_evidence: probe?.visible_rejection_evidence === true,
    dialog_observed: Boolean(String(probe?.dialog_message || '').trim()),
    dialog_message: String(probe?.dialog_message || ''),
    dialog_settled: probe?.dialog_settled === true,
    managed_teams_ax_required: probe?.managed_teams_ax_required === true,
    managed_dialog_evidence: probe?.managed_dialog_evidence === true,
    rejected_before_send: probe?.rejected_before_send === true,
  };
  const screenshots = {
    rejection: coreBetaEvidenceFileRecord(rejectionScreenshot, 128),
    after_dismissal: coreBetaEvidenceFileRecord(postDismissalScreenshot, 128),
  };
  const dialogEvidence = coreBetaEvidenceFileRecord(dialogEvidenceArtifact, 1);
  const evidenceValid = Boolean(
    expectedType
    && rejection.type === expectedType
    && rejection.expected_pattern_matched
    && rejection.visible_rejection_evidence
    && rejection.dialog_observed
    && expectedMessage.test(rejection.dialog_message)
    && rejection.dialog_settled
    && (!rejection.managed_teams_ax_required || rejection.managed_dialog_evidence)
    && rejection.rejected_before_send
    && Number(composer.count) === 0
    && Array.isArray(composer.names)
    && composer.names.length === 0
    && mutationGuard.valid
    && screenshots.rejection.path
    && screenshots.after_dismissal.path
    && dialogEvidence.path
    && JSON.stringify(roles) === JSON.stringify(CORE_BETA_PRE_SEND_ATTACHMENT_REJECTION_NA_ROLES)
  );
  return {
    schema_version: 'qbot-core-beta-pre-send-attachment-rejection/v1',
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: evidenceValid,
    applicable: evidenceValid,
    outcome: evidenceValid ? 'pass' : 'automation_error',
    kind: 'verified_attachment_rejection_before_send',
    source: 'visible_attachment_rejection_and_public_zero_send_readback',
    dependent_case_id: caseId,
    rejection,
    composer_state: composer,
    mutation_guard: {
      ...mutationGuard,
      before_state: beforeState,
      after_state: afterState,
    },
    screenshots,
    dialog_evidence: dialogEvidence,
    not_applicable_roles: roles,
    reason: evidenceValid
      ? '产品在发送前明确拒绝附件；弹窗已安全关闭，Composer 为空，且任务、消息与发送计数均未变化。'
      : '发送前附件拒绝的文案、弹窗收尾、Composer、公开状态、截图或零发送证据不完整。',
  };
}

export function coreBetaPreSendImeFailureEvidence({
  testCaseId = '',
  before = {},
  after = {},
  focusArm = {},
  traceData = {},
  screenshot = '',
  noPromptRecorded = false,
  noSendReceiptRecorded = false,
  notApplicableRoles = CORE_BETA_PRE_SEND_IME_FAILURE_NA_ROLES,
} = {}) {
  const beforeTask = before?.task || {};
  const afterTask = after?.task || {};
  const mutationGuard = {
    task_absent_before: beforeTask?.id == null,
    task_absent_after: afterTask?.id == null,
    not_running_before: beforeTask?.running === false,
    not_running_after: afterTask?.running === false,
    message_count_zero_before: Number(beforeTask?.message_count) === 0,
    message_count_zero_after: Number(afterTask?.message_count) === 0,
    send_count_observed: Number.isFinite(Number(beforeTask?.send_count))
      && Number.isFinite(Number(afterTask?.send_count)),
    send_count_unchanged: Number(beforeTask?.send_count) === Number(afterTask?.send_count),
    no_prompt_recorded: noPromptRecorded === true,
    no_send_receipt_recorded: noSendReceiptRecorded === true,
  };
  mutationGuard.valid = Object.values(mutationGuard).every(Boolean);
  const roles = (Array.isArray(notApplicableRoles) ? notApplicableRoles : [])
    .map(String)
    .filter((role, index, items) => (
      CORE_BETA_PRE_SEND_IME_FAILURE_NA_ROLES.includes(role)
      && items.indexOf(role) === index
    ));
  const screenshotValid = coreBetaBatchScreenshotPresent(screenshot);
  const traceValid = focusArm?.ready === true
    && Number(traceData?.native_command_status) === 0
    && traceData?.valid === false
    && traceData?.evidence_valid === true
    && traceData?.oracle_valid === false
    && traceData?.adapter_noop === false
    && Number(traceData?.event_count) > 0;
  const evidenceValid = Boolean(
    String(testCaseId || '').trim()
    && traceValid
    && mutationGuard.valid
    && screenshotValid
    && roles.length > 0
  );
  const interaction = {
    schema_version: 'qbot-core-beta-native-ime-interaction/v1',
    focus_arm: focusArm,
    trace: {
      valid: traceData?.valid === true,
      evidence_valid: traceData?.evidence_valid === true,
      oracle_valid: traceData?.oracle_valid === true,
      exact_readback: traceData?.exact_readback === true,
      composition_start: traceData?.composition_start === true,
      composition_end: traceData?.composition_end === true,
      event_count: Number(traceData?.event_count || 0),
      native_command_status: traceData?.native_command_status,
      adapter_noop: traceData?.adapter_noop === true,
    },
    screenshot: screenshotValid ? path.resolve(screenshot) : '',
  };
  return {
    schema_version: 'qbot-core-beta-pre-send-ime-failure/v1',
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: false,
    applicable: evidenceValid,
    outcome: evidenceValid ? 'bug' : 'automation_error',
    kind: 'native_ime_product_failure_before_send',
    source: 'native_ime_composition_and_zero_send_readback',
    dependent_case_id: String(testCaseId || ''),
    interaction,
    mutation_guard: {
      ...mutationGuard,
      before_task: beforeTask,
      after_task: afterTask,
    },
    screenshot: {
      path: interaction.screenshot,
      sha256: screenshotValid
        ? createHash('sha256').update(fs.readFileSync(screenshot)).digest('hex')
        : '',
    },
    not_applicable_roles: roles,
    reason: evidenceValid
      ? '真实原生IME已产生composition事件但未满足文本Oracle；已证明当前任务为空、消息数为0且发送计数未变化。'
      : '原生IME产品失败的前台焦点、事件、截图或零发送变更证据不完整。',
  };
}

export function coreBetaPreSendCapabilityFailureEvidence({
  testCaseId = '',
  capabilityKind = 'skill',
  expectedIdentity = '',
  before = {},
  after = {},
  interaction = {},
  noPromptRecorded = false,
  noSendReceiptRecorded = false,
  notApplicableRoles = CORE_BETA_PRE_SEND_CAPABILITY_FAILURE_NA_ROLES,
} = {}) {
  const beforeTask = before?.task || {};
  const afterTask = after?.task || {};
  const beforeSelection = capabilityKind === 'connector'
    ? before?.connectors?.selected
    : before?.skills?.selected;
  const afterSelection = capabilityKind === 'connector'
    ? after?.connectors?.selected
    : after?.skills?.selected;
  const screenshot = String(interaction?.screenshot || '');
  const manualSurface = interaction?.manual_surface;
  const interactionValid = interaction?.schema_version === 'qbot-core-beta-capability-interaction/v1'
    && interaction?.capability_kind === capabilityKind
    && ['manual_mode', 'manual_skill_selection', 'manual_connector_selection'].includes(String(interaction?.stage || ''))
    && String(interaction?.expected_identity || '') === String(expectedIdentity || '')
    && interaction?.control_located === true
    && interaction?.click_dispatched === true
    && interaction?.expected_state_observed === false
    && interaction?.category === 'bug'
    && interaction?.aria_checked === 'false'
    && manualSurface && typeof manualSurface === 'object'
    && typeof manualSurface.list_visible === 'boolean'
    && Number.isFinite(Number(manualSurface.option_count))
    && typeof manualSurface.empty_visible === 'boolean'
    && (capabilityKind !== 'skill' || typeof manualSurface.search_visible === 'boolean')
    && (interaction?.stage !== 'manual_skill_selection'
      || (manualSurface.list_visible === true && Number(manualSurface.option_count) > 0))
    && coreBetaBatchScreenshotPresent(screenshot);
  const mutationGuard = {
    task_absent_before: beforeTask?.id == null,
    task_absent_after: afterTask?.id == null,
    not_running_before: beforeTask?.running === false,
    not_running_after: afterTask?.running === false,
    message_count_zero_before: Number(beforeTask?.message_count) === 0,
    message_count_zero_after: Number(afterTask?.message_count) === 0,
    send_count_observed: Number.isFinite(Number(beforeTask?.send_count))
      && Number.isFinite(Number(afterTask?.send_count)),
    send_count_unchanged: Number(beforeTask?.send_count) === Number(afterTask?.send_count),
    capability_selection_empty_before: Array.isArray(beforeSelection) && beforeSelection.length === 0,
    capability_selection_empty_after: Array.isArray(afterSelection) && afterSelection.length === 0,
    no_prompt_recorded: noPromptRecorded === true,
    no_send_receipt_recorded: noSendReceiptRecorded === true,
  };
  mutationGuard.valid = Object.values(mutationGuard).every(Boolean);
  const roles = (Array.isArray(notApplicableRoles) ? notApplicableRoles : [])
    .map(String)
    .filter((role, index, items) => (
      CORE_BETA_PRE_SEND_CAPABILITY_FAILURE_NA_ROLES.includes(role)
      && items.indexOf(role) === index
    ));
  const evidenceValid = Boolean(
    String(testCaseId || '').trim()
    && String(expectedIdentity || '').trim()
    && ['skill', 'connector'].includes(capabilityKind)
    && interactionValid
    && mutationGuard.valid
    && roles.length > 0
  );
  return {
    schema_version: 'qbot-core-beta-pre-send-capability-failure/v1',
    valid: evidenceValid,
    evidence_valid: evidenceValid,
    oracle_valid: false,
    applicable: evidenceValid,
    outcome: evidenceValid ? 'bug' : 'automation_error',
    kind: 'visible_capability_control_product_failure',
    source: 'visible_capability_control_click_and_zero_send_readback',
    dependent_case_id: String(testCaseId || ''),
    capability_kind: capabilityKind,
    expected_identity: String(expectedIdentity || ''),
    interaction,
    mutation_guard: {
      ...mutationGuard,
      before_task: beforeTask,
      after_task: afterTask,
      before_selection: Array.isArray(beforeSelection) ? beforeSelection : null,
      after_selection: Array.isArray(afterSelection) ? afterSelection : null,
    },
    screenshot: {
      path: screenshot,
      sha256: coreBetaBatchScreenshotPresent(screenshot)
        ? createHash('sha256').update(fs.readFileSync(screenshot)).digest('hex')
        : '',
    },
    not_applicable_roles: roles,
    reason: evidenceValid
      ? `已真实点击 ${capabilityKind} 能力控件，但产品未进入期望状态；已证明当前任务为空、消息数为0且发送计数未变化。`
      : '发送前能力产品失败的点击、状态读回、截图或零发送变更证据不完整。',
  };
}

